  str_item_6001531 = "Ode Cinta",
  str_item_6001532 = "Starlight Anda",
  str_item_intro_6000001 = "Stand By Me Medali. Seiring berlalunya waktu, jumlah koin telah berkembang ke ukuran yang mengkhawatirkan. Pada titik ini, hanya dompet koin seukuran rumah yang bisa memuat kekayaan sebanyak ini.",
  str_item_intro_6000002 = "Stand By Me Medali. Rasanya hampir mustahil untuk menghitung jumlah akumulasi kekayaan yang sangat besar ini. Berani melakukannya akan membuat pedagang Umbraton yang paling rakus pun pusing sampai pingsan.",
  str_item_intro_6000101 = "Stand By Me Medali. Selamat! Meskipun hanya mencoba beberapa kali, tidak ada yang tahu apa yang akan terjadi di masa depan!",
  str_item_intro_6000102 = "Stand By Me Medali. Anda cukup mampu mengemudikan Colossus sekarang! Ikatan Anda dengan Fireflies tampaknya semakin kuat juga.",
  str_item_intro_6000103 = "Stand By Me Medali. Awan di depan Anda, dan awan di sekitar Anda. Berendamlah di bawah mereka untuk melihat dunia luas di bawah, dan langit biru bertitik awan di atas.",
  str_item_intro_6000104 = "Stand By Me Medali. Anda telah melakukan perjalanan jauh dan jauh sebagai Navigator Soroz. Orang bahkan bisa mengatakan bahwa rumah sejati Anda terletak di langit tak terbatas di atas Astra.",
  str_item_intro_6000201 = "Stand By Me Medali. Bawalah gambar tanah di hati Anda, dan pergi ke mana pun Anda mau dengan lambaian tangan. Seluruh dunia berada dalam jangkauan Anda.",
  str_item_intro_6000202 = "Stand By Me Medali. Setelah sekian lama melakukan perjalanan, hamparan tanah tersebut pasti terpatri dalam-dalam di benak Anda, ya? Dapatkah Anda melihat gunung dan sungainya, bahkan ketika Anda menutup mata?",
  str_item_intro_6000301 = "Stand By Me Medali. Jalan di depan pasti akan panjang dan sulit. Menemukan teman yang dapat dipercaya dari semua lapisan masyarakat akan membantu Anda dengan baik.",
  str_item_intro_6000302 = "Stand By Me Medali. Sepanjang perjalanan Anda, Anda telah menjalin persahabatan baru dengan orang-orang di seluruh dunia. Sebuah prestasi yang menakjubkan, memang!",
  str_item_intro_6000303 = "Stand By Me Medali. Ke mana pun Anda pergi, Anda selalu dikelilingi oleh teman-teman dekat. Teman yang akan tertawa dan menangis di sisimu, dan menghadapi kesulitan apa pun yang mungkin menghadangmu...",
  str_item_intro_6000401 = "Stand By Me Medali. Langit tampaknya sedikit lebih cerah dengan setiap sekutu baru yang menyadari potensi mereka yang sebenarnya. Mungkinkah cahaya misterius ini adalah kekuatan yang menyatukan Anda dan teman-teman Anda?",
  str_item_intro_6000402 = "Stand By Me Medali. Setelah sekutu Anda memperoleh kekuatan cahaya, energi yang menerangi langit juga dapat dilihat di tangan mereka.",
  str_item_intro_6000403 = "Stand By Me Medali. Mereka yang diberkahi dengan kekuatan cahaya akan berkumpul dan menawarkan kekuatan mereka kepada anak takdir, sehingga kecemerlangan mereka dapat mencapai bahkan sudut paling gelap dan paling menyedihkan di dunia.",
  str_item_intro_6000501 = "Stand By Me Medali. Ketika dua bintang muncul di dekat satu sama lain, cahaya mereka yang berkilauan adalah simbol kepercayaan mereka, sebuah tanda bahwa mereka akan mencerminkan kecemerlangan satu sama lain selama berabad-abad yang akan datang.",
  str_item_intro_6000502 = "Stand By Me Medali. Saat bintang-bintang melintasi langit, jalan mereka bertemu, saling terhubung dan beresonansi seperti hati dan pikiran dari roh yang sama dengan keyakinan yang sama.",
  str_item_intro_6000503 = "Stand By Me Medali. Seperti rasi bintang di langit malam, sekutu Anda bersinar dengan cahaya kepercayaan dan persatuan mutlak. Ikatan yang menghubungkan Anda mewakili konvergensi harapan dan ide Anda.",
  str_item_intro_6000601 = "Stand By Me Medali. Meskipun ini adalah pertama kalinya Anda melihat mereka, benih pemahaman sudah ditanam. Empat tangan, saling terkait di ujung jari, mewakili hubungan antara dua hati.",
  str_item_intro_6000602 = "Stand By Me Medali. Meskipun bertahun-tahun dihabiskan di bawah tanah, kegembiraan penerbangan tidak pernah terlupakan. Meskipun ini baru pertama kali, itu sudah lebih dari cukup.",
  str_item_intro_6000603 = "Stand By Me Medali. Suara langkah kaki yang mendekat tidak hanya menandakan bahaya, tetapi juga datangnya kehancuran total.",
  str_item_intro_6000604 = "Stand By Me Medali. Di hadapan musuh yang tak terhitung jumlahnya, dia memilih untuk mengakhiri semuanya dengan raungan yang menghancurkan bumi. Itu bukan tindakan pengorbanan yang putus asa, tetapi strategi yang diperhitungkan dan disengaja.",
  str_item_intro_6000605 = "Stand By Me Medali. Sebuah pesan dari orang-orang Anda! Tapi masa lalu macam apa yang ada di balik suara lembut itu?",
  str_item_intro_6000606 = "Stand By Me Medali. Berada selamanya di langit biru di atas, itu adalah pusat dari semua peradaban dan simbol cahaya.",
  str_item_intro_6000607 = "Stand By Me Medali. \"Masa depan bukan milik cahaya, tetapi milik kegelapan.\" Pada saat itu, senyumnya berubah menjadi sesuatu yang biadab... sesuatu yang jahat. Meskipun orang yang sama denganmu, dia sudah lama tersesat.",
  str_item_intro_6000608 = "Stand By Me Medali. Musuh tersenyum sombong saat rencana jahat mereka membuahkan hasil. Dalam keputusasaan yang paling gelap, dandelion mengapung dengan angin sepoi-sepoi. Apa masa depan bagi kita semua? Atau lebih tepatnya... apakah ada masa depan yang bisa dilihat?",
  str_item_intro_6000609 = "Stand By Me Medali. Ada pepatah di Astra: \"Pilihan seseorang jauh lebih besar daripada usahanya.\" Banyak yang ragu pada persimpangan takdir yang paling penting; dalam menghadapi keputusan ini, mereka hanya bisa mengandalkan hati mereka, intuisi mereka, dan teman-teman mereka.",
  str_item_intro_6000610 = "Stand By Me Medali. Senjata yang mengubah cahaya menjadi sinar energi yang kuat adalah domain Lumopolis dan Lumopolis saja. Meskipun datang dengan harga yang mahal, ancaman musuh yang akan datang harus dihindari dengan segala cara.",
  str_item_intro_6000611 = "Stand By Me Medali. Colossus hitam telah dikalahkan, dan baik master maupun mesin telah mendarat darurat di lembah yang jauh. Namun demikian, kekalahan mereka tidak berarti kematian mereka ...",
  str_item_intro_6000612 = "Stand By Me Medali. Mereka yang mengejar kekuasaan dengan niat tunggal ditakdirkan untuk binasa karenanya. Ketika dia melemparkan dirinya ke dalam kegelapan, itu adalah takdirnya untuk menemui ajalnya dalam kegelapan juga.",
  str_item_intro_6000613 = "Stand By Me Medali. Garis adalah \"alam\" yang diungkapkan dalam matematika. Cangkang adalah wadah mata uang, dan kontinuitas tidak selalu diperlukan.",
  str_item_intro_6000614 = "Stand By Me Medali. Pasangan yang pernah berjuang sebagai kawan dalam perang kini telah berpisah karena perbedaan masa lalu.",
  str_item_intro_6000615 = "Stand By Me Medali. Dia tertidur tanpa henti di bawah Chord Link. Saat terbangun, harapkan dia melepaskan kekuatan besar.",
  str_item_intro_6000616 = "Stand By Me Medali. Caelestite akhirnya memiliki tempat untuk disebut rumah di bawah Obelisk of Return, tetapi kehadirannya juga mengubah takdirnya...",
  str_item_intro_6000617 = "Stand By Me Medali. Untuk menjelajahi wilayah Eternal Night, Ksatria Lumopolis dan petugas dari Federasi Illumina harus bergabung, karena bahayanya tidak biasa.",
  str_item_intro_6000618 = "Stand By Me Medali. Ini merupakan kehormatan besar dalam latihan militer yang telah diikuti oleh banyak pasukan.",
  str_item_intro_6000619 = "Stand By Me Medali. Gerbang tebal memblokir semua penyusup di tingkat terendah Undercity untuk melindungi barang-barang penting dan berharga dari pencuri dan bajingan.",
  str_item_intro_6000701 = "Stand By Me Medali. Ini bukan hanya awal, tetapi kesempatan untuk naik di atas yang lain. Mereka yang cukup berani untuk selalu membuat langkah pertama akan menjadi orang yang mengatasi kesulitan dan mencapai puncak.",
  str_item_intro_6000702 = "Stand By Me Medali. Meskipun banyak rintangan mungkin terbentang di depan, perjuangan tetap sama, dan seseorang tidak boleh berhenti berjuang untuk meningkatkan dan mencapai tingkat yang lebih tinggi. Mungkinkah ini kekuatan Ascension?",
  str_item_intro_6000703 = "Stand By Me Medali. Setelah mencapai puncak ini, mudah untuk memandang rendah dunia di bawah dan berpuas diri. Namun, bagi mereka yang benar-benar ambisius, kepuasan ini hanyalah momen kegembiraan sesaat dalam perjalanan untuk mencapai ketinggian tertinggi...",
  str_item_intro_6000704 = "Stand By Me Medali. Mereka yang berhasil mencapai puncak lebih unggul dari banyak penantang, namun rasa lapar untuk menaklukkan tidak dapat dipuaskan, dan langkah kaki tidak akan pernah berhenti.",
  str_item_intro_6000705 = [[
Stand By Me Medali. Puncaknya telah melihat banyak pertempuran;
Hanya di puncak orang akan tahu kesulitannya.
Puncaknya disediakan untuk pemenang,
Hanya di puncak seseorang akan mengabaikan sisanya.]],
  str_item_intro_6000706 = "Stand By Me Medali. Meskipun ini baru pertama kali, mereka yang bisa mencapai ini luar biasa dan lebih hebat dari banyak orang.",
  str_item_intro_6000801 = [[
Stand By Me Medali. Pengurungan yang mengejutkan, reuni yang tidak terduga;
tinggi di dalam sangkar, mereka yang tidak mau terjebak melepaskan belenggu.]],
  str_item_intro_6000802 = "Stand By Me Medali. Apa yang diidamkan kucing? Selain makanan kaleng favoritnya, itu pasti...",
  str_item_intro_6000803 = "Stand By Me Medali. Ini adalah keluarga untuk \"Liburan\" dan membuatnya sadar bahwa kafe adalah rumahnya dan di mana dia harus tinggal...",
  str_item_intro_6000804 = "Stand By Me Medali. Istana tertutup rapat di tengah salju dan es, tetapi ketika sosok ramping itu datang untuk aurora, istana itu akan terbuka.",
  str_item_intro_6000901 = "Stand By Me Medali. Celah-celah terhampar seperti sarang laba-laba di tanah, dan semua tanda menunjukkan keberadaan busuk yang muncul dari bawah...",
  str_item_intro_6000902 = "Stand By Me Medali. Gua itu gelap kecuali sumber cahaya penyusup itu sendiri. Tapi tidak sepi di sini, karena banyak \"penduduk asli\" menunggu...",
  str_item_intro_6000903 = "Stand By Me Medali. Apakah ada akhir untuk ini? Pikiran itu sering menghantui pikiran penjelajah, meskipun yang kuat tidak akan takut dan berani masuk sekali lagi.",
  str_item_intro_6001001 = "Stand By Me Medali. Gambar bisa menjadi senjata, dan ilusi bisa membahayakan. Terkadang, mata yang tajam jauh lebih baik daripada lengan yang kokoh.",
  str_item_intro_6001002 = "Stand By Me Medali. Membiarkannya terbakar! Saksikan kobaran api menghancurkan orang-orang kafir!",
  str_item_intro_6001003 = "Stand By Me Medali. Panggilan keras itu menandakan kehadiran musuh, dan keheningan menandai kematian dan akhir darinya.",
  str_item_intro_6001004 = "Stand By Me Medali. Apakah lawan atau kekosongan lebih menakutkan? Tampaknya satu-satunya cara untuk mengalahkannya adalah dengan mengikat dan menjebaknya selamanya.",
  str_item_intro_6001005 = "Stand By Me Medali. Tidak ada tubuh fana, hanya kesadaran yang melayang-layang, meskipun itu hanya bisa menyebar dalam cahaya yang membengkak.",
  str_item_intro_6001006 = "Stand By Me Medali. Ketidakadilan takdir dapat membuat seseorang menjadi gila dan berubah menjadi kegelapan. Pada saat itu, senjata dan pisau adalah satu-satunya solusi untuk melawannya.",
  str_item_intro_6001007 = "Stand By Me Medali. Ketika dihadapkan dengan rasa sakit dan kemarahan yang tak ada habisnya sepanjang waktu, mengakhirinya adalah hadiah terbaik.",
  str_item_intro_6001008 = "Stand By Me Medali. Itu yang paling gelap sebelum terang. Bertahanlah, dan Anda akan melihat matahari menyinari jalan yang Anda tuju.",
  str_item_intro_6001009 = "Stand By Me Medali. Suara-suara tanpa tubuh dan suara-suara tak tertahankan terjalin untuk membentuk rasa sakit dan mimpi buruk musuh.",
  str_item_intro_6001010 = "Stand By Me Medali. Bisakah seseorang tanpa rumah diasingkan? Mungkin, tetapi sangat sedikit yang akan mengetahuinya.",
  str_item_intro_6001011 = "Stand By Me Medali. Batu merah tua itu berasal dari sasaran yang tercemar dan, setelah lepas, menjadi permata yang paling indah.",
  str_item_intro_6001012 = "Stand By Me Medali. Manusia tidak memiliki nilai kecuali jiwa mereka, yang diperebutkan oleh para dewa.",
  str_item_intro_6001013 = "Stand By Me Medali. Bukan ksatria Lumopolis, tapi musuh lama mereka. Penyamaran mereka telah dipatahkan—sekarang yang tersisa hanyalah pertempuran sampai akhir.",
  str_item_intro_6001101 = "Stand By Me Medali. Dengan setiap pergantian halaman, teks yang luar biasa membanjiri mata dan merangsang pikiran seperti lonceng yang menyenangkan.",
  str_item_intro_6001102 = "Stand By Me Medali. Tidaklah tidak sopan untuk duduk di atas sebuah buku ketika Anda telah mempelajari semua yang ada di dalamnya.",
  str_item_intro_6001103 = "Stand By Me Medali. Menggunakan buku untuk tempat tidur dan bantal berarti seseorang juga dapat menikmati dunia yang terkandung dalam mimpi Anda.",
  str_item_intro_6001201 = "Stand By Me Medali. Tukang kebun sejati merawat setiap bibit dengan tangan mereka sendiri. Meskipun tangan dan pakaian mereka sering kotor oleh keringat dan tanah, melihat setiap bibit mencapai kedewasaan dan mekar dengan subur adalah salah satu kebahagiaan terbesar dalam hidup mereka.",
  str_item_intro_6001202 = "Stand By Me Medali. Saat tanaman aneh ini tumbuh dan memenuhi ruangan dengan keindahan alamnya, Cloud Gardens akan terlihat jauh lebih berbeda dalam cahaya matahari terbenam.",
  str_item_intro_6001203 = "Stand By Me Medali. Hanya seorang master yang bisa menangkap ikan langka seperti ini!",
  str_item_intro_6001204 = "Stand By Me Medali. Ini adalah kesempatan besar bagi semua pemancing, bukan hanya karena festival itu sendiri, tetapi karena kedatangan seorang nelayan ahli tertentu.",
  str_item_intro_6001205 = "Stand By Me Medali. Tanpa disadari, Anda telah mengumpulkan banyak pengetahuan untuk membangun struktur baru. Segera, ruang kosong di lembah itu tidak akan tampak begitu sepi.",
  str_item_intro_6001206 = "Stand By Me Medali. Setelah menguasai konstruksi begitu banyak struktur, Anda siap untuk mengubah Cloud Gardens menjadi kota yang makmur kapan saja. Sebagai penguasa Cloud Gardens, tugas ini jatuh kepada Anda sendiri.",
  str_item_intro_6001301 = "Stand By Me Medali. Elysium, tempat dengan masa lalu yang legendaris... Setelah membangunkan pahlawan yang tertidur lama, ikatan seperti apa yang akan mereka bagi?",
  str_item_intro_6001302 = "Stand By Me Medali. Sumpah dari masa lalu masih utuh, dan musuh saat itu masih menjadi ancaman. Kata-kata tidak akan pernah bisa mematahkan sumpah mereka atau mencegah mereka mengambil tindakan.",
  str_item_intro_6001400 = "Stand By Me Medali. Hidup itu seperti permainan, dan petualangan yang dimainkan di tangan Anda sama-sama mengasyikkan. Mereka yang bisa menyelesaikan tahapan dengan kondisi sulit seperti itu pasti juga akan berhasil di kehidupan nyata.",
  str_item_intro_6001401 = "Stand By Me Medali. Itu dicatat dengan setia tanpa bias atau penyembunyian. Itu menyimpan kenangan bagi Anda untuk membaca dengan teliti masa lalu yang indah.",
  str_item_intro_6001402 = "Medali Stand By Me. Panggung yang melayang di langit bergema dengan lagu-lagu pujian yang jatuh ke setiap sudut benua seperti berkah ilahi. Antara mimpi dan penglihatan muncul nada cinta dan penyembuhan.",
  str_item_intro_6001403 = "Stand By Me Medali. Sekutu yang sangat diperlukan di lautan tak berujung. Dikatakan bahwa itu tidak hanya memandu kapal di sepanjang jalan yang benar, tetapi juga memandu seseorang melalui labirin takdir ...",
  str_item_intro_6001404 = "Medali Stand By Me. Itu adalah hadiah, ekspresi hati, bentuk komunikasi. Tidak perlu kata-kata—cukup memberikannya kepada orang yang Anda kasihi.",
  str_item_intro_6001405 = "Stand By Me Medali. Buket bunga yang dipesan untuk hari spesial. Ketika waktu yang ditentukan tiba, mereka diarak dengan mekar penuh, memenuhi udara dengan keharuman cinta yang memabukkan. Ambil napas dalam-dalam dan nikmati momen yang tak ternilai ini.",
  str_item_intro_6001406 = "Stand By Me Medali. Jangan pernah meninggalkan sisi detektif, yang perlu dilakukan detektif hanyalah menjangkaunya dan ia akan memberikan layanannya. Dengan ini, bahkan petunjuk terkecil pun dapat ditemukan.",
  str_item_intro_6001407 = "Stand By Me Medali. Kenangan Hari Keluarga, ilusi sekilas dalam kilauan kristal. Meskipun peristiwa ilusi ini termasuk dalam dunia ilusi orang dan benda ilusi, semuanya tampak begitu nyata, seolah-olah telah dialami secara langsung.",
  str_item_intro_6001408 = "Orang-orang nyata terjebak dalam dunia buatan, yang tidak dapat dipatahkan dengan paksa atau mereka akan terjebak di dalamnya selamanya...",
  str_item_intro_6001409 = "Stand By Me Medali. Mewakili pertapa yang penyendiri di Lembah Denuo, yang menaburkan sisik berkilauan dan partikel berkilau saat menari dengan anggun, melemparkan mantra pesona pada semua yang memandangnya...",
  str_item_intro_6001410 = "Stand By Me Medali. Kemenangan tidak hanya berasal dari peperangan, tetapi juga berakar dalam konstruksi sehari-hari, pertumbuhan, dan pengembangan yang terus-menerus.",
  str_item_intro_6002001 = "Stand By Me Medali. Apakah penjaga orang baik dan utusan para dewa benar-benar ada? Atau itu hanya fantasi?",
  str_item_intro_6002002 = "Stand By Me Medali. Buat persiapan Anda saat matahari masih bersinar. Dalam terang matahari, jangan pernah melupakan ancaman kegelapan. Di masa damai, jangan pernah lupa bahwa musuh selalu bisa bersembunyi di bayang-bayang di dekatnya...",
  str_item_intro_6002003 = "Stand By Me Medali. Sebuah legenda binatang misterius dari pelosok Northland, dikatakan menghembuskan api dari es terdingin, dan dapat membekukan seluruh desa dalam satu gerakan.",
  str_item_intro_6002004 = "Stand By Me Medali. Ada cermin tertentu di suatu tempat di dunia, cermin yang hanya akan mencerminkan wajah orang yang melihatnya dan bukan milik orang lain. Refleksi itu, bagaimanapun, dikatakan memiliki kehidupan dan pikirannya sendiri ...",
  str_item_intro_6002005 = "Stand By Me Medali. Mereka mulai sebagai objek umum. Hanya di tangan orang bijak mereka akan memperoleh kesadaran dan jiwa untuk menyelesaikan misi mereka.",
  str_item_intro_6002006 = "Stand By Me Medali. Jika baja lebih berat dari udara, lalu mengapa bisa dibuat terbang? Dan jika besi lebih berat dari air, lalu bagaimana bisa digunakan untuk membuat kapal? Dalam menghadapi pertanyaan seperti ini, pengetahuan dan logika akan melayani Anda lebih baik daripada \"akal sehat\".",
  str_item_intro_6002007 = "Stand By Me Medali. Hanya dewa yang bisa membuat baja besar bergerak seperti suara inkorporeal.",
  str_item_intro_6002008 = "Stand By Me Medali. Gurun tidak terbatas. Mengapa seseorang berkeliaran di sini mungkin tidak pernah diketahui. Atau itu bisa menjadi satu-satunya niat, untuk berkeliaran.",
  str_item_intro_6002009 = "Stand By Me Medali. Kenikmatan datang dengan harga, tidak peduli siapa Anda. Bahkan jika harga itu tidak dibayar pada awalnya, itu akan dibayar suatu hari nanti... Dan dengan bunga.",
  str_item_intro_6002010 = "Stand By Me Medali. Jeritan yang menakutkan, sorakan sekutu... Daya pikat perang tidak terletak pada penaklukan, strategi, atau keberanian, tetapi pada kemenangan dan fakta bahwa raja lain telah lahir.",
  str_item_intro_6002011 = "Stand By Me Medali. Cangkang baja tidak cukup untuk mengubah manusia biasa menjadi petarung yang tidak bisa dihancurkan. Anda akan membutuhkan koordinasi, fleksibilitas, dan ketekunan.",
  str_item_intro_6002012 = "Stand By Me Medali. Mungkinkah benar-benar ada yang namanya botol tanpa di dalam atau di luar? Tanpa perbedaan ini, tidak akan ada ruang dan dengan demikian tidak ada botol untuk dibicarakan ... Tapi mungkin ruang itu tak terbatas, dan tidak memerlukan perbedaan? Bagaimanapun, objek seperti itu terletak di alam para dewa, dan hanya bisa ada melalui sarana ilahi.",
  str_item_intro_6002013 = "Stand By Me Medali. Bisakah pita kertas hanya memiliki satu sisi? Jawabannya tersembunyi di dalam strip itu sendiri; semua yang perlu dilakukan adalah melihatnya dengan cara yang benar. Dengan melakukan itu, seseorang juga dapat melihat seluruh dunia dalam cahaya yang berbeda...",
  str_item_intro_6002014 = "Stand By Me Medali. Hal-hal bisa eksis bahkan di ruang terkecil sekalipun. Ketika melihat dunia ini dalam botol, pernahkah terpikir oleh Anda bahwa seseorang mungkin juga melakukan hal yang sama pada dunia Anda?",
  str_item_intro_6002015 = "Stand By Me Medali. Banyak legenda menyebutkan bahwa semua makhluk hidup lahir dari pohon yang sama, sebuah anggapan yang mengundang cemoohan dari sejumlah orang. Namun, setelah meneliti asal usul makhluk tertentu, orang-orang itu pasti mulai meragukan pernyataan mereka sebelumnya...",
  str_item_intro_6002016 = "Stand By Me Medali. Jika satu baris senar dapat menghasilkan suara yang menggetarkan, bagaimana jika itu adalah baris ganda? Padahal itu juga akan membutuhkan seorang musisi dengan keterampilan dan kekuatan yang luar biasa.",
  str_item_intro_6002017 = "Stand By Me Medali. Rodanya adalah tubuhnya, jadi menginjak-injak adalah serangan utamanya. Berdoalah agar Anda tidak harus menghadapi pisau yang berputar dalam pertempuran.",
  str_item_intro_6002018 = "Stand By Me Medali. Jika benteng suatu hari nanti bisa mendominasi tanah seperti raksasa legendaris, mereka tidak akan terkalahkan.",
  str_item_intro_6002019 = "Stand By Me Medali. Ketika manusia memikirkan \"ketiadaan\", mereka memberinya semacam keberadaan. Tanpa bentuk, itu masuk melalui mata mereka, menembus jauh ke dalam pikiran mereka dan menciptakan jenis \"ketiadaan\" yang berbeda di dalam.",
  str_item_intro_6002020 = "Stand By Me Medali. Tak kenal lelah, tidak ada keluhan... Itu akan menggambarkan tunggangan bagi mereka yang melintasi padang pasir.",
  str_item_intro_6002021 = "Stand By Me Medali. Permainan strategi dinikmati di mana-mana di dunia, dan mereka yang memegang posisi tinggi dalam masyarakat mereka cenderung melihat seluruh dunia sebagai permainan catur. Namun, \"buah\" dalam permainan catur ini sadar diri, seperti halnya papan catur itu sendiri. Jadi, banyak dari permainan catur ini ditakdirkan untuk dihancurkan seluruhnya, seperti yang telah terjadi sepanjang sejarah.",
  str_item_intro_6002022 = "Stand By Me Medali. \"Jatuh ke dalam kehancuran abadi... Tataplah dunia sekali lagi, dan biarkan itu menjadi kenangan terakhirmu.\" Inilah yang dikatakan makhluk kegelapan kepada semua makhluk hidup di dunia.",
  str_item_intro_6002023 = "Stand By Me Medali. Diduga, posisi bintang-bintang di langit mewakili takdir manusia, sehingga manusia membangun menara yang menjulang untuk mengamati bintang-bintang dan meramalkan masa depan. Ironisnya, masa depan menara ini tidak bisa diprediksi.",
  str_item_intro_6002024 = "Stand By Me Medali. Seekor binatang buas dengan tubuh yang kuat dan gerakan yang cepat. Tapi yang benar-benar menakutkan orang adalah paku ekornya yang licik dan beracun.",
  str_item_intro_6002025 = "Stand By Me Medali. Seperti utusan dari neraka, ia datang ke dunia ini dengan murka. Dunia bawah bukanlah tempatnya, tetapi siklus kematian dan reinkarnasi.",
  str_item_intro_6001500 = [[
Stand By Me Medali.
Lanskap suara luas, begonia dalam masa jayanya. Mendekatlah, dengar gema seperti sajak. Angin timur membawa bunyi bunga mekar. Di paviliun, saat yang luar biasa.]],
  str_item_intro_6001507 = [[
Stand By Me Medali.
Di Northland, beberapa butir salju baru saja jatuh dan beberapa telah bertahan selama berabad-abad. Kategori mana medali yang Anda pegang ini termasuk?]],
  str_item_intro_6001508 = [[
Stand By Me Medali.
Semua petualangan yang kita jalani akan selalu dihargai.]],
  str_item_intro_6001510 = [[
Bunga yang tak ternoda ini begitu murni dan indah.
Sama seperti dia.]],
  str_item_intro_6001511 = [[
Stand By Me Medali.
Dengan kebijaksanaan luar biasa, seseorang dapat membuat kapal untuk menghubungkan daratan yang jauh atau membuat senjata untuk melepaskan kekacauan. Pada saat-saat seperti itu, kebijaksanaan sejati terletak pada pilihan seseorang.]],
  str_item_intro_6000620 = [[
Stand By Me Medali.
Sebuah mecha tempur raksasa yang diciptakan oleh Illumina. Mech ini memiliki luar yang kokoh dan kekuatan tembakan yang luar biasa. Seperti biasa, kelemahan dari raksasa semacam itu sering tersembunyi di bawah permukaan...]],
  str_item_intro_6000621 = "Medali Stand By Me. Menara yang menjaga garis pertahanan terakhir, melenyapkan semua musuh yang masuk.",
  str_item_intro_6001512 = [[
Stand By Me Medali.
Semua orang menginginkannya, tetapi tidak semua orang dapat menanggung beban itu.]],
  str_item_intro_6001515 = [[
Stand By Me Medali. 
Sebuah mesin yang dipenuhi dengan bahaya yang tidak diketahui. Tidak ada yang tahu berapa lama lagi mesin ini akan terus berfungsi, dan selalu membuat suara mendesis yang menakutkan di tengah malam.]],
  str_item_intro_6001516 = [[
Stand By Me Medali.
Aurorian dan fiendlings, apa bedanya? Keduanya mengunyah figur gula manis di bawah kembang api Festival Musim Semi, merayakan kesempatan baik ini bersama.]],
  str_item_intro_6001517 = [[
Stand By Me Medali.
Algol mengembangkan gelang ini untuk memantau data kesehatan seperti denyut jantung, tekanan darah, dan saturasi oksigen darah secara real time, dan menggunakan data ini untuk mengembangkan rencana kebugaran untuk pemakainya.]],
  str_item_intro_6001520 = [[
Stand By Me Medali.
Tugas para penjaga membawa beban berat, tetapi mereka dengan sukarela menerimanya, memilih untuk tetap berada di dalam badai salju.]],
  str_item_intro_6001521 = [[
Stand By Me Medali.
Pengorbanan tidak boleh dilakukan hanya untuk kehormatan. "Kamu mungkin pahlawan, tetapi kamu jauh lebih dari itu."]],
  str_item_intro_6001524 = [[
Stand By Me Medali.
"Itu menyenangkan! Mari kita pergi lagi, mari kita pergi lagi!"]],
  str_item_intro_6001525 = "Stand By Me Medali. Inspirasi membara di pikiran saya, membuat ini menjadi momen yang tak terlupakan untuk buku catatan.",
  str_item_intro_6001526 = [[
Stand By Me Medali.
"Kekuatan ini bukan milik saya sendiri."]],
  str_item_intro_6001529 = [[
Stand By Me Medali.
"Sudah lama, kontraktorku. Meskipun berbahaya, perjalanan ini menuju kebenaran."]],
  str_item_intro_6001530 = [[
Stand By Me Medali. 
Meskipun sang pangeran tidak pernah kembali, perjalanannya telah membuka jalan bagi kelangsungan hidup rakyatnya. Tidak peduli berapa lama waktu berlalu, hati mereka akan selalu bersatu. Karena hal ini, keturunan mereka suatu hari, cepat atau lambat, akan berkumpul kembali di benua itu.]],
  str_item_intro_6001531 = [[
Stand By Me Medali.
Dia diberitahu bahwa cinta itu seperti mimpi yang indah.]],
  str_item_intro_6001532 = [[
Stand By Me Medali.
Ini adalah perjalanan yang berat, tetapi pada akhirnya, sepertinya Anda hanya menonton kebahagiaan orang lain yang bersatu kembali.
Namun, untuk semua usaha Anda membantu bintang-bintang, bagaimana kami bisa tidak memberi Anda rasa terima kasih kami yang terdalam?]],
  str_item_6100001 = "Papan Peringatan Stand By Me",
  str_item_6100002 = "Stand By Me Battle Board",
  str_item_6100003 = "Stand By Me Lempengan Obsidian",
  str_item_6100004 = "Dewan Mesin Stand By Me",
  str_item_intro_6100001 = "Papan Peringatan Stand By Me. Papan peringatan yang sangat cocok untuk Cloud Gardens, tempat Stand By Me Medallions dapat ditampilkan.",
  str_item_intro_6100002 = "Papan Peringatan Stand By Me. Meskipun visual di papan ini membangkitkan rasa perang yang kuat, itu tidak menghentikan siapa pun untuk menaruh medali mereka di atasnya.",
  str_item_intro_6100003 = "Papan Peringatan Stand By Me. Batuan berwarna hitam ini terlihat seperti berada di hutan belantara. Siapa yang memindahkannya ke sini? Setidaknya tonjolan kecil di atasnya bagus untuk menjaga medali tetap di tempatnya.",
  str_item_intro_6100004 = "Papan Peringatan Stand By Me. Latar belakang ini membuat Anda merasa seperti berada di mesin raksasa atau pabrik, dan Anda tidak dapat menahan keinginan untuk mengatur medali Anda dengan rapi. Tetapi mengaturnya dengan bebas juga merupakan suatu kemungkinan; mungkin spontanitas akan terasa istimewa?",
  str_item_6400001 = "Judul - Pahlawan Garis Depan",
