  str_item_4090334 = "Sakura Memories",
  str_item_intro_1400851 = "Witness Umbraton yang selalu netral apa pun yang terjadi. Ada banyak catatan yang dia bawa setiap saat. Kabarnya dia adalah Arsip Berjalan Umbraton.",
  str_item_intro_3000220 = "Poin Aksi: Digunakan untuk tantangan stage event spesial. Secara otomatis diperbarui setiap waktu.",
  str_item_intro_3000221 = "Mistletoe Fruit yang langka. Buah ini dianggap sebagai simbol harapan dan kelimpahan oleh orang-orang Northland. Digunakan untuk menukar hadiah di Cedar Market.",
  str_item_intro_3000001 = "Carrier of Light dibuat dengan teknik spesial, penting untuk segala jenis ekspedisi.",
  str_item_intro_3000002 = "Koin yang dikeluarkan oleh Lumopolis. Berkilauan dan berlimpah, juga diakui dan dipertukarkan di seluruh kontinen.",
  str_item_intro_3000003 = [[
Permata yang diperoleh dengan menggosok Lumocrystal.
Dapat digunakan untuk memanggil Aurorian, menukarkan dengan Star Flares Khusus, dan Star Flares, serta membeli Prism.]],
  str_item_intro_3000004 = "Wawasan dari perintah dan pengalaman perang terdahulu. Makin tinggi levelnya, makin baik koneksinya dengan Colossus. Berguna untuk mempelajari lebih banyak tentang Colossus.",
  str_item_intro_3000005 = [[
Firefly pulih secara otomatis. Kecepatan pemulihan mereka dipengaruhi oleh Lumina Grid dan dapat ditingkatkan dengan melebur Colossus Patch di Workshop.
Firefly mungil ini bekerja di bawah perintah pengendali Colossus dan bertanggung jawab untuk memulihkan dan memelihara integritas struktural Colossus.]],
  str_item_intro_3000006 = "Hasil pembacaan Luminameter. Semua orang harus dievakuasi jika indikatornya menunjukkan angka 0, atau bahaya takkan bisa dihindari.",
  str_item_intro_3000007 = "Fragmen dari kitab kuno yang ditemukan di Secret Territory. Ada sejumlah lembaga tertentu yang cukup tertarik untuk membelinya.",
  str_item_intro_3000008 = "Poin yang diberikan setelah menyelesaikan Quest Harians. Dapatkan reward ekstra pada jumlah total tertentu.",
  str_item_intro_3000009 = "Proof of Achievements",
  str_item_intro_3000010 = "Aurorian akan lebih dekat denganmu",
  str_item_intro_3000011 = "Holy Dice",
  str_item_intro_3000012 = [[
Sebuah struktur khusus yang ditemukan di Resource Station. Itu dapat mengumpulkan semua jenis sumber daya untuk Anda.
(Gunakan selama Sapuan Berturut-turut untuk mengurangi jumlah Prism yang diperlukan untuk menyelesaikan tahapan dan segera mendapatkan sumber daya)]],
  str_item_intro_3000013 = "Substansi khusus yang dibuat di Colossus Workshop. Dengar-dengar, prinsip kerjanya berasal dari teknologi kuno. Gunakan untuk mengganti komposisi dasar item tertentu untuk mengubahnya menjadi item baru.",
  str_item_intro_3000014 = [[
Kristal alami yang diberi kekuatan Lumina.
Anda dapat menggunakan Lumocrystal di store untuk membeli gift pack dan pakaian Aurorian. Selain itu, Anda dapat mengkonversi Lumocrystal menjadi Lumamber untuk memanggil Aurorian dan memulihkan Prism.]],
  str_item_intro_3000015 = "Permata transparan yang ditemukan bersama Heartstone. Memancarkan kilau sangat kuat seperti api dan bisa ditukarkan dengan item berharga di Star Gem Store.",
  str_item_intro_3000016 = "Star Gems yang lebih langka lagi. Sangat berharga, sangat populer di Star Store.",
  str_item_intro_3000017 = "Material yang dibutuhkan untuk mendukung aktivitas Colossus didistribusikan oleh Lumina Grid, yang menyediakan aliran daya untuk Colossus.",
  str_item_intro_3000018 = "Kepingan batu yang ditemukan di berbagai sudut Cloud Gardens. Tampaknya kepingan ini adalah relik, tetapi fungsi sebenarnya tidak diketahui. Chubb suka kepingan-kepingan ini, dan mau membarter barang-barang tertentu untuk mendapatkannya.",
  str_item_intro_3000019 = "Star Gem yang sangat langka dan harganya tak terjangkau oleh kebanyakan orang. Hanya bisa diperdagangkan di Astral Store.",
  str_item_intro_3000021 = "Disk penyimpanan yang dibuat oleh jembatan Soroz dan simulator. Navigator dapat menempatkan ingatan mereka di dalam untuk membuat hologram di cakram awan Colossus.",
  str_item_intro_3000022 = "Kayu langka dan berharga yang konon berasal dari beberapa tanaman eksotis. Kayu ini populer di kalangan masyarakat kelas atas karena sangat langka. Tak hanya itu, bentuknya bulat alami dan bertekstur halus. Ada Guild khusus di Umbraton yang membelinya dan menggunakannya sebagai mata uang di lokasi khusus.",
  str_item_intro_3000025 = "Dikabarkan mengandung kata-kata The Forsaken, artefak tersebut tetap tidak dapat diuraikan, meninggalkan klaim ini sebagai spekulasi belaka. Namun, kondisinya yang bagus membuatnya menarik bagi afiliasi pencari kebenaran yang tertarik untuk mendapatkannya.",
  str_item_intro_3000026 = "Dikabarkan mengandung kata-kata The Forsaken, artefak tersebut tetap tidak dapat diuraikan, meninggalkan klaim ini sebagai spekulasi belaka. Keadaannya yang terfragmentasi menunjukkan bahwa mengumpulkan banyak bagian mungkin diperlukan untuk menarik pembeli potensial.",
  str_item_intro_3000029 = [[
Bookmark emas yang dapat diperoleh oleh para elit yang telah menyelesaikan Special Event Book.
Dapat ditukarkan dengan reward di Event Book Store.]],
  str_item_intro_3000030 = [[
Bookmark yang dapat diperoleh oleh pemain yang telah melalui Special Event Book.
Dapat ditukarkan dengan reward di Event Book Store.]],
  str_item_intro_3000031 = [[
Item yang dapat diperoleh oleh pemain yang telah melalui Buku Acara Khusus.
Dapat ditukarkan dengan pakaian normal di Toko Buku Acara.]],
  str_item_intro_3000032 = [[
Item yang dapat diperoleh oleh pemain yang telah melewati Buku Acara Spesial.
Dapat ditukarkan dengan furnitur Colossus di Toko Buku Acara.]],
  str_item_intro_3501001 = [[
Item yang digunakan untuk menyempurnakan peralatan.
Zat misterius ini menciptakan ikatan yang lebih kuat antara barang dan pembawanya, tetapi harus disimpan dalam wadah khusus untuk mencegahnya menyebar.]],
  str_item_intro_3000100 = [[
Perangkat yang mampu mengeluarkan sinyal rekrutmen.
Dapat digunakan dalam rekrutmen untuk mendapatkan Aurorian.]],
  str_item_intro_3000101 = [[
Perangkat yang mampu mengeluarkan sinyal rekrutmen khusus.
Dapat digunakan dalam rekrutmen waktu terbatas untuk mendapatkan Aurorian.]],
  str_item_intro_3000110 = [[
Item rekrutmen Halloween eksklusif. Berfungsi untuk merekrut sepuluh kali dari kumpulan rekrutmen Halloween spesial.
Ini adalah item berbatas waktu. Setelah Special Halloween Recruitment berakhir, item ini akan dikonversi menjadi 3.000 Lumamber.]],
  str_item_intro_3000112 = "Item rekrutmen Natal eksklusif yang membuatmu bisa melakukan Rekrutmen ×10 dari Christmas Recruitment Pool. Ini adalah item terbatas dan akan diubah menjadi Lumamber ×3.000 setelah Rekrutmen Natal berakhir.",
  str_item_intro_3000113 = [[
Item rekrutmen eksklusif kolaborasi yang dapat digunakan dalam rekrutmen kolaborasi untuk merekrut 10 kali.
Item ini akan kedaluwarsa, jadi gunakan sebelum pukul 09.00, 26 Januari 2022 (UTC+0) atau akan hilang. Item tidak akan dikonversi menjadi item lain setelah kedaluwarsa.]],
  str_item_intro_3000114 = [[
Item rekrutmen eksklusif kolaborasi yang bisa digunakan dalam rekrutmen kolaborasi untuk merekrut 10 kali.
Harap gunakan item terbatas waktu ini sebelum 12 Februari 2022, 09.00 (UTC+0) atau item tersebut akan hilang. Item ini tidak akan diubah menjadi item lain.]],
  str_item_intro_3000343 = [[
