Item ini akan kedaluwarsa. Gunakan sebelum rekrutmen eksklusif Enlightened Illumination berakhir. Jika tidak, item ini akan hilang. Jika sudah kedaluwarsa, item ini tidak akan diubah menjadi item lain.]],
  str_item_intro_3000117 = [[
