Item dengan waktu terbatas, akan diubah menjadi 3.000 Lumamber di akhir Rekrutmen Spesial Festival Musim Semi.]],
  str_item_intro_3000126 = "Memungkinkan Anda merekrut sepuluh kali dari Perekrutan Khusus Pasukan Patroli. Item waktu terbatas, itu akan diubah menjadi 3.000 Lumamber di akhir Rekrutmen Khusus Pasukan Patroli.",
  str_item_intro_3000127 = [[
