Item ini akan kedaluwarsa, jadi harap gunakan sebelum perekrutan eksklusif Lustrous Soul berakhir, atau item ini akan hilang. Itu tidak akan dikonversi ke item lain saat kedaluwarsa.]],
  str_item_intro_3000128 = [[
Dapat digunakan untuk merekrut sepuluh kali dari rekrutmen eksklusif Lustrous Soul.
Item ini akan kedaluwarsa, jadi harap gunakan sebelum perekrutan eksklusif Lustrous Soul berakhir, atau item ini akan hilang. Itu tidak akan dikonversi ke item lain saat kedaluwarsa.]],
  str_item_intro_3000129 = [[
Memungkinkan Anda untuk merekrut sepuluh kali dari Rekrutmen Spesial Funfair.
Item berbatas waktu, akan dikonversi menjadi 3.000 Lumamber di akhir Rekrutmen Spesial Funfair.]],
  str_item_intro_3000133 = [[
Memungkinkan Anda merekrut sepuluh kali dari Rekrutmen Khusus Winter Ode.
Item dengan waktu terbatas, akan diubah menjadi 3.000 Lumamber di akhir Rekrutmen Khusus Winter Ode.]],
  str_item_intro_3000138 = [[
Memungkinkan Anda merekrut sepuluh kali dari Rekrutmen Spesial Festive.
Item dengan waktu terbatas, akan diubah menjadi 3.000 Lumamber di akhir Rekrutmen Spesial Festive.]],
  str_item_intro_3000201 = "Emblem kecil yang dibuat oleh beberapa anggota Rediesel Wrench dengan cara memodifikasi mur. Mereka yakin emblem ini melambangkan pengakuan gurun, sehingga hanya diberikan kepada mereka yang diakui oleh Rediesel Wrench.",
  str_item_intro_3000211 = "Voucher hadiah yang dapat ditukarkan dengan hadiah spesial di meja resepsionis Tir' Hotel. Konon, stempel di atasnya adalah potret manajer umum hotel itu.",
  str_item_intro_3000212 = "Setelah menyelesaikan quest di Special Event Book, kamu akan mendapatkan sejumlah Poin Kontribusi Umbraton yang dapat digunakan untuk membuka Reward. Umbraton selalu bangga pada petualang yang berani bermimpi.",
  str_item_intro_3000213 = "Poin Aksi: Digunakan untuk menantang stage event tertentu. Poin Aksi secara otomatis pulih seiring waktu.",
  str_item_intro_3000214 = [[
Makanan khusus yang dikeluarkan oleh Courier Union untuk melengkapi energi para kurirnya yang bekerja keras. 
Rasa dari tiap bungkusan masih misteri sebelum dibuka... Silakan dicoba kapan-kapan.]],
  str_item_intro_3000215 = "Progres Remodeling (tidak ada detail untuk saat ini)",
  str_item_intro_3000217 = "Merit: Manifestasi fisik dari pencapaian militer seseorang dan melambangkan kontribusi seorang prajurit kepada Illumina Federation.",
  str_item_intro_3000219 = "Tahan rasa sakit dari pertempuran dan buktikan kekuatanmu melalui keringat dan darah di Underground Arena! Biarkan namamu yang mulia bergema di seantero Umbraton!",
  str_item_intro_3000202 = [[
Item event. Dapat digunakan dalam event undian Daruma Smash. Kumpulkan dalam jumlah tertentu untuk membuka cerita eksklusif Hiiro.
Cloud Blossom Petal yang jatuh merupakan ciri khas Cloud Mountain. Penduduk Cloud Mountain percaya bahwa itu membawa keberuntungan.]],
  str_item_intro_3000224 = "Item event Aurora Aeterna. Kumpulkan dalam jumlah tertentu untuk meraih reward Scala Gloriari.",
  str_item_intro_3000225 = [[
Item Dragon Maid's Break yang digunakan untuk pengundian hadiah di Dapur Tohru.
Makanan panasnya hampir siap, ambil piringmu!]],
  str_item_intro_3000226 = "Minuman yang tidak biasa di Astra dan terasa menyegarkan saat diminum.",
  str_item_intro_3000227 = "Koin yang terlihat kuno, sangat berbeda dengan koin yang kita lihat sekarang.",
  str_item_intro_3000229 = "Benda yang menjadi tanda kehormatan bagi penjelajah dan petualang ini biasanya didapat melalui upaya yang sangat sulit atau dengan mengatasi kesulitan besar.",
  str_item_intro_3000236 = "Poin yang dihadiahkan setelah menyelesaikan tantangan. Setiap tingkat kesulitan memberikan jumlah yang berbeda.",
  str_item_intro_3000238 = "Selama festival, penduduk Cloud Island menulis ucapan penuh berkah di kertas ini untuk mengharapkan kebahagiaan di tahun itu.",
  str_item_intro_3000239 = "Makanan pokok yang populer di Far East, terlihat menarik dan mudah dibawa. Biasanya disajikan dengan lauk pauk.",
  str_item_intro_3000240 = [[
Item Fluffy Serendipity's Wishing Mirror eksklusif. Memungkinkanmu membuat permintaan di Fluffy Serendipity's Wishing Mirror.
Ini adalah item waktu terbatas. Setelah Fluffy Serendipity's Wishing Mirror berakhir, item ini akan diubah menjadi 100 Lumamber.]],
  str_item_intro_3000241 = "Koin perak ini adalah mata uang utama di Cloud Island.",
  str_item_intro_3000242 = "Selembar kartu yang berisi catatan performa setiap kontestan dan dibubuhi tanda tangan setiap petugas titik periksa.",
  str_item_intro_3000244 = "Benda ini memiliki kekuatan aneh yang mampu membuat orang yang terjerat perangkap bisa bergerak bebas, bahkan melepaskan diri dari perangkap…",
  str_item_intro_3000245 = "Produk yang konon disebut sebagai fragmen jiwa di Warp. Sejumlah orang menunjukkan ketertarikan pada benda ini.",
  str_item_intro_3000246 = "Informasi yang diperoleh melalui penghitungan dan evaluasi yang komprehensif. Bisa digunakan untuk menentukan denah perimeter pencarian.",
  str_item_intro_3000247 = "Normal Signal yang terdeteksi oleh Portable Detector",
  str_item_intro_3000248 = "Special Signal yang terdeteksi oleh Portable Detector",
  str_item_intro_3000253 = "Tiket yang diterbitkan oleh Andersen Association yang dulunya sangat berkuasa. Kamu mungkin bisa menukarnya dengan sesuatu jika ada orang yang mau menyetujuinya.",
  str_item_intro_3000256 = "Poin diperlukan untuk menyerang tempat persembunyian bandit. Keluarkan mereka dan terus maju!",
  str_item_intro_3000258 = "Coretan berita, anekdot, dan gosip. Jika Anda ingin mengetahui keseluruhan cerita, ikuti saja gambar dan cari sendiri.",
  str_item_intro_3000259 = "Di Harbour Fair setiap tahun, Harbour City mengeluarkan koin khusus, yang dapat digunakan sebagai pengganti uang di Street Fair, kepada semua warganya.",
  str_item_intro_3000266 = [[
Akuarium baru! Peralatan dan makhluk air, semuanya lengkap. Akuarium ini juga masih sepi pengunjung! Kunjungi sekarang kalau kau melewatkannya!
Item eksklusif Day at the Aquarium yang bisa digunakan untuk membuat permintaan di akuarium. Item ini berbatas waktu. Saat event Day at the Aquarium berakhir, item ini akan dikonversi menjadi 100 Lumamber.]],
  str_item_intro_3000267 = "Normal Signal yang terdeteksi oleh Portable Detector",
  str_item_intro_3000268 = "Special Signal yang terdeteksi oleh Portable Detector",
  str_item_intro_3000270 = [[
Menurut seorang penyihir, jenis kartu yang tampak biasa ini memiliki kekuatan magis yang memungkinkannya untuk berubah menjadi banyak hal!
Diperoleh dengan mengkonsumsi Prism dan menyelesaikan stage selama event.]],
  str_item_intro_3000271 = [[
Selongsong peluru kosong yang dapat digunakan kembali yang dapat ditukar di Depot Pasokan dengan persediaan.
Diperoleh dengan menggunakan Prism untuk menghapus tahapan selama acara.]],
  str_item_intro_3000275 = [[
Tiket ini tidak hanya akan memberi Anda tontonan film terbaru aktor terkenal tertentu, tetapi juga wawancara langsung dengan mereka!
Item acara Under the Spotlight eksklusif yang dapat digunakan untuk membuat keinginan. Item dengan waktu terbatas ini akan diubah menjadi 100 Lumamber saat event Under the Spotlight berakhir.]],
  str_item_intro_3000276 = "Alat peraga berbentuk koin yang dibuat oleh Nina untuk menambah suasana seram rumah hantu tersebut. Dapat digunakan untuk bertukar souvenir.",
  str_item_intro_3000278 = [[
Bagian yang telah berserakan di semua tempat. Mungkin mereka akan berguna!
Diperoleh dengan menggunakan Prism untuk menyelesaikan stage selama event.]],
  str_item_intro_3000280 = [[
Item tayangan ulang Fluffy Serendipity Eksklusif. Lihatlah ke cermin untuk membuat keinginan.
Ini adalah item waktu terbatas. Ketika pemutaran ulang Fluffy Serendipity - Wishing Mirror berakhir, item ini akan diubah menjadi 100 Lumamber.]],
  str_item_intro_3000281 = "Disebut-sebut sebagai karya sutradara jenius, legenda mengatakan bahwa dia tertawa terbahak-bahak menonton filmnya yang sudah selesai untuk pertama kalinya hingga dia meninggal.",
  str_item_intro_3000282 = "Tampaknya menjadi naskah untuk petualangan fantasi. Sementara beberapa bagian cukup romantis dan imajinatif, yang lain terlalu klise.",
  str_item_intro_3000283 = "Naskah ini sepertinya merupakan adaptasi dari kisah nyata. Namun, karena tidak ada yang tahu nasib akhir dari protagonis asli, akhir cerita sepenuhnya diserahkan kepada interpretasi artistik penulis.",
  str_item_intro_3000284 = "Sebuah naskah yang Jomu secara misterius menyelinap ke tangan Anda. Dia menyebutkan sesuatu tentang kompensasi yang besar sekali \"semuanya dikatakan dan dilakukan.\"",
  str_item_intro_3000285 = "Sebuah skrip yang diberikan kepadamu oleh Lilica. Percaya bahwa Anda memiliki potensi penyutradaraan, dia mempercayakan Anda dengan tugas merekam video promosi untuk itu.",
  str_item_intro_3000286 = "Sebuah skrip yang diberikan kepadamu oleh Vivian. Menurutnya, ini adalah upaya terbaru Federasi Illumina untuk meningkatkan upaya perekrutannya.",
  str_item_intro_3000288 = [[
Sebuah buku catatan yang dipenuhi dengan ide yang kamu dan Bethlehem ciptakan saat menciptakan sebuah mimpi.
Item Pelukan Sweet Melody Eksklusif. Diperlukan untuk membuat keinginan selama Pelukan Sweet Melody. Ini adalah item waktu terbatas. Ketika Sweet Melody's Embrace berakhir, item ini akan diubah menjadi 100 Lumamber.]],
  str_item_intro_3000291 = "Catatan tentang hal-hal yang ditemukan selama perjalanan Anda. Dengan ini, Anda akan dapat mengingat banyak informasi penting bahkan setelah Anda kembali ke rumah.",
  str_item_intro_3000292 = "Bagaimana mungkin Anda melewatkan merchandise eksklusif untuk idola paling populer di seluruh benua?! Para oportunis pasti akan mencari uang cepat dari penggemar fanatik dengan barang dagangan spesial seperti itu.",
  str_item_intro_3000293 = "Barang tradisional Northland. Menjelang festival musim dingin, anak-anak menggantung stoking dari tempat tidur mereka dan menulis surat yang menyatakan apa yang paling mereka inginkan. Keesokan paginya, hadiah yang mereka inginkan muncul di stoking mereka! Adapun siapa yang menempatkan mereka di sana, siapa yang tahu?",
  str_item_intro_3000294 = "Kartu kosong ini sepertinya memiliki semacam kekuatan sihir. Legenda mengatakan jika Anda menulis keinginan Anda di atasnya, itu menjadi kenyataan. Meskipun sulit untuk mempercayai klaim yang keterlaluan seperti itu, siapa yang akan mengangkat hidung mereka pada kesempatan untuk menerima berkat seperti itu?",
  str_item_intro_3000297 = [[
Naskah yang diterima dari orang tak dikenal ini sepertinya mengandung cerita yang mendebarkan dan romantis,
tapi cerita di dalamnya sepertinya familiar untuk beberapa alasan...]],
  str_item_intro_3000298 = "Naskah yang diadaptasi dari kisah-kisah yang diceritakan di seluruh dunia. Anda akan menemukan cerita tentang segala macam bahaya dan hal-hal menyeramkan di sini.",
  str_item_intro_3000299 = [[
Salah satu buku cerita terpopuler di Cloud Island saat ini. Anda menerima ini dari orang misterius yang menyeberangi lautan.
Pada pandangan pertama, sepertinya cerita tentang pertarungan pedang dan kiamat yang akan datang...]],
  str_item_intro_3000300 = "Sebuah cek dari Lin Guild. Dapat diuangkan untuk barang-barang di The Docks, sesuai jumlah yang tertera di atas.",
  str_item_intro_3000307 = "Pecahan plester yang tampak aneh yang tampaknya telah jatuh dari sebuah patung. Mungkin ada beberapa petunjuk...",
  str_item_intro_3000311 = [[
Legenda mengatakan bahwa jika Anda bersulang sambil minum dari gelas yang megah ini, Anda akan tetap sadar sepanjang malam.
Item Eventide Mesmerizing Eksklusif. Gunakan itu selama acara untuk membuat permintaan! Ini adalah item dengan waktu terbatas, dan akan diubah menjadi 100 Lumamber saat event Mesmerizing Eventide berakhir.]],
  str_item_intro_3000313 = "Mata uang yang digunakan di Illumina Supply Center. Ini adalah satu-satunya bukti transportasi dan pengerahan perbekalan.",
  str_item_intro_3000321 = [[
Ini tampaknya merupakan pecahan kristal yang aneh, berisi tetesan air yang lebih aneh lagi.
Penggunaan: Anda dapat membeli item yang Anda inginkan di Ruang Ramalan.
Sumber: Selesaikan tahapan Main Story atau Resource Raid yang membutuhkan Prism.]],
  str_item_intro_3000326 = [[
Koin yang terlihat indah tapi entah bagaimana memancarkan aura berbahaya... Nah, Ms. Rot bilang itu bisa ditukar dengan sesuatu, jadi tidak apa-apa...
Sumber: Selesaikan Ms. Rot's Quest.]],
  str_item_intro_3000330 = "Apakah bunga yang terikat duri akan mekar atau tidak tergantung sepenuhnya pada bunga itu, bukan pada apa yang dunia pikirkan tentangnya. Item acara Eksklusif Blooming Firethorn. Bisa digunakan untuk membuat permintaan selama event Blooming Firethorn. Ini adalah item waktu terbatas, dan akan dikonversi menjadi 100 Lumamber saat event Blooming Firethorn berakhir.",
  str_item_intro_3000332 = "Pekerjaan telah menumpuk seperti gunung saat menjaga dari gangguan Eclipsites dan memantau gerakan di depan... Semua ini membuat Wrath: Proud Fervor tidak punya pilihan selain mengatur sumber daya manusia yang minim secara teliti untuk rekonstruksi sebagian dari Twilight.",
  str_item_intro_3000334 = "Pengakuan Barton Terhadap Taktik Wrath",
  str_item_intro_3000335 = "Pengakuan Hiiro Terhadap Taktik Wrath",
  str_item_intro_3000336 = "Pengakuan Vivian Terhadap Taktik Wrath",
  str_item_intro_3000337 = "Pengakuan Sharona Terhadap Taktik Wrath",
  str_item_intro_3000353 = "Keinginan Anda akan menjadi kenyataan suatu hari nanti.",
  str_item_intro_3000354 = "Kumpulkan sejumlah Kokon Divergen tertentu dan tukarkan mereka untuk hadiah di Pusat Penukaran.",
  str_item_intro_3000356 = "Dupa favorit di Kerajaan Ji, dirancang dengan teliti dengan aroma yang halus dan lembut.\n\"Saat dupa yang terbakar mengirim asap ke langit, orang-orang mengirim persembahan ke langit dan bumi—Chen'ni mengerti praktik budaya ini. Tetapi selalu ada beberapa hari setiap tahun ketika asapnya begitu tebal sehingga Chen'ni tidak bisa membuka matanya...\"",
  str_item_intro_3000361 = [[
Butuh banyak usaha hanya untuk mengumpulkan dan menyortir data yang telah berantakan karena kerusakan.
Tahap pemulihan foto baru terbuka setelah sejumlah tertentu dikonsumsi.]],
  str_item_intro_3000366 = "Item penting untuk membuat pact dengan Aurorian tertentu.",
  str_item_intro_3000367 = "Sebuah lolipop spesial dari Umbraton yang secara acak mengubah rasa, memberikan kejutan tanpa henti. Di tengah kekurangan di gurun, nilai permen ini setara dengan emas.",
  str_item_intro_3000368 = [[
Sebuah paket persediaan yang telah disiapkan untuk semua Navigator yang bekerja keras.
Semua usaha dan perkembanganmu akan dicatat dan dihargai.]],
  str_item_intro_3000374 = "Sebuah token permainan yang tampak nostalgia dan kasar saat disentuh. Dikatakan bahwa pemain terbaik hanya perlu satu token untuk bermain sepanjang malam.",
  str_item_intro_3000376 = "Dapat ditukar dengan voucher komoditas harian di Kota Gannon. Mereka yang telah memberikan kontribusi khusus kepada Illumina juga dapat menggunakannya untuk mengajukan item kustom pribadi.",
  str_item_intro_3000377 = "Seperti legenda yang beredar, darah sang santo tidak pernah mengalir sia-sia tetapi tetap abadi, seperti amber. Menawarkannya kepada Truth adalah seperti menunjukkan pengabdian kepada Lord.",
  str_item_intro_3000381 = "Bangun dari mimpi besar, embun yang mengental di antara daun-daun menghilang dalam sekejap seperti mimpi indah yang tidak bisa kamu kembali ke dalamnya. Tawarkan itu kepada naga fatamorgana dalam mimpi untuk kemungkinan mendapatkan hadiah.",
  str_item_intro_3000383 = "Magi Windelion menjadi hidup dengan kertas berwarna Eraveil. Teksturnya yang lembut dan tahan lama sangat cocok untuk membuat hiasan unik atau boneka Windelion. Ini adalah wadah untuk kenangan yang disayangi dan percikan untuk impian yang akan datang.",
  str_item_intro_3100001 = [[
Digunakan untuk menaikkan level Aurorian, +50% EXP untuk Forest Aurorian.
Jasper hijau. Bermeditasilah dengannya untuk mengingat memori tentang pertempuran dan memperoleh sedikit EXP.]],
  str_item_intro_3100002 = [[
Dipakai untuk menaikkan level Aurorian, +50% EXP untuk Forest Aurorian.
Jasper hijau. Gunakan untuk mengulang adegan pertempuran di pikiranmu dan memperoleh cukup banyak EXP.]],
  str_item_intro_3100003 = [[
Digunakan untuk menaikkan level Aurorian, +50% EXP untuk Forest Aurorian.
Jasper hijau yang sangat berharga. Gunakan untuk membangkitkan pertempuran masa lalu dan memperoleh EXP besar.]],
  str_item_intro_3100004 = [[
Digunakan untuk menaikkan level Aurorian, +50% EXP untuk Water Aurorian.
Jasper biru. Bermeditasilah dengannya untuk mengingat memori tentang pertempuran dan memperoleh sedikit EXP.]],
  str_item_intro_3100005 = [[
