Jasper merah. Bermeditasilah dengannya untuk mengingat memori tentang pertempuran dan memperoleh sedikit EXP.]],
  str_item_intro_3100011 = [[
Digunakan untuk menaikkan level Aurorian, +50% EXP untuk Fire Aurorian.
Jasper merah yang berharga. Gunakan untuk mengulang adegan pertempuran di pikiranmu dan memperoleh cukup banyak EXP.]],
  str_item_intro_3100012 = [[
Digunakan untuk menaikkan level Aurorian, +50% EXP untuk Fire Aurorian.
Jasper merah yang sangat berharga. Gunakan untuk membangkitkan pertempuran masa lalu dan memperoleh EXP besar.]],
  str_item_intro_3100013 = [[
Digunakan untuk menaikkan level Aurorian.
Jasper putih keabu-abuan dengan energi spesial. Semua Aurorian bisa menggunakannya untuk memperoleh sedikit EXP.]],
  str_item_intro_3100014 = [[
Digunakan untuk menaikkan level Aurorian.
Jasper biru keabu-abuan yang lebih berharga. Semua Aurorian bisa menggunakannya untuk mengulang adegan pertempuran di pikiran dan memperoleh cukup banyak EXP.]],
  str_item_intro_3100015 = [[
Digunakan untuk menaikkan level Aurorian.
Jasper putih keabu-abuan yang sangat langka. Semua Aurorian bisa menggunakannya untuk membangkitkan pertempuran masa lalu dan memperoleh EXP besar.]],
  str_item_intro_3210101 = [[
Basic Ascension Material yang digunakan untuk Ascension bagi Aurorian dari Lumopolis.
Tersimpan di Dawn Academy of Lumopolis dan diperkaya dengan sihir unik, bisa menambah kekuatan Aurorian.]],
  str_item_intro_3210201 = [[
Basic Ascension Material yang digunakan untuk Ascension bagi Aurorian dari Umbraton.
Anggur persembahan spesial yang trendi di Umbraton. Kuat dan halus, bisa menambah kekuatan peminumnya.]],
  str_item_intro_3210301 = [[
Basic Ascension Material yang digunakan untuk Ascension bagi Aurorian dari Northland.
Embun pinus kental yang menyerap elemen unik Northland untuk memberi kekuatan besar kepada penduduk Northland.]],
  str_item_intro_3210401 = [[
Basic Ascension Material yang digunakan untuk Ascension bagi Aurorian dari Rediesel Wrench.
Hanya anggota Rediesel Wrench yang kuat yang berani mencoba Rediesel spesial dengan rasa sangat tajam ini.]],
  str_item_intro_3210501 = [[
Basic Ascension Material yang digunakan untuk Ascension bagi Aurorian di Illumina Federation.
Battle Archive dari Illumina Federation yang menambah skill tempur pembaca.]],
  str_item_intro_3210601 = [[
Basic Ascension Material yang digunakan untuk Ascension bagi Aurorian dari True Order.
Perkamen berisi pengetahuan kuno. Anggota True Order bisa meningkatkan diri mereka dengan cara menafsirkannya.]],
  str_item_intro_3210701 = [[
Basic Ascension Material yang digunakan untuk Ascension bagi Independent Aurorian.
Kisah dari banyak orang dari berbagai latar belakang dengan jargon membingungkan. Pembaca lepas akan mempelajari banyak trik bertahan hidup.]],
  str_item_intro_3210801 = [[
Basic Ascension Material yang digunakan untuk Ascension bagi Aurorian dari Longzhou.
Diproduksi oleh Longzhou Apothecary, pil unggulan ini meningkatkan kekuatan fisik serta menguatkan tulang dan otot.]],
  str_item_intro_3210102 = [[
Regular Ascension Material yang digunakan untuk Ascension bagi Aurorian dari Lumopolis.
Disimpan di Dawn Academy of Lumopolis, konon terbuat dari kekuatan cahaya pagi dan bisa sangat meningkatkan kekuatan Aurorian.]],
  str_item_intro_3210202 = [[
Regular Ascension Material yang digunakan untuk Ascension bagi Aurorian dari Umbraton.
Versi penyempurnaan dari Destiny Champagne I. Lebih kuat dan lebih lembut untuk membuat kekuatan meningkat jauh lebih besar lagi.]],
  str_item_intro_3210302 = [[
Regular Ascension Material yang digunakan untuk Ascension bagi Aurorian dari Northland.
Pine frost pekat yang tidak banyak ditemukan. Salah satu sumber penting bagi sihir Northland.]],
  str_item_intro_3210402 = [[
Regular Ascension Material yang digunakan untuk Ascension bagi Aurorian dari Rediesel Wrench.
Biasanya hanya ditemukan di pusat Rediesel Desert, material ini menambah kemampuan bertarung anggota Rediesel Wrench.]],
  str_item_intro_3210502 = [[
Regular Ascension Material yang digunakan untuk Ascension bagi Aurorian dari Illumina Federation.
Battle Archive Illumina Federation yang disusun dengan info penting bisa sangat menambah combat skill pembacanya.]],
  str_item_intro_3210602 = [[
Regular Ascension Material yang digunakan untuk Ascension bagi Aurorian dari True Order.
Buku ini berisi pengetahuan kuno yang penting. Anggota True Order bisa lebih meningkatkan diri mereka dengan cara menafsirkannya.]],
  str_item_intro_3210702 = [[
Regular Ascension Material yang digunakan untuk Ascension bagi Independent Aurorian.
Tips dari banyak orang dari berbagai latar belakang untuk diterapkan oleh para pembaca lepas.]],
  str_item_intro_3210802 = [[
Regular Ascension Material yang digunakan untuk Ascension bagi Aurorian dari Longzhou.
Pil ini disempurnakan oleh para kultivator Longzhou dengan bahan-bahan spiritual dan dikatakan memiliki efek membersihkan sumsum tulang dalam tubuh seseorang.]],
  str_item_intro_3210103 = [[
Advanced Ascension Material yang dibutuhkan untuk Ascension bagi Aurorian dari Lumopolis.
Tersimpan di Dawn Academy of Lumopolis dan diperkaya dengan sihir unik, bisa menaikkan level kekuatan Aurorian.]],
  str_item_intro_3210203 = [[
Advanced Ascension Material yang dibutuhkan untuk Ascension bagi Aurorian dari Umbraton.
