  str_item_intro_3220000 = [[
Punya tujuan khusus dalam Aurorian Breakthrough.
Permata langka dengan energi tak dikenal yang menyalurkan kekuatan khusus di tangan beberapa Aurorian yang potensinya bisa terbuka dengan cara menguasai permata ini.]],
  str_item_intro_3220001 = [[
Benda Breakthrough yang penting bagi Nikinis.
Permata unik yang menyerupai cermin. Jika diamati dengan cermat, kamu bisa melihat bayangan seorang wanita berpakaian putih.]],
  str_item_intro_3220002 = [[
Benda Breakthrough yang penting bagi Hiiro.
Permata yang sangat berharga ini terkadang menampilkan gambar naga merah mencolok.]],
  str_item_intro_3220004 = [[
Benda Breakthrough yang penting bagi Kuma & Pengy.
Permata ini mengeluarkan hawa dingin saat Kuma dan Pengy memakainya, karena itulah permata ini menjadi kesukaan mereka.]],
  str_item_intro_3220005 = [[
Benda Breakthrough yang penting bagi Mia.
Sisi lain diri Mia sepertinya terjebak di dalam permata ini... Mungkin ini bisa jadi petunjuk tentang jati dirinya yang sesungguhnya.]],
  str_item_intro_3220006 = [[
Benda Breakthrough yang penting untuk Carleen.
Permata ini terkadang memancarkan bentuk tombak cahaya yang suram dan pucat.]],
  str_item_intro_3220009 = [[
Benda Breakthrough yang penting bagi Faust.
Permata dengan pola aneh dan janggal yang membuat orang panik, tetapi Faust tidak menyerah dan justru tertarik padanya.]],
  str_item_intro_3220010 = [[
Benda Breakthrough yang penting bagi Louise.
Permata unik dan cerah yang konon mendorong Louise Carlisle untuk menulis banyak cerita.]],
  str_item_intro_3220011 = [[
Benda Breakthrough yang penting bagi Sharona.
Amati dari dekat agar bisa melihat siluet kabur naga raksasa yang sedang melayang.]],
  str_item_intro_3220012 = [[
Benda Breakthrough yang penting bagi Nemesis.
Permata keras dengan potongan sempurna dan kekuatan luar biasa.]],
  str_item_intro_3220013 = [[
Benda Breakthrough yang penting bagi Noah.
Sangat dingin ketika disentuh tanpa menyebabkan radang dingin atau damage apa pun. Kesukaan Noah.]],
  str_item_intro_3220014 = [[
Benda Breakthrough yang penting untuk Schwartz.
Batu permata putih yang berkilau terang. Schwartz merasa batu ini tidak hanya melambangkan dirinya, tapi juga Lumopolis.]],
  str_item_intro_3220015 = [[
Hachi & Gin dapat melihat banyak pemandangan berbeda di dalam permata ini dan mendapatkan inspirasi artistik yang luar biasa darinya.
Benda Breakthrough yang penting untuk Hachi & Gin.]],
  str_item_intro_3220016 = [[
Benda Breakthrough yang penting bagi Kafka.
Permata yang sangat keras, kabarnya telah melindungi seseorang dari serangan mematikan.]],
  str_item_intro_3220017 = [[
Benda Breakthrough yang penting bagi Rabbie.
Saat diamati dengan cermat, akan tampak api yang terus melompat menyerupai kelinci. Jimat keberuntungan Rabbie.]],
  str_item_intro_3220018 = [[
Benda Breakthrough yang penting bagi Regina.
Permata mirip matahari yang menerangi sudut tergelap sekalipun, serta menambah kualitas musik Regina.]],
  str_item_intro_3220019 = [[
Benda Breakthrough yang penting bagi Victoria.
Permata ini berisi banyak partikel berbentuk air mata, konon merupakan darah Victoria sendiri.]],
  str_item_intro_3220021 = [[
Benda Breakthrough yang penting bagi Jola.
Ketika Jola menyentuh permata ini, riak hijau berbentuk rantai akan tampak menari-nari di tepiannya.]],
  str_item_intro_3220023 = [[
Benda Breakthrough yang penting untuk Connolly.
Hasil pengembunan tetesan air hitam yang berubah menjadi permata keras di tangan Connolly.]],
  str_item_intro_3220024 = [[
Benda Breakthrough yang penting untuk Benny dan Curo.
Permata ini berkilau dengan cahaya merah serta hitam, dan kamu bahkan bisa mendengar suara tebasan pedang serta peluru jika mendekatinya.]],
  str_item_intro_3220025 = [[
Benda Breakthrough yang penting untuk Charon.
Sebagai kesukaan Charon, permata ini berkilau dengan garis merah dan hitam.]],
  str_item_intro_3220026 = [[
Benda Breakthrough yang penting bagi Uriel.
Permata yang terkadang memancarkan api kecokelatan dan kehitaman. Sangat indah dilihat tapi juga terasa hampa...]],
  str_item_intro_3220027 = [[
Benda Breakthrough yang penting bagi Michael.
Permata yang konon ditemukan dalam badai petir yang hebat ini memberikan kekuatan besar kepada pemiliknya.]],
  str_item_intro_3220028 = [[
Benda Breakthrough yang penting bagi Raphael.
Permata transparan dengan kekuatan luar biasa. Saat Raphael memakainya, kemampuan Healing-nya akan bertambah.]],
  str_item_intro_3220029 = [[
