Permata ini memancarkan cahaya hijau yang indah ketika Gabriel mengaktifkannya.]],
  str_item_intro_3220030 = [[
Benda Breakthrough yang penting bagi Sinsa.
Permata ini selalu memancarkan panas yang kuat. Hanya Sinsa yang bisa memakainya.]],
  str_item_intro_3220033 = [[
Benda Breakthrough yang penting bagi Vice.
Permata ini berkerlip warna-warni menakjubkan setiap kali dilihat, seolah menampilkan kilasan masa lalu...]],
  str_item_intro_3220036 = [[
Benda Breakthrough yang penting bagi Hydrad.
Permata yang menakutkan. Namun Hydrad tidak takut dengannya, bahkan sering membual bahwa "Permata ini mirip denganku."]],
  str_item_intro_3220038 = [[
Benda Breakthrough yang penting bagi Gronru.
Kabarnya berisi banyak elemen buatan, jadi tidak mungkin item ini adalah buatan alam, melainkan sisa peradaban kuno.]],
  str_item_intro_3220040 = [[
Benda Breakthrough yang penting bagi Joanie Boom.
Lebih baik tidak bermain dengan permata yang mudah terbakar ini, demi keselamatan.]],
  str_item_intro_3220041 = [[
Benda Breakthrough yang penting bagi Ms. Blanc.
Permata dengan cahaya elegan yang membuat tenang saat dipandang. Sangat cocok untuk semua wanita anggun.]],
  str_item_intro_3220042 = [[
Benda Breakthrough yang penting untuk Barton.
Permata ini menyembunyikan titik api perang merah yang cuma bisa dilihat Barton. Atau mungkin itu adalah perwujudan hasrat terdalamnya.]],
  str_item_intro_3220044 = [[
