Permata yang cahayanya kuat. Aksesoris yang fantastis untuk pangkal pedang.]],
  str_item_intro_3220045 = [[
Benda Breakthrough yang penting bagi Nails.
Beberapa orang menyebut pinggiran permata yang sangat tajam ini merupakan perlambang hukuman...]],
  str_item_intro_3220046 = [[
