Banyak "puisi" akan muncul di benak para anggota Keating saat mereka memakai permata ini.]],
  str_item_intro_3220048 = [[
Benda Breakthrough yang penting bagi Dayna.
Dayna bisa mempelajari banyak skill bertarung dengan permata ini.]],
  str_item_intro_3220054 = [[
Benda Breakthrough yang penting untuk Nadine.
Permata putih yang selalu memancarkan kilau lembut dan menenangkan.]],
  str_item_intro_3220055 = [[
Pittman sering mendapati dirinya tersesat di jalan menuju kebenaran, tetapi kristal ini memberinya kekuatan dan keteguhan hati.
Benda Breakthrough yang penting bagi Pittman.]],
  str_item_intro_3220056 = [[
Benda Breakthrough yang penting untuk Constantine.
Permata ini otomatis merekam semuanya ketika Constantine memburu para Eclipsite, dan item ini pun menjadi mitra terbaik Constantine.]],
  str_item_intro_3220057 = [[
Benda Breakthrough yang penting bagi Philyshy.
Kristal ini terkadang melepaskan napas kegelapan kepada seseorang agar bisa melihat sifat Philyshy yang sesungguhnya dari dekat.]],
  str_item_intro_3220060 = [[
Benda Breakthrough yang penting bagi Jona.
Alas kristal ini, yang terbuat dari perunggu yang dilelehkan, ditempa dari peluru Jona dan memamerkan kemenangannya pada masa lalu.]],
  str_item_intro_3220061 = [[
Benda Breakthrough yang penting untuk Chandra.
Setelah pemeriksaan cermat, di dalam permata transparan ini ada putaran energi yang menari, seolah berisi berbagai emosi yang dikumpulkannya.]],
  str_item_intro_3220062 = [[
Benda Breakthrough yang penting bagi Sylva.
Konon, permata ini ditemukan di kedalaman Windward Forest. Rasanya dingin saat disentuh dan melambangkan Sylva the Forest Keeper.]],
  str_item_intro_3220064 = [[
Benda Breakthrough yang penting bagi Wrath.
Permata besar dan kuat ini menjadi ringan di tangan Wrath, bahkan hingga bisa melayang di udara...]],
  str_item_intro_3220065 = [[
Ketika Tweety menatap ke dalam kristal ini, dia bisa melihat bayangan samar 
dari kampung halamannya, Cloud Mountain...
Objek Breakthrough penting untuk Tweety.]],
  str_item_intro_3220067 = [[
Benda Breakthrough yang penting untuk Alice.
Permata ini berubah menjadi bentuk hati dan mengeluarkan kekuatan istimewa saat Alice memegangnya.]],
  str_item_intro_3220068 = [[
Benda Breakthrough yang penting bagi Wendy
Permata yang sangat ringan ini juga sangat keras, mencerminkan kepribadian Wendy.]],
  str_item_intro_3220070 = [[
Benda Breakthrough yang penting bagi Leona.
Tataplah kristal ini dan dengarlah raungan naga yang menggelegar di telingamu.]],
  str_item_intro_3220071 = [[
Benda Breakthrough yang penting bagi Taki.
Adegan naga raksasa yang menyemburkan api terkadang muncul di permata ini, yang melambangkan Taki karena hanya dialah yang memiliki permata ini.]],
  str_item_intro_3220073 = [[
Benda Breakthrough yang penting bagi Patty & Patsy.
Permata ini bergantian mengeluarkan kilau merah tua dan hawa kegelapan.]],
  str_item_intro_3220075 = [[
Benda Breakthrough yang penting bagi Odi.
Kamu bisa mendengar suara statis samar-samar ketika meletakkan permata ini ke telingamu. Mungkin bisa digunakan untuk berkomunikasi.]],
  str_item_intro_3220076 = [[
Benda Breakthrough yang penting bagi Kleken.
Permata luar biasa yang menampilkan berbagai warna dari berbagai sudut. Makin sering berubah-ubah jika dipegang oleh Kleken.]],
  str_item_intro_3220077 = [[
Benda Breakthrough yang penting untuk Bethlehem.
Bening dan sangat dingin ketika disentuh. Konon, item ini berevolusi dari balok es pertama dalam sejarah, dan hanya Queen of the North yang bisa memakainya.]],
  str_item_intro_3220078 = [[
Benda Breakthrough yang penting bagi Robyn.
Permata hijau zamrud yang konon bisa menangkal semua benda beracun demi pemakainya. Jimat Robyn.]],
  str_item_intro_3220079 = [[
Benda Breakthrough yang penting bagi Michenny.
Permata bujur sangkar tanpa cela dan seimbang, cocok untuk menjaga keseimbangan neraca.]],
  str_item_intro_3220081 = [[
Benda Breakthrough yang penting untuk Brock.
Permata ini terasa sangat panas ketika disentuh, mencerminkan semangat abadi seseorang.]],
  str_item_intro_3220083 = [[
Benda Breakthrough yang penting bagi Lilliam.
Saat permata ini mendekati pemilik sejatinya, permata ini akan mengeluarkan pola listrik.]],
  str_item_intro_3220084 = [[
Benda Breakthrough yang penting bagi Istvan.
Api biru terkadang menari di sekitar tepi permata ini. Jika kamu mendekat, kamu akan mendengarnya memanggil Shadowlord.]],
  str_item_intro_3220085 = [[
Benda Breakthrough yang penting bagi Jane.
Tataplah permata hitam ini cukup lama, maka kamu akan melihat tulisan untuk catatan...]],
  str_item_intro_3220086 = [[
Benda Breakthrough yang penting bagi Uriah.
Giok putih dan anggun ini berbentuk bunga.]],
  str_item_intro_3220087 = [[
Benda Breakthrough yang penting untuk Beverly.
Petir berbentuk tombak yang tampak seperti Lightning Spear milik Beverly sesekali berkedip dalam permata ini.]],
  str_item_intro_3220088 = [[
Benda Breakthrough yang penting bagi Maggie.
Kristal ini terkadang memancarkan kilau kuning yang aneh. Periksalah dengan teliti, maka kamu bisa melihat siluet seorang gadis.]],
  str_item_intro_3220089 = [[
Benda Breakthrough yang penting bagi Irridon.
Permata ini terkadang memancarkan petir biru dan punya kekuatan besar.]],
  str_item_intro_3220090 = [[
Benda Breakthrough yang penting untuk Barbara.
Dekatkan permata ini dengan alas berwarna merah, maka kamu akan mendengar nada-nada berisik mengalun.]],
  str_item_intro_3220091 = [[
Benda Breakthrough yang penting untuk Chloe.
Kristal putih ini sepertinya membentuk embun mirip air mata. Dekatilah, maka kamu akan mendengar suara harpa mengalun lirih.]],
  str_item_intro_3220092 = [[
Benda Breakthrough yang penting bagi Pact.
Permata ini luar biasa keras, dan konon tidak pernah tergores.]],
  str_item_intro_3220093 = [[
Benda Breakthrough yang penting bagi Migard.
Permata yang menyimpan energi misterius ini sepertinya diekstrak dari suatu makhluk buatan.]],
  str_item_intro_3220095 = [[
Benda Breakthrough yang penting bagi Lester.
Jika kamu mengendus permata ini, kamu akan merasa seperti berada di suatu tempat di padang belantara. Lester bisa memakainya untuk menemukan bau yang disukainya.]],
  str_item_intro_3220096 = [[
Benda Breakthrough yang penting bagi Sariel.
Ketika Sariel menggenggamnya, permata ini akan berubah bentuk menjadi tetesan air. Permata ini juga memberikan kekuatan besar kepada Sariel.]],
  str_item_intro_3220097 = [[
Benda Breakthrough yang penting untuk Corax.
Permata ini terasa sedingin es dan pinggirannya sangat tajam. Bisa dipakai untuk menggantikan pisau.]],
  str_item_intro_3220098 = [[
Benda Breakthrough yang penting untuk Cuscuta.
Jika kamu mengamati permata ini dengan teliti, kamu akan melihat bunga hitam layu di dalamnya.]],
  str_item_intro_3220099 = [[
Benda Breakthrough yang penting untuk Areia.
Kutukan yang menimpa Areia sepertinya melemah ketika dia melihat permata ini...]],
  str_item_intro_3220100 = [[
Benda Breakthrough yang penting bagi Sikare.
Langit berbintang tersembunyi di dalam permata ini. Ada yang bilang itu sumber kekuatan Sikare yang sesungguhnya.]],
  str_item_intro_3220101 = [[
Benda Breakthrough yang penting untuk Ansia.
berkilau memikat seperti kuningan, dan bergetar lembut. Getaran ini hampir menyamai frekuensi suara dari gelombang suara tertentu...]],
  str_item_intro_3220102 = [[
Benda Breakthrough yang penting bagi Tessa.
Sebaran petir selalu berkedip-kedip dalam permata ini dan menyambar saat didekati orang. Hanya Tessa yang bisa memegangnya.]],
  str_item_intro_3220103 = [[
Benda Breakthrough yang penting bagi Eicy.
Jika kamu menatap permata ini, kamu akan melihat sinar menakutkan yang terpancar darinya...]],
  str_item_intro_3220104 = [[
Benda Breakthrough yang penting untuk Dawn.
Permata ini dimiliki Dawn karena memantulkan bayangan bunga putih saat dia memegangnya, dan bunga ini adalah makanan spiritualnya.]],
  str_item_intro_3220105 = [[
Benda Breakthrough yang penting bagi Eve.
Busur petir yang kecil muncul di sekitar permata ini saat Eve menyentuhnya. Inilah kekuatan spesial Eve.]],
  str_item_intro_3220107 = "Regal Solamber",
  str_item_intro_3220108 = "Frostfire Solamber",
  str_item_intro_3220109 = "Mythos Solamber",
  str_item_intro_3220110 = "Requiem Solamber",
  str_item_intro_3220111 = [[
Benda Breakthrough yang penting untuk Beryl.
Warna kristal ini berubah menjadi merah darah di tangan Beryl sehingga menjadi identik dengan kristal-kristal di tubuhnya.]],
  str_item_intro_3220112 = [[
Benda Breakthrough yang penting untuk Smokey.
Permata ini kelihatannya selalu membuat benda yang mudah terbakar di sekitarnya terbakar secara misterius. Kekuatan aneh ini hanya memudar ketika berada di tangan Smokey.]],
  str_item_intro_3220113 = [[
Benda Breakthrough yang penting untuk Bonacie.
Saat Bonacie menyentuh permata ini, dia akan sangat terinspirasi sehingga dapat mencetuskan gerakan baru dan tak terlupakan.]],
  str_item_intro_3220114 = [[
Benda Breakthrough yang penting untuk Genevieve.
Permata yang selalu bersinar dalam warna merah bak api yang menyala-nyala ini terkadang mengeluarkan suara meringkik...]],
  str_item_intro_3220115 = [[
Ketika dia memakai kristal ini, Naroxel dapat mendengar suara alam dengan sangat jelas, meningkatkan kemampuannya untuk berkomunikasi dengan hewan dan tumbuhan.
Objek Breakthrough penting untuk Naroxel.]],
  str_item_intro_3220116 = [[
Benda Breakthrough yang penting untuk Fleur.
Permata ini bisa memberi Fleur banyak inspirasi cetak biru sehingga "Rencana Pembuatan Mecha"-nya mulai terwujud.]],
  str_item_intro_3220117 = [[
Saat Gram menggenggam benda ini dengan tangannya, dia merasa seolah-olah telah dibawa kembali ke masa-masa bersama Stone Forces, dan hatinya terasa sesak oleh emosi.
Benda Breakthrough yang penting Gram.]],
  str_item_intro_3220119 = [[
Saat Revy menyentuh permata ini, kamu bisa mendengar suara pedang raksasanya yang bergesekan dengan rantainya, dan bisa merasakan semburan aliran listrik.
Benda Breakthrough yang penting untuk Revy.]],
  str_item_intro_3220120 = [[
Di bawah sinar mentari, permata ini memancarkan kilau yang mirip dengan baju besi putih yang megah.
Benda Breakthrough yang penting untuk Hedy.]],
  str_item_intro_3220121 = [[
Permata ini sesekali memperlihatkan sosok wanita muda berambut pendek 
yang tidak lagi dikenali Paloma...
Objek Breakthrough penting untuk Paloma.]],
  str_item_intro_3220122 = [[
Allura bisa mendengar suara detik jam saat meletakkan permata ini di telinganya sehingga dia bisa menggunakan penguasaannya dari waktu ke waktu secara lebih akurat.
Benda Breakthrough yang penting untuk Allura.]],
  str_item_intro_3220123 = [[
Dengan permata ini, Cordy dapat menangani keadaan darurat dengan mudah.
Benda Breakthrough yang penting untuk Cordy.]],
  str_item_intro_3220126 = [[
Kristal ini bisa ditempelkan pada permata di depan dada Bethel dan meningkatkan kilau cemerlangnya.
Benda Breakthrough yang penting bagi Bethel.]],
  str_item_intro_3220127 = [[
Benda Breakthrough yang penting untuk Pasolo.
Di tangan Pasolo, kristal ini menjadi sangat tipis dan ringan, dan bisa menari-nari di udara bagaikan secarik kertas yang ditiup angin.]],
  str_item_intro_3220129 = [[
Saking ringannya kristal ini, Luke bahkan bisa membuatnya melayang di udara dan menari bagaikan seekor kupu-kupu.
Benda Breakthrough yang penting bagi Luke.]],
  str_item_intro_3220131 = [[
Permukaan permata yang diukir dengan kata-kata kuno, dan sepertinya hanya Novio yang mengerti artinya.
Benda Breakthrough yang penting untuk Novio.]],
  str_item_intro_3220132 = [[
Permata yang direndam dalam madu, bersinar berkilauan dan memancarkan aroma manis.
Benda Breakthrough yang penting untuk Lola.]],
  str_item_intro_3220133 = "Permata yang meledak menjadi sebuah cahaya berkobar setiap kali seseorang mendekat, kecuali Kobayashi, yang berubah menjadi merah muda lembut. Objek Breakthrough penting untuk Tohru.",
  str_item_intro_3220134 = [[
Permata yang sesekali memancarkan kilat, terasa lembut saat dipegang.
Objek Breakthrough penting untuk Kanna.]],
  str_item_intro_3220135 = [[
Arus hangat terus-menerus mengalir melalui permata ini. Pikiran yang lebih tenang bisa mendengar suara sungai yang menggelegak.
Objek Breakthrough penting untuk Elma.]],
  str_item_intro_3220136 = "Jika menatapnya cukup lama, kau akan melihat pemandangan seperti langit, laut, gunung, sungai, kota, sampai ke sepasang mata aneh yang melihat kembali padamu. Objek Breakthrough penting untuk Lucoa.",
  str_item_intro_3220137 = [[
Kamu bisa mendengar raungan yang mengganggu di permata ini, dengan mantra Fafnir yang tidak terdengar di antaranya.
Objek Breakthrough penting untuk Fafnir.]],
  str_item_intro_3220138 = [[
Kamu merasa seolah-olah bisa melihat benang hijau saat Siobhan memegangnya...
Benda Breakthrough yang penting untuk Siobhan.]],
  str_item_intro_3220139 = [[
Dekatkan permata ini ke telingamu dan dengarkan baik-baik, mungkin kamu bisa mendengar suara entitas misterius yang dipanggil.
Benda Breakthrough yang penting untuk Erica.]],
  str_item_intro_3220140 = [[
Permata yang digosok dengan hati-hati menggunakan aroma campuran perkamen dan tinta. Kamu hampir bisa mendengar dengungan bacaan dan doa.
Benda Breakthrough yang penting untuk Florine.]],
  str_item_intro_3220141 = [[
Permata sangat keras yang akan mengeluarkan suara tajam jika dipukul dengan tongkat. Sangat baik untuk latihan mengayun tongkat Ruby.
Penting untuk Breakthrough Ruby.]],
  str_item_intro_3220142 = [[
Permata yang tampak biasa dan bisa menghasilkan ilusi api yang berkobar di bawah sentuhan lembut Rouge.
Benda Breakthrough yang penting untuk Rouge.]],
  str_item_intro_3220143 = [[
Permata yang terkadang bersinar merah muda pucat dan mengeluarkan suara nan menyegarkan dan menyenangkan saat diguncang dengan lembut.
Item Breakthrough Rinne.]],
  str_item_intro_3220144 = [[
Permata yang tampak biasa, sejuk saat disentuh, dan memancarkan cahaya kecil dalam kegelapan.
Item Breakthrough Kayano.]],
  str_item_intro_3220145 = [[
Di tangan Amemori, batu permata ini menjadi lebih ringan, terkadang memancarkan kata "sabar."
Benda Breakthrough penting untuk Amemori.]],
  str_item_intro_3220146 = [[
Batu permata itu mengeluarkan aroma makanan, dan dari dekat tampak memantulkan warna merah menyala yang aneh.
Benda Breakthrough untuk Yao.]],
  str_item_intro_3220147 = [[
Batu permata berwarna-warni yang membuat orang berpikir bahwa itu lezat. Setelah diperiksa lebih dekat, ada dua lampu kembar bercahaya di dalamnya.
Benda Breakthrough untuk Momo&Anzu.]],
  str_item_intro_3220148 = [[
Batu permata ini dingin saat disentuh dan memantulkan cahaya biru redup saat terkena sinar matahari.
Benda Breakthrough yang penting bagi Azure.]],
  str_item_intro_3220149 = [[
Batu permata dengan tekstur halus yang tampak biasa saja. Terkadang, sosok berambut perak muncul di permukaannya. Sebelum kau sempat menyadari siapa sosok itu, Roy menyembunyikan batu permatanya. Yah, lagi pula, posturnya yang sangat tinggi membuat orang lain tak akan bisa merebut batu itu darinya.
Benda Breakthrough yang penting bagi Roy.]],
  str_item_intro_3220150 = [[
Entah mengapa, batu permata ini berdecit sepanjang waktu seolah-olah sedang diasah.
Item yang penting untuk Breakthrough Lenore.]],
  str_item_intro_3220151 = [[
Batu permata ini keras dan sangat panas. Giles dapat mengubah batu permata ini menjadi tanduk biri-biri secara ajaib hanya dengan menyentuhnya.
Item yang penting untuk Breakthrough Giles.]],
  str_item_intro_3220152 = [[
Genggaman May dapat memunculkan gambar kucing di permukaan batu permata ini. Terkadang, yang muncul adalah gambar Aurorian, tapi tak ada yang tahu dia siapa.
Item yang penting untuk Breakthrough May.]],
  str_item_intro_3220153 = [[
Dipoles dengan tangan oleh salah satu ahli permata Illumina yang paling dihormati, hanya mereka yang berada di posisi puncak Illumina Federation yang dapat menggunakannya.
Benda Breakthrough penting bagi Reinhardt.]],
  str_item_intro_3220154 = "Setiap kali Vice ada di dekatnya, permata ini mulai bergetar sedikit, bergantian memancarkan cahaya merah dan hijau.\nBenda Breakthrough penting bagi Vice: Keen Sight.",
  str_item_intro_3220187 = [[
Sebuah batu permata yang sedikit lengket mengeluarkan aroma manis dan lembut yang dapat tercium saat Anda mendekatinya. Li Tianxian selalu tersenyum puas setiap kali menggunakannya. Mungkin sebenarnya ini adalah batangan permen?
Objek Terobosan Penting untuk Li Tianxian.]],
  str_item_intro_3220188 = [[
Permata ini memiliki tekstur yang halus dan aroma bunga yang lembut. Jika diperhatikan lebih dekat, Anda akan menemukan pola-pola rumit yang membentuk bunga begonia.
Benda Breakthrough yang penting untuk Dantang.]],
  str_item_intro_3221000 = "Bisa ditukar dengan Aurorian Solamber eksklusif.",
  str_item_intro_3221001 = "Bisa ditukar dengan 5-Star Forest Aurorian Solamber non-eksklusif.",
  str_item_intro_3221002 = "Bisa ditukar dengan 5-Star Thunder Aurorian Solamber non-eksklusif.",
  str_item_intro_3221003 = "Bisa ditukar dengan 5-Star Fire Aurorian Solamber non-eksklusif.",
  str_item_intro_3221004 = "Bisa ditukar dengan 5-Star Water Aurorian Solamber non-eksklusif.",
  str_item_intro_3221005 = "Bisa ditukar dengan 6-Star Forest Aurorian Solamber non-eksklusif.",
  str_item_intro_3221006 = "Bisa ditukar dengan 6-Star Thunder Aurorian Solamber non-eksklusif.",
  str_item_intro_3221007 = "Bisa ditukar dengan 6-Star Fire Aurorian Solamber non-eksklusif.",
  str_item_intro_3221008 = "Bisa ditukar dengan 6-Star Water Aurorian Solamber non-eksklusif.",
  str_item_intro_5840001 = "Paket benih Unique Tree paling umum yang akan menghasilkan Unique Tree paling umum.",
  str_item_intro_5840002 = "Unique Tree Seedpack II untuk menumbuhkan Unique Tree II dengan sedikit mutasi.",
  str_item_intro_5840003 = "Unique Tree Seedpack III untuk menumbuhkan Unique Tree III dengan mutasi berulang kali.",
  str_item_intro_5840004 = "Unique Tree Seedpack IV untuk menumbuhkan Unique Tree IV dengan mutasi kompleks.",
  str_item_intro_3220155 = [[
Sebuah permata keras dan berat. Bayangan hitam besar sesekali terlihat berkedip di dalamnya, disertai sesuatu yang terdengar seperti geraman binatang buas.
Benda Breakthrough penting bagi Barton: Deft Blades.]],
  str_item_intro_3220156 = [[
Batu permata langka. Jika diamati dengan cermat, kamu akan menyadari bahwa kilauan cahayanya menari-nari, seakan menggambarkan tekad yang teguh.
Benda Breakthrough yang penting untuk Nina.]],
  str_item_intro_3220157 = [[
Permata yang tersusun dari material keras ini tak akan hancur meski dibanting dengan kencang. Bagaimana kami bisa tahu? Tanyakan saja pada Sanae.
Benda Breakthrough yang penting untuk Sanae.]],
  str_item_intro_3220158 = [[
Kebutuhan untuk terobosan Joker.
Permata dengan kilau cerah.
Itu mengandung rasa pemberontakan yang kuat.]],
  str_item_intro_3220159 = [[
Suatu keharusan untuk terobosan Queen.
Permata yang benar-benar tembus cahaya.
Itu mengandung rasa pemberontakan yang kuat.]],
  str_item_intro_3220160 = [[
Kebutuhan untuk terobosan Fox.
Permata yang hangat saat disentuh.
Itu mengandung rasa pemberontakan yang kuat.]],
  str_item_intro_3220161 = [[
Suatu keharusan untuk terobosan Violet.
Permata berbentuk bunga.
Itu mengandung rasa pemberontakan yang kuat.]],
  str_item_intro_3220162 = [[
Kebutuhan untuk terobosan Mona.
Goresan bantalan permata tampaknya dibuat oleh cakar yang tajam.
Itu mengandung rasa pemberontakan yang kuat.]],
  str_item_intro_3220164 = [[
Sepintas, permata ini tampak dipenuhi uap yang langsung berubah menjadi api, tetapi terlepas dari perubahan apa pun yang terjadi di dalam batu permata ini, kekokohannya tetap kokoh.
Objek Terobosan Esensial untuk Carleen: Smoldering Soul.]],
  str_item_intro_3220165 = [[
Ketika Ciel melihat kristal ini dari dekat, dia merasa seperti dia bisa melihat beberapa formula misterius yang memberinya aliran inspirasi yang stabil.
Objek Terobosan Penting untuk Ciel.]],
  str_item_intro_3220166 = [[
Permata ini bergetar hebat saat ada binatang ajaib di sekitar.
Benda Breakthrough penting bagi Fia.]],
  str_item_intro_3220167 = [[
Permata magis ini menciptakan ilusinya sendiri... Hati-hati, jangan sampai kau teperdaya.
Benda Breakthrough penting bagi Jeno.]],
  str_item_intro_3220168 = [[
Permata ini dingin jika disentuh. Terkadang, terdengar suara deburan ombak di dalamnya.
Benda Breakthrough penting bagi Rainbow.]],
  str_item_intro_3220169 = [[
Setiap kali dia memegang batu permata ini, Sadie merasakan keberanian yang luar biasa mengalir dari telapak tangannya ke seluruh tubuhnya. Bahkan detak jantungnya pun berubah!
Objek terobosan penting untuk Sadie.]],
  str_item_intro_3220170 = [[
Permata dengan aroma smoky yang kuat. Yang lebih menakjubkan adalah gambar pedang yang sesekali berkedip di permukaannya.
Objek Terobosan Penting untuk Pollux.]],
  str_item_intro_3220171 = [[
Ketika Anda mendengarkan permata yang luar biasa ini dari dekat, Anda dapat mendengar suara gagak dari dalam.
Objek Terobosan penting untuk Casta.]],
  str_item_intro_3220172 = [[
Jika Anda perhatikan dengan seksama, batu permata ini berkedip dan berkedip seperti momen terbesar dalam sejarah sinematik. Dengan itu, keterampilan Lilica dapat mencapai tingkat yang lebih tinggi lagi!
Objek Terobosan Penting untuk Lilica.]],
  str_item_intro_3220173 = [[
Ketika Minos menembakkan senjatanya, gambar minotaur yang mengamuk tampak muncul di bawah permukaan batu permata ini.
Objek Terobosan Penting untuk Minos.]],
  str_item_intro_3220175 = [[
Permata yang ditutupi bekas luka. Anda bisa merasakan ujung dan sudutnya yang tajam saat berada dalam genggaman Anda, tetapi jika Anda terus memegangnya dan tidak pernah melepaskannya, tangan Anda memanas oleh kehangatan yang tak dapat dijelaskan.
Objek Terobosan Penting untuk Axelia.]],
  str_item_intro_3220176 = [[
Permata yang bersinar semarak dengan segudang warna. Itu bersinar cemerlang bahkan tanpa dipoles, dan siluet burung terbang dapat dilihat di dalam permata dari waktu ke waktu.
Objek Terobosan Penting untuk Beretta.]],
  str_item_intro_3220177 = [[
Permata berwarna-warni ini terasa sangat hangat. Jika Anda membawanya cukup lama, Anda bahkan dapat berbagi keberuntungan Goldie.
Objek terobosan penting untuk Goldie.]],
  str_item_intro_3220178 = [[
Permata ini sangat keras, bahkan jika Anda memukulnya sekeras mungkin dengan palu raksasa, Anda tidak akan meninggalkan goresan.
Objek Terobosan Penting untuk Vic.]],
  str_item_intro_3220180 = [[
Terasa kokoh, tetapi memantul kembali jika Anda menekannya. Brandy rupanya menggunakan ini untuk melatih kecepatan jari rananya.
Objek terobosan penting untuk Brandy.]],
  str_item_intro_3220181 = [[
Kehangatan batu ini di tangan Anda adalah bukti dari hati Zhong Xu yang penuh gairah.
Objek Terobosan Penting untuk Zhong Xu.]],
  str_item_intro_3220182 = [[
Warna batu permata yang tipis dan keras ini berubah sesuai dengan sudut cahaya yang menyinari batu tersebut.
Objek terobosan penting untuk Mu Yuebai.]],
  str_item_intro_3220183 = [[
Batu permata ini memancarkan aroma herbal yang samar dengan rasa yang sedikit pahit dan berbau seperti apoteker Liqing.
Objek terobosan penting untuk Liqing.]],
  str_item_intro_3220184 = [[
Ini memiliki kesan usang dan lapuk, tetapi pada saat yang sama, sangat cerah dan indah.
Objek Terobosan Penting untuk Jeriah.]],
  str_item_intro_3220185 = [[
Halus saat disentuh, sepertinya Kya sering membelainya. Setelah diperiksa lebih dekat, sepertinya ada tombol yang bergerak di dalamnya... apakah ini jam tangan?
Objek terobosan penting untuk Kya.]],
  str_item_intro_3220186 = [[
Cahaya murni dan suci yang menyelimuti permata ini memberi orang perasaan bahwa mereka akan menodai kecemerlangannya dengan menyentuhnya.
Objek Terobosan Penting untuk Tina.]],
  str_item_intro_3220189 = [[
Sulit disentuh, batu ini memantulkan cahaya menyilaukan di bawah matahari. Jika Anda menciumnya dengan hati-hati, Anda dapat mendeteksi sedikit aroma bunga di atasnya.
Objek Terobosan Penting untuk Leyn.]],
  str_item_intro_3220190 = [[
Potongan batu permata yang dipoles indah dengan keahlian luar biasa. Either way, itu terlihat sangat mahal, jadi mari kita letakkan dengan hati-hati.
Objek Terobosan Penting untuk Matthieu.]],
  str_item_intro_3220191 = [[
Meskipun terlihat sangat keras, ternyata lembut dan kenyal saat disentuh, seperti kaki anjing. Anda tidak bisa menahan diri untuk tidak meremas lagi dan lagi.
Objek Terobosan Penting untuk Hati.]],
  str_item_intro_3220192 = [[
Batu permata kusam ini terasa kasar saat disentuh. Leo mengatakan ini adalah bukti bahwa itu telah dipoles oleh angin dan pasir di perbatasan.
Objek Terobosan Penting untuk Leo.]],
  str_item_intro_3220193 = [[
Mendekatinya dan Anda akan mendengar suara deras air yang berbeda. Mungkin aliran arus bawah yang bergelombang seperti ini mengalir di hati Kristen ...
Objek Terobosan Penting untuk Kristen.]],
  str_item_intro_3220199 = [[
Suara merdu seperti burung dapat terdengar dari dalam batu permata sebening kristal ini.
Objek Terobosan Penting untuk Yingel.]],
  str_item_intro_3220200 = [[
Sebuah batu permata itu Anatoli dikumpulkan diproduksi di pembuluh darah di dalam Eternal Night dan diangkut ribuan mil kembali ke Illumina. Hangat saat disentuh, dan pantulan seseorang dapat terlihat samar-samar di permukaannya.
Objek Terobosan Penting untuk Anatoli.]],
  str_item_intro_3220201 = "Pada pandangan pertama, itu tampak seperti batu taman biasa, tetapi dekatkan ke telinga Anda dan dengarkan baik-baik—Anda akan mendengar benturan dua raungan yang terjalin, entah bagaimana membuatnya tampak lebih mempesona.\nObjek Terobosan Penting untuk Mia: Lustrous Soul.",
  str_item_intro_3220202 = [[
Tatap batu permata ini dan Anda akan melihat hari yang cerah setelah badai petir. Inilah masa depan yang menanti Lumopolis di bawah pemerintahannya.
Objek Terobosan Penting untuk Schwartz: Almighty Clamor.]],
  str_item_intro_3220203 = [[
Batu permata indah yang memancarkan kilau warna-warni saat terkena sinar matahari, memproyeksikan gambar buku ramalan.
Objek Terobosan Penting untuk Jakine.]],
  str_item_intro_3220204 = [[
Sebuah batu permata diselimuti cahaya hangat seperti lilin di musim dingin atau lampu jalan di kegelapan yang memandu jalan bagi mereka yang tersesat.
Objek Terobosan Penting untuk Joshua.]],
  str_item_intro_3220205 = [[
Batu permata indah yang sering dimainkan oleh Blanc. Dia mengatakan bahwa bagian bawah batu permata ini memantulkan lingkaran cahaya merah, tetapi tidak ada orang lain yang dapat melihatnya.
Objek Terobosan Penting untuk Blanc: Pura Cordis.]],
  str_item_intro_3220206 = [[
Lorelei dengan gembira mengklaim bahwa batu permata ini mencium bau uang, namun dia sangat menyukainya.
Objek Breakthrough penting untuk Lorelei]],
  str_item_intro_3220207 = "Halus di permukaan namun tajam saat disentuh, apakah kristal ini menggambarkan bahwa di bawah luarnya yang mengkilap juga terdapat bekas luka masa lalu yang tersembunyi? Objek Terobosan Esensial untuk Cena.",
  str_item_intro_3220208 = [[
Sebuah kristal yang menyala dan mempesona, berputar pelan-pelan...
Objek Terobosan Esensial untuk Bopper.]],
  str_item_intro_3220209 = [[
Benda Breakthrough yang penting untuk Wrath: Proud Fervor.
Siapa pun yang berani menyentuhnya akan tertusuk, disebabkan oleh petir merah yang tak henti-hentinya berputar di dalam kristal, menunggu dia untuk menaklukkan medan perang pilihannya.]],
  str_item_intro_3220210 = [[
Benda Breakthrough yang penting untuk Joselyne.
Setelah pengamatan yang cermat, kilau lembut yang berdenyut di inti permata ini mengingatkan pada nyanyian para penyembah yang taat dan cahaya suci yang memecahkan kegelapan malam.]],
  str_item_intro_3220211 = [[
Permata ini terkubur di bawah tanah selama berabad-abad hingga Antony menggali, menghapus kotoran, dan mengungkap akar misterinya.
Benda Breakthrough yang penting untuk Antony.]],
  str_item_intro_3220212 = [[
Ini lebih terlihat seperti kristal es yang terbentuk secara alami daripada batu permata. Mungkin Zarya membuatnya sendiri?
Benda Breakthrough yang penting bagi Zarya.]],
  str_item_intro_3220213 = [[
No. 33 menemukan batu permata ini di dekat reruntuhan yang pernah ia jaga. Setiap kali kesepiannya menjadi terlalu berat untuk dihadapi, No. 33 menganggapnya sebagai teman dan mencoba berkomunikasi dengannya.
Objek terobosan penting untuk No. 33.]],
  str_item_intro_3220214 = "Objek terobosan penting untuk Rebecca. Batu permata ini diberikan kepada Rebecca oleh orang tuanya. Setiap kali dia memegangnya dengan erat, dia dapat merasakan kehangatan abadi dari keluarganya.",
  str_item_intro_3220215 = [[
Sebuah batu permata yang terbentuk dari racun Rebecca. Isa merasa tubuhnya penuh energi setiap kali dia membawa batu ini.
Benda Breakthrough penting bagi Isa.]],
  str_item_intro_3220216 = [[
Batu yang tampak biasa ini mengandung kekuatan yang tidak diketahui. Tak ada yang tahu jebakan atau kreasi mekanik apa yang akan Xuan Ji tanamkan batu ini ke dalamnya.
Benda Breakthrough yang penting bagi Xuan Ji.]],
  str_item_intro_3220218 = [[
Permata misterius ini memiliki berat yang sama persis dengan Nightium. Jika Anda mendengarkan dengan saksama, Anda bahkan dapat mendengar suara Nightium berderak di dalam permata.
Objek Terobosan Penting untuk Sheol.]],
  str_item_intro_3220219 = [[
Permata berkilau berat ini terasa seolah-olah sedikit gemetar dari emosi jauh di tangan Anda. Hampir seolah-olah peristiwa masa lalu yang telah terkubur dalam-dalam akan meledak keluar.
Objek Terobosan Penting untuk Istvan: Scarred Pith]],
  str_item_intro_3220220 = "Vergil menilai batu permata ini memiliki nilai artistik yang tinggi. Dikabarkan bahwa dia suka membawa batu permata ini seperti jimat keberuntungan. Benda Breakthrough yang penting untuk Vergil.",
  str_item_intro_3220221 = [[
Sebuah batu permata yang sangat mendalam dan menakjubkan dari asal yang tidak diketahui. Sepertinya meramalkan masa depan yang misterius dan tak terduga dari Aurorians...
Objek Terobosan Penting untuk Algol.]],
  str_item_intro_3220223 = [[
Batu yang terbentuk dari sisik di era kuno, mungkin menyimpan renungan jauh dari klan Chen'ni.
Benda Breakthrough yang penting bagi Chen'ni.]],
  str_item_intro_3220224 = [[
Sebuah batu yang mungkin menyimpan kekuatan misterius. Luo Song mungkin menggunakannya untuk memberi pelajaran kepada makhluk nakal.
Objek Terobosan Penting untuk Luo Song.]],
  str_item_intro_3220225 = [[
Batu permata dengan warna pelindung yang menyatu sempurna dengan es begitu jatuh ke salju, membuatnya hampir mustahil untuk diambil kembali. Jadi, sebaiknya Anda menanganinya dengan hati-hati.
Objek terobosan penting untuk Tiare.]],
  str_item_intro_3220227 = [[
Sebuah potongan Lumamber dengan ujung dan sudut yang sangat tajam. Meskipun harus sangat hati-hati saat menangani Lumamber ini, bisa dirasakan kehangatan yang lembut dan samar-samar datang darinya.
Objek Breakthrough penting untuk Rachel.]],
  str_item_intro_3220228 = [[
Batu permata indah yang memancarkan kilau warna-warni yang cemerlang dan sedikit petunjuk permen.
Benda Breakthrough yang penting untuk Zeta.]],
  str_item_intro_3220229 = [[
Batu biasa yang menurut Batia bisa didapatkan dengan menggunakan kapak dan tungku, serta metode lainnya.
Benda Breakthrough yang penting bagi Batia.]],
  str_item_intro_3220230 = [[
Saat kamu menyentuh batu permata ini, kamu bisa mendengar bisikan kuno, tidak dari jauh atau dekat telingamu, tetapi dalam pikiranmu, seperti makhluk kuno yang berdenyut dan berjuang untuk bebas.
Objek Terobosan Penting untuk Victoria: Elegy.]],
  str_item_intro_3220231 = [[
Sebuah batu permata dengan warna yang mencolok dan menyeramkan. Saat Anda menyentuhnya, darah mulai menetes di dinding. Hanya ketika Anda menarik tangan Anda dalam ketakutan, Anda melihat itu semua adalah halusinasi.
Objek Terobosan Penting untuk Wilhelm.]],
  str_item_intro_3220232 = [[
Begitu kamu memegang batu permata ini, kamu melihat ribuan pedang jatuh dari langit, memotong dagingmu. Kamu berteriak kesakitan, tetapi ketika kamu melihat dirimu sendiri, kamu tidak menemukan luka.
Benda Breakthrough yang penting bagi Nails: Sacred Rite.]],
  str_item_intro_3220233 = [[
Sebuah permata yang digali dari reruntuhan. Mungkin kamu bisa merasakan semangat petualangan darinya.
Benda Breakthrough yang penting bagi Ryza.]],
  str_item_intro_3220234 = [[
Permata yang digali dari reruntuhan. Mungkin kamu bisa merasakan keindahan musik darinya.
Benda Breakthrough yang penting untuk Klaudia.]],
  str_item_intro_3220235 = [[
Sebuah permata yang digali dari reruntuhan. Mungkin kamu bisa merasakan temperamen noble darinya.
Benda Breakthrough yang penting bagi Patricia.]],
  str_item_intro_3220237 = [[
Sebuah permata sebening kristal dengan sentuhan angin sejuk di atas awan dan kelembutan lembab dari laut dalam.
Peganglah di tanganmu, dan kamu akan mendengar bisikan lembut, "Jangan takut. Dunia sedang tidur dalam mimpimu."
Objek Terobosan Penting untuk Maya.]],
  str_item_intro_3220238 = [[
Pada pandangan pertama tampak biasa saja, tetapi ketika kamu menyentuh tepinya, kamu akan melihat betapa tajamnya sebenarnya. Ada energi yang berdenyut di dalamnya, seperti kemarahan yang tak terucapkan.
Benda Breakthrough yang penting bagi Mithra.]],
  str_item_intro_3231101 = [[
Common Gift. Sangat cocok jika diberikan kepada Aurorian dari Lumopolis.
Lembaran perak setipis dan selembut bulu. Banyak digemari di Lumopolis.]],
  str_item_intro_3232101 = [[
Valuable Gift. Efeknya paling besar jika diberikan kepada Aurorian dari Lumopolis.
Lumamber yang dikemas dalam emas. Barang favorit utama masyarakat kelas atas Lumopolis.]],
  str_item_intro_3233101 = [[
Sangat cocok jika diberikan kepada Aurorian dari Lumopolis.
Kerajinan tangan dari permata Lumina yang sangat mahal ini dipasang pada kristal putih yang berharga.]],
  str_item_intro_3231102 = [[
Common Gift. Sangat cocok jika diberikan kepada Aurorian dari Umbraton.
Replika berbagai lukisan terkenal. Populer di Umbraton.]],
  str_item_intro_3232102 = [[
Valuable Gift. Efeknya paling besar jika diberikan kepada Aurorian dari Umbraton.
Hanya beberapa taipan di Umbraton saja yang pernah mencicipi anggur persembahan yang berharga ini.]],
  str_item_intro_3233102 = [[
Sangat cocok jika diberikan kepada Aurorian dari Umbraton.
Permata yang memikat dengan kilau hijau unik, banyak dicari di Umbraton.]],
  str_item_intro_3231103 = [[
Common Gift. Sangat cocok jika diberikan kepada Aurorian dari Rediesel Wrench.
Zat peninggalan masa lalu. Anggota Rediesel Wrench memakainya untuk dekorasi atau menyanjung Colossus mereka.]],
  str_item_intro_3232103 = [[
Valuable Gift. Efeknya paling besar jika diberikan kepada Aurorian dari Rediesel Wrench.
Penting untuk dinamit, amunisi, dan peledak. Uang tunai untuk kalangan sendiri di Rediesel Wrench.]],
  str_item_intro_3233103 = [[
Sangat cocok jika diberikan kepada Aurorian dari Rediesel Wrench.
Minuman keras yang langka yang akan membuat peminumnya mabuk hanya dengan satu teguk saja. Digemari semua anggota Rediesel Wrench.]],
  str_item_intro_3231104 = [[
Common Gift. Sangat cocok jika diberikan kepada Aurorian dari Illumina.
Buku kelas pemula di Illumina Federation, dengan banyak gambar agar mudah dipelajari.]],
  str_item_intro_3232104 = [[
Valuable Gift. Efeknya paling besar jika diberikan kepada Aurorian dari Illumina Federation.
Buku panduan Illumina Federation yang mengajarkan cara memakai ilmu pengetahuan untuk mengatasi berbagai masalah.]],
  str_item_intro_3233104 = [[
Sangat cocok jika diberikan kepada Aurorian dari Illumina.
Digunakan untuk kalangan sendiri di Illumina Federation, dan mencakup semua bidang pengetahuan yang sudah dikenal oleh federasi ini.]],
  str_item_intro_3231105 = [[
Common Gift. Sangat cocok jika diberikan kepada Aurorian dari Northland.
Kristal dari kepingan salju pada saat terbentuk dari air. Para penghuni Northland meyakini bahwa kristal ini menyimpan sihir kuat dan mereka suka mengumpulkannya.]],
  str_item_intro_3232105 = [[
Valuable Gift. Efeknya paling besar jika diberikan kepada Aurorian dari Northland.
Permata warna-warni yang sangat berharga dan ditemukan di bawah pelangi, diyakini para penghuni Northland sebagai pembawa keberuntungan abadi.]],
  str_item_intro_3233105 = [[
Sangat cocok jika diberikan kepada Aurorian dari Northland.
Lembaran es warna-warni yang diambil dari Lake Mirror yang selalu beku di Northland. Kesukaan para penghuni Northland.]],
  str_item_intro_3231106 = [[
Common Gift. Sangat cocok jika diberikan kepada Aurorian dari True Order.
Kumbang purba yang terbungkus batu amber. True Order meyakini bahwa item ini menyimpan kekuatan misterius.]],
  str_item_intro_3232106 = [[
Valuable Gift. Efeknya paling besar jika diberikan kepada Aurorian dari True Order.
Perkamen berisi wahyu gaib. Banyak rahasia yang akan terungkap jika anggota True Order bisa menafsirkannya.]],
  str_item_intro_3233106 = [[
Sangat cocok jika diberikan kepada Aurorian dari True Order.
True Order meyakini bahwa item ini berisi wahyu besar yang akan mengubah peradaban yang kita kenal ini.]],
  str_item_intro_3231107 = [[
Common Gift. Sangat cocok jika diberikan kepada Independent Aurorian.
Ransum kering yang ringan dan ringkas, banyak digunakan di permukiman kecil.]],
  str_item_intro_3232107 = [[
Valuable Gift. Efeknya paling besar jika diberikan kepada Independent Aurorian.
Ramuan ajaib dan magis yang bisa mengubah siapa pun menjadi dokter di beberapa permukiman tertentu.]],
  str_item_intro_3233107 = [[
Sangat cocok jika diberikan kepada Independent Aurorian.
Potongan peta harta karun yang dicari-cari banyak orang yang menganggapnya layak dipertaruhkan.]],
  str_item_intro_3232108 = [[
Common Gift. Sangat cocok jika diberikan kepada Aurorian dari Longzhou.
Kipas lipat dengan bingkai bambu dan permukaan kertas yang dihiasi dengan gambar gunung dan sungai yang menawan. Digunakan di ruangan gelap di aula utama Longzhou.]],
  str_item_intro_3233108 = [[
Valuable Gift. Efeknya paling besar jika diberikan kepada Aurorian dari Longzhou.
Simpul hias yang terbuat dari tali merah ini melambangkan ikatan hati yang tulus dan cinta kasih yang saling berbalas, serta menjadi salah satu hadiah terpenting di hati masyarakat Longzhou.]],
  str_item_intro_3231201 = [[
Common Gift. Sangat cocok jika diberikan kepada Aurorian yang polos seperti anak kecil.
Disukai siapa pun yang berjiwa kanak-kanak. Tersedia dalam lima pilihan rasa, dan kamu bisa menggunakannya untuk bersiul.]],
  str_item_intro_3232201 = [[
Valuable Gift. Efeknya paling besar jika diberikan kepada Aurorian yang polos seperti anak kecil.
Produk hiburan bagi siapa pun yang berjiwa kanak-kanak. Pemain bermain dengan deskripsi verbal.]],
  str_item_intro_3233201 = [[
Sangat cocok jika diberikan kepada Aurorian yang polos seperti anak kecil.
Model yang disukai siapa pun yang masih berjiwa kanak-kanak. Sangat detail dan kini tidak dibuat lagi.]],
  str_item_intro_3231202 = [[
Common Gift. Sangat cocok jika diberikan kepada Aurorian yang romantis.
Boneka buatan tangan yang disukai orang romantis. Menyerupai kelinci sekaligus beruang. Pembuatnya tidak diketahui.]],
  str_item_intro_3232202 = "Valuable Gift. Efeknya paling besar jika diberikan kepada Aurorian yang romantis. Melihat rangkaian cahaya indah di dalam botol minum ini dalam suasana redup sangatlah romantis.",
  str_item_intro_3233202 = [[
Sangat cocok jika diberikan kepada Aurorian yang romantis.
Pembatas buku yang terbuat dari tanaman langka, menampilkan pola dan warna yang berubah-ubah.]],
  str_item_intro_3231203 = [[
Common Gift. Sangat cocok jika diberikan kepada Aurorian yang ahli dalam bidang tertentu.
Serangga yang terkenal karena penampilan anehnya ini menarik perhatian para kolektor yang penasaran.]],
  str_item_intro_3232203 = [[
Valuable Gift. Efeknya paling besar jika diberikan kepada Aurorian yang ahli dalam bidang tertentu.
Fosil berduri yang mengkristal dari makhluk tidak dikenal untuk para kolektor yang sangat penasaran.]],
  str_item_intro_3233203 = [[
Sangat cocok jika diberikan kepada Aurorian yang ahli dalam bidang tertentu.
Kayu lapuk yang dikumpulkan oleh orang penasaran karena kadang bisikan aneh akan terdengar di penampangnya.]],
  str_item_intro_3231204 = [[
Common Gift. Sangat cocok jika diberikan kepada Aurorian bangsawan.
Lonceng perak kecil, ringan, dan berukir indah yang dianggap sebagai jimat keberuntungan oleh orang-orang cerdas.]],
  str_item_intro_3232204 = [[
Valuable Gift. Efeknya paling besar jika diberikan kepada Aurorian bangsawan.
Bijih langka yang memancarkan berbagai warna di bawah intensitas cahaya yang berbeda-beda. Digunakan sebagai hadiah di kalangan bangsawan.]],
  str_item_intro_3233204 = [[
Sangat cocok jika diberikan Aurorian bangsawan.
Material khusus dan langka yang dipuja bangsawan. Kebanyakan berasal dari daerah dingin. Halus, ringan, tapi tahan lama.]],
  str_item_intro_3231205 = [[
Common Gift. Sangat cocok jika diberikan kepada Aurorian yang suka terus terang.
Item andalan dari gurun. Orang-orang yang suka terus terang sangat menikmati rasanya yang unik.]],
  str_item_intro_3232205 = [[
Valuable Gift. Efeknya paling besar jika diberikan kepada Aurorian yang suka terus terang.
Kotak peralatan untuk sebagian besar keperluan crafting dan perbaikan. Sangat disukai orang-orang yang tidak suka basa-basi.]],
  str_item_intro_3233205 = [[
Sangat cocok jika diberikan kepada Aurorian yang suka terus terang.
Bisa mengukur fungsi biologis dan mekanis. Produk sempurna untuk orang-orang intuitif.]],
  str_item_intro_3239997 = "Ini datang dalam semua jenis rasa! Berikan kepada Aurorian untuk meningkatkan Affinity secara signifikan.",
  str_item_intro_3239998 = "Berikan kepada Aurorian untuk meningkatkan Affinity secara signifikan!",
  str_item_intro_3239999 = "Cokelat yang sangat menggoda! Berikan kepada Aurorian untuk meningkatkan Affinity secara signifikan!",
  str_item_intro_3300001 = "Zat yang sangat keras tetapi bukan logam... Sepertinya ini senyawa biologis dari zaman dahulu, bisa memperbaiki beberapa bagian Colossus yang rusak dan menyambungkan lagi saluran energinya.",
  str_item_intro_3300002 = "Jelas, ini adalah tambalan yang ditambahkan ke Colossus, cukup untuk memperkuat bagian dalam Colossus.",
  str_item_intro_3300003 = "Bukan cuma tahan lama tetapi juga fleksibel, dengan aksara tidak dikenal yang muncul dan menghilang. Material ini dibutuhkan untuk memulihkan sejumlah fasilitas utama Colossus.",
  str_item_intro_3300004 = "Dibutuhkan untuk meng-upgrade Bridge, yang merupakan instalasi penting di Colossus. Sangat langka. Gunakan dengan hati-hati.",
  str_item_intro_3300005 = "Kubus magis dengan struktur yang menarik ini mungkin ditinggalkan oleh seorang penjelajah berani. Jika informasi yang ditorehkan pada kubus ini dimasukkan ke database Colossus, ruangan baru mungkin akan terbuka.",
  str_item_intro_3300006 = "Plugin ini telah terkubur di dalam tanah selama bertahun-tahun. Benda ini seperti kepunyaan Soroz yang hilang tujuh belas tahun lalu! Kamu bisa menggunakannya untuk membuka sebuah ruang di Colossus.",
  str_item_intro_3400001 = "Dapatkan 1 dari setiap Basic Material untuk Water Ascension.",
  str_item_intro_3400002 = "Dapatkan 1 dari setiap Basic Material untuk Fire Ascension.",
  str_item_intro_3400003 = "Dapatkan 1 dari setiap Basic Material untuk Forest Ascension.",
  str_item_intro_3400004 = "Dapatkan 1 dari setiap Basic Material untuk Thunder Ascension.",
  str_item_intro_3400005 = "Dapatkan 1 dari setiap Regular Material untuk Water Ascension.",
  str_item_intro_3400006 = "Dapatkan 1 dari setiap Regular Material untuk Fire Ascension.",
  str_item_intro_3400007 = "Dapatkan 1 dari setiap Regular Material untuk Forest Ascension.",
  str_item_intro_3400008 = "Dapatkan 1 dari setiap Regular Material untuk Thunder Ascension.",
  str_item_intro_3400009 = "Dapatkan 1 dari setiap Advanced Material untuk Water Ascension.",
  str_item_intro_3400010 = "Dapatkan 1 dari setiap Advanced Material untuk Fire Ascension.",
  str_item_intro_3400011 = "Dapatkan 1 dari setiap Advanced Material untuk Forest Ascension.",
  str_item_intro_3400012 = "Dapatkan 1 dari setiap Advanced Material untuk Thunder Ascension.",
  str_item_intro_3400013 = "Dapatkan 1 Basic Material mana saja untuk Water Ascension.",
  str_item_intro_3400014 = "Dapatkan 1 Basic Material mana saja untuk Fire Ascension.",
  str_item_intro_3400015 = "Dapatkan 1 Basic Material mana saja untuk Forest Ascension.",
  str_item_intro_3400016 = "Dapatkan 1 Basic Material mana saja untuk Thunder Ascension.",
  str_item_intro_3400017 = "Dapatkan 1 Regular Material mana saja untuk Water Ascension.",
  str_item_intro_3400018 = "Dapatkan 1 Regular Material mana saja untuk Fire Ascension.",
  str_item_intro_3400019 = "Dapatkan 1 Regular Material mana saja untuk Forest Ascension.",
  str_item_intro_3400020 = "Dapatkan 1 Regular Material mana saja untuk Thunder Ascension.",
  str_item_intro_3400021 = "Dapatkan 1 Advanced Material mana saja untuk Water Ascension.",
  str_item_intro_3400022 = "Dapatkan 1 Advanced Material mana saja untuk Fire Ascension.",
  str_item_intro_3400023 = "Dapatkan 1 Advanced Material mana saja untuk Forest Ascension.",
  str_item_intro_3400024 = "Dapatkan 1 Advanced Material mana saja untuk Thunder Ascension.",
  str_item_intro_3400025 = "Dapatkan 1 dari setiap Basic Material untuk Ascension.",
  str_item_intro_3400026 = "Dapatkan 1 dari setiap Regular Material untuk Ascension.",
  str_item_intro_3400027 = "Dapatkan 1 dari Advanced Material untuk Ascension.",
  str_item_intro_3400028 = "Dapatkan 1 Basic Material mana saja untuk Ascension.",
  str_item_intro_3400029 = "Dapatkan 1 Regular Material mana saja untuk Ascension.",
  str_item_intro_3400030 = "Dapatkan 1 Advanced Material mana saja untuk Ascension.",
  str_item_intro_3400031 = "Common Raw Jasper. Dapatkan 1 Jasper I mana saja (Biru, Merah, Kuning, atau Hijau).",
  str_item_intro_3400032 = "Kumpulan beragam Jasper. Dapatkan 1 Jasper I untuk setiap warna (Biru, Merah, Kuning, dan Hijau).",
  str_item_intro_3400033 = "Common Raw Jasper. Dapatkan 1 Jasper II mana saja (Biru, Merah, Kuning, atau Hijau).",
  str_item_intro_3400034 = "Kumpulan beragam Jasper. Dapatkan 1 Jasper II untuk setiap warna (Biru, Merah, Kuning, dan Hijau).",
  str_item_intro_3400035 = "Raw Jasper yang warnanya lebih cemerlang. Dapatkan 1 Jasper III mana saja (Biru, Merah, Kuning, atau Hijau).",
  str_item_intro_3400036 = "Kumpulan beragam Jasper. Dapatkan 1 Jasper III untuk setiap warna (Biru, Merah, Kuning, dan Hijau).",
  str_item_intro_3400037 = [[
Hadiah dari sumber tidak dikenal. Buka dan lihatlah isinya.
Gunakan untuk mendapatkan 1 Common Gift mana saja.]],
  str_item_intro_3400038 = [[
Paket hadiah yang sangat indah dari sumber tidak dikenal. Mestinya, isinya bagus, ya?
Gunakan untuk mendapatkan 1 Valuable Gift mana saja.]],
  str_item_intro_3400039 = [[
Hadiah dalam paket yang menakjubkan ini pasti sangat berharga. Bukalah!
Gunakan untuk mendapatkan sembarang Aurorian Gift yang sangat mahal.]],
  str_item_intro_3400040 = [[
Kotak transparan yang terbuat dari kristal dan diperkuat dengan Luminatics. Ringan dan kokoh, berisi Lumamber yang berharga.
Gunakan untuk mendapatkan 50 Lumamber.]],
  str_item_intro_3400041 = [[
Peti besi untuk emas yang dikeluarkan oleh Lumopolis. Sekarang sepertinya dipakai di mana saja karena Nightium makin populer.
Berisi 100.000 Nightium.]],
  str_item_intro_3400042 = [[
Kotak kristal yang cahayanya redup dan menyimpan cukup banyak Lumina untuk mengisi ulang Prism hingga penuh.
Gunakan untuk mendapatkan 10 Prism.]],
  str_item_intro_3400043 = [[
Kotak kristal bujur sangkar yang bagian tengahnya berkilau dan mengalirkan lebih banyak energi ke Prism.
Gunakan untuk mendapatkan 60 Prism.]],
  str_item_intro_3400044 = [[
Peti besar yang terbuat dari kristal yang dipoles dan memiliki dekorasi yang rumit. Berisi Lumina yang cukup untuk mengisi ulang Prism dengan lebih banyak energi daripada sebelumnya.
Gunakan untuk mendapatkan 50 Prism.]],
  str_item_intro_3400045 = [[
Kotak kristal besar yang berkilau samar dan menyimpan cukup banyak Lumina untuk mengisi ulang beberapa Prism hingga penuh.
Gunakan untuk mendapatkan 60 Prism.]],
  str_item_intro_3400046 = "Supply Kit yang dikembangkan oleh Aurorian Coalition. Dapatkan 1 dari sembarang material berikut: White Night Stone, Destiny Champagne I, Pine Dew, Rediesel Extract, Battle Archive I, Ancient Scroll, Tales of Survival, Bone Strengthening Pill.",
  str_item_intro_3400047 = "Supply Kit yang dikembangkan oleh Aurorian Coalition. Dapatkan 1 dari sembarang material berikut: Morning Stone, Destiny Champagne III, Pine Frost, Rediesel Concentrate, Battle Archive II, Ancient Book, Survival 101, Marrow Cleansing Pill.",
  str_item_intro_3400048 = "Supply Kit yang dikembangkan oleh Aurorian Coalition. Dapatkan 1 dari sembarang material berikut: Daybreak Stone, Destiny Champagne III, Tear of Pine, Rediesel Essence, Battle Archive III, Ancient Book, Survivalpedia, Reconstruction Pill.",
  str_item_intro_3400049 = "Di Northland, berdiri sebuah menara tinggi dengan mercusuar bercahaya di puncaknya. Selama cahayanya tidak padam, Eclipsite tidak akan pernah menjadi ancaman bagi daratan paling utara benua itu.",
  str_item_intro_3400050 = [[
Membuka asisten: Vice Casual Wear.
Penampilan kasual Vice.]],
  str_item_intro_3400052 = [[
Membuka latar belakang: Snowy Forest.
Hutan lebat di perbatasan Northland ini tertutup lapisan salju tebal di musim dingin. Mereka yang memasuki hutan yang indah ini secara tidak sengaja sering tersesat di dalamnya.]],
  str_item_intro_3400053 = [[
Membuka latar belakang: Far East Dojo.
Tempat yang ada di Far East ini digunakan untuk berlatih seni bela diri dan juga bermeditasi.]],
  str_item_intro_3400054 = [[
Membuka latar belakang: Marvelous Sky.
Di kota kuno yang hilang, langit ini pernah menjadi pelipur lara terbesar bagi penghuninya.]],
  str_item_intro_3400055 = [[
Membuka latar belakang: Perfect Stage.
Tempat para gadis tampil di musim panas. Meskipun telah lama berlalu, rasanya tidak ada yang berubah.]],
  str_item_intro_3400056 = [[
Membuka latar belakang: Sakura Court Hallway.
Lorong dan halaman bergaya Far East menawarkan pemandangan unik selama musim bunga sakura.]],
  str_item_intro_3400057 = [[
Membuka latar belakang: Legion Commander's Train.
Ketika empat Legion Commander dari Illumina Federation naik kereta khusus bersama-sama, pasti ada hal penting yang terjadi...]],
  str_item_intro_3400058 = [[
Membuka latar belakang: Oasis.
Salah satu benteng utama Rediesel Wrench yang terletak di medan yang menyulitkan dan bermacam rupa.]],
  str_item_intro_3400059 = [[
Membuka latar belakang: Four Angels.
Empat panglima kesatria yang mencerminkan ketangguhan Lumo Noble.]],
  str_item_intro_3400060 = [[
Membuka latar belakang: Summer Night Party.
Di puncak pesta malam musim panas, para gadis benar-benar menikmati musik. Suara tawa dan nyanyian mereka masih bisa terdengar hingga sekarang.]],
  str_item_intro_3400061 = [[
Membuka latar belakang: Blazing Tooth.
Ngarai yang namanya diambil dari topografi lanskapnya yang bergerigi ini sangat curam dan sulit dilalui.]],
  str_item_intro_3400062 = "Membuka latar belakang: Mystery Residence.\nRumah megah yang asal-usul dan pemiliknya tak diketahui ini menawarkan waktu senggang yang santai dan tanpa beban…",
  str_item_intro_3400063 = [[
Membuka latar belakang: Circular System.
Berasal dari suatu wilayah kuno, rahasia apa yang tersimpan di dalamnya?]],
  str_item_intro_3400064 = [[
Membuka latar belakang: Chord Link.
Kekuatan misterius dari suatu tempat misterius...]],
  str_item_intro_3400065 = [[
Membuka latar belakang: Piano Duet.
Masih ingat saat kamu memulainya dengan Vice?]],
  str_item_intro_3400066 = [[
Membuka latar belakang: Eraveil Colossus.
Colossus bermunculan lagi di Eraveil. Apakah artinya?]],
  str_item_intro_3400067 = [[
Membuka latar belakang: Letter from the Skies.
Surat yang terbawa angin ini mengabarkan bahwa sudah waktunya Caelestite pulang.]],
  str_item_intro_3400068 = [[
Membuka latar belakang: Serene Cemetery.
Tempat terpencil di Eraveil. Di sini, bahkan waktu pun tidak berjalan.]],
  str_item_intro_3400069 = [[
Membuka latar belakang: Decorated Post.
Eraveil Post yang baru saja didekorasi. Nantikan malam liburan di hari-hari yang akan datang.]],
  str_item_intro_3400070 = [[
Membuka latar belakang: Holiday Memories.
Itu adalah malam liburan pertama yang kuhabiskan di Eraveil...]],
  str_item_intro_3400071 = [[
Membuka Latar Belakang: Umbraton Street at Night.
Saat malam menjelang di Umbraton, jalanan tampak sunyi sepi, tapi ada bahaya yang mengintai.]],
  str_item_intro_3400072 = [[
Membuka latar belakang: Kesuraman Malam.
Malam Umbraton menelan semua yang disentuhnya. Bisakah seberkas cahaya menembus?]],
  str_item_intro_3400073 = [[
Membuka latar belakang: Andersen Mansion.
Rumah megah ini mencerminkan kekayaan dan keanggunan pemiliknya.]],
  str_item_intro_3400074 = [[
Membuka kunci latar belakang: Cloud Blossom Hotel.
Makanan yang luar biasa, sumber air panas yang luar biasa, dan mereka bahkan menyediakan yukata!]],
  str_item_intro_3400075 = [[
Membuka kunci gambar latar belakang: Dermaga Kota Pelabuhan.
Area di sebelah pelabuhan Harbour City adalah tempat terbaik untuk menikmati angin sepoi-sepoi di bawah langit yang cerah!]],
  str_item_intro_3400076 = [[
Membuka latar belakang: Summer Night.
Kebahagiaan tertinggi akan tercapai jika momen indah ini bertahan selamanya.]],
  str_item_intro_3400077 = [[
Membuka latar belakang: Beach Thunder Warning.
Pukul keras-keras, permainan pun akan selesai lebih awal!]],
  str_item_intro_3400078 = [[
Membuka kunci latar belakang: Memori Gereja.
Sebuah bangunan yang membusuk di Euphoria. Bagaimanapun, itu hanya bagus untuk tempat berteduh, sama seperti di tempat lain.]],
  str_item_intro_3400079 = [[
Membuka kunci latar belakang: Tanah Misterius.
Sebuah tanah tanpa nama yang tersembunyi di mana terlalu banyak masa lalu telah terkubur. Akankah rahasia-rahasia ini akan terlihat lagi?]],
  str_item_intro_3400080 = [[
Membuka kunci latar belakang: Pengorbanan?
Dia memilih untuk mengorbankan dirinya melawan Eclipsites yang menyerangnya. Namun, tidak ada yang tahu bahwa ini hanyalah salah satu bagian dari rencananya ...]],
  str_item_intro_3400082 = [[
Membuka kunci latar belakang: Mengejar Kebenaran.
Mereka percaya apa yang dunia anggap sebagai pengetahuan umum adalah salah. Kebenaran sejati terletak jauh melampaui apa yang dapat dilihat mata mereka, hanya menunggu mereka untuk mengejarnya.]],
  str_item_intro_3400083 = [[
Buka latar belakang: Colossus Stage.
Panggung berperalatan lengkap telah disiapkan di dekat bar di Soroz untuk semua orang memamerkan bakat mereka.]],
  str_item_intro_3400084 = [[
Buka latar belakang: Kota Terbengkalai Kuno.
Pemandangan bangunan besar yang runtuh saja sudah cukup untuk menggambarkan betapa dahsyatnya perang kuno itu.]],
  str_item_intro_3400085 = [[
Membuka latar belakang: Di Bawah Langit Musim Dingin.
Jika Anda melihat pedang yang bersinar dan kilatan rambut pirang melayang di udara, itu mungkin Ratu Negeri Utara yang berkeliling di bawah langit musim dingin saat dia mengawasi kerajaannya dengan mata waspada setiap musim dingin.]],
  str_item_intro_3400086 = [[
Buka latar belakang: Aurora Sky.
Bahkan di Northland, jenis aurora yang menutupi setiap jengkal langit dan menghilang ke cakrawala jarang terjadi. Mereka mengatakan bahwa setiap kali muncul, itu mungkin memiliki efek yang tidak diketahui di masa depan...]],
  str_item_intro_3400087 = [[
Buka latar belakang: Jalan Lagu.
Dalam Colossus yang mengembara melalui negeri yang tak terhitung jumlahnya, sosok bintang muda yang cerah menghiasi aula. Lagu ketuhanannya, yang dijiwai dengan kekuatan harapan, akan segera menyebar ke seluruh benua.]],
  str_item_intro_3400088 = [[
Buka latar belakang: Deck of The Shadowind.
Hanya geladak yang besar dan kokoh ini yang dapat menampung kastil setinggi itu.]],
  str_item_intro_3400089 = [[
Buka latar belakang: Dermaga Timur.
Dermaga, rumah, dan perahu di benua di seberang laut sangat berbeda dengan yang ada di Astra, tetapi pemandangan kehidupan yang bising dan ramai tetap sama.]],
  str_item_intro_3400090 = [[
Buka latar belakang: Kawan Tidak Lagi.
Setelah bertarung berdampingan dengan Grand Marshal, mengalahkan musuh yang tak terhitung jumlahnya bersama-sama, waktunya telah tiba untuk melawannya.
Nasib, mengapa kamu mengejekku begitu?]],
  str_item_intro_3400091 = [[
Buka latar belakang: Rediesel Courier.
Cabang Rediesel Desert dari Courier Union tampaknya secara bertahap beradaptasi dengan kehidupan di Rediesel Desert.]],
  str_item_intro_3400092 = [[
Buka latar belakang: Kantor Jeriah.
Jeriah menangani urusan sehari-harinya di sini dan telah menanamkan tempat ini dengan gaya pribadinya.]],
  str_item_intro_3400093 = "Buka kunci latar belakang: Carefree Place.\nDalam suasana hati ini, kafe, restoran, atau bar semuanya memiliki satu fungsi yang sama — istirahat, pemulihan, dan tempat bagi semua orang untuk bersenang-senang.",
  str_item_intro_3400094 = [[
Buka latar belakang: Pernikahan Musim Dingin
Dekorasi sebening kristal itu mencerminkan sosok pasangan yang sempurna dan transparan serta mewakili perasaan murni mereka. Bahkan hawa dingin pun tidak bisa menahan kontak dekat dengan hati yang penuh gairah di pernikahan musim dingin.]],
  str_item_intro_3400099 = [[
Buka latar belakang: Bayangan di Api.
Saat iblis yang menghanguskan menyerang dari semua sisi, sesosok tubuh mengulurkan tangan membantu...]],
  str_item_intro_3400100 = [[
Buka latar belakang: Ikhtisar Gudang.
Ruang penyimpanan mengelilingi, sejauh mata memandang. Mungkin mereka menyembunyikan rahasia masa lalu yang tidak diketahui.]],
  str_item_intro_3400101 = [[
Membuka latar belakang: Uptown Vista.
Sebuah tempat yang sempurna dan elegan, terkenal tidak hanya sebagai jantung tak terkalahkan dari Lumopolis tetapi juga sebagai pusat dari seluruh benua.]],
  str_item_intro_3400102 = [[
Membuka latar belakang: Bersenda Gurau Bersaudara.
Sebuah pemandangan mengharukan dari saudara kandung yang tenggelam dalam tawa. Meskipun berlalu begitu banyak hari dan malam, kenangan itu tetap jelas, terukir selamanya di hati mereka.]],
  str_item_intro_3400103 = [[
Membuka latar belakang: Alun-alun Nightfall.
Alun-alun Pusat yang megah di Lumopolis bersinar dengan indahnya bahkan ketika malam tiba, menyaingi kecemerlangan siang harinya.]],
  str_item_intro_3400109 = [[
Membuka latar belakang: Dawn Academy.
Di Lumopolis, ada tempat di mana penganut yang taat mempelajari ajaran Dewa Cahaya, dan semua yang melalui pintu suci tempat itu dipenuhi dengan rasa hormat.]],
  str_item_intro_3400110 = [[
Membuka latar belakang: Puing Misterius.
Di ruang tak dikenal yang terletak jauh di bawah Northland ini, tampaknya seolah-olah ada perangkat buatan yang masih aktif.]],
  str_item_intro_3400111 = [[
Membuka latar belakang: Gentle Starlight.
Malam yang tak terlelap sendirian, di Jembatan di bawah langit berbintang. Anda masih bisa mendengar musik alam semesta tanpa harus menekan tombol panel kontrol.]],
  str_item_intro_3400112 = [[
Membuka latar belakang: Sore yang Tenang.
Lumopolis memiliki banyak taman kecil yang indah dan hangat tempat para bangsawan menikmati teh sore. Bahkan kiamat yang mengancam dunia terasa jauh sekali dari sini.]],
  str_item_intro_3400113 = [[
Membuka latar belakang: Klinik Bawah Tanah.
Sebuah klinik yang cukup sederhana yang menjadi tempat kenangan berharga.]],
  str_item_intro_3400114 = [[
Membuka latar belakang: Sudut Terkelam.
Meskipun tersesat dalam kegelapan, dia masih merindukan untuk merangkul cahaya sekali lagi.]],
  str_item_intro_3400115 = [[
Membuka latar belakang: Hospitality.
Hanya mereka yang disetujui oleh Sheol yang diizinkan untuk tinggal di kamar mewah dan nyaman ini.]],
  str_item_intro_3400116 = [[
Membuka latar belakang: Benua Baru.
Shadowind telah berhasil tiba di benua baru, tetapi ini tidak berarti petualangannya telah berakhir karena masih banyak hal yang belum diketahui menunggu mereka.]],
  str_item_intro_3400117 = [[
Membuka latar belakang: Bayangan Ada Di Mana-mana.
Shadowlord terus mengawasi Umbraton. Bayangan akan selalu mengawasimu.]],
  str_item_intro_3400118 = [[
Membuka latar belakang: Sejarah Gelap.
Sejarah yang disegel debu akan terbuka suatu hari. Apakah orang ini seorang diktator yang mendominasi Umbraton atau seorang pahlawan yang menyelamatkan Umbraton?]],
  str_item_intro_3400119 = [[
Membuka latar belakang: Ruang Resepsionis.
Dalam ruangan dengan pencahayaan sedang, berbagai barang dan dekorasi tersusun dengan rapi. Ruangan ini dikhususkan untuk bekerja dan menerima tamu.]],
  str_item_intro_3400120 = [[
Membuka latar belakang: Pesona Longzhou.
Sisi barat Twin Pavilions Bay berada di bawah manajemen Umbraton, namun secara budaya, pesona unik Longzhou masih tetap bersinar. Mulai dari lentera yang tergantung di setiap jalan hingga camilan lezat Longzhou, semuanya menampilkan fitur-fitur yang penuh warna dari tanah yang jauh itu, memungkinkan pengunjung di sini untuk sepenuhnya tenggelam dalam budaya dan adat istiadat yang eksotis.]],
  str_item_intro_3400121 = [[
Membuka latar belakang: Pelabuhan Twin Pavilions Bay.
Kapal kargo yang berangkat dari benua Longzhou akhirnya berlabuh di pelabuhan di Twin Pavilions Bay, di mana mereka menyelesaikan perdagangan dan pertukaran barang mereka sebelum kembali. Pelabuhan ini memainkan peran vital dalam pengiriman antara benua Longzhou dan Astra.]],
  str_item_intro_3400122 = [[
Membuka latar belakang: Festival Musim Semi di Kerajaan Ji
Festival Musim Semi adalah festival paling penting di Benua Longzhou. Keluarga kerajaan akan mengadakan pesta untuk tamu-tamu terhormat sementara warga berkumpul untuk bersantai dan berbincang. Di Kerajaan Ji, penduduk setempat mengadakan pameran kuil, memberikan penghormatan kepada Gadis Naga, dan mengusir binatang Nian selama festival, dengan harapan mendapatkan kesehatan dan keberuntungan di tahun yang akan datang. Beberapa pedagang menyewa fiendlings untuk mengadakan pertunjukan bertema ritual pengejaran binatang, menambahkan sentuhan keceriaan di awal tahun baru.]],
  str_item_intro_3400126 = [[
Membuka latar belakang: Pesta Reuni Festival Musim Semi
Di Longzhou, malam Festival Musim Semi adalah waktu untuk berkumpul. Caelestite dan semua temannya di Longzhou telah berkumpul bersama untuk menikmati pesta liburan yang lezat dan beruntung bersama dan berharap semua orang memiliki waktu yang lebih baik di tahun yang akan datang.]],
  str_item_intro_3400123 = [[
Membuka Latar Belakang: Pemandangan Manor.
Dengan lokasi geografis yang unik dan akar budaya yang dalam, manor di Pulau Azurite ini menawarkan pemandangan yang memukau dan daya tarik, menjadikannya tempat peristirahatan favorit bagi Bangsawan Lumo untuk berjalan-jalan dan bersantai.]],
  str_item_intro_3400129 = [[
Membuka latar belakang: Gua Perbatasan
Jauh di dalam gua yang tertutup es, pilar-pilar es menghubungkan kubah ke bumi, menyerupai patung dewa-dewi. Saat aurora turun, pilar-pilar es yang menjulang dan kasar serta bunga-bunga es di dinding gua berkilauan dalam bentuk mereka yang aneh, melengkapi suasana yang serius dan menyeramkan.]],
  str_item_intro_3400130 = "Membuka latar belakang: Perbatasan Bersalju\nPada hari-hari bersalju yang suram, gurun salju yang tampaknya tak berujung ini memiliki akhir—Gunung-gunung tinggi berdiri seperti tembok kota di kejauhan, membagi dunia. Beberapa rumah kecil yang tertutup es dan salju tampak samar di kaki gunung. Hidup di sana pasti dipenuhi dengan kesepian, bukan?",
  str_item_intro_3400133 = [[
Dapatkan untuk membuka latar belakang: Inti Vulkanik Bawah Tanah.
Setelah bertahun-tahun, Rediesel Wrench yang nomaden ini tidak pernah menyadari bahwa gunung berapi di bawah kaki mereka masih penuh dengan kehidupan.]],
  str_item_intro_3400134 = [[
Dapatkan untuk membuka latar belakang: Bulan di Atas Pasir Gurun.
Duduk di gurun di bawah langit malam adalah sekelompok orang yang tidak mungkin. Saat mata mereka berkilau di bawah cahaya bintang, kenangan mereka saling berjalin.]],
  str_item_intro_3400135 = [[
Membuka latar belakang: Spearhead
Struktur internalnya lebih ringkas dan halus dibandingkan dengan Soroz, dan setiap panel kontrol memancarkan aura yang berbahaya.]],
  str_item_intro_3400136 = [[
Membuka latar belakang: Keseruan Api.
Pemberontakan dan ketaatan hanyalah dua jenis kayu bakar yang berbeda. Dengan jumlah panas yang tepat, keduanya akan menyala dan menjadi bola api yang tak terhentikan!]],
  str_item_intro_3400138 = [[
Membuka kunci latar belakang: Kedatangan Parade Kebenaran.
Kamu adalah perwujudan dari kebijaksanaan kolektif True Order. Semua yang kamu alami akan membimbing True Order menuju masa depan yang lebih besar.]],
  str_item_intro_3400139 = [[
Membuka latar belakang: Pantai Pulau Sepi.
Di lautan yang jauh, terdapat sebuah pulau sepi yang terlupakan oleh dunia, dikelilingi oleh biru azure yang tak berujung dan ditutupi oleh vegetasi yang lebat dan rimbun. Puing-puing kuno beristirahat di dalam buaian hijau yang masih asli ini, telah bertahan sepanjang zaman.]],
  str_item_intro_3400140 = [[
Membuka latar belakang: Waveswept Rendezvous.
Pulau itu berbaring diam di dasar laut, bersama dengan bukti kejayaan masa lalunya. Sekarang, petualangan musim panas baru akan dimulai.
Teman yang berdiri di sampingmu adalah harta karun yang paling berharga.
Dalam waktu terbatas yang kamu miliki, nikmati petualangan tanpa akhir ini bersama teman-temanmu!]],
  str_item_intro_3400141 = "Membuka latar belakang: Millennial Yearning.",
  str_item_intro_3400142 = [[
Membuka latar belakang: Bertemu Lagi.
Ketika bintang-bintang mencapai tujuan mereka.
Dia melangkah maju, menuju teman-temannya dan ke dalam sinar matahari.]],
