  str_item_intro_3410501 = "Order Box yang disiapkan oleh Aurorian Coalition. Buka untuk memilih 1 Basic Ascension Material untuk sembarang faction.",
  str_item_intro_3410502 = "Order Box yang disiapkan oleh Aurorian Coalition. Buka untuk memilih 1 Regular Ascension Material untuk sembarang faction.",
  str_item_intro_3410503 = "Order Box yang disiapkan oleh Aurorian Coalition. Buka untuk memilih 1 Advanced Ascension Material untuk sembarang faction.",
