  str_item_intro_3410601 = "Jasper Order Box yang disiapkan oleh Umbraton Guild. Buka untuk memilih 1 Jasper I.",
  str_item_intro_3410602 = "Jasper Order Box yang disiapkan oleh Umbraton Guild. Buka untuk memilih 1 Jasper II.",
  str_item_intro_3410603 = "Jasper Order Box yang disiapkan oleh Umbraton Guild. Buka untuk memilih 1 Jasper III.",
  str_item_intro_3410604 = "Paket yang sebelumnya digunakan oleh Aurorian Coalition. Buka dan pilih 1 hadiah faction yang berharga.",
  str_item_intro_3410605 = [[
Anda telah meninggalkan jejak yang signifikan pada Desolation Codex dan menerima hadiah yang pantas Anda terima.
Terbuka untuk menerima berbagai materi peningkatan acak, ditambah peluang kecil untuk mendapatkan Star Flare!]],
  str_item_intro_3410606 = "Peti harta karun ini adalah bukti ikatan mendalam antara kamu dan anggota Silent Hunter. Buka untuk mendapatkan hadiah menarik.",
  str_item_intro_3410607 = "Peti dengan cetak biru mekanik yang unik, buka untuk mendapatkan 1 Carrier.",
  str_item_intro_3410608 = "Sebuah kotak yang didapatkan dari perayaan meriah yang kacau balau. Isinya masih tidak diketahui. Siapa yang tak suka kejutan?",
  str_item_intro_3410609 = "Paket bingkisan yang dipesan secara khusus. Buka lalu pilih 1 bingkisan berharga.",
  str_item_intro_3410610 = "Rainbow Kotak Pemesanan III. Buka untuk memilih 1 materi kenaikan lanjutan.",
  str_item_intro_3410611 = "Rainbow Kotak Pemesanan IV. Buka pilih 1 bahan Ascension Premium.",
  str_item_intro_3410612 = "Pilih salah satu antara Thunder Solamber Druse, Water Solamber Druse, Forest Solamber Druse, atau Fire Solamber Druse untuk mendapatkannya.",
  str_item_intro_3410613 = "Rainbow Kotak Pemesanan I. Buka untuk memilih 1 bahan kenaikan dasar.",
  str_item_intro_3410614 = "Rainbow Kotak Pemesanan II. Buka untuk memilih 1 bahan kenaikan reguler.",
  str_item_intro_3410615 = "Buka untuk menerima semua Upgrade Material yang diperlukan untuk menaikkan Aurorian ke Ascension III, termasuk: General Jasper II ×300, Nightium ×750.000, Coalition Order Box I ×10, Coalition Order Box II ×10, Coalition Order Box III ×10, Rainbow Order Box I ×30, Rainbow Order Box II ×50, Rainbow Order Box III ×50, dan Rainbow Order Box IV ×20.",
  str_item_intro_3410616 = "Upaya yang Anda lakukan untuk melakukan patroli yang sulit dan pengusiran berbahaya tidak sia-sia. Buka ini dan lihat hadiah apa yang ada di dalamnya!",
