  str_item_intro_3514003 = [[
Meningkatkan level Pencerahan Petir.
Integrasikan kubus misterius yang disediakan oleh Enlightener ke dalam tablet secara mulus untuk mengaktifkan dan mengungkapkan sebagian dari pelatihan pencerahan.]],
  str_item_intro_3514004 = [[
Meningkatkan level Pencerahan Petir.
Integrasikan kubus misterius yang disediakan oleh Enlightener ke dalam tablet secara mulus untuk mengaktifkan dan mengungkapkan bagian penting dari pelatihan pencerahan.]],
  str_item_intro_3514005 = [[
Meningkatkan level Pencerahan Petir.
Tempatkan kubus misterius yang disediakan oleh Enlightener ke dalam tablet secara mulus untuk mengaktifkan dan mengungkap urutan kunci dari pelatihan pencerahan.]],
  str_item_intro_3621001 = "Kursi empuk dengan sandaran tinggi. Mampu menopang punggung dengan baik dan tampak nyaman untuk tidur-tiduran.",
  str_item_intro_3621002 = "Sofa tunggal kecil. Karena tak punya sandaran punggung, mungkin harus ada meja kecil di depannya...",
  str_item_intro_3621003 = "Sofa lebar yang bisa diduduki dua orang, meskipun sangat nyaman pula jika diduduki satu orang saja...",
  str_item_intro_3621004 = "Sofa unik yang bisa diduduki empat orang. Sangat cocok untuk pertemuan besar.",
  str_item_intro_3621005 = "Meja segienam kecil yang biasanya dipakai untuk menaruh minuman, teko, cangkir, dan piring camilan. Paling pas diletakkan di ruang pesta kecil.",
  str_item_intro_3621006 = "Meja teh panjang, biasanya dipadukan dengan loveseat atau sofa 4-seater. Paling pas jika diletakkan di ruang pesta besar.",
  str_item_intro_3621007 = "Perangkat yang otomatis menyajikan minuman, selama diisi dengan bahan-bahan yang tepat. Memang, mana bisa kita membuat kopi hanya dengan gula dan air...",
  str_item_intro_3621008 = "Alat musik yang konon berasal dari suku tak dikenal di negeri nun jauh di sana, awalnya populer di Umbraton. Biasanya terdiri dari satu drum besar, beberapa drum kecil, dan beberapa simbal, serta bisa dilengkapi dengan alat perkusi lainnya. Terlepas dari konfigurasinya, keseluruhan set alat ini dimainkan oleh satu musisi saja.",
  str_item_intro_3621009 = "Tanaman kecil dalam sebuah pot kecil. Membantu memurnikan udara di ruangan dan membuat ruang terasa lebih segar.",
  str_item_intro_3621010 = "Tanaman pot yang setinggi orang, memurnikan udara sekitarnya dan membuat suasana kamar mana pun terasa lebih alami. Juga menjadi tempat persembunyian yang layak.",
  str_item_intro_3622001 = "Lukisan pemandangan yang sangat indah dan rumit. Orang yang melihatnya jadi bisa menghargai keindahan alam tanpa harus keluar dari rumah.",
  str_item_intro_3623001 = "Lampu berbentuk matahari yang bisa digantung di plafon. Namanya berasal dari cahayanya yang kuat dan area cakupannya yang luas.",
  str_item_intro_3623002 = "Plafon indoor yang ringan dan mudah dipasang dengan penopang besi. Bisa ditempeli berbagai macam dekorasi sehingga item ini sangat digemari.",
  str_item_intro_3623003 = "Membuat angin sepoi-sepoi di ruang mana pun. Dulunya dipakai untuk menyalurkan air bersih ke Undercity, dan setelah itu orang juga tahu bahwa item ini ternyata bisa membuat ruangan dingin, segar, serta nyaman.",
  str_item_intro_3623004 = "Lampu yang dipasang di plafon. Digunakan oleh banyak negara kota karena lampu ini hemat energi, area cahayanya luas, dan ukurannya ringkas.",
  str_item_intro_3623005 = "Lampu plafon yang tergantung di plafon. Struktur kuncinya yang dilengkapi engsel membuatnya sangat mudah disetel, tetapi lampu ini akan bergoyang jika terjadi gempa bumi atau cuaca berangin, dan ini bisa jadi sangat berbahaya. Karena alasan itu, jenis lampu seperti ini tidak boleh dipasang di kapal.",
  str_item_intro_3631001 = "Furnishing mewah yang diimpor dari Far East dengan armada yang menguasai lautan. Warna dan gayanya elegan, tetapi teksturnya lembut. Berhati-hatilah saat menaruhnya.",
  str_item_intro_3631002 = "Ikon berbentuk matahari. Senyap dan khidmat, menguatkan iman siapa pun yang melihatnya.",
  str_item_intro_3631003 = "Tong besar dan indah yang dibuat oleh pengrajin legendaris. Hanya wine terbaik yang bisa disimpan dalam wadah seindah ini.",
  str_item_intro_3631004 = "Konon berasal dari Far East, furnitur sederhana tetapi bermanfaat ini bisa digunakan sebagai penahan angin, pembatas ruangan, dan untuk menjaga privasi. Selain itu, furnitur ini juga bisa dihias agar ruang di sekitarnya tampak lebih indah dan pemiliknya bisa merasakan suasana misterius. Langsung populer di kota-kota di Astra.",
  str_item_intro_3631005 = "Alat besar dengan sepuhan ini dihiasi dengan berbagai batu permata yang melambangkan bermacam-macam benda angkasa. Membantu kaum intelektual agar mudah mengenal astrologi dan meramal dengan cepat walau ketepatannya diragukan...",
  str_item_intro_3632001 = "Perangkat komunikasi Illumina Federation yang berasal dari dalam Undercity. Karena komunikasi antara berbagai negara kota meningkat, teknologi khusus ini pun makin banyak digunakan.",
  str_item_intro_3632002 = "Piala sepuhan ini sering terlihat dalam berbagai perayaan di Lumopolis. Penciptanya juga mengisi piala ini dengan Luminatics tak dikenal, sehingga memberinya sepasang sayap ilusi yang bergerak.",
  str_item_intro_3632003 = "Papan timbul ini menggambarkan sejarah kuno peradaban Lumopolis. Konon, setiap pola punya banyak kiasan sastra. Dengan melihatnya saja, kita akan merasakan aura keabadian...",
  str_item_intro_3632004 = "Tempat lilin yang ditingkatkan oleh Luminatics, tidak akan hitam akibat asap, dan bisa secara otomatis menyalakan dan memadamkan lilinnya sendiri.",
  str_item_intro_3632005 = "Jam gantung yang sangat indah yang berasal dari perpaduan harmonis antara mesin Illumina dan keterampilan Lumopolis. Fungsi utamanya adalah sebagai hiasan belaka; kebetulan saja jam ini juga bisa menunjukkan waktu dengan tepat.",
  str_item_intro_3641101 = "Baju armor dekoratif yang merupakan furnishing tradisional di kalangan klan bangsawan Lumopolis, terutama mereka yang punya latar belakang kesatria. Armor ini juga berfungsi untuk mengingatkan keturunan mereka akan kemuliaan warisan perang leluhur dan mencegah perilaku hedonistik dalam keluarga.",
  str_item_intro_3641201 = "Furnishing yang disukai oleh masyarakat Umbraton yang bersikap seperti orang berbudaya. Sebagian besar bagiannya terbuat dari kayu mahal dan menjadi tempat menyimpan buku kuno dan wadah-wadah mahal. Namun, kita perlu mempertanyakan keaslian barang-barang antik ini...",
  str_item_intro_3641301 = "Rak senapan yang dibuat oleh Illumina Federation yang mengisi ruangan mana pun dengan semangat bertempur. Percaya sajalah, hanya pasukan utama yang bertarung melawan Eclipsite sajalah yang bisa menciptakan furnitur semacam ini. Dibandingkan cetak biru terdahulunya, rak senapan ini secara keseluruhan lebih ringan, tetapi lebih stabil.",
  str_item_intro_3641501 = "Miniatur mobil yang dilengkapi dengan pipa, keling, segala jenis pelat logam, bahkan beberapa bagian dari kayu. Model tambal sulam yang kecil ini sangat mirip dengan mobil kebanggaan dan favorit Rediesel Wrench, mobil atap terbuka Powerball.",
  str_item_intro_3641102 = "Permadani yang dibuat dari kain mahal oleh pengrajin terampil dari Lumopolis dengan keahlian hebat. Ini bukanlah permadani yang bisa dibeli semua orang biasa... Selain cukup mahal, ini juga merupakan simbol status.",
  str_item_intro_3641202 = "Permadani besar dan hitam yang dibuat di Umbraton. Halus dan tebal, ditenun dengan sangat baik serta benar-benar meredam langkah kaki.",
  str_item_intro_3641302 = "Permadani berbentuk agak persegi dengan benang horizontal dan vertikal yang rapi dan cukup mencerminkan gaya industrial Illumina Federation. Sekali lihat saja, langsung ketahuan bahwa item ini diproduksi oleh pabrik di Gannon City. Sangat tahan lama.",
  str_item_intro_3641402 = "Permadani tebal dan berat yang ditenun dari sejumlah besar kapas serta bulu binatang dari Northland. Bisa memberikan kenyamanan di lingkungan paling dingin sekalipun.",
  str_item_intro_3641502 = "Orang-orang kasar dari Rediesel Wrench pasti telah menjahit sembarang pakaian usang untuk membuatnya... Bau Rediesel menunjukkan bahwa mereka pasti memakai Rediesel untuk mewarnai permadani ini. Adakah orang yang benar-benar mau mengeluarkan uang untuk membelinya dan menyimpannya di rumah?",
  str_item_intro_3641602 = "Karpet merah yang menarik dengan pola yang sama sekali tidak mencolok. Setelah diamati dari dekat, polanya tampak bergetar dan sedikit berputar, membuat mereka yang melihatnya merasa gelisah dan tidak nyaman... Siapa yang mau membeli karpet semacam ini?",
  str_item_intro_3642102 = [[
Item furnitur. Bisa diletakkan di ruang-ruang di Colossus-mu.
Sebuah mahakarya ciptaan seorang pelukis Lumopolis yang tak dikenal. Yang asli bisa ditemukan dalam koleksi bangsawan berpangkat tinggi, dan yang ini tentu saja adalah replika. Keterampilan melukis yang luar biasa membuat penonton merasa nyaman setelah memandangnya. Itulah mengapa ada banyak sekali salinan yang dibuat. Meski begitu, setiap salinan sangat mahal harganya, dan para pembeli rela berebut untuk memilikinya.]],
  str_item_intro_3642201 = "Pasukan bawah tanah dari Umbraton bertempur secara terbuka maupun tersembunyi. Dua pedang ini digunakan saat mereka mengalami pertikaian yang tidak bisa diselesaikan. Kedua pihak yang bertikai akan menunjuk pendekar pedang untuk berduel dengan pedang ini untuk memutuskan perkara.",
  str_item_intro_3642301 = "Sebagai contoh lain dari kuatnya pengaruh militer dalam furnitur Illumina, senapan ini adalah benda pertama yang muncul di benak penghuni Illumina saat mereka memikirkan dekorasi dinding—sepertinya mereka siap berperang setiap saat.",
  str_item_intro_3642401 = [[
Item furnitur. Bisa diletakkan di ruangan-ruangan di Colossus.
Bahkan di Northland yang dingin pun, ia tetap hijau sepanjang tahun. Oleh karena itu, penduduk setempat menganggapnya sebagai simbol harapan dan kelimpahan, dengan ungkapan, "Tidak ada mistletoe, tidak ada kebahagiaan." Mereka sering mengumpulkan tanaman dan merangkainya menjadi karangan bunga untuk ditaruh di rumah dengan harapan bahwa benda itu akan mendatangkan keberuntungan.]],
  str_item_intro_3641103 = [[
Item furnitur. Bisa diletakkan di ruang-ruang di Colossus-mu.
Item ini melambangkan kekuatan yang dimiliki oleh para pangeran dan bangsawan Lumopolis. Benda yang dihias secara mewah dan terbuat dari logam mulia ini menyiratkan keinginan untuk berkuasa dan melambangkan beban yang dipikulnya.]],
  str_item_intro_3641503 = "Campuran besi tua, lembaran baja, dan paku sumbat dengan bantalan yang entah di mana di atasnya... Meskipun agak kasar dan rusak, ternyata lembut dan kokoh.",
  str_item_intro_3651001 = "Miniatur Spire. Karena ini merupakan replika berkualitas tinggi, item ini tampaknya berisi kekuatan yang terkunci, sama seperti aslinya.",
  str_item_intro_3651002 = "Item ini tampak seperti versi miniatur realistis dari Spire yang asli. Kamu bisa merasakan kekuatan misterius kuno dalam Spire saat mendekatinya.",
  str_item_intro_3651003 = "Hiasan ini hanya bisa didapatkan oleh mereka yang mengeksplorasi level tertinggi Spire. Hiasan ini bukan hanya sangat realistis, tetapi juga memiliki sebagian kekuatan Spire. Saat mereka melihatnya, mereka merasa seakan-akan sedang berdiri di depan Spire yang asli.",
  str_item_intro_3651004 = "Suvenir yang sangat langka ini hanya bisa didapatkan oleh mereka yang menyelidiki Spire. Meskipun hanya model, bentuknya sama persis dengan Spire. Jika kamu teliti mengamatinya, kamu bahkan bisa melihat banyak detail Spire yang asli. Dengar-dengar, ini bisa memengaruhi Spire yang asli...",
  str_item_intro_3651005 = "Sebuah kenang-kenangan misterius yang diberikan dari sebuah menara, dan hanya dapat diperoleh dengan menjelajahi kedalaman menara. Ada yang bilang itu melambangkan kehendak puncak menara dan pengakuan untuk mereka yang cukup berani untuk menjelajahinya.",
  str_item_intro_3651101 = "Miniatur patung kecil Eclipsite yang ditemukan di Secret Territory, mungkin merupakan suvenir yang ditinggalkan oleh penjelajah lain. Kegarangannya tak sengeri aslinya, bahkan tampak agak imut... Setelah kamu terbiasa dengannya.",
  str_item_intro_3651102 = "Patung kecil yang ditemukan di kedalaman Secret Territory ini tampaknya dibuat menyerupai suatu High-Level Eclipsite. Karena wajahnya mengerikan, patung ini bisa menakuti banyak orang sekalipun tidak bergerak. Namun, jika kamu sudah terbiasa, kamu bisa memakainya untuk menakut-nakuti pencuri yang menyelinap ke kamarmu...",
  str_item_intro_3651201 = "Patung kecil yang sangat langka dan tampak sama persis dengan Soroz. Diciptakan dari Luminatics pekat oleh teman-teman Navigator, dan dibuat dengan teknik pembuatan misterius milik Soroz. Melambangkan ikatan yang teguh antara Soroz, Navigator, dan teman-teman mereka.",
  str_item_intro_3662001 = "Setelah menghindari kejaran para Eclipsite, untuk memperingati saat pertama kali semua orang saling bertemu, Soroz secara khusus meminta Firefly untuk menggambar lukisan gantung ini berdasarkan gambar yang terekam olehnya. Hampir semua orang mengiranya foto karena hasilnya tampak sangat realistis.",
  str_item_intro_3661101 = "Batu yang ditemukan di Red-Eye Gorge dan berisi sejumlah kecil kekuatan gunung berapi dan terasa panas ketika disentuh. Sesekali, batu ini mengeluarkan suara gemuruh atau erupsi kecil, tetapi tidak terlalu berbahaya. Mereka yang berani mungkin bisa memakainya untuk memasak makanan atau daging barbeku.",
  str_item_intro_3661102 = "Dawn flower putih Dawn ditanam di Red-Eye Gorge, yang hanya mekar sekali setiap beberapa tahun. Bunga ini sangat indah, dan bahasa bunganya berarti \"harapan fajar.\"",
  str_item_intro_3662101 = "Karena penyakitnya, Eve hanya bisa minum air dingin yang suhunya sekitar 15 derajat, dan air panas yang suhunya sekitar 45 derajat. Di Rediesel Desert, yang langka air, Sinsa selalu membawa dua botol termos agar adik kecilnya itu bisa minum sewaktu-waktu. Dia bahkan menggambar smiley face di botolnya itu agar adiknya senang.",
  str_item_intro_3661103 = "Meskipun dojonya tak ada lagi, rak katana Sakae Dojo masih bagus. Bersihkan debunya dan letakkan beberapa katana di dalamnya untuk mengingat kejayaan masa lalu Sakae Dojo.",
  str_item_intro_3661104 = "Pohon ceri yang langka dan berwarna-warni ini hanya ditemukan di daerah sekitar Cloud Mountain. Banyak orang suka meletakkan persembahan di sana sebagai bentuk doa agar keinginan mereka terkabul.",
  str_item_intro_3662102 = "Lukisan eksotis tentang seekor naga yang sedang menari sambil memamerkan taring dan cakarnya. Namun, alih-alih membuat orang takut, lukisan ini justru memberikan rasa aman yang tidak bisa dijelaskan. Mungkin ini berhubungan dengan budaya Far East yang unik.",
  str_item_intro_3661105 = "Daruma yang populer di wilayah Cloud Mountain. Menyimpannya di rumah akan mendatangkan keberuntungan. Benda ini bahkan mungkin mengabulkan permintaan pemiliknya.",
  str_item_intro_3661106 = "Daruma yang kelihatan agak bengis. Simpan di rumah untuk menangkal kesialan dan mencegah kedatangan penjahat.",
  str_item_intro_3661107 = "Daruma yang sesekali bersinar dengan cahaya keemasan. Kamu hampir bisa melihat keberuntungan menghampiri ketika melihatnya—yah, semoga begitu.",
  str_item_intro_3661108 = "Daruma yang melambangkan pengetahuan. Konon, daruma ini membawa keberhasilan akademis sehingga banyak sekali siswa yang berdoa agar memperolehnya. Mungkin benda ini akan sangat populer di Gannon City.",
  str_item_intro_3661109 = "Konon, semua orang akan menemukan daruma yang paling cocok untuk mereka. Boneka ini akan mengabulkan harapan terbesarmu dan memberkatimu seumur hidup.",
  str_item_intro_3661110 = [[
Item furniture. Bisa ditempatkan di ruangan-ruangan di Colossus kamu.
Sebuah model kastel besar di tepi laut yang menangkap aura misterius dan aneh dengan sangat baik. Suara samar-samar kadang terdengar dari dalam dindingnya, yang tidak sepenuhnya berbeda dengan legenda kuno yang mengelilingi struktur ini.]],
  str_item_intro_3661111 = [[
Item furniture. Bisa ditempatkan di ruangan-ruangan di Colossus-mu.
Setelah mempelajari teknologi Soroz, Fleur menciptakan mesin yang disebut "Rediesel Steel MkV Zero", yang merupakan modelnya. Dibandingkan dengan mesin yang sebenarnya, model ini menawarkan kinerja yang jauh lebih baik dan bisa dikatakan sempurna, kecuali ukurannya yang sangat kecil.]],
  str_item_intro_3661112 = "Item furniture. Bisa ditempatkan di ruangan-ruangan di Colossus-mu.\nGerobak yang dibuat untuk mendapatkan uang tambahan selama musim panas. Berisi peralatan khusus untuk membuat es batu dan menghancurkannya menjadi es serut, menyajikan suguhan sejuk di hari musim panas kepada pelanggan yang beruntung. Meskipun musim es serut sudah berakhir, peralatan di gerobak masih bisa digunakan, dan kadang-kadang bekerja dengan sendirinya—indikasi yang jelas bahwa mesin ini menganggap dirinya masih terlalu muda untuk pensiun.",
  str_item_intro_3661113 = [[
Item furniture. Bisa ditempatkan di ruangan-ruangan di Colossus-mu.
Sofa tiup yang diproduksi oleh Tir' Hotel. Dilengkapi dengan pistol air di bagian belakang, yang menyemprotkan air secara berkala, membuat semua orang merasa sejuk dan segar di bawah terik matahari musim panas.]],
  str_item_intro_3661114 = [[
Item furniture. Bisa ditempatkan di ruangan-ruangan di Colossus-mu.
Sofa tiup yang diproduksi oleh Tir' Hotel. Alat penyemprot di belakang bantalnya dapat menghasilkan semprotan seperti air mancur secara berkala. Meskipun memberikan kenyamanan lebih, air mancurnya sangat kuat, terkadang membuat takut orang-orang yang duduk di atasnya.]],
  str_item_intro_3661115 = [[
Item furniture. Bisa ditempatkan di ruangan-ruangan di Colossus-mu.
Sofa tiup yang diproduksi oleh Tir' Hotel. Tangani dengan hati-hati karena ada detonator kembang api otomatis yang terpasang di bagian belakangnya. Setelah diaktifkan, sofa ini akan meluncurkan beragam kembang api sehingga menyajikan pertunjukan kembang api mini kepada semua yang berada di sekitarnya. Sudut peluncurannya memastikan bahwa orang-orang yang duduk di atasnya terhindar dari bahaya, tetapi bukan berarti itu tidak akan membuat mereka ketakutan.]],
  str_item_intro_3661116 = [[
Item furniture. Bisa ditempatkan di ruangan-ruangan di Colossus-mu.
Sofa tiup yang diproduksi oleh Tir' Hotel. Pegangan di kedua sisi sebenarnya adalah mesin gelembung. Setelah diaktifkan, gelembung yang berwarna-warni memenuhi udara sehingga membuatnya sangat populer di kalangan anak-anak.]],
  str_item_intro_3661117 = [[
Item furniture. Bisa ditempatkan di ruangan-ruangan di Colossus-mu.
Sofa air portabel yang diproduksi oleh Tir' Hotel. Setelah membuka lipatan sofa ini, kamu bisa menghiasnya dengan aksesori pohon kelapa. Setelah terisi air, sofa ini akan membuat tiap harinya terasa seperti hari di tepi pantai.]],
  str_item_intro_3661118 = [[
Item furniture. Bisa ditempatkan di ruangan-ruangan di Colossus-mu.
Papan selancar yang diproduksi oleh Tir' Hotel. Terbuat dari material khusus sehingga menghasilkan papan yang ringan, tahan lama, dan kokoh. Dengan bentuk aquadynamic yang dibuat dengan ahli, papan selancar ini mampu menjinakkan ombak apa pun.]],
  str_item_intro_3662103 = [[
Item furniture. Bisa ditempatkan di ruangan-ruangan di Colossus-mu.
Suvenir saat kamu berkunjung ke festival Ocean Sovereign. Saat menatap laut dan langit yang biru, serta pantai dengan pepohonan hijau yang melambai, seolah-olah kamu kembali ke tepi pantai, mengingat-ingat kembali hari bahagia itu.]],
  str_item_intro_3661119 = [[
Item furniture. Bisa ditempatkan di ruangan-ruangan di Colossus-mu.
Undercity 24 adalah salah satu markas penting dari Dunefire Line, dan menangani sebagian besar logistik, pelatihan, serta operasi medis garda depan, di antara tugas-tugas lainnya. Model miniatur ini dengan sempurna mencerminkan sifatnya yang komprehensif.]],
  str_item_intro_3661120 = [[
Item furniture. Bisa ditempatkan di ruangan-ruangan di Colossus-mu.
Meja pasir ini dulunya digunakan untuk keperluan internal di Illumina Federation Military Academy. Benda ini dipetakan satu demi satu oleh surveyor khusus dan kemudian diperkecil. Meja yang terdiri dari pasir, kayu, dan patung-patung ini secara akurat menyimulasikan situasi strategis dari medan tempur yang sebenarnya sehingga para siswa bisa melakukan latihan komando perang di berbagai kondisi pertempuran.]],
  str_item_intro_3661121 = [[
Item furniture. Bisa ditempatkan di ruangan-ruangan di Colossus-mu.
Badan utama papan pengumpul medali ini terbuat dari pelat besi yang ditandai dengan banyak lubang. Konon, benda ini merupakan penghargaan atas keberanian Stone Forces melawan Eclipsite sekaligus simbol kejayaan abadi mereka. Medali yang tergantung darinya menunjukkan bahwa Stone Forces tidak pernah jauh dan akan selamanya berdiri tegap di Defensive Line bersama setiap prajurit generasi baru untuk menahan ancaman Eclipsite.]],
  str_item_intro_3662104 = "Item furniture. Bisa ditempatkan di ruangan-ruangan di Colossus-mu.\nInterior Illumina Federation secara khusus memberikan spanduk ini kepada para prajurit Dunefire Line sebagai pujian atas keberhasilan mereka dalam memukul mundur invasi Eclipsite berskala besar. Setiap kali para prajurit itu melihat spanduk ini melambai di garis pertahanan, rasa hormat yang ditanamkan mengingatkan mereka akan keyakinan yang khusyuk—Di mana pun kalian menghadapi bahaya, kami akan selalu ada.",
  str_item_intro_3661122 = "Jangan khawatir—tidak ada jasad yang dikubur di sini, kok. Jadi, bisa dibilang ini bukan pusara. Apa? Tangan itu? Oh, itu hanya properti pertunjukan!",
  str_item_intro_3661123 = "Muncul jika kamu tidak mau memberikan Nightium! Yah, dia tidak bisa bicara, lho. Sebenarnya dia bukan hantu sungguhan—hanya ayam yang sembunyi di balik seprai.",
  str_item_intro_3662105 = "Sebenarnya, lampu ini terbuat dari panel kayu yang diukir berbentuk labu. Saat dinyalakan, cahaya akan bersinar dari mata, hidung, dan mulutnya sehingga menciptakan suasana yang agak menakutkan.",
  str_item_intro_3661124 = "Menara tinggi yang berwarna putih dari atas sampai bawah dengan bentuk puncak lurus sempurna ini berfungsi sebagai simbol Eraveil. Model istimewa ini mengembalikan penampilan monumen yang membanggakan itu dengan sempurna.",
  str_item_intro_3661125 = "Boneka berbentuk pemuda Caelestite. Mainan ini terlihat menggemaskan jika kamu menaruhnya di atas tanah—dan sepertinya kunang-kunang pun sangat menyukainya.",
  str_item_intro_3661126 = "Bunga dandelion dalam pot. Walau bunganya kelihatan sangat rapuh, bunga yang tahan banting ini bisa bertahan hidup di mana pun selama ada air dan tanah.",
  str_item_intro_3661127 = [[
Item Furniture. Bisa diletakkan di ruangan-ruangan di Colossus-mu.
Ini hanya model? Bukan, ini adalah dunia mini! Selain kereta api bergerak, item ini juga menampilkan lanskap alam yang realistis, termasuk gunung, sungai, dan pepohonan! Lihat sejenak kereta api model yang meliuk-liuk di sekitar gunung, kamu akan merasa seperti menjadi bagian dari dunia mini ini, menikmati pemandangan yang indah.]],
  str_item_intro_3661128 = [[
Item Furniture. Bisa diletakkan di ruangan-ruangan di Colossus-mu.
Kini kamu juga bisa memandangi pepohonan musim gugur yang indah di Colossus! Entah bagaimana, tanaman bonsai ini tetap mempertahankan warna musim ini sepanjang tahun. Daunnya yang kuning sesekali jatuh, memungkinkanmu untuk menikmati kesemuan menyedihkan melankolis dari musim gugur kapan saja dan di mana saja, meski Firefly jadi sibuk membersihkannya.]],
  str_item_intro_3661129 = "Item Furniture. Bisa diletakkan di ruangan-ruangan di Colossus-mu.\nKembang ini selalu menghadap matahari! Lihatlah tanaman pot kecil positif ini—letakkan di kamarmu dan perhatikan saat ia dipenuhi dengan kehangatan dan optimisme.",
  str_item_intro_3661130 = [[
Item Furniture. Bisa diletakkan di ruangan-ruangan di Colossus-mu.
Sabuk emas lambang kehormatan dan bukti darah, keringat, dan air mata yang kamu kucurkan di Underground Arena Umbraton. Meski kamu keberatan jika ada sembarang orang yang menyentuhnya, tidak apa-apa jika mereka mengaguminya dari kejauhan.]],
  str_item_intro_3661131 = [[
Item Furniture. Bisa diletakkan di ruangan-ruangan di Colossus-mu.
Transaksi wajar harus adil bagi kedua belah pihak. Sebagai simbol penimbangan barang, timbangan berlapis emas ini melambangkan konsep keadilan yang diakui oleh kedua belah pihak. Inilah sebabnya item ini kerap ditempatkan di aula guild Umbraton untuk menunjukkan kepada tamu bahwa transaksi mereka adil dan jujur.]],
  str_item_intro_3662106 = [[
Item Furniture. Bisa diletakkan di ruangan-ruangan di Colossus-mu.
Kipas yang dipenuhi budaya asing. Terbuat dari kertas yang lembut, tetapi kokoh. Lukisan pada kipas ini mengungkapkan gaya eksotis yang jarang terlihat di belahan dunia ini.]],
  str_item_intro_3662107 = [[
Item furnitur. Bisa diletakkan di ruang-ruang di Colossus-mu.
Mosaik kaca patri ciptaan seorang perajin Lumopolis yang melampaui keindahan alam itu sendiri. Saat cahaya menyinarinya, benda ini memantulkan warna-warna cerahnya sehingga terlihat indah dan memesona.]],
  str_item_intro_3661132 = [[
Item furnitur. Bisa diletakkan di ruangan-ruangan di Colossus.
Konon, seekor naga es pernah berpatroli di langit Northland. Namun, kini ia tidak berbahaya karena hanya merupakan patung belaka. Ia juga memancarkan jejak udara dingin yang indah. Nyaman sekali!]],
  str_item_intro_3661133 = [[
Item furnitur. Bisa diletakkan di ruangan-ruangan di Colossus.
Rak dan jubahnya memang tampak biasa saja, tetapi menurut beberapa tetua di Northland, ada kisah yang aneh di baliknya...]],
  str_item_intro_3661134 = [[
Item furnitur. Bisa diletakkan di ruangan-ruangan di Colossus.
Menurut cerita rakyat Northland tertentu, kamu akan menemukan cinta sejatimu jika mengenakannya!]],
  str_item_intro_3661135 = [[
Item furnitur. Bisa diletakkan di ruangan-ruangan di Colossus.
Jenis paling umum di Northland. Bahkan asap yang sesekali keluar dari cerobong asap di atap yang penuh salju pun juga turut direplika. Kilauan di jendela memberi kesan bahwa rumah miniatur itu memang berpenghuni.]],
  str_item_intro_3662109 = [[
Item furnitur. Bisa diletakkan di ruangan-ruangan di Colossus.
Kepala rusa, tetapi bukan yang asli. Benda ini sebenarnya adalah boneka bulu yang diisi dengan serpihan kayu, dan memiliki mekanisme spesial untuk membuat matanya bergerak sesekali!]],
  str_item_intro_3661136 = [[
Furnitur untuk ruangan di Colossus.
Tidak ada ekspresi cinta yang lebih besar dari memasak dan menyajikan bagian tubuhmu sendiri. Mengingat distribusi lemak yang merata, Tohru sangat percaya diri dengan betapa lezatnya rasa ekornya. Dia juga ahli memanggang, karena sering latihan, sekarang jadi sempurna. Namun, tetaplah berhati-hati karena beracun.]],
  str_item_intro_3661137 = [[
Furnitur untuk ruangan di Colossus.
Kerajinan tangan spontan dari Tohru. Bagi naga, seni manusia berada di luar pemahaman, karena subjek dan prosedurnya terlalu disederhanakan. Tohru meniru karya orang lain dalam menciptakan ukiran kayu ini. Dia tidak peduli apa tujuannya, selama itu dihargai.]],
  str_item_intro_3662110 = [[
Furnitur untuk ruangan di Colossus.
Groupfie itu wajib di semua perjalanan yang beramai-ramai! Ayo berdiri berdekatan... Susah juga dapat lima naga dalam satu jepretan... Bilang "Cheese"!]],
  str_item_intro_3661138 = [[
Item furnitur. Bisa diletakkan di ruang di Colossus-mu.
Sebuah piano yang ditemukan di Lost City. Meskipun memiliki gaya yang mirip dengan beberapa piano di Astra, piano ini dibuat dengan sangat baik dan masih menghasilkan suara yang indah bahkan setelah bertahun-tahun. Bahkan walau suaranya agak kurang pas, piano ini masih bisa disetel sesuai dengan struktur internalnya yang unik! Sungguh permata yang langka bagi para musisi!]],
  str_item_intro_3661139 = [[
Item furnitur. Bisa diletakkan di ruang di Colossus-mu.
Sebuah karya sederhana yang entah bagaimana berbeda dengan gaya sederhana Illumina yang biasa. Dengan tekstur halus yang unik dan cetak biru yang indah, bahkan mereka yang berasal dari Lumopolis pun akan menyukainya.]],
  str_item_intro_3661140 = [[
Item furnitur. Bisa diletakkan di ruang di Colossus-mu.
Sebuah karpet yang ditemukan di Lost City. Tidak hanya terbuat dari bahan yang sangat spesial, polanya yang berpotongan dan berbentuk berlian membuatnya makin mencolok.]],
  str_item_intro_3661141 = [[
Item furnitur. Bisa diletakkan di ruang di Colossus-mu.
Benda yang mudah ditemukan di jalan-jalan Lost City ini hampir sama seperti lampu jalan, menjadikannya pengganti yang menggiurkan untuk rambu-rambu jalan... Layarnya menampilkan kumpulan pola yang terus berkedip, dan tidak mungkin untuk mengetahui apa yang ada di dalamnya. Sepertinya satu-satunya cara untuk mengetahuinya adalah dengan memecahkannya.]],
  str_item_intro_3661142 = [[
Item furnitur. Bisa diletakkan di ruang di Colossus-mu.
Kotak surat yang ditemukan di Lost City. Karena ukiran di atasnya telah memudar, awalnya benda ini dikira kotak penyimpanan kecil untuk ransum darurat. Baru setelah mereka menemukan surat di dalamnya, orang-orang menyadari bahwa itu adalah kotak surat. Namun, sepertinya tidak ada yang masih menggunakannya.]],
  str_item_intro_3661143 = [[
Item furnitur. Bisa diletakkan di ruang di Colossus-mu.
Instalasi umum yang diletakkan di pinggir jalan-jalan di Lost City agar orang yang lewat bisa beristirahat. Nah, jika diletakkan di rumah, benda ini bisa digunakan untuk duduk dan berbaring.]],
  str_item_intro_3661144 = [[
Item furnitur. Bisa diletakkan di ruang di Colossus-mu.
Setelah bertahun-tahun, secara ajaib benda ini masih utuh! Teknologi di Lost City sungguh mencengangkan. Sehelai kertas yang diletakkan akan segera diiris menjadi potongan-potongan tipis sehingga pesan apa pun yang ada di atasnya jadi tak bisa dipahami.]],
  str_item_intro_3661145 = [[
Item furnitur. Bisa diletakkan di ruang di Colossus-mu.
Benda ini masih dalam kondisi yang luar biasa setelah bertahun-tahun... tetapi sudah tidak digunakan lagi. Setelah sedikit ditata, terlihat permukaan meja yang bersih dan rapi serta segala jenis perlengkapan kantor yang mengisi kantor dengan energi.]],
  str_item_intro_3661146 = [[
Item furnitur. Bisa diletakkan di ruang di Colossus-mu.
Selain bisa berputar dengan menyenangkan, ketinggian kursi ini juga bisa disesuaikan, sandarannya bahkan bisa diturunkan sehingga penggunanya dapat berbaring dengan nyaman untuk memejamkan mata sejenak. Bicara soal suasana, menempatkannya dengan meja akan menciptakan rasa harmoni nan luar biasa yang membuat seseorang mampu berlama-lama di tempat kerja sampai lupa waktu.]],
  str_item_intro_3661147 = [[
Furnitur yang bisa ditempatkan di ruang-ruang di Colossus.
Sebuah ornamen dari Far East yang terbuat dari bambu yang membutuhkan air mengalir. Karena mekanismenya yang kreatif, ornamen ini bisa mengeluarkan bunyi "duk" yang menyegarkan dan menyenangkan secara berkala, yang juga berfungsi sebagai pengatur waktu.]],
  str_item_intro_3661148 = [[
Furnitur yang bisa ditempatkan di ruang-ruang di Colossus.
Tanaman bambu yang tumbuh dengan cepat dan membutuhkan pemangkasan teratur. Meski sedikit merepotkan, kamu bisa mendapatkan berton-ton bambu darinya. Suara gemeresik saat daunnya tertiup angin juga menyegarkan.]],
  str_item_intro_3663001 = [[
Furnitur yang bisa ditempatkan di ruang-ruang di Colossus.
Sebuah boneka yang tergantung di bawah atap. Boneka ini mudah dibuat dan sangat lucu. Ia akan turut menari bersama angin yang bertiup, seolah-olah berdoa agar hujan segera pergi. Jika berhasil, berarti surga melihat tarian mereka!]],
  str_item_intro_3661149 = [[
Furnitur yang bisa ditempatkan di ruang-ruang di Colossus.
Sebuah helm yang dikenakan oleh prajurit Far East. Benda ini berhiaskan ornamen berlebihan yang konon tidak hanya mewakili kekuatan atau klan dari prajurit, tetapi yang lebih penting, simbol kehormatan.]],
  str_item_intro_3661150 = [[
Furnitur yang bisa ditempatkan di ruang-ruang di Colossus.
Awalnya, itu adalah bendera yang dipasang oleh tentara atau samurai di punggung mereka untuk memandu pasukan di belakang dalam pertempuran. Ketika dipasang di rumah, bendera ini memberikan perasaan khidmat.]],
  str_item_intro_3662111 = [[
Furnitur yang bisa ditempatkan di ruang-ruang di Colossus.
Kaligrafi Far East populer yang biasanya ditulis oleh para kaligraf, tetapi tentu saja kebanyakan hanya salinan. Kata-kata ini memiliki keindahan khusus di mata rakyat Far East dan hampir tidak mungkin dihargai oleh orang luar.]],
  str_item_intro_3661151 = [[
Furnitur yang bisa ditempatkan di ruang-ruang di Colossus.
Meski disebut "lanskap", kata "layu" di bagian depan menunjukkan bahwa lanskap miniatur ini sesungguhnya tidak memiliki air, melainkan menggunakan pasir halus untuk mewakili air dan batu di pegunungan berbatu. Di Far East, lanskap statis semacam ini diyakini dapat membantu seseorang bermeditasi dan menenangkan pikiran.]],
  str_item_intro_3661152 = [[
Furnitur yang bisa ditempatkan di ruang-ruang di Colossus.
Lampu jalan yang dihias dengan gaya Far East yang biasa ditemukan di Cloud Island. Penduduk setempat tidak hanya menggunakannya untuk penerangan, tetapi juga sebagai rambu-rambu jalan.]],
  str_item_intro_3663002 = [[
Furnitur yang bisa ditempatkan di ruang-ruang di Colossus.
Penduduk setempat Koufu-jou menggantungnya di pintu mereka sebagai penerangan, dan lentera dari setiap rumah membuat jalanan seterang siang hari. Orang-orang juga menggunakannya dengan tiang bambu untuk menerangi jalan di malam hari.]],
  str_item_intro_3661159 = [[
Item furnitur. Bisa diletakkan di ruangan-ruangan di Colossus.
Sebuah tombak diberikan kepada Carleen ketika dia dinobatkan sebagai seorang kesatria. Benda itu kemudian menjadi senjata pertempuran eksklusifnya. Meskipun hanya replika, benda ini tetap memancarkan kekuatan Moon Cocoon saat diletakkan di rumah...]],
  str_item_intro_3662116 = "Item furnitur. Bisa diletakkan di ruangan-ruangan di Colossus-mu.\nDekorasi favorit produser ternama—Tourdog. Dia berujar bahwa selama papan genta ini tergantung di dindingnya, suara papan beradu nyaring yang kerap dia dengar terus menumbuhkan motivasinya untuk memulai hari kerja baru. Semua orang yang menyaksikan ketekunannya dalam bekerja turut terdorong untuk bekerja keras juga.",
  str_item_intro_3661153 = [[
Item furnitur. Bisa diletakkan di ruangan-ruangan di Colossus.
Sering digunakan sebagai aksesori tarian pemandu sorak saat balapan. Namun, seseorang memodifikasi item ini dengan memasang komponen yang aneh agar bisa memandu sorak sendiri. Mungkin pada awalnya kau akan menganggap item ini aneh, tapi, setelah terbiasa, item ini akan cukup menghibur.]],
  str_item_intro_3661154 = [[
Item furnitur. Bisa diletakkan di ruangan-ruangan di Colossus.
Ban bekas mobil balap yang didaur ulang dan ditumpuk hingga membentuk kursi. Tampak sederhana, tapi sangat empuk untuk diduduki.]],
  str_item_intro_3662112 = [[
Item furnitur. Bisa diletakkan di ruangan-ruangan di Colossus.
Bendera yang konon digunakan sebagai garis finis Blazing Rally. Peserta balapan gemar membawa pulang bendera ini untuk digantung sebagai dekorasi atau dipasang di mobil sebagai kenang-kenangan.]],
  str_item_intro_3661155 = [[
Item furnitur. Bisa diletakkan di ruangan-ruangan di Colossus.
Setiap tahunnya, hampir seluruh anggota Rediesel Wrench akan turut serta dan berkompetisi dalam balapan yang mereka selenggarakan sendiri, menarik penonton dari berbagai lapisan masyarakat. Piala ini membuktikan performa menakjubkan pemiliknya saat balapan.]],
  str_item_intro_3661156 = [[
Item furnitur. Bisa diletakkan di ruangan-ruangan di Colossus.
Tanaman yang biasanya hanya tumbuh di gurun, tahan iklim dingin dan kering yang ekstrem. Di antara semua tanaman hias yang tangguh di segala cuaca, tanaman ini tidak perlu sering disiram. Awas durinya tajam!]],
  str_item_intro_3662113 = "Item furnitur. Bisa diletakkan di ruangan-ruangan di Colossus. Meski disebut sebagai \"ban penyalur energi\", ban ini hanyalah ban mobil balap biasa. Namun, jika digantung sebagai hiasan dinding, ban ini memberikan suasana balapan yang penuh semangat dan kegembiraan di ruangan.",
  str_item_intro_3661157 = "Item furnitur. Bisa diletakkan di ruangan-ruangan di Colossus.\nMenurut anggota True Order, gulungan ini pertama kali ditemukan di reruntuhan kuno. Meskipun tidak bertuliskan apa-apa, anggota True Order mampu melihat Revelation dalam gulungan ini…",
  str_item_intro_3642602 = "Item furnitur. Bisa diletakkan di ruangan-ruangan di Colossus.\nDilukis oleh anggota True Order tak dikenal yang menasbihkan bahwa dirinya pernah melihat Truth of the World sebelum ditinggalkan dan raib tak bersisa. Meskipun banyak orang meragukan pengakuannya, tak bisa dimungkiri bahwa lukisan aneh ini memancarkan aura yang memikat…",
  str_item_intro_3661158 = "Item furnitur. Bisa diletakkan di ruangan-ruangan di Colossus.\nTak terpisahkan, sempurna, bisa berputar, nyata, unik… Anggota True Order memiliki pemahaman berbeda akan pola, tapi mereka semua percaya bahwa menggunakan bintang bersudut tujuh sebagai alas dapat membantu mereka melihat kebenaran sejati…",
  str_item_intro_3662115 = [[
Item furnitur. Bisa diletakkan di ruangan-ruangan di Colossus.
Bukit pasir! Mobil balap! Blazing Rally mengundang pembalap yang paling berani, tak terkalahkan, dan panjang akal untuk beradu kecepatan! Hingga kau merasa senang! Hingga dunia berakhir!]],
  str_item_intro_3661169 = [[
Item furnitur. Bisa diletakkan di ruang di Colossus.
Sepotong kecil mesin yang digerakkan oleh kekuatan misterius yang berputar tanpa henti saat sedikit didorong. Konon, benda ini akan terus berputar hingga akhir dunia jika tidak dihentikan.]],
  str_item_intro_3661170 = [[
Item furnitur. Bisa diletakkan di ruang di Colossus.
Gerbang yang dulunya terpasang di Cloud Gardens. Gerbang ini berkelas dan cocok untuk dekorasi di tempat lain.]],
  str_item_intro_3661162 = [[
Item furnitur. Bisa diletakkan di ruang di Colossus.
Siapa pun yang mampu mengeluarkan susunan tulang ikan yang utuh dan menyusunnya dengan rapi pasti memiliki pengetahuan yang mendalam tentang ikan. Ornamen tulang ikan ini bukan hanya sebagai hiasan, melainkan juga wujud dari keahlian pembuatnya.]],
  str_item_intro_3662117 = [[
Item furnitur. Bisa diletakkan di ruang di Colossus.
Kepiawaian si nelayan bisa ditaksir dari cetakan ikannya. Ikan berukuran sebesar ini pasti menimbulkan gelombang ombak yang dahsyat saat mengibaskan ekor dan siripnya untuk membebaskan diri. Si nelayan mungkin harus beradu tenaga dengan ikan ini untuk waktu yang cukup lama sebelum akhirnya berhasil menangkapnya dan memutuskan untuk menyimpan hasil cetakannya sebagai suvenir.]],
  str_item_intro_3661163 = [[
Item furnitur. Bisa diletakkan di ruang di Colossus.
Sebuah kursi yang terbuat dari tunggul bundar, permukaannya kasar dan cincin pertumbuhannya terlihat jelas. Furnitur ini menambah nuansa unik khas hutan belantara ke ruangan.]],
  str_item_intro_3661164 = [[
Item furnitur. Bisa diletakkan di ruang di Colossus.
Konon, karpet yang berhiaskan pola garis dan bentuk geometri ini pernah digunakan oleh bangsa Caelestite. Sebagian orang bilang polanya menyerupai bagian menara jika dilihat cukup lama, sementara menurut yang lain polanya menyerupai langit. Memang karpet yang misterius.]],
  str_item_intro_3661165 = "Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.\nModel kendaraan dari dunia lain.\nTampaknya objek yang sangat akrab dengan Phantom Thieves of Hearts.\nMona melihatnya dengan senyum puas—atau hanya imajinasimu saja?",
  str_item_intro_3661166 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Boneka mainan iblis dari dunia lain.
Bentuknya agak seperti manusia salju, itulah sebabnya orang-orang menyukainya.
Apakah Anda mendengar itu? Kedengarannya seperti seseorang mengatakan "hee-ho."]],
  str_item_intro_3661167 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Perangkat misterius ditemukan di reruntuhan kuno. Dikatakan bisa menggoreng makanan dan bahkan memiliki kemampuan membumbui! Ini adalah barang langka dan berharga sehingga banyak yang berpartisipasi dalam kompetisi Raja Keranjang Makanan untuk mendapatkan kesempatan mendapatkannya...]],
  str_item_intro_3661168 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Masukkan minyak, biji-bijian yang dikuliti, dan bumbu-bumbu, biasanya gula, dan biji-bijian yang dikuliti akan mulai mengembang setelah mesin diaktifkan, membuat camilan yang enak. Sayangnya, ini hanya hiasan yang tidak bisa digunakan ...]],
  str_item_intro_3661160 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Suatu keharusan di semua taman hiburan! Anak-anak menyukainya! Tentu saja, ini agak kecil... Ini hanya bisa digunakan sebagai hiasan.]],
  str_item_intro_3661161 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Ini jungkat-jungkit! Sebuah jungkat-jungkit! Tapi sepertinya itu dibangun untuk hewan kecil. Kunang-kunang di atas Colossus menyukainya. Anda sering dapat melihat mereka melompat-lompat, berlatih mengoordinasikan gerakan mereka.]],
  str_item_intro_3661001 = "Item furnitur. Bisa ditempatkan di kamar di Colossus kamu.\nSaat dipompa penuh, cincin renang ini terlihat seperti... Eclipsite yang kuat?! Oh... Omong-omong, itu hanya cincin renang dan warnanya merah muda. Kelihatannya tidak begitu menyeramkan—sebenarnya, lumayan manis.",
  str_item_intro_3661002 = [[
Item furniture. Bisa ditempatkan di ruangan-ruangan di Colossus-mu.
Awalnya diproduksi dan dijual di Illumina Federation, item ini dicat ulang di sebuah kota kecil untuk menghadirkan suasana musim panas. Setelah dicat, item ini ternyata menghasilkan angin yang lebih sejuk dari sebelumnya!]],
  str_item_intro_3661003 = [[
Item furniture. Bisa ditempatkan di ruangan-ruangan di Colossus-mu.
Rambu pangkalan dari Lumopolis Shuttle Hub ini terlihat kokoh dan tahan lama secara misterius dan tetap bebas karat setelah bertahun-tahun terkena sinar matahari dan hujan. Warnanya yang sederhana dan desainnya yang bergaya menjadikannya suvenir sempurna dari perjalanan panjang ke Lumopolis.]],
  str_item_intro_3661004 = [[
Item furniture. Bisa ditempatkan di ruangan-ruangan di Colossus-mu.
Meski tidak bisa memberimu kekuatan sungguhan, mahkota ini adalah tanda seseorang yang benar-benar menarik. Benda ini pernah dihadiahkan kepada pemenang ajang Miss Umbraton. Permatanya yang luar biasa cocok dengan keindahannya yang menakjubkan dan meninggalkan kesan yang mendalam pada semua orang.]],
  str_item_intro_3661005 = [[
Item furniture. Bisa ditempatkan di ruangan-ruangan di Colossus-mu.
Topi ini sangat populer di daerah gurun. Karena bagian tepinya sangat lebar, benda ini bisa memberikan perlindungan dari angin dan pasir. Orang-orang yang tinggal di dan sekitar gurun sering mengenakan jubah, topi ini, dan topeng selama festival tertentu. Mereka menyanyi dan menari untuk para pendatang sebagai cara memperkenalkan budaya di kampung halaman.]],
  str_item_intro_3661006 = [[
Item furniture. Bisa ditempatkan di ruangan-ruangan di Colossus-mu.
Semula "bean bag" merupakan makanan lezat dari daerah gurun dan terbuat dari kacang abadi asli daerah tersebut. Konsep ini akhirnya terbawa ke ranah pembuatan furnitur. Menurut para penduduk setempat, menambahkan ekspresi imut pada bean bag akan membuat orang makin ingin mendudukinya.]],
  str_item_intro_3661007 = [[
Item Furniture. Bisa diletakkan di ruangan-ruangan di Colossus-mu.
Nikmati kembali pertempuran Underground Arena di Colossus! Citra para penantang yang diproyeksikannya akan menunjukkan setiap detail pertempuran dan menciptakan ulang getaran turnamen.]],
  str_item_intro_3661008 = [[
Item Furniture. Bisa diletakkan di ruangan-ruangan di Colossus-mu.
Cukup satu bonsai maple besar ini saja untuk menghiasi ruangan. Tentu saja akan lebih baik ditambahi beberapa dekorasi tambahan untuk menemaninya.]],
  str_item_intro_3661009 = [[
Item Furniture. Bisa diletakkan di ruangan-ruangan di Colossus-mu.
Tanaman pot pohon maple kecil. Padukan dengan berbagai tanaman pot untuk membuat susunan yang sungguh indah.]],
  str_item_intro_3661010 = [[
Item furnitur. Bisa diletakkan di ruang-ruang di Colossus-mu.
Beberapa penduduk desa percaya bahwa kekuatan di dalam topeng ini mampu menangkal kejahatan dan mendatangkan keberuntungan. Karenanya, benda ini sering ditaruh di tempat yang menonjol di rumah mereka. Mereka berharap benda ini akan memberkati seluruh keluarga.]],
  str_item_intro_3661011 = [[
Item furnitur. Bisa diletakkan di ruang-ruang di Colossus-mu.
Jenis furnitur yang berasal dari Far East ini lambat laun menjadi populer di seluruh benua dalam beberapa tahun terakhir. Di musim dingin, benda ini membawa kehangatan dan ketenangan pikiran. Kalau sudah mendudukinya, kamu pasti akan betah menghabiskan sepanjang hari tanpa bergerak. Beberapa orang bahkan mulai menyebut fenomena ini sebagai Spell of Warm Table.]],
  str_item_intro_3661012 = [[
Item furnitur. Bisa diletakkan di ruangan-ruangan di Colossus.
Cemara adalah pohon yang paling umum di Northland, dan juga merupakan material penting yang digunakan dalam pembangunan rumah dan furnitur. Karena itu, pohon cemara melambangkan konsep keluarga di Northland, dan para penduduk Northland meletakkan pohon cemara di rumah mereka selama liburan Tahun Baru. Mereka menggantung berbagai dekorasi dari cabang-cabang pohon cemara dan menaruh hadiah di bawahnya. Kemudian mereka akan membukanya di hadapan keluarga dan merayakan festival paling penting.]],
  str_item_intro_3661013 = [[
Item furnitur. Bisa diletakkan di ruangan-ruangan di Colossus.
Para penduduk Far East suka merayakan hari raya dengan ini. Meski semula hanya makanan biasa, setelah penduduk Northland meyakininya sebagai pembawa keberuntungan, benda ini diganti dengan tanah liat dan pakaian. Namun, entah bagaimana benda ini justru mirip Tweety...]],
  str_item_intro_3661014 = [[
Item furnitur. Bisa diletakkan di ruang di Colossus-mu.
"Buat keik berbentuk hati untuk seseorang yang spesial ketika saatnya tiba." Tren ini tampaknya berlangsung dalam semalam, tetapi cukup populer di kalangan gadis-gadis muda. Lagi pula, keik ini tidak hanya sedap dipandang, tetapi juga lezat. Dan yang penting, keik ini memberi seseorang perasaan yang menyenangkan!]],
  str_item_intro_3661015 = [[
Item furnitur. Bisa diletakkan di ruang di Colossus-mu.
Benda ini sepertinya menjadi ornamen gantung dari Far East. Karena ringan dan praktis, benda ini bisa digantung di bawah atap, di pintu, atau jendela. Selama ada angin, benda ini akan membuat suara dering yang jernih, menyegarkan, dan menenangkan.]],
  str_item_intro_3661016 = [[
Furnitur yang bisa ditempatkan di ruang-ruang di Colossus.
Beruang yang tampak lucu ini sangat cocok sebagai hadiah dan rasanya juga enak. Namun, apa kamu benar-benar tega memakannya?]],
  str_item_intro_3661017 = [[
Furnitur yang bisa ditempatkan di ruang-ruang di Colossus.
Konon mainan ini dibuat berdasarkan "pelawak" raja kuno. Benda yang terlihat konyol dan lucu ini bisa menjadi hadiah yang bagus dan mampu menghadirkan kegembiraan unik.]],
  str_item_intro_3661018 = [[
Item furnitur. Bisa diletakkan di ruangan-ruangan di Colossus.
Disukai anggota Rediesel Wrench, helm ini melindungi pengendara dari segala macam kecelakaan selain menahan angin dan debu. Warna cerahnya seakan memastikan pemakainya akan selalu menarik perhatian.]],
  str_item_intro_3661019 = [[
Item furnitur. Bisa diletakkan di ruangan-ruangan di Colossus.
Soroz yang dirakit dari berbagai lembaran khusus ini merupakan buah karya sejumlah anak. Bentuknya sangat menyerupai kendaraan udara yang sebenarnya, tapi jika diamati baik-baik, detailnya menonjolkan kegembiraan dan selera humor anak kecil.]],
  str_item_intro_3661020 = [[
Item furnitur. Bisa diletakkan di ruang di Colossus.
Menara kue raksasa yang dibuat khusus untuk merayakan satu tahun kebersamaan. Menara kue ini tampak luar biasa kalau jika dilihat dari dekat karena sangat... tinggi! Selain penampilannya yang memukau, setiap lapisan kuenya juga berputar perlahan, memperlihatkan ornamen rendanya yang beraneka warna.]],
  str_item_intro_3661021 = [[
Item furnitur. Bisa diletakkan di ruang di Colossus.
Oh... rupanya satu tahun telah berlalu. Semua kenangan di masa lalu bisa ditemukan di benda ini.]],
  str_item_intro_3662118 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Poster surat peringatan yang dikirim oleh Phantom Thieves of Hearts ke target mereka di dunia lain. Desain grafisnya cukup artistik.
Melihat poster itu, Fox tampak sangat senang dengan dirinya sendiri. Atau itu imajinasimu?]],
  str_item_intro_3661022 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Apakah Anda menemukan skema warna yang familier? Betul sekali! Papan selancar ini dirancang berdasarkan Brock dan sama tahan lama, andal, dan mudah dikendalikan seperti dia!]],
  str_item_intro_3661176 = [[
Item furnitur. Bisa diletakkan di ruangan-ruangan di Colossus.
Seseorang menanam pohon di pot! Cuma sebagai hiasan! Kalau dipikir-pikir, pasti pelakunya sangat suka pohon palem.]],
  str_item_intro_3661171 = [[
Item furnitur. Bisa diletakkan di ruangan-ruangan di Colossus.
Patung bintang laut yang sangat mirip dengan aslinya. Kalau dilihat sekilas, patung ini sering dianggap bintang laut sungguhan. Meski terbuat dari pasir halus, bentuknya tetap solid dan ternyata cukup keras.]],
  str_item_intro_3661172 = [[
Item furnitur. Bisa diletakkan di ruangan-ruangan di Colossus.
Ya, meskipun solid, kastel ini tetap terbuat dari pasir. Jadi, jangan tafsirkan namanya secara mentah-mentah, ya! Kastel ini dinamai demikian dengan harapan bisa bertahan lama. Sejauh ini, kastel ini masih tetap utuh tanpa cela.]],
  str_item_intro_3661173 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Saksikan berikut ini! Sebuah acara yang diisi dengan banyak pertunjukan menakjubkan yang tidak akan pernah dilupakan oleh penonton! Itu sebabnya bahkan posternya terlihat memikat.]],
  str_item_intro_3661174 = [[
Item furnitur. Bisa diletakkan di ruangan-ruangan di Colossus.
Bola yang berhiaskan corak warna-warni. Memberikan beberapa sentuhan di panggung saja sudah cukup untuk menarik perhatian penonton, apalagi melakukan trik Vaudeville. Salah satu item kunci yang diperlukan dalam pertunjukan yang memukau.]],
  str_item_intro_3661175 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Banyak balon! Mereka berwarna-warni dan membuat Anda merasa sedikit ringan saat memegangnya! Ingatlah untuk tidak membiarkan anak-anak yang terlalu muda bermain dengan mereka, atau balon-balon itu akan benar-benar menyeret mereka ke langit!]],
  str_item_intro_3661177 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Pohon jenis apa ini? Cabang-cabangnya semua kasar dan bengkok... Sepertinya jenis pohon yang akan Anda lihat di film horor. Akan lebih menakutkan lagi dengan beberapa lentera seram yang tergantung di sana...]],
  str_item_intro_3661178 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Apakah seharusnya... tersenyum? Hanya orang yang membuatnya yang tahu, tapi pasti ada yang aneh dengan bagaimana senyumnya. Sekali lagi, apakah itu benar-benar sebuah senyuman...?]],
  str_item_intro_3661179 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Glub, glub, glub ... Siapa yang tahu ramuan gila macam apa yang mendidih di kuali ini? Mungkinkah itu ramuan cinta, seperti yang ada di dongeng? Atau mungkin sesuatu yang jauh lebih jahat ...]],
  str_item_intro_3661180 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Boneka aneh yang dibuat oleh pedagang yang lebih aneh di Umbraton. Di permukaan, itu terlihat seperti Soroz, tetapi jika Anda menekannya sedikit ... Itu mengeluarkan jeritan yang keras dan menyeramkan. Aku ingin tahu apa jenis shenanigan ini seharusnya?]],
  str_item_intro_3661023 = [[
Item furnitur. Bisa diletakkan di ruangan-ruangan di Colossus.
Alat yang menghasilkan aliran air menggunakan mekanisme bawaan jika diisi dengan air. Alat ini menyejukkan udara dan cocok digunakan saat musim panas. Jangan lupa lap lantai setelah menggunakan alat ini, ya.]],
  str_item_intro_3661024 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Sepeda roda satu ini benar-benar dapat bergerak maju bahkan dengan satu roda! Cuma agak lambat... Saat melihat skill riding akrobatik pengendaranya, mau tak mau orang merasa kagum dan cemas di saat yang bersamaan.]],
  str_item_intro_3661025 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Tampaknya menjadi perangkat kuno yang ditemukan di salah satu dari banyak reruntuhan misterius Astra. Meskipun relatif tua, itu masih bekerja dengan sangat baik, dan dapat dengan setia merekam cuplikan video.]],
