  str_item_intro_3751002 = [[
Membuka avatar yang sesuai.
Aku punya ide bagus! Oh? Kamu juga? Sst, kita simpan jadi rahasia kita saja, ya?]],
  str_item_intro_3751003 = [[
Membuka avatar yang sesuai.
Lihat orang itu, keren sekali! Wah, orang itu! Tidak mungkin, tidak mungkin, tidak mungkin!]],
  str_item_intro_3751004 = [[
Membuka avatar yang sesuai.
Ada yang tidak beres lagi! Apa yang harus dilakukan sekarang? Aku tak ingin mengutuk, tapi...]],
  str_item_intro_3751005 = "Membuka avatar yang sesuai.\nAah... Sialan, kok bisa terjadi? Sepertinya masih ada yang bisa diperbaiki lagi—ayo berusaha lebih keras!",
  str_item_intro_3751006 = [[
Membuka avatar yang sesuai.
Oh, tidak, tugas kita gagal. Apakah ketua akan memarahi kita? Jangan terlalu pesimistis...]],
  str_item_intro_3751009 = [[
Membuka avatar yang sesuai.
Jangan ragukan dirimu. Setiap orang punya misinya sendiri-sendiri. Aku yakin itu!]],
  str_item_intro_3751011 = [[
Membuka avatar yang sesuai.
Apakah kamu sudah menyelesaikan semua quest yang diberikan kepadamu? Ambil bunga merah kecil ini.]],
  str_item_intro_3751015 = [[
Membuka avatar yang sesuai.
Suara ini sangat menenangkan dan merdu. Ingin mendengarkannya bersamaku?]],
  str_item_intro_3751017 = [[
Membuka avatar yang sesuai.
Aku tak mau cuma duduk dan menjadi beban. Haruskah aku menciptakan sesuatu yang baru? Mungkin sesuatu seperti...]],
  str_item_intro_3751019 = [[
Membuka avatar yang sesuai.
Meskipun punya pengetahuan yang sangat luas, mustahil menggambarkan apa yang terjadi. Ini mengejutkan...]],
  str_item_intro_3751023 = [[
Membuka avatar yang sesuai.
Kenapa kamu begitu terburu-buru? Pergi setelah makan gratis? Sebaiknya pergilah sebelum terlambat.]],
  str_item_intro_3751025 = [[
Membuka avatar yang sesuai.
Mengapa kamu mencoba untuk membunuh waktu, bocah malang? Apakah tidak ada lagi yang bisa dilakukan?]],
  str_item_intro_3751030 = [[
Membuka avatar yang sesuai.
Colossus terkasih, mengapa kamu melampaui kekuatanmu dan terbang di langit...?]],
  str_item_intro_3751032 = [[
Membuka avatar yang sesuai.
Mengapa kamu tidak mengenali dirimu sendiri? Mengapa kamu tidak bercermin? Mereka yang sama sekali tidak berguna sebenarnya hidup dalam ketidakpedulian...]],
  str_item_intro_3751033 = [[
Membuka kunci avatar yang sesuai.
Sedekat mungkin, pedangku tidak memungkinkan pelanggar hukum.]],
  str_item_intro_3751034 = [[
Membuka kunci avatar yang sesuai.
Ketika Anda menatap bayangan, bayangan itu memperhatikan Anda.]],
  str_item_intro_3751035 = [[
Membuka kunci avatar yang sesuai.
Kebenaran sering tersembunyi di balik awan, setengah terselubung dan setengah terungkap. Anda dan saya sama-sama harus membuka mata.]],
  str_item_intro_3751036 = [[
Membuka kunci avatar yang sesuai.
Memesan? Aturan? Ha ha! Apa itu?]],
  str_item_intro_3751037 = [[
Membuka kunci avatar yang sesuai.
Masa depan masih suram, tapi saya melihat secercah harapan.]],
  str_item_intro_3751038 = [[
Membuka kunci avatar yang sesuai.
Bagus sekali! Bergabunglah dengan saya dalam perang melawan Eclipsites! Kemegahan Illumina!]],
  str_item_intro_3751301 = [[
Dapatkan untuk menggunakan avatar ini.
"Lumayan juga! Hei, mau bergabung dengan Rediesel Wrench?"]],
  str_item_intro_3751302 = [[
Dapatkan untuk menggunakan avatar ini.
"Terima kasih, semuanya. Kekuatanku telah kembali... Kamu mau aku membereskan beberapa Eclipsite?"]],
  str_item_intro_3751303 = [[
Membuka avatar yang sesuai.
Ikutlah denganku ke Cloud Mountain, ayo bermain-main di antara bunga-bunga yang menari.]],
  str_item_intro_3751304 = [[
Membuka avatar yang sesuai.
Es serut yang dibuat dengan hati-hati oleh pemilik kios dengan Brain Freeze dijamin akan membuatmu merasa sangat segar di bawah terik matahari musim panas.]],
  str_item_intro_3751305 = [[
Membuka avatar yang sesuai.
Kenakan dan jadilah Rediesel Steel MkV Zero!]],
  str_item_intro_3751306 = [[
Membuka avatar yang sesuai.
Hah...? Semua orang pergi untuk bersenang-senang? Yah, kalau begitu, aku juga pergi saja, deh...]],
  str_item_intro_3751307 = [[
Membuka avatar yang sesuai.
Mau yang sejuk-sejuk? Sini, kuperlihatkan sesuatu! Ice! Blossom!]],
  str_item_intro_3751308 = [[
Membuka avatar yang sesuai.
Apa? Sudah seratus hari? Saatnya potong kue!]],
  str_item_intro_3751309 = [[
Membuka avatar yang sesuai.
Hmm... Aku mulai suka hidangan pencuci mulut ini.]],
  str_item_intro_3751310 = [[
Membuka avatar yang sesuai.
Kok kepalaku jadi sangat berat, ya? Oh, mereka rupanya... Baiklah, kubiarkan saja.]],
  str_item_intro_3751311 = [[
Membuka avatar yang sesuai.
Hah? Kita menang? Mana meriam kembang apinya? Saatnya merayakan!]],
  str_item_intro_3751312 = [[
Membuka avatar yang sesuai.
Semoga kita bisa mencapai kesepakatan tentang masalah ini.]],
  str_item_intro_3751313 = [[
Membuka avatar yang sesuai.
Mau lihat wajah di balik topeng ini? Itu bisa diatur... Kamu hanya tinggal bergabung dengan skuad tentara bayaranku.]],
  str_item_intro_3751314 = [[
Membuka avatar yang sesuai.
Demi White Night... Kelak, aku ingin menyingkirkan segala ketidakadilan di dunia ini.]],
  str_item_intro_3751315 = [[
Membuka avatar yang sesuai.
Melambangkan kehormatan tertinggi di Underground Arena di Umbraton! Bukti tak terbantahkan seorang ahli pertempuran!]],
  str_item_intro_3751316 = [[
Membuka avatar yang sesuai.
Navi-Navi-Navigatow! Sini, kupewwihatkan yang namanya sihiw!]],
  str_item_intro_3751317 = [[
Membuka avatar yang sesuai.
Senyuman yang sangat nakal... Ayo kita membuat kekacauan!]],
  str_item_intro_3751318 = [[
Membuka avatar yang sesuai.
Aku bertemu dengan seekor kucing yang manis saat berpatroli! Ini adalah hari yang indah!]],
  str_item_intro_3751319 = "Membuka avatar yang sesuai.\nSimbol otoritas di Lumopolis—yang umumnya diperuntukkan bagi bangsawan.",
  str_item_intro_3751320 = [[
Membuka avatar yang sesuai.
Beginilah cara berpakaian para penduduk Northland untuk Tahun Baru, tak terkecuali denganku.]],
  str_item_intro_3751321 = [[
Membuka avatar yang sesuai.
Semoga kamu merasa damai dan bahagia di Tahun Baru.]],
  str_item_intro_3751322 = [[
Membuka avatar yang sesuai.
Sekarang kamu tahu akulah pelayan yang terbaik!]],
  str_item_intro_3751323 = "Membuka avatar yang sesuai. Anak yang berperilaku baik akan bersifat sopan bahkan ketika tidur. Dia tidak akan meronta-ronta, bahkan kau bisa meletakkan jeruk di kepalanya saat dia tidur.",
  str_item_intro_3751324 = [[
Membuka avatar yang sesuai.
"Perlahan dan pasti, aku akan menggambar mereka..."]],
  str_item_intro_3751325 = [[
Membuka avatar yang sesuai.
"Kalau dilihat-lihat... benda ini sekurang-kurangnya pasti berusia seribu tahun!"]],
  str_item_intro_3751326 = [[
Membuka avatar yang sesuai.
"Ingin merayakan? Setiap festival memiliki ciri khas spesialnya sendiri."]],
  str_item_intro_3751327 = [[
Membuka avatar yang sesuai.
"Hei! Mau jalan-jalan denganku?!"]],
  str_item_intro_3751328 = [[
Membuka avatar yang sesuai.
"Sebuah buku catatan selalu lebih baik ketimbang ingatan yang bagus."]],
  str_item_intro_3751329 = [[
Membuka avatar yang sesuai.
*auuuumm* Kuharap kau tidak takut!]],
  str_item_intro_3751330 = [[
Membuka avatar yang sesuai.
"Cinta itu berharga,
Kebebasan apalagi.
Keduanya bisa runtuh,
Demi satu sumpah."]],
  str_item_intro_3751331 = [[
Membuka avatar yang sesuai.
"Kerincing! Mau sekerincing meong?"]],
  str_item_intro_3751332 = [[
Membuka avatar yang sesuai.
"Dengarkan suara Kagura Bell."]],
  str_item_intro_3751333 = [[
Membuka avatar yang sesuai.
"Aku tidak akan menyerahkan roti itu kepada siapa pun!"]],
  str_item_intro_3751334 = [[
Membuka avatar yang sesuai.
"Apa kau sudah bangun? Pergi kerja sekarang!"]],
  str_item_intro_3751335 = [[
Membuka avatar yang sesuai.
Menang! Haruskah kita merayakannya dengan berseru-seruan?]],
  str_item_intro_3751336 = [[
Membuka avatar yang sesuai.
Apakah itu tampak mirip sepertiku?]],
  str_item_intro_3751338 = [[
Membuka avatar yang sesuai.
Ahahah. Kepala kucing ini memperhatikanmu.]],
  str_item_intro_3751339 = [[
Membuka avatar yang sesuai.
"Apa... bedanya?"]],
  str_item_intro_3751340 = [[
Membuka avatar yang sesuai.
"Kau selalu menjagaku dengan baik, tolong terimalah ini."]],
  str_item_intro_3751341 = [[
Membukan Avatar yang sesuai.
"Kudengar ini adalah hari untuk mengekspresikan perasaan kita... seperti ini?"]],
  str_item_intro_3751342 = [[
Membuka avatar yang sesuai.
"Kudengar piama ini sedang tren di kalangan Navigator. Aku harus mengantre lama demi mendapatkannya!"]],
  str_item_intro_3751343 = [[
Membuka avatar yang sesuai.
Warna matanya... berubah.]],
  str_item_intro_3751344 = [[
Membuka avatar yang sesuai.
"Hmm... Apa aku lupa melakukan sesuatu?"]],
  str_item_intro_3751345 = [[
Membuka bingkai avatar yang sesuai.
Mencatat hal-hal yang sangat penting merupakan kebiasaan baik Chief of Staff.]],
  str_item_intro_3751346 = [[
Membuka avatar yang sesuai.
Setelan ini? Aku membelinya saat berbelanja di Umbraton. Unik, 'kan?]],
  str_item_intro_3751347 = [[
Membuka avatar yang sesuai.
Sepertinya Chubb Merchant baru saja menerima hadiah istimewa sehingga dia menyanyi dengan gembira.]],
  str_item_intro_3751348 = [[
Membuka avatar yang sesuai.
Illumina membutuhkanmu! Kami menantikanmu bergabung dengan kami!]],
  str_item_intro_3751349 = [[
Membuka avatar yang sesuai.
Hmm? Mau mendengar nyanyianku? Boleh. Sebagai gantinya, kau harus mau bermain denganku!]],
  str_item_intro_3751350 = [[
Membuka avatar yang sesuai.
"Kenapa aku berdandan seperti Yumi? Karena dia sangat imut."]],
  str_item_intro_3751351 = [[
Membuka avatar yang sesuai.
"Telinga ini? Philyshy menyuruhku memakai ini. Kalau tidak, ia akan melaporkanku kepada Officer Sharona karena aku tak sengaja menginjak ekornya..."]],
  str_item_intro_3751352 = [[
Membuka kunci avatar yang sesuai.
"Bekerjasamalah denganku! Kamu tidak akan pernah kalah!"]],
  str_item_intro_3751353 = [[
Membuka kunci avatar yang sesuai.
"Hah? Apa susahnya sih?"]],
  str_item_intro_3751354 = [[
Membuka kunci avatar yang sesuai.
"Kamu juga harus istirahat dari waktu ke waktu."]],
  str_item_intro_3751355 = [[
Membuka kunci avatar yang sesuai.
"Di mana aku?"]],
  str_item_intro_3751356 = [[
Membuka kunci avatar yang sesuai.
"Aghhh! Panas sekali!"]],
  str_item_intro_3751357 = [[
Membuka kunci avatar yang sesuai.
"Ini musim panas yang panas dan mengenakan topi matahari adalah cara yang bagus untuk mencegah kulit terbakar. Hati-hati dengan panasnya, Navigator."]],
  str_item_intro_3751358 = [[
Membuka kunci avatar yang sesuai.
"Siapa yang akan menolak secangkir es serut yang dingin dan lezat di hari musim panas?"]],
  str_item_intro_3751359 = [[
Membuka avatar yang sesuai.
Di tengah teriknya musim panas ini, kamu selalu bisa merasakan hawa sejuk di sekitar Carleen.]],
  str_item_intro_3751360 = [[
Membuka kunci avatar yang sesuai.
"Sangat nyaman di sini. Mari kita nikmati kedamaian di karnaval."]],
  str_item_intro_3751361 = [[
Membuka kunci avatar yang sesuai.
Malam adalah temanku, dan kelelawar adalah subjekku. Siapa saya?]],
  str_item_intro_3763022 = [[
Membuka kunci avatar yang sesuai.
Jangan takut! Lampion labu ini saya buat untuk meningkatkan suasana acara selama beberapa hari ke depan. Tidak buruk, kan?]],
  str_item_intro_3751362 = [[
Membuka kunci avatar yang sesuai.
Biarkan aku melihat apa yang terjadi!]],
  str_item_intro_3751363 = [[
Membuka kunci avatar yang sesuai.
Ini sangat serius, tetapi seekor ular masih diperbolehkan untuk tetap berada di kepalaku.]],
  str_item_intro_3751365 = "Membuka kunci avatar yang sesuai setelah mendapatkannya. \"Mau membeli permen? Tukarkan ceritamu dengan mereka.\"",
  str_item_intro_3751366 = "Membuka kunci avatar yang sesuai setelah mendapatkannya. \"Kau tidak keberatan aku mendandanimu seperti serigala, kan?\"",
  str_item_intro_3751367 = [[
Membuka kunci avatar yang sesuai setelah mendapatkannya.
"Charon dengan penuh semangat memakai gigi palsu dan jubah. Acaranya sudah dimulai!"]],
  str_item_intro_3751368 = "Membuka kunci avatar yang sesuai setelah mendapatkannya. \"Bagi Hiiro, menjadi seorang penyihir juga bisa berfungsi sebagai jenis pelatihan.\"",
  str_item_intro_3751369 = "Membuka kunci avatar yang sesuai setelah mendapatkannya. \"Paloma membungkus dirinya dengan perban untuk mengejutkan semua anak yang datang menipu atau mengobati.\"",
  str_item_intro_3751370 = [[
Buka kunci avatar yang sesuai.
"Koin ini... mewakili masa laluku."]],
  str_item_intro_3751371 = [[
Buka kunci avatar yang sesuai.
"Lampu berbagai warna ini sangat indah."]],
  str_item_intro_3751372 = [[
Buka kunci avatar yang sesuai.
"Ikutlah denganku dan jadilah idola!"]],
  str_item_intro_3751373 = [[
Buka kunci avatar yang sesuai.
"Siap... Aksi!"]],
  str_item_intro_3751374 = [[
Buka kunci avatar yang sesuai.
Philyshy berkata bahwa dia menukar beberapa ikan kering dengan piyama Tahun Baru yang populer ini. Hmm... Mereka sangat nyaman, tapi kenapa mereka punya telinga?]],
  str_item_intro_3751375 = "Buka kunci avatar yang sesuai. Mie siput sungai, dengan aromanya yang unik, adalah makanan favorit Mu Yuebai.",
  str_item_intro_3751376 = [[
Buka kunci avatar yang sesuai.
Anda tidak terlihat terlalu baik. Apakah Anda ingin kami memeriksa Anda?]],
  str_item_intro_3751377 = [[
Buka kunci avatar yang sesuai.
Diam-diam mengamati orang dan hal-hal adalah kebiasaan Jeriah.]],
  str_item_intro_3751378 = [[
Buka kunci avatar yang sesuai.
Dengan wajahnya yang selalu benar, Michael merebut semua mawar yang dilihatnya.]],
  str_item_intro_3751379 = [[
Buka kunci avatar yang sesuai.
Menyambut dunia dengan kostum yang menarik terkadang bisa menawarkan pengalaman yang sama sekali berbeda.]],
  str_item_intro_3751380 = [[
Buka kunci avatar yang sesuai.
"Berbahaya. Tolong jangan ditiru."]],
  str_item_intro_3751381 = [[
Buka kunci avatar yang sesuai.
"Jeno mengundang Anda untuk minum secangkir kopi hitam bersamanya. Apa kau menerima undangannya?"]],
  str_item_intro_3751382 = [[
Buka kunci avatar yang sesuai.
"Seorang hakim Lumopolis harus berani membuat keputusan akhir."]],
  str_item_intro_3751383 = [[
Buka kunci avatar yang sesuai.
"Boneka ini mirip denganku, jadi aku merasa aman saat memeluknya."]],
  str_item_intro_3751384 = [[
Buka kunci avatar yang sesuai.
"Saya suka musik ini karena menenangkan saya."]],
  str_item_intro_3751385 = [[
Buka kunci avatar yang sesuai.
"Yingel, yang sangat dekat dengan penangkap lalat, pasti sangat lembut."]],
  str_item_intro_3751386 = [[
Buka kunci avatar yang sesuai.
"Gunakan pedangmu untuk memperluas perbatasan dan tanganmu untuk menghibur hati orang-orang. Leo berpegang teguh pada prinsip ini."]],
  str_item_intro_3751387 = [[
Buka kunci avatar yang sesuai.
"Aroma teh hitam menenangkan Mia dan membantunya bersantai."]],
  str_item_intro_3751388 = [[
Buka kunci avatar yang sesuai.
"Bunga favorit siapa bunga violet di tangannya?"]],
  str_item_intro_3751389 = [[
Buka kunci avatar yang sesuai.
"Apa yang kamu lihat di bola kristal? Masa lalu atau masa depan?"]],
  str_item_intro_3751390 = [[
Buka bingkai avatar yang sesuai.
"Ketika kamu sedih, pelukan lembut mungkin membuatnya lebih baik?"]],
  str_item_intro_3751391 = [[
Buka bingkai avatar yang sesuai.
"Jadilah penontonku atau jadilah pasanganku, apa pilihanmu?"]],
  str_item_intro_3751392 = [[
Buka bingkai avatar yang sesuai.
"Dinginkan panasnya musim panas dengan semangkuk es serut yang menyegarkan!"]],
  str_item_intro_3751393 = [[
Membuka avatar yang sesuai.
Saya punya ide menghasilkan uang yang bagus. Mau coba?]],
  str_item_intro_3751394 = [[
Membuka avatar yang sesuai.
Ingin tahu apa yang membuatku tertawa? Ayo, coba tebak!]],
  str_item_intro_3751395 = [[
Membuka avatar yang sesuai.
Ingin tahu makanan penutup musim panas favorit saya? Yah, kemungkinan besar itu es krim dengan daging kering kadal ditaburkan di atasnya.]],
  str_item_intro_3751501 = [[
Membuka avatar yang sesuai.
Dawn Flower ini melambangkan harapan. Kenakan dan musnahkan kesuraman masa lalu!]],
  str_item_intro_3751502 = [[
Membuka avatar yang sesuai.
Lambang Sakura Family. Ini menunjukkan pengakuan Hiiro atas dirimu.]],
  str_item_intro_3751503 = [[
Membuka avatar yang sesuai.
Kalau kamu butuh bantuan prajurit misterius ini, hubungi saja Odd Jobs milik Taki.]],
  str_item_intro_3751504 = [[
Membuka avatar yang sesuai.
Heehee... Mau minum teh sore hari bersama-sama?
Atau jangan-jangan kau tak sanggup minum tujuh tong teh, ya?]],
  str_item_intro_3751505 = [[
Membuka avatar yang sesuai.
Tenggelam dalam kegelapan abadi bersamaku.]],
  str_item_intro_3751506 = "Membuka avatar yang sesuai.\nTidak bisa melawan Eclipsite? Jangan khawatir—biar aku saja!",
  str_item_intro_3751507 = [[
Membuka avatar yang sesuai.
Kejutan Windelion! Hadiah menarik apa yang ada di dalamnya?]],
  str_item_intro_3751508 = [[
Membuka avatar yang sesuai.
Minumlah denganku. Ayo kita nikmati malam yang indah ini bersama-sama.]],
  str_item_intro_3751509 = [[
Membuka avatar yang sesuai setelah mendapatkannya.
"Kamu... Sepertinya butuh bantuanku."]],
  str_item_intro_3751510 = [[
Membuka avatar yang sesuai.
Kuberitahu sekarang, makanan ini dibuat untuk Kobayashi. Kalian semua sebaiknya tidak menyentuhnya!]],
  str_item_intro_3751511 = [[
Membuka avatar yang sesuai.
"Aku? Aku sudah tidur lebih awal..."]],
  str_item_intro_3751512 = [[
Membuka avatar yang sesuai.
"Ahh... Aku haus... Di mana airnya?"]],
  str_item_intro_3751513 = [[
Membuka avatar yang sesuai.
"Apa kau sungguh-sungguh menanyakan pendapatku tentang Lord Navigator...?"]],
  str_item_intro_3751514 = [[
Membuka avatar yang sesuai.
Di mana lagi aku bisa menyantap makanan lezat?]],
  str_item_intro_3751515 = [[
Membuka avatar yang sesuai.
"Ayo kita jalan-jalan!"]],
  str_item_intro_3751516 = [[
Membuka avatar yang sesuai.
"Adakah yang bisa memahami suasana hati Lenore?"]],
  str_item_intro_3751517 = [[
Membuka avatar yang sesuai.
Strategi masa mendatang...]],
  str_item_intro_3751518 = [[
Membuka avatar yang sesuai.
"Waktu minum teh sore hari merupakan momen yang paling membahagiakan."]],
  str_item_intro_3751519 = [[
Membuka kunci avatar yang sesuai.
"Roger."]],
  str_item_intro_3751520 = [[
Membuka kunci avatar yang sesuai.
"Apakah giliranku sekarang?"]],
  str_item_intro_3751521 = [[
Membuka kunci avatar yang sesuai.
"Lumopolis dan benua... Kita pasti tidak akan dan tidak boleh menjadi seperti ini."]],
  str_item_intro_3751522 = [[
Membuka avatar yang sesuai.
Ada yang mengusik pikiranmu? Ayo bersantai sejenak di air!]],
  str_item_intro_3751523 = [[
Membuka avatar yang sesuai.
"Ayolah, kita mainkan satu pertandingan!"]],
  str_item_intro_3751524 = [[
Membuka kunci avatar yang sesuai.
"Fiuh... Selesai."]],
  str_item_intro_3751525 = [[
Membuka kunci avatar yang sesuai.
Untuk bertahan atau binasa?
Itulah pertanyaannya.]],
  str_item_intro_3751526 = [[
Membuka kunci avatar yang sesuai.
Ini dia inspirasi! Mengerti! Yang ini akan menjadi hit besar!]],
  str_item_intro_3751527 = [[
Membuka kunci avatar yang sesuai.
Sebuah topi dengan tengkorak di atasnya. Sang jagoan menukik dengan topi tengkorak; itu Sadie dan Coolster, menghukum penjahat dan menyanyikan rap.]],
  str_item_intro_3751530 = [[
Buka kunci avatar yang sesuai.
"Berkebun benar-benar membantu meningkatkan temperamen seseorang!"]],
  str_item_intro_3751531 = [[
Buka kunci avatar yang sesuai.
"Dia cantik tapi juga sangat... berbahaya."]],
  str_item_intro_3751532 = [[
Buka kunci avatar yang sesuai.
"Ah! Hangat sekali... Lembut sekali!"]],
  str_item_intro_3751533 = [[
Buka kunci avatar yang sesuai.
"Sepertinya dia masih asyik dengan cerita lama itu. Jangan ganggu dia."]],
  str_item_intro_3751534 = [[
Buka kunci avatar yang sesuai.
"Selamat Tahun Baru! Mari menyalakan kembang api!"]],
  str_item_intro_3751535 = [[
Buka kunci avatar yang sesuai.
Perahu ini... sangat menarik.]],
  str_item_intro_3751536 = [[
Buka kunci avatar yang sesuai.
Nyam nyam! Apakah ada lagi?]],
  str_item_intro_3751537 = [[
Buka kunci avatar yang sesuai.
Aku akan terlambat! Kurasa aku harus makan sambil berjalan lagi hari ini!]],
  str_item_intro_3751538 = [[
Buka kunci avatar yang sesuai.
"Aku tidak tidur... Zzz..."]],
  str_item_intro_3751539 = [[
Buka kunci avatar yang sesuai.
"Bisakah kamu menghapusnya sekaligus?"]],
  str_item_intro_3751540 = [[
Buka kunci avatar yang sesuai.
"Ayah, ibu..."]],
  str_item_intro_3751541 = [[
Buka kunci avatar yang sesuai.
"Penjahat jahat itu... aku tidak akan membiarkanmu pergi!"]],
  str_item_intro_3751542 = [[
Buka kunci avatar yang sesuai.
"Di mana mangsaku? Tepat di depanku, tentu saja!"]],
  str_item_intro_3751543 = [[
Buka kunci avatar yang sesuai.
"Buku catatan selalu lebih baik daripada ingatan yang baik ..."]],
  str_item_intro_3751544 = [[
Buka kunci avatar yang sesuai.
"Latihan Militer Gabungan dimulai sekarang!"]],
  str_item_intro_3751545 = [[
Buka kunci avatar yang sesuai.
"Jangan mengabaikan apa pun karena detail itu penting."]],
  str_item_intro_3751547 = [[
Membuka avatar yang sesuai.
"Menonton mereka seperti ini membuat saya senang."]],
  str_item_intro_3751548 = [[
Membuka avatar yang sesuai.
Merasa terdorong? Kemudian nikmati saja dengan keterbukaan dan percaya diri.]],
  str_item_intro_3751549 = [[
Membuka avatar yang sesuai.
Apakah bahaya benar-benar memperindah kecantikan?]],
  str_item_intro_3751550 = [[
Membuka avatar yang sesuai.
Ide dan tindakan yang solid menjadi pondasi keberhasilan!]],
  str_item_intro_3751601 = [[
Membuka avatar yang sesuai.
Tower Shield retak yang dibawa secara eksklusif oleh Lumo Knights. Bentuknya seperti layang-layang, lebar di bagian atas dan sempit di bagian bawah, dengan tepi yang istimewa dan permukaan yang diukir dengan lambang gereja.]],
  str_item_intro_3751602 = [[
Membuka kunci avatar yang sesuai.
"Pohon mati dengan tiga bola warna tergantung di sana. Bagi Martha, masa lalu telah layu, dan di alam bersalju yang dipenuhi cahaya ini, dia sekali lagi akan menyambut kehidupan baru."]],
  str_item_intro_3751603 = [[
Membuka avatar yang sesuai.
"Ada gir di tengah ban. Rosa mengemudi jauh ke tengah gurun, dan siapa pun yang mengikuti jejaknya tak bisa menemukannya, hanya bekas roda dari bannya."]],
  str_item_intro_3751604 = [[
Membuka avatar yang sesuai.
"Di antara bunga lili yang bermekaran, terdapat sebilah pedang yang tajam. Menurut catatan Yvonne, takdir Nyonya Red Mercury tersembunyi dalam kabut. Tak seorang pun tahu apa yang akan diberikannya, pedang atau bunga lili di lengannya."]],
  str_item_intro_3751901 = [[
Membuka avatar yang sesuai.
Soroz tak sekadar Colossus. Ia adalah teman yang telah menemanimu selama tujuh belas tahun.]],
  str_item_intro_3751902 = [[
Membuka avatar yang sesuai.
Mengenakan pelindung kepala ini membuatmu merasa seperti penjaga White Night. Tipe White Night yang mana? Jangan senang dulu.]],
  str_item_intro_3755004 = [[
Membuka avatar yang sesuai.
"Mutiaranya bersinar lembut, anugerah cahaya pagi; Mekar dalam keheningan, pelukan yang lembut; Apakah dunia menyadari, kejaran yang indah ini?"]],
  str_item_intro_3762001 = [[
Membuka bingkai avatar yang sesuai.
Pola kuno ini menunjukkan pengakuan Silent Hunters atas dirimu. Terimalah kehormatan tertinggi ini dari masa lalu.]],
  str_item_intro_3762002 = [[
Membuka avatar yang sesuai.
Aksesori yang indah. Pakai untuk menghias Avatarmu!]],
  str_item_intro_3763001 = [[
Membuka bingkai avatar yang sesuai.
Di bawah terik matahari yang menyengat, di atas ombak biru, kenangan yang tak terlupakan kita akan selalu abadi di pantai yang panas ini.]],
  str_item_intro_3763002 = [[
Membuka bingkai avatar yang sesuai.
Jika mengenakan topi ini, kamu akan jadi kelihatan seperti Illumina Soldier yang luar biasa.]],
  str_item_intro_3763003 = [[
Membuka bingkai avatar yang sesuai.
Siapa yang tidak butuh bantuan saat menimbang baik dan buruk suatu masalah?]],
  str_item_intro_3763004 = [[
Membuka bingkai avatar yang sesuai.
Pakai dan jadilah pria paling keren di pesta!]],
  str_item_intro_3763005 = [[
Membuka avatar yang sesuai.
Spanduk yang didedikasikan untuk siswa yang baik! Pertahankan!]],
  str_item_intro_3763006 = [[
Membuka avatar yang sesuai.
Bukankah ini menggemaskan?]],
  str_item_intro_3763007 = [[
Membuka bingkai avatar yang sesuai.
Kami akan tetap menemanimu...]],
  str_item_intro_3763008 = [[
Membuka bingkai avatar yang sesuai.
Hadiah memancing!]],
  str_item_intro_3763010 = [[
Membuka bingkai avatar yang sesuai.
Ini aroma musim semi!]],
  str_item_intro_3763011 = [[
Membuka avatar yang sesuai.
"Saat memakainya, aku merasa bahwa aku bisa menjadi pembalap yang hebat!"]],
  str_item_intro_3763012 = "Membuka bingkai avatar yang sesuai.\nDi balik tirai merah ini, terdengar alunan lagu anak-anak yang bernuansa gelap…",
  str_item_intro_3763013 = [[
Membuka bingkai avatar yang sesuai.
Mahkota yang mencolok ini merupakan perlambang kehormatan dan kemuliaan.]],
  str_item_intro_3763014 = [[
Membuka bingkai avatar yang sesuai.
Khusus untuk Grand Marshal!]],
  str_item_intro_3763015 = [[
Membuka bingkai avatar yang sesuai.
"Apakah kualitas pelayanan seseorang akan meningkat jika memakai ini?"]],
  str_item_intro_3763016 = [[
Membuka bingkai avatar yang sesuai.
Pakai ini, wahai pesulap hebat!]],
  str_item_intro_3763017 = [[
Membuka bingkai avatar yang sesuai.
Sinar mataharinya terlalu terik, jaga dirimu agar tidak terbakar sinar matahari, ya!]],
  str_item_intro_3763018 = [[
Membuka bingkai avatar yang sesuai.
Sekarang 1-Year Anniversary! Pakailah dan rayakan!]],
  str_item_intro_3763019 = [[
Membuka kunci bingkai avatar yang sesuai.
Pakai saja ini dan Anda akan terlihat kabur seperti Bica!]],
  str_item_intro_3763020 = [[
Membuka kunci bingkai avatar yang sesuai.
Jangan khawatir, itu tidak panas!]],
  str_item_intro_3763021 = [[
Membuka kunci bingkai avatar yang sesuai.
Apakah itu terlihat seperti cakar kelelawar meraih kepala Anda? Ikat kepala terlalu ketat.]],
  str_item_intro_3763023 = [[
Membuka kunci bingkai avatar yang sesuai.
Mereka bilang memakai topi ini membantumu rap lebih baik. Anehnya, itu meningkatkan keterampilan bisbol Anda juga.]],
  str_item_intro_3763024 = [[
Buka bingkai avatar yang sesuai.
Suatu keharusan bagi penyanyi mana pun! Benamkan diri Anda dalam musik!]],
  str_item_intro_3763025 = "Desbloqueia o quadro de avatar correspondente.\nNão é para comer, é para vestir!",
  str_item_intro_3763026 = [[
Buka bingkai avatar yang sesuai.
Apakah dengan memakai ini benar-benar bisa membuatmu sekuat Jeriah? Satu hal yang pasti, setidaknya itu akan membuatmu aman dari angin...]],
  str_item_intro_3763027 = [[
Buka kunci avatar yang sesuai.
"Sebenarnya, itu sepasang kacamata lensa bening."]],
  str_item_intro_3763028 = [[
Buka kunci avatar yang sesuai.
"Aha! Dia pelakunya!"]],
  str_item_intro_3763029 = "Buka bingkai avatar yang sesuai. \"Peringatan 2 Tahun? Pasang! Ingatlah untuk menghapus yang dari tahun lalu, eh?\"",
  str_item_intro_3763031 = "Buka bingkai avatar yang sesuai. \"Apakah dunia itu benar-benar ada? Jika tidak, mengapa aku ada di sini?\"",
  str_item_intro_3763032 = [[
Membuka bingkai avatar yang sesuai.
Tampaknya mudah untuk tertusuk; siapa yang mau mengenakannya...]],
  str_item_intro_3763033 = [[
Membuka bingkai avatar yang sesuai.
Itu yang kamu maksud dengan menjadi seorang pria sopan?]],
  str_item_intro_3800001 = "Berisi 50 Lumamber.",
  str_item_intro_3800002 = "Berisi 50 Lumamber.",
  str_item_intro_3800003 = "Berisi 50 Lumamber.",
  str_item_intro_3800004 = "Berisi 50 Lumamber.",
  str_item_intro_3800005 = "Berisi 50 Lumamber.",
  str_item_intro_3801001 = [[
Breakthrough Material untuk Legendary Aurorian.
Semua anggota Silent Hunters punya Crest ini. Meskipun ribuan tahun sudah berlalu, Crest ini masih punya kekuatan besar dan bisa membangkitkan potensi para Silents Hunter.]],
  str_item_intro_3900101 = "Setelah setiap perintah disimulasikan, Command Archives ini akan memberikan sejumlah poin sesuai dengan kinerjamu. Setelah mengumpulkan sejumlah Command Point, kamu akan dipromosikan ke Command Level yang sesuai, yang mewakili kemampuan taktismu.",
  str_item_intro_3900201 = "Kamu bisa mendapatkan Data Fragment yang berharga dari Command Battle di Simulation Room melalui pengumpulan data besar-besaran yang tersimpan di Data Disk-nya. Jika memiliki fragmen data yang cukup, kamu bisa mendapatkan pesan lengkap dari mereka.",
  str_item_intro_3910100 = [[
Kemenangan bisa diraih dengan latihan yang tekun.
Kalahkan semua musuh dalam tantangan Data Disk ini untuk menyelesaikan stage.]],
  str_item_intro_3910200 = [[
Kemenangan bisa diraih dengan latihan yang tekun.
Kalahkan semua musuh dalam tantangan Data Disk ini untuk menyelesaikan stage.]],
  str_item_intro_3910300 = [[
Pertahankan sekutumu hingga titik darah penghabisan meski nyawa adalah taruhannya.
Dalam tantangan dari Data Disk ini, pastikan bahwa NPC bertahan selama X putaran.]],
  str_item_intro_3910400 = [[
Tahukah kamu seperti apa musuh yang ada di depan? Mereka semua pasti sangat kuat. Jadi, berhati-hatilah.
Dalam tantangan dari Data Disk ini, kalahkan musuh elite untuk menyelesaikan stage.]],
  str_item_intro_3910500 = [[
Pikiran lebih tajam dari pedang mana pun.
Dalam tantangan dari Data Disk ini, kamu harus memecahkan puzzle untuk menyelesaikan stage.]],
  str_item_intro_3910600 = [[
Seperti halnya catur, pertempuran adalah permainan.
Dalam tantangan dari Data Disk ini, kalahkan semua musuh untuk menyelesaikan stage.]],
  str_item_intro_3910700 = [[
Di medan pertempuran yang kejam, juara sejati adalah penyintas terakhir.
Dalam tantangan dari Data Disk ini, bertahanlah selama X putaran untuk menyelesaikan stage.]],
  str_item_intro_3910800 = [[
Serangan musuh laksana ombak, dan pertahananmu bagaikan tanggulnya.
Dalam tantangan dari Data Disk ini, kalahkan semua musuh untuk menyelesaikan stage.]],
  str_item_intro_3910900 = [[
Kamu dan musuhmu memiliki taktik yang sama. Semangat kalian mungkin juga sama.
Dalam tantangan dari Data Disk ini, kalahkan semua musuh untuk menyelesaikan stage.]],
  str_item_intro_3911000 = [[
Penggal kepala si ular, dan tubuhnya pasti akan jatuh. Jika kamu mengalahkan pemimpin musuh, kemenangan pasti akan jadi milikmu.
Dalam tantangan dari Data Disk ini, kalahkan pemimpin musuh untuk menyelesaikan stage.]],
  str_item_intro_4090014 = "Terikat oleh takdir, kenangan si kembar perlahan menyatu, seperti bunga daffodil putih yang mekar di bawah salju hitam di Lake Mirror, menunggu reuni mereka melalui cermin.",
  str_item_intro_4090334 = "Disediakan oleh Cloud Blossom Hotel, jubah ini menunjukkan gaya lokal Cloud Mountain. Yukata ini dibuat khusus untuk Vice. Hadir dengan selendang dan liontin yang unik, serta lonceng yang menggemaskan, menciptakan suasana lembut yang sedikit tidak menggambarkan Vice. Setiap kali ia mengenakan yukata ini, ia ingat kenangan yang tak terlupakan dan berharga itu.",
  str_item_intro_4090923 = "Berhenti menatapku...!\nApakah ada yang lebih memalukan? Jalinan duri mengangkat kaki Pact, merobek stoking sutra dan kerudung hitamnya hingga compang-camping. Di tengah kekacauan itu, Pact mencoba menyeimbangkan gelas anggur merah di tangannya—sepertinya mengendalikan gaun yang bermartabat dan mewah ini tidak semudah kelihatannya.",
  str_item_intro_4090383 = "Ini tidak baik! Gronru terjebak di kotak mainannya dan tidak bisa keluar! Untuk merayakan datangnya Tahun Baru, Gronru punya hadiah kejutan untukmu! Lihat saja betapa lucunya dia, membengkak dengan setumpuk mainan dalam pakaian merah putih yang meriah itu—dia bahkan mengikat lengan mekaniknya dengan pita cantik! Coba abaikan saja bom yang tampak mematikan di tangannya...",
  str_item_intro_4090333 = "Vice memilih baju renang sederhana dan nyaman untuk menghadiri festival Ocean Sovereign. Baju renang ini menggunakan cetak biru berstruktur khusus agar sesuai dengan kebiasaan berpakaian Vice dan memungkinkan ekornya ditempatkan dengan bebas. Selain struktur khususnya, coba lihat dengan cermat dan kamu akan menyadari bahwa peneduh berwarna hitam dan emasnya juga cocok dengan kepribadiannya yang ceria. Selagi mesin pemecah esnya meremuk bongkahan es, perempuan cantik berambut pendek ini sambil tersenyum mengajakmu bergabung dengannya di dalam air. Voli pantai, minuman es, gerobak es serut... selama musim panas itu, kau dan Vice berbagi memori yang sangat pribadi.",
  str_item_intro_4090853 = "Pakaian yang sangat memikat terdiri dari atasan menawan, rok elegan, lengan tenunan indah, kerudung upacara, dan sepatu bot bergaya... Pakaian Jane tidak hanya memukau, bunga di sepanjang ujung roknya juga memiliki arti spesial. Kenapa dia memilih untuk mengenakan pakaian semacam ini ketika membanggakan dirinya sebagai orang luar?",
  str_item_intro_4090863 = "Bagian dari seri White Maiden yang didesain untuk perayaan Ocean Sovereign. Pancaran putih murni sempurnanya dipilih khusus untuk mencerminkan keluguan dan kealiman yang tidak dapat dipisahkan dari identitas Uriah. Bunga rambat mengitarinya, diam-diam menuruti panggilannya. Untuk yang lain, pikirannya tidak berubah. Hanya bunga-bunga di sekitarnyalah yang mengetahui kebenaran—saat berdiri tanpa penghalang di tepi laut, dia merasa sedikit malu dengan outfit ini. Langit cerah, angin samudra yang terasa asin, air laut yang dingin... Saat dia mengibaskan pedang perayaannya, musik paling indah dan puitis akan dimainkan sekali lagi.",
  str_item_intro_4090573 = "Sewaktu Philyshy meringkuk di ranjang dengan mengenakan piyama berbulu halus, dia tertidur lelap dan memimpikan mimpi sore yang indah. Dalam mimpi ini, Yumi ada di sampingnya, memeluknya dan membelai rambutnya—seperti pemanas pribadi kecil, menghangatkan hatinya dan membawanya kembali ke masa-masa yang lebih sederhana.",
  str_item_intro_4091023 = "Pakaian sederhana ini melambangkan esensi dari apa artinya memiliki jiwa yang membara. Dalam kegelapan batas-batas arena bawah tanah yang menindas, pakaian ini berfungsi sebagai satu-satunya cahaya penuntun. Para pemberontak naik ke panggung, bertarung dengan tubuh yang kuat, semangat, dan kegigihan, darah mereka membara seperti api. Mereka mengamuk bak meteor yang menyala-nyala, lalu menghilang seperti abu. Dia menjentikkan jarinya, siap memburu semua yang ada di hadapannya.",
  str_item_intro_4090453 = "Saat salju mulai turun, musim dingin pun tiba. Sekarang, jalan-jalan yang lengang hanya diisi dengan kerlip lampu kuning yang hangat. Jika kamu seorang musafir yang kesepian, jangan khawatir bakal kehilangan arah. Lihat ke sebelah sana—keretamu sudah menunggu. Dengan tuksedo putih, sepatu bot hitam, rambut licin berkilau, dan sikap elegan, seorang pria yang bijaksana dan tenang telah menunggu untuk memberimu tumpangan.",
  str_item_intro_4090993 = "Areia meringkuk malu-malu di sofa. Kakinya yang telanjang, sepatu yang dibuang ke satu sisi, dan gaun kunonya menunjukkan bahwa dia baru saja kembali dari pesta. Seperti putri dalam dongeng, gaunnya yang anggun dan ajaib akan lenyap bersama dengan detak jam, tetapi kenangan ini—waktu yang dihabiskan bersamamu—tak akan pernah hilang atau pudar.",
  str_item_intro_4090263 = "Apa arti keberadaan bagi kesadaran tak berwujud? Setelah mengenakan pakaian aneh ini, pertanyaan yang membingungkan melekat di benak Uriel, memaksanya untuk merenungkannya tanpa akhir. Bisakah dia menemukan jawabannya di dunia sastra simulasi? Siapa tahu. Namun, kamu bisa berjalan, berpikir, dan turut merasakan seiring dengan pencariannya.",
  str_item_intro_4090543 = "Keras dan serius, begitulah modus operandi Nadine. Dia tidak pernah lelah dan selalu menjalankan tugasnya. Bahkan dengan pakaian musim semi barunya dan lentera kecil yang lucu, sosoknya tetap bersinar.",
  str_item_intro_4091113 = "Setelah sampai di pantai, malah biasanya melankolis Beryl lebih santai dari biasanya. Baju renang ini cukup minimalis, namun tetap bisa menonjolkan sosok Beryl sesekali. Namun, dia tidak menyadari hal ini dan selesai terpaku pada pembangunan istana pasirnya. Itu mungkin hal favorit Beryl tentang perjalanan pantai ini.",
  str_item_intro_4090883 = "Langit biru, awan putih, jalanan mulus—ini tidak terlihat seperti Rediesel Desert, dan Maggie juga terlihat sangat berbeda. Dia mengenakan seragam pelaut yang bersih dan rapi, dasi kupu-kupunya tertiup angin. Di pagi yang cerah ini, kamu bisa melihatnya berkendara dengan santai sambil menggigiti rotinya. Apa dia tidak akan terlambat ke sekolah?\n\nPakaian ini tidak hanya membuat Maggie menonjol di antara para anggota Rediesel Wrench, tetapi juga membuatnya bisa melihat pemandangan yang sangat berbeda. Mungkinkah ini bagian dari keajaibannya?",
  str_item_intro_4090963 = "Sariel? Jadi guru? Sepertinya Sariel menganggap serius pekerjaan keduanya. Dia bahkan memakai seragam! Sariel versi baru ini tampaknya jauh lebih bisa diandalkan ketimbang yang lama. Dia berbicara dengan lembut dan fasih. Mungkin sebentar lagi kamu bisa menerima pelajaran darinya!",
  str_item_intro_4091053 = "Meski pakaiannya mungkin biasa saja, Eve tetap menjadi yang terpopuler di Rediesel Wrench. Dia bahkan tidak tahu seberapa populer dirinya. Dan sekarang, sebagai pemandu sorak, dia justru lebih disukai setelah mengenakan pakaian ini! Namun, jangan menatapnya, nanti ada kunci pas yang mendarat di wajahmu!",
  str_item_intro_4090064 = [[
Pakaian nan ringan dan sehalus sutra yang ditutupi pita ini... adalah piama?! Mengapa ada orang yang mendesain barang semacam itu? Bagaimana cara memakainya di depan orang lain? Karena bingung bagaimana cara memakainya, Carleen memutuskan untuk mencobanya terlebih dahulu. Namun, tak disangka dia justru merasa sangat berbeda dengan dirinya yang biasanya serius.
Karena ingin ikut pesta tidur dan bersenang-senang dengan semua orang, Carleen memutuskan untuk bersikap berani.]],
  str_item_intro_4090303 = "Lengan baju hitam legam dan jubah merah tua. Memperkenalkan, samurai yang menyingkirkan para pelaku kejahatan dari dunia—Shinnosuke!\nSebagai pemimpin Rediesel Wrench, Sinsa mempraktikkan prinsip \"lakukan seperti yang dilakukan penduduk setempat\". Baik pakaian yang dia kenakan maupun pedang di pinggangnya adalah gambaran sempurna dari pesona Cloud Island, dan bahkan tawanya tampak benar-benar spontan. Namun, berhati-hatilah, jika suasana hati samurai ronin ini sedang bagus, dia mungkin membacakan puisi dadakan dan menyanyikan lagu...",
  str_item_intro_4090443 = [[
Angin sepoi-sepoi bertiup melalui pohon pinus, dan sinar matahari yang hangat menerangi aula. Saat kita menjauh dari hiruk pikuk kota dan pekerjaan tanpa akhir, kenapa tidak mengambil kesempatan untuk beristirahat di Cloud Mountain Hotel yang damai? Prinsip keseimbangan kehidupan kerja Vivian adalah cara yang tepat untuk mendapatkan kembali kekuatan dan energi sebelum melanjutkan pekerjaan!
Tentu saja, ini semua harus direncanakan!]],
  str_item_intro_4090643 = "Pakaian tempur baru Wrath ditenun dari benang sutra oriental... tidak hanya pas di badan, tetapi juga elegan dan anggun. Meskipun terlihat sedikit tipis, pakaian itu membuatnya bergerak leluasa, dan tampaknya tidak menghalangi kemampuan bertarungnya sama sekali.\nMemukul dan melenturkan otot-ototnya, bergegas menyingkirkan segala rintangan di jalannya—tidak peduli bahaya apa pun yang menghampirinya, Wrath yang tak tergoyahkan akan segera membereskannya!",
  str_item_intro_4090893 = [[
Untuk memanfaatkan liburan yang jarang-jarang ini, Irridon menyiapkan pakaian bergaya Cloud Island. Kain emas berhiaskan sulaman yang dipasangkan dengan jubah bulu seputih salju terlihat sangat indah. Dia sangat ingin mengenakan pakaiannya saat berjalan-jalan di jalanan Cloud Island atau naik kereta untuk menikmati pemandangan.
Namun, ada kejadian-kejadian yang tiba-tiba mengacaukan semua rencananya. Untuk melindungi liburannya, Irridon tidak ragu-ragu untuk mengubah stasiun Cloud Island menjadi Hall of Justice.]],
  str_item_intro_4090653 = [[
"Navigator, ayo main hanetsuki denganku!"
Tweety sangat bersemangat saat dia mendekat. Namun, siapa tahu, permainan sederhana yang menyenangkan akan berubah menjadi pertarungan tanpa henti untuk menjadi yang paling unggul?! Dengan servis luar biasa dan drop shot kuat, mustahil bagi pemain biasa untuk bertahan!
Siapa pun yang kalah dalam permainan akan digambari wajahnya sebagai hukuman. Satu-satunya harapan adalah agar Tweety mau berbelas kasih dan sedikit mengendalikan diri...]],
  str_item_intro_4090233 = [[
Meski karakternya pemalu, Connolly memutuskan untuk ikut menyoraki temannya yang turut serta dalam balapan. Namun, jika dibandingkan dengan pakaian yang dia kenakan sehari-hari, seragam ini memang "tak biasa."
Meski demikian, Connolly menerima pakaian berani yang diberikan oleh seorang pemasar dengan harapan dirinya dapat menjadi pribadi yang lebih ramah.]],
  str_item_intro_4090613 = "\"Ooh… Jadi benua itu seperti ini, toh.\"\nChandra, yang berada di atas hamparan awan, tak takut akan ketinggian sama sekali. Sambil menonton jalannya balapan jauh di bawah, dia sesekali berteriak akibat sengitnya persaingan. Namun… kenapa dia naik balon udara sambil mengenakan setelan aneh?\nTernyata, itu adalah sekelumit \"terapi visualisasi\" misteriusnya yang tampak bermanfaat bagi orang-orang untuk meluapkan emosi yang terpendam.",
  str_item_intro_4090843 = "\"Sepanas pasir gurun dan sesegar air dari sumber mata air, pakaian itu merupakan paduan sempurna antara gaya tradisional dan modern.\"\n\"Mengejutkan dan konyol…\"\nMeskipun respons audiens bagaikan bumi dengan langit, semua kritik pun sirna begitu Istvan mengenakan kostumnya. Kendati lebih cocok dikenakan di aula besar, di sini pun dia memancarkan karisma seorang superstar. Mungkin, dia tampak lebih memesona berkat aura \"Shadowlord\" yang menyelimutinya.",
  str_item_intro_4090603 = [[
Pakaian wasit balapan selalu menarik perhatian. Lagi pula, mereka memang harus berbeda dari yang lain agar pembalap bisa mengenali wasit saat melaju dengan kecepatan tinggi.
Jona, yang mendaftarkan diri sebagai wasit karena dia membutuhkan uang untuk melunasi tagihan barnya, lantas mengungkap rahasia kelam balapan. Meski dia awalnya hanya ingin memikirkan urusannya sendiri, pada akhirnya dia memasuki trek balapan demi seorang gadis kecil untuk menegakkan keadilan pada kawanan penjahat yang mencurangi balapan.]],
  str_item_intro_4090713 = [[
Panas matahari yang menyengat menyebabkan mobil balap diselimuti kepulan asap. Keringat langsung menguap disertai suara desis begitu menetes ke tanah.
Meski begitu, Taki ikut serta dalam balapan dengan "persiapan penuh" karena bertekad untuk mengungguli lawannya. Namun, apakah dia turut serta semata-mata karena hadiah uangnya?]],
  str_item_intro_4091263 = "Sang penulis paling laris itu, yang sedang terbentur kebuntuan ide, berdandan rapi dengan niat ingin berjalan-jalan mencari ide. Kenapa harus berdandan? Barangkali karena dia tak ingin orang-orang tahu bahwa sang Guild Manager yang hebat itu ternyata diam-diam punya hobi \"centil\".\nTapi, hati-hati, jangan meremehkan dedikasi Bethel pada hobinya—dia bersedia mengambil risiko apa pun demi sekadar mencari sekadar mencari inspirasi...",
  str_item_intro_4090673 = "Angin bertiup, dan gaun putihnya yang berlapis-lapis itu berayun pelan, menampakkan bordiran berbentuk bunga-bunga merah. Entah kenapa, pakaian Alice membuat kita jadi membayangkan... kue. Ya. Kue stroberi yang biasanya hanya disajikan saat pesta ulang tahun. Tapi, di Dream Dessert House, kamu bisa mencicipi segala jenis makanan penutup yang kamu inginkan secara gratis, asalkan kamu bisa menjawab pertanyaan dari Alice, pemilik toko itu, dengan jujur. Ini hukuman khusus dari Alice untukmu. Ups, maksudku... \"imbalan\" istimewa.",
  str_item_intro_4090103 = [[
"Pakaian yang bersih dan rapi adalah kebanggaan pelayan!"
Kenakan seragam pelayan hasil jahitan tangan Lita, dan kenakan juga bando berhias rendanya. Oh, jangan lupa kenakan juga celemek berhias pita keemasan itu.
Hari ini, Louise harus membantu majikannya berdandan dan menyiapkan jamuan minum teh sore. Jangan khawatir, lebah, anak rusa, bahkan awan pun akan membantumu.
Lihat! Si pelayan sudah mulai bekerja.]],
  str_item_intro_4090283 = [[
Ehem, mari beri sambutan hangat kepada Head Maid dari Upton Manor! Tunggu, apa dia tampak tak asing? Ya, kalian benar. Dia adalah Raphael kesayangan kita semua!
Baru-baru ini, dia menerima tugas khusus untuk memberikan pelatihan tempur kepada pelayan di Lumopolis. Kini, seiring semakin dekatnya akhir semester, seluruh pelayan menunjukkan hasil yang luar biasa di bawah bimbingan Raphael. Hanya saja... karier Raphael sebagai pelayan tidak berjalan begitu mulus.]],
  str_item_intro_4091163 = [[
Demi membuat roti dalam ingatannya, Fleur mengerahkan segenap upaya yang menyita waktu, tapi jerih payahnya belum pernah membuahkan hasil.
Kali ini, persiapan Fleur lebih matang. Ia mengenakan kemeja yang dijahit rapi, celemek yang baru disetrika, dan sepatu yang sudah disemir. Konon, roti yang dibuat dijamin enak jika mengenakan setelan ini. Meski terdengar janggal, Fleur tetap memercayainya untuk memuaskan hasrat dalam hatinya.]],
  str_item_intro_4090703 = "Di bawah pengawasan tajam Leona, Anda merasakan udara di sekitar Anda memanas dan napas Anda memendek. Apakah karena saraf? Memang, siapa yang tidak gugup di depan yang kuat dan cantik Leona? Dengan sandal bertali yang melilit kakinya dan tubuhnya yang dihiasi dengan aksesoris, dia terlihat sangat berbeda dari dirinya yang biasanya. Namun, dia dengan mudah memancarkan perasaan bahwa segala sesuatu di dunia adalah tiramnya.",
  str_item_intro_4090813 = "Ini kostumnya Brock dipersiapkan secara khusus untuk dirinya sendiri dalam mencari \"sesuatu\" tertentu. Celana renang yang membantunya berkeliling dengan mudah, papan selancar dengan gaya khusus, dan mantel transparan yang mengingatkan pada jas hujan. Mantel transparan? Mari kita jujur, alasan sebenarnya Brock merancang mantel transparan mungkin untuk memancing pujian dari kami—Lihatlah, tubuhnya yang dibangun dari bubuk protein dan olahraga keras, dari sinar matahari dan keringat, merindukan pujian Anda.",
  str_item_intro_4091123 = "Sebuah legenda urban populer di Umbraton baru-baru ini. Kartu panggil, pencuri merusak kekacauan di mana-mana, permata curian... Apakah tersangka utama kita ceroboh? Smokey Lagipula? Jika Anda ingin tahu yang sebenarnya, saya khawatir Anda harus membuka borgolnya terlebih dahulu. Tentu saja, gelar barunya sama menariknya dengan pakaian barunya—\"Kucing Hitam\", yang akan datang dan mengambil permata dalam tiga hari, seperti yang dijanjikan.",
  str_item_intro_4090384 = "Mana yang lebih dulu muncul, setelan ini atau permainan yang menyertai pakaian ini? Tak perlu dipikirkan. Yang penting, Gronru menyiapkan pakaian khusus liburan ini dan dia langsung memasuki mode berlibur begitu mengenakannya, meskipun dia hanya berlibur ke akuarium seharian, bukan ke pantai.",
  str_item_intro_4090413 = "Berapa banyak identitas yang dia miliki? Dia adalah Pemandu Lumopolis, tetapi dia juga memiliki banyak tanggung jawab lainnya. Salah satunya adalah menjadi duta publik untuk Hotel Tir'. Baju renang yang dia kenakan ini untuk pemotretan selebaran. Halus dan presisi, terbuat dari bahan yang paling indah. Melihatnya, orang tidak bisa tidak bertanya-tanya tentang hotel yang dia promosikan ini.",
  str_item_intro_4090873 = "Beverly mengenakan baju renang baju besi ini agar lebih cocok dengan lingkungan setempat saat dia mengunjungi wilayah pulau keluarganya. Meskipun jauh lebih minimalis daripada pakaian biasanya, aura aristokratnya terlalu kuat untuk disembunyikan, bukan hanya karena akar keluarga prajuritnya, tetapi juga karena mengejar kehormatan bangsawan.",
  str_item_intro_4091293 = "Meskipun dia mengenakan pakaian musim panas yang keren, tatapannya yang serius memberi tahu semua orang bahwa dia tidak di sini untuk bersantai tetapi untuk menyelesaikan misi wajib. Pakaian ini memungkinkan Luke untuk mempertahankan staminanya di hutan yang panas dan lembab, dan juga pakaian formal yang disiapkan khusus untuk dipakai dalam pertarungan untuk melindungi kupu-kupu berharga dari pemburu yang tidak tahu malu.",
  str_item_intro_4091483 = "Pesta air di gurun akan segera dimulai, tetapi yang membuat banyak orang sangat bersemangat adalah kesempatan untuk menyaksikan sosok Azure yang menakjubkan! Dia sangat memikat di balik pakaian tipis... Ahem, tolong kendalikan dirimu dan jangan menatap terlalu lama! Menikmati angin malam yang hangat dan lembap, mendengarkan musik yang keras, dan menari dengan orang banyak dari waktu ke waktu adalah hal yang menyenangkan!",
  str_item_intro_4090254 = "Pakaian panggung megah yang memancarkan aura bangsawan kuno yang elegan. Kelihatannya agak tidak pada tempatnya dengan mode saat ini, tapi itu karena Charon mendesain kostum barunya seperti ini. Meski luar biasa, dengan cepat menarik perhatian penonton setiap kali Charon berdiri di depan kamera, memberinya kesempatan untuk menunjukkan kemampuan aktingnya yang mengesankan dengan potensi penuh mereka. Pada saat-saat itu, dapat dikatakan bahwa Charon dan kostumnya dibuat untuk akting.",
  str_item_intro_4090683 = "Ekstra, ekstra! Kolaborasi baru-baru ini antara Serikat Kurir dan surat kabar Umbraton memberi kurir pekerjaan tambahan: penjualan langganan surat kabar. Dan dengan demikian, Wendy mengenakan seragam papergirl barunya dan memulai usaha penjualan korannya dengan kegembiraan dan ketekunan khasnya! Sifat Wendy yang cepat dan bersemangat tidak pernah membuatnya tertinggal dari teman-temannya, bahkan ketika dia melakukan tugas yang tidak biasa!",
  str_item_intro_4091003 = "Sikare, yang biasanya terikat dengan masa lalu, telah mengubah penampilan regulernya menjadi yang baru untuk menghadapi situasi yang tidak terduga. Meskipun dia terlihat seperti dokter biasa, isi tas kerjanya dipenuhi dengan peralatan medis yang tidak biasa. Ini karena dia tidak hanya harus memperhatikan penyakit orang yang masih hidup, tetapi juga keinginan orang yang meninggal ...",
  str_item_intro_4091203 = "Berkat permintaan populer, Hedy akhirnya berpartisipasi dalam acara pertukaran yang dimaksudkan untuk mendorong persatuan dan kerja sama antara Federasi Illumina dan Lumopolis. Atas perintah atasannya, dia melakukan perjalanan ke Kota Gannon untuk bertindak sebagai sheriff selama sehari, mempromosikan keselamatan lalu lintas dan pencegahan kejahatan di jalanan. Meskipun menjadi ksatria kebanggaan Lumopolis, Hedy mematuhi dan mengenakan seragam Federasinya. Meskipun dia merasa agak tidak nyaman, itu tidak mengaburkan pesona alami dan kepercayaan dirinya.",
  str_item_intro_4091193 = "Revy dengan sengaja memasukkan dirinya ke penjara dalam usahanya untuk mendapatkan saus pedas legendaris dari ingatannya, menuju ke dalam bahaya sendirian. Di balik tembok batu besar itu, dia mendapati dirinya dikelilingi oleh penjahat keras dari daerah yang merajalela. Benar-benar situasi yang berbahaya... Bisakah Revy, yang berasal dari Federasi Illumina dan belum pernah mengalami bahaya kacau di tempat seperti itu, berhasil dalam misi penyamarannya yang khusus?",
  str_item_intro_4091213 = "Bunga merah tua yang indah dihiasi dengan duri ganas yang tak terhitung jumlahnya: segala sesuatu tentang penampilan Paloma berteriak, \"mendekati risikomu sendiri.\" Ditambah dengan senyum tipis, udara keanggunan yang dingin mengelilinginya. Mereka yang melihat gadis yang mematikan ini tahu di dalam hati mereka bahwa memprovokasi dia akan menjadi hal terakhir yang pernah mereka lakukan. Menimbulkan kemarahan penguasa kejahatan Umbraton yang paling jahat akan menjadi keputusan yang lebih bijak jika dibandingkan. Atau apakah dia sudah menjadi raja kejahatan ...",
  str_item_intro_4090123 = "Suatu hari, sebuah legenda tiba-tiba muncul di Gannon — tentang \"Penegak Keadilan\" alias \"The Punisher\". Kilatan petir yang tiba-tiba membelah langit setiap kali seseorang melanggar peraturan, dan Nemesis muncul di samping mereka untuk menjatuhkan hukuman yang menggelegar. Setelah melakukannya, dia memberikan satu kalimat yang memotong mereka sampai ke tulang dan memaksa mereka untuk bertobat. Setelah menjalankan keadilannya, dia menghilang dalam sekejap untuk menghukum pelaku kejahatan lainnya.",
  str_item_intro_4090773 = "Pada hari libur yang langka, Bethlehem menemukan biografi seorang penyanyi wanita berbakat. Dia segera tersesat di halaman-halaman buku ini, menjadi satu dengan penyanyi, mengalami kenaikan ketenarannya, kemenangannya, dan kemudian kehilangan suaranya. \"Bagaimana jika aku seperti dia?\" Ini adalah pertanyaan yang Bethlehem tidak punya jawabannya. Yang bisa dia lakukan hanyalah membayangkan dirinya sebagai penyanyi wanita, mengambil alat musik dan tampil. Dia membayangkan memiliki hasrat untuk berkreasi, dia membayangkan kehilangan suaranya di atas panggung, dia membayangkan hidup sebagai penyanyi wanita, sambil berdamai dengan masa depannya sendiri.",
  str_item_intro_4090833 = "Untuk membangkitkan Lilin yang begitu gigih mereka bela, mereka harus... menjadi idola? Meski begitu, mereka tampaknya dengan kaku mematuhi program mereka sebagai pelayan. Bisakah mereka benar-benar mencapai puncak profesi di mana vitalitas dan kreativitas sangat penting? Nah, jika ada cetak biru yang bisa mereka ikuti, dan keunggulan jumlah mereka bisa dimanfaatkan entah bagaimana, itu mungkin saja...",
  str_item_intro_4091313 = "Meskipun ia mempertahankan perspektifnya yang unik tentang dunia, Novio menjadi pianis ulung begitu ia mengenakan penampilan baru ini. Dia membawa kehangatan dan niat baik kepada para penyintas Northland yang berhati kuat, dan mendorong anggota audiensi khusus tertentu untuk bertahan dan bergerak maju dengan tegas, selamanya berjuang untuk perbaikan diri.",
  str_item_intro_4091383 = "Meski atasannya memaksanya untuk mengikuti kompetisi idola, Siobhan tetap melakukan yang terbaik untuk mempersiapkannya dengan baik. Saat mengerjakan bakatnya, dia juga mencurahkan banyak upaya untuk meneliti dan merancang pakaian yang sempurna. Semangat penelitian ilmiah yang tak tergoyahkan ini menghasilkan transformasi luar biasa dalam diri Siobhan—sinar cahayanya yang tidak dapat dipadamkan, jalan yang tidak dapat diabaikan menuju ketenaran di masa depan.",
  str_item_intro_4090273 = "Dia adalah horor di antara para pecinta Lumopolis — Setiap Hari Mooncrown, akan ada seorang ksatria berbaju putih yang berpatroli di seluruh penjuru kota, mencari mereka yang sedang jatuh cinta. Begitu dia menemukannya, dia akan segera mengeluarkan \"Larangan Jatuh Cinta\". Oleh karena itu, dia dikenal sebagai \"petir yang menghancurkan cinta\", yang menakutkan para kekasih.",
  str_item_intro_4090553 = "Tidak seperti penampilan profesionalnya yang biasa, Pittman tampaknya terpengaruh oleh kemeriahan Mooncrown Day saat ia memilih pakaiannya. Itu membawa kelembutan yang tidak sering terlihat dalam dirinya tanpa kehilangan ketegasan dan keanggunannya yang biasa. Tentu saja, ini bukan karena dia dilamar, tetapi hanya untuk menjadi pembawa pesan yang memenuhi syarat dan memenuhi keinginan orang lain yang telah lama disayangi.",
  str_item_intro_4090913 = "Di dunia Chloe, cinta selalu datang dengan perpisahan, jadi akan sedikit berlebihan untuk memintanya memainkan musik yang merayakan cinta yang manis. Dalam hal ini, kita mungkin memuji cinta abadi atas nama Tuhan—kasih sayang orang mungkin memudar setelah beberapa tahun, tapi jangan khawatir, cahaya akan memberkati dan mencintai semua orang secara setara.",
  str_item_intro_4091673 = "Tidak ada kekurangan dari segala macam trik sulap di tempat sosial seperti ini, tetapi rasa misteri adalah kunci dari semuanya. Kartu, kata, atau bahkan hanya sekilas. Seseorang dapat menyelesaikan pertunjukan yang megah dan indah di saat-saat tanpa perhatian tanpa ada yang lebih bijak. Meskipun tidak ada tepuk tangan seperti biasanya, itu bagus untuk Jeno ketika dia ingin melakukan kebaikan untuk teman-temannya sesekali.",
  str_item_intro_4090043 = "Mayat yang dingin, petunjuk yang ditandai, barisan demi barisan... Adegan klasik dan menegangkan seperti itu selalu bisa membuat imajinasi semua orang menjadi liar. Misalnya, detektif bisa jadi pembunuhnya atau berkolusi dengan si pembunuh, pembunuhnya bisa bersembunyi di antara kita, atau semua saksi bisa jadi pembunuh... Siapa sangka almarhum dan detektif itu bekerja sama?",
  str_item_intro_4090483 = "Suasana tak menyenangkan menyelimuti jalan-jalan Umbraton yang damai. Meski orang-orang yang lewat di jalan tampak menikmati malam yang sunyi, mata waspada seorang petugas patroli mengawasi dengan saksama untuk menangkap semua jejak dosa. Selama mereka bersembunyi di kota ini, dia, penjaga perdamaian, tidak akan berhenti berpatroli di jalanan. Semuanya untuk ... satu-satunya saudara perempuannya!",
  str_item_intro_4091484 = "Kantor dengan jendela cerah dan bersih, sofa empuk, anggur yang memabukkan, dan direktur sementara setengah berbaring di sofa. Jangan biarkan sikap malasnya menipu Anda — wanita cantik ini berbahaya, terutama bagi orang yang akan segera menjadi mangsanya, secara harfiah.",
  str_item_intro_4091663 = "\"Yah ... di mana anak-anak kecil yang lucu itu?\" Untuk menemukan binatang-binatang yang menakjubkan itu dan mengungkapkan kebenarannya, Fia menjadi seorang detektif dan mulai menyelidiki kasus misterius ini dengan hati-hati dengan memeriksa semua jenis bukti dan mempertimbangkan poin-poin penting dari kecurigaan. Melihat betapa sungguh-sungguh dan pekerja kerasnya dia, mungkin dia benar-benar akan menemukan sesuatu.",
  str_item_intro_4090983 = "Di bawah perintah Shadowlord, penyendiri Cuscuta bertugas menjadi detektif dan menangkap penjahat yang merajalela. Meskipun dia bergumul dengan kunjungan jalan dan wawancara saksi, intuisinya yang tajam memungkinkan dia untuk menyimpulkan identitas penjahat dari petunjuk yang ada. Dari kenyamanan kursinya, dia mengamati permainan catur dan tenggelam dalam kontemplasi sampai dia menemukan jawabannya melalui deduksi.",
  str_item_intro_4091034 = "Orang tidak boleh melakukan kejahatan, atau mereka akan menghadapi penghukuman dari surga, yang dikenal di dunia fana sebagai pencobaan, penghakiman, dan hukuman. Tentu saja, prosesnya tidak seseram kedengarannya, terutama saat Eicy menjadi petugas interogasi Anda. Gadis lembut tidak pernah bergantung pada kekerasan untuk meruntuhkan pertahanan seseorang... Atau lebih tepatnya, pertahanan itu tidak berguna sejak awal. Jadi jika Anda pernah bertemu dengannya, jangan bertengkar sia-sia. Tinggalkan saja semuanya Eicy.",
  str_item_intro_4090293 = "Untuk menghormati keinginan terakhir master, Gabriel mengenakan gaun megah dan berkelana ke panti asuhan di Umbraton. Lingkungan yang suram dan kumuh kontras dengan pakaian indahnya, dan tindakan Gabriel yang agak canggung membuat anak yatim piatu salah mengira dia sebagai penyihir. Namun pada akhirnya, anak-anak yatim itu merasakan dedikasi tulus Gabriel untuk menjaga rumah mereka, dan gaun itu sendiri tampak memancarkan cahaya yang menenangkan.",
  str_item_intro_4090463 = "Bagi orang dewasa, ini mungkin merupakan sihir hitam yang mengerikan, tetapi bagi mereka, itu adalah pintu gerbang ke dunia fantasi, pesona, dan keajaiban luar biasa yang dibuat khusus untuk jiwa mereka yang ingin tahu dan bersemangat. Untuk membuat ramuan terlarang, mereka tanpa lelah mencari bahan-bahan aneh, mengenakan pakaian unik yang semakin menonjolkan individualitas mereka.",
  str_item_intro_4090623 = "Untuk memastikan sesi belajar diselenggarakan oleh Leah berjalan lancar, Sylva bersusah payah mengenakan pakaian formal ini, menyerupai cendekiawan muda yang siap menemui gurunya yang terhormat—cerdas, bijaksana, dan santun. Sikapnya dengan mudah menanamkan suasana positif pada sesi belajar, membuatnya mendapatkan gelar 'siswa teladan'...",
  str_item_intro_4091433 = [[
Saat menjelajahi hutan pada malam hari, makhluk-makhluk tak menyenangkan dikatakan tinggal di dunia setelah badai petir. Untuk alasan ini, Rinne mengenakan pakaian seremonialnya dan mengangkat Lonceng Kagura tinggi-tinggi, siap untuk melenyapkan kehadiran jahat dari dunia ini untuk membela yang hidup.
"Sebuah ode untuk yang mati dan yang hidup. May lagu ini menemanimu ke seberang Sungai Lethe."
"Sungai Lethe mengalir. Kebencian dan kepahitan tumbuh."
"Datura bernyanyi dalam harmoni."
"Dengarkan dengan damai. Biarkan jiwamu mengikutiku."]],
  str_item_intro_5000001 = "Konon mengandung zat misterius yang berisi informasi kuno, yang bisa mempercepat proses konstruksi bangunan dan pembuatan furnitur.",
  str_item_intro_5000002 = "Cloud Gardens - Treasure Refreshes",
  str_item_intro_5002101 = "Kayu kokoh, cocok untuk konstruksi bangunan, furnitur, dsb.",
  str_item_intro_5002201 = "Bijih yang baru saja digali perlu diproses lebih lanjut. Walau begitu, dalam wujud mentah sekalipun, bijih itu sudah punya nilai jual di pasaran.",
  str_item_intro_5003001 = "Kepingan batu yang ditemukan di berbagai bagian Cloud Gardens. Tampaknya kepingan ini adalah relik, tetapi fungsi sebenarnya tidak diketahui. Chubb suka kepingan-kepingan ini, dan mau membarter barang-barang tertentu untuk mendapatkannya.",
  str_item_intro_5003101 = "Lem biasa untuk konstruksi bangunan dan pembuatan furnitur. Mampu melekatkan material dan membuat komponen menjadi kuat.",
  str_item_intro_5003102 = "Lem terbaik untuk konstruksi bangunan dan pembuatan furnitur. Sedikit lem ini saja sudah cukup untuk merekatkan material dengan kencang dan membuat komponennya jadi sangat kuat.",
  str_item_intro_5011001 = "Light Axe Lv. 1. Gagangnya yang berongga memungkinkan kapak ini menebang batang pohon dengan sangat cepat.",
  str_item_intro_5011002 = "Light Axe Lv. 2. Gagangnya yang berongga memungkinkan kapak ini menebang batang pohon dengan sangat cepat.",
  str_item_intro_5011003 = "Light Axe Lv. 3. Gagangnya yang berongga memungkinkan kapak ini menebang batang pohon dengan sangat cepat.",
  str_item_intro_5011004 = "Light Axe Lv. 4. Gagangnya yang berongga memungkinkan kapak ini menebang batang pohon dengan sangat cepat.",
  str_item_intro_5011005 = "Light Axe Lv. 5. Gagangnya yang berongga memungkinkan kapak ini menebang batang pohon dengan sangat cepat.",
  str_item_intro_5012001 = "Champion's Rod Lv. 1. Joran ini sangat seimbang, kokoh, dan dilengkapi dengan senar pancing yang kuat, membuatnya sangat cocok untuk memancing ikan besar.",
  str_item_intro_5012002 = "Champion's Rod Lv. 2. Joran ini sangat seimbang, kokoh, dan dilengkapi dengan senar pancing yang kuat, membuatnya sangat cocok untuk memancing ikan besar.",
  str_item_intro_5012003 = "Champion's Rod Lv. 3. Joran ini sangat seimbang, kokoh, dan dilengkapi dengan senar pancing yang kuat, membuatnya sangat cocok untuk memancing ikan besar.",
  str_item_intro_5012004 = "Champion's Rod Lv. 4. Joran ini sangat seimbang, kokoh, dan dilengkapi dengan senar pancing yang kuat, membuatnya sangat cocok untuk memancing ikan besar.",
  str_item_intro_5012005 = "Champion's Rod Lv. 5. Joran ini sangat seimbang, kokoh, dan dilengkapi dengan senar pancing yang kuat, membuatnya sangat cocok untuk memancing ikan besar.",
  str_item_intro_5013001 = [[
