  str_item_intro_5014001 = "Bagian kepala sekop ini dibuat lebih tebal sehingga tidak akan retak walaupun menghantam batuan keras. Dengan sekop ini, menggali jadi semudah membalikkan telapak tangan.",
  str_item_intro_5011012 = [[
Batu keras nan kasar yang dapat mengasah sisi tumpul.
Light Axe dapat ditingkatkan di dalam ransel.]],
  str_item_intro_5012012 = "Kayu bermutu tinggi yang ditemukan di Cloud Gardens itu diiris tipis-tipis untuk menambah kekerasan badan alat pancing dan meningkatkan keawetannya. Dengan senar pancing khusus, Champion's Rod mampu dengan mudah mengatasi segala situasi. Champion's Rod bisa ditingkatkan di dalam ransel.",
