  str_item_intro_5176208 = "Ini adalah cetak biru Spanduk Nostalgia. Gunakan itu untuk membuka metode produksi item di Menara Hyacinth.",
  str_item_intro_5176209 = "Ini adalah cetak biru Lampu Nostalgia. Gunakan itu untuk membuka metode produksi item di Menara Hyacinth.",
  str_item_intro_5176210 = "Ini adalah cetak biru Pagar Nostalgia. Gunakan itu untuk membuka metode produksi item di Menara Hyacinth.",
  str_item_intro_5176211 = "Ini adalah cetak biru Tanaman Nostalgia. Gunakan itu untuk membuka metode produksi item di Menara Hyacinth.",
  str_item_intro_5176212 = "Ini adalah cetak biru Nostalgia Vine Canopy. Gunakan itu untuk membuka metode produksi item di Menara Hyacinth.",
  str_item_intro_5134049 = "Ini adalah cetak biru Record Obelisk. Gunakan itu untuk membuka metode produksi item di Menara Hyacinth.",
  str_item_intro_5211001 = "Paviliun dengan pilar-pilar bengkok dan atap batu yang ditumbuhi lumut. Walau tampak tak selaras dengan gaya arsitektur pada umumnya, paviliun ini sangat kokoh.",
  str_item_intro_5211002 = "Konon, gapura itu diukir dari sebongkah batu saja. Walaupun kini sudah ditumbuhi rerumputan, keawetannya tak perlu diragukan.",
  str_item_intro_5211003 = "Tempat transit untuk orang-orang yang ingin beristirahat saat mengangkut suplai di lembah. Bisa didirikan dengan cepat dan dibongkar dengan mudah, sehingga bisa dibangun dalam jumlah banyak di sepanjang rute perjalanan.",
  str_item_intro_5211004 = "Sumur tak berujung yang dibangun di muara beberapa sumber air tanah. Pagar batu dibangun di sekelilingnya agar tak ada orang yang jatuh ke dalamnya. Sumur ini sangat dalam, dan airnya sangat jernih dan dingin.",
  str_item_intro_5211005 = "Kincir angin berbentuk unik. Walau tampaknya pendek, kincir ini bisa memanfaatkan angin dengan baik! Selain itu, berkat adanya teknologi yang keren, layar pada kincir ini tetap akan berputar perlahan walaupun tak ada angin.",
  str_item_intro_5221001 = "Pagar kayu. Kalau disambungkan, pagar ini bisa mengitari sepetak lahan di Cloud Gardens.",
  str_item_intro_5221002 = "Selusur berukuran lebih pendek. Papan-papan kayunya yang dijalin tak beraturan memancarkan aura pedesaan.",
  str_item_intro_5221003 = "Pagar kayu yang mudah dibuat. Ideal untuk barikade dan memisah-misahkan area.",
  str_item_intro_5221004 = "Pagar batu yang berat tetapi kuat. Lebih awet daripada pagar kayu.",
  str_item_intro_5221005 = "Pagar batu. Setelah ditancapkan di tanah, pagar ini bisa bertahan hingga bertahun-tahun, bahkan walaupun terpapar cuaca yang berubah-ubah.",
  str_item_intro_5221006 = "Selusur batu yang kokoh memang tak hanya tampak stabil, tapi juga membuat kita merasa aman.",
  str_item_intro_5223001 = "Ubin lantai persegi yang bisa dipasang dengan rapi. Cocok untuk jalan utama dan bangunan penting.",
  str_item_intro_5223005 = "Ubin lantai yang terbuat dari batu berbentuk tak beraturan. Cocok untuk jalan konblok dan dekorasi halaman.",
  str_item_intro_5231001 = "Meja yang ditopang oleh dua lempeng batu berbentuk trapesium. Berat, tetapi kokoh.",
  str_item_intro_5231002 = "Meja batu bundar berukuran agak kecil. Jika dipadukan dengan kursi yang senada, meja ini cocok untuk tempat mengobrol antara sepasang sahabat.",
  str_item_intro_5231003 = "Meja kayu dengan penyangga di keempat sisinya. Lebar dan rata, cocok untuk duduk-duduk santai bersama beberapa orang.",
  str_item_intro_5232001 = "Bangku batu bundar yang ditopang oleh sebuah pilar batu di bagian dalamnya yang berongga. Tak hanya kokoh, tepiannya yang halus juga bisa meminimalkan bahaya.",
  str_item_intro_5232002 = "Bangku batu berbentuk persegi, lebar di bagian bawah dan menyempit di bagian atas, dan diberi lapisan kayu di atasnya untuk meredam dingin dari batunya. Bentuknya mewah, tetapi produksinya sederhana. Satu-satunya kekurangannya adalah kita mudah terantuk bagian tepinya.",
  str_item_intro_5232003 = "Kursi kayu sederhana dan ringan yang dilengkapi penyangga di kedua sisinya. Saat diduduki, kursi ini akan bergoyang sedikit.",
  str_item_intro_5232005 = "Digantung dengan tali yang diikatkan pada pilar batu berbentuk aneh, ranjang ini dirancang menyerupai daun berbentuk bundar, sehingga mampu menjaga keseimbangan dan nyaman digunakan untuk berbaring tanpa harus takut terguling.",
  str_item_intro_5232006 = "Bangku yang terbuat dari landasan batu. Selain duduk, kamu juga bisa berbaring di atasnya. Karena terbuat dari batu, bangku ini juga terasa adem.",
  str_item_intro_5233001 = "Dua bongkah batu, satu besar dan satu lagi kecil, ditumpuk dalam posisi agak goyah. Kalau diletakkan di posisi yang tepat, hasilnya adalah pemandangan unik bagi warga di sekitarnya.",
  str_item_intro_5233002 = "Bentuknya menyerupai stalagmit yang diperbesar beberapa kali. Kalau dihias dengan baik, aura yang dipancarkannya akan terasa berbeda.",
  str_item_intro_5233003 = "Sekumpulan kerikil dengan bentuk beragam, biasanya dipasang sebagai dekorasi di pinggir jalan dan halaman.",
  str_item_intro_5233004 = "Atap paviliun ini berbentuk seperti payung. Ditopang oleh sebuah tiang, atap ini memang sengaja dirancang miring agar makin teduh. Langit-langitnya tertutup tanaman merambat. Saat angin bertiup melalui cabang dan daun yang bergelantungan, pemandangan jadi sungguh istimewa.",
  str_item_intro_5233005 = "Kombinasi bebatuan yang tumpang tindih, beberapa air terjun kecil yang terbentuk dari air yang menggelegak, dan sebuah kolam kecil yang dikelilingi serpihan-serpihan batu tebal mampu menghadirkan bunyi gemercik air yang menyenangkan dan tiada henti sampai ke halaman.",
  str_item_intro_5233006 = "Pilar batu tegak lurus yang bisa digunakan sebagai badan utama dalam kelompok batuan.",
  str_item_intro_5233007 = "Struktur ini terbuat dari banyak pilar batu yang disusun miring, dan bentuknya menyerupai gunung kecil.",
  str_item_intro_5233008 = "Pilar-pilar batu yang agak miring ini cocok untuk digunakan sebagai peralihan antara bebatuan yang bentuknya sangat beragam.",
  str_item_intro_5233009 = "Dengan puncak tajam dan bentuk keseluruhan yang ramping, pilar batu ini memancarkan aura dingin. Sebaiknya cari bebatuan yang cocok agar tampak serasi dengannya.",
  str_item_intro_5233010 = "Bentuknya menyerupai bukit yang condong. Bisa pula dianggap sebagai struktur utama dalam kelompok batuan.",
  str_item_intro_5234001 = "Berkat teknologi fantastis, lampu jalan ini memancarkan cahaya yang tahan lama. Karena pendek, lampu ini hanya bisa menerangi area kecil saja.",
  str_item_intro_5234002 = "Lampu jalan yang ditopang dengan tiang. Karena tinggi, sumber cahaya ini mampu menerangi hingga area yang jauh.",
  str_item_intro_5234007 = "Dudukan pot bunga berukuran tinggi sehingga keindahan bunganya bisa terlihat dari jauh.",
  str_item_intro_5234009 = "Karena ada berbagai petunjuk arah yang dipaku ke bagian atasnya, papan kayu ini bisa mencegah agar kita tak tersesat di Cloud Gardens. Pastikan kamu memasangnya dalam posisi yang benar!",
  str_item_intro_5234011 = "Payung yang cukup memberikan naungan. Kekurangannya adalah payung ini berat dan sulit dibawa.",
  str_item_intro_5234012 = "Setangkai bunga yang namanya diambil dari nama matahari. Batangnya yang tinggi dan bunganya yang besar memberikan kesan yang arogan. Beberapa orang percaya bahwa bunga ini melambangkan \"hati yang mencari cahaya\".",
  str_item_intro_5234013 = "Area yang penuh dengan timbunan batu. Tanahnya sudah diratakan, dan area ini digunakan khusus untuk menanam beragam bunga.",
  str_item_intro_5234014 = "Dudukan pot bunga berukuran pendek. Cocok sebagai hiasan di pinggir jalan dan depan pintu.",
  str_item_intro_5234018 = "Tenda untuk satu orang yang bisa digunakan di alam liar. Bentuk kerucutnya memastikan tenda itu cukup tinggi. Meskipun mudah dipasang, tenda ini sangat kecil sehingga hanya bisa menampung satu orang.",
  str_item_intro_5234019 = "Taplak meja dengan segala jenis makanan. Sepertinya kamu bisa menikmati makanan lezat di alam liar!",
  str_item_intro_5234020 = "Kompor yang kokoh dan tahan panas. Celah di kakinya memastikan aliran udara yang masuk cukup sehingga api bisa menyala besar dan memancarkan panas yang tinggi.",
  str_item_intro_5234023 = "Bahkan rumput liar pun tak boleh disia-siakan. Kumpulkan sekarang karena kamu tak pernah tahu untuk apa rumput liar itu bisa digunakan nantinya.",
  str_item_intro_5234024 = "Peti besar dari papan kayu yang mudah diolah. Sangat cocok untuk menyimpan material.",
  str_item_intro_5234025 = "Tumpukan beberapa peti kayu. Saat melihatnya, kamu akan langsung tahu bahwa ini adalah gudang.",
  str_item_intro_5234037 = "Kompor kemah yang tersusun dari batu. Cocok untuk menyalakan api dengan aman saat berada di alam liar.",
  str_item_intro_5234038 = "Sebuah jangkar diselamatkan dari dasar laut. Ini sangat kuat dan kokoh dan terlihat seperti dapat menahan kapal besar di tempatnya bahkan ketika lautan sedang bergolak. Sangat disayangkan bahwa muatannya telah lama menghilang, meninggalkannya terus-menerus menunggu pemilik baru.",
  str_item_intro_5234039 = "Didukung oleh ombak yang bergelombang, papan selancar ini memungkinkan penggunanya untuk datang dan pergi sesuka hati di atas air dan melakukan berbagai gerakan. Sepertinya sayang untuk menempatkan ini di Cloud Gardens...",
  str_item_intro_5241002 = "Ayunan yang bergoyang pelan saat diduduki. Hati-hati, jangan berayun terlalu tinggi! Ada sebagian orang yang suka duduk dan tidur di ayunan ini. Kalau diayun-ayun seperti itu, memang jadi mudah mengantuk.",
  str_item_intro_5241003 = "Mainan yang menawarkan pengalaman seperti menunggang kuda sungguhan. Kata orang, mainan ini bisa membantu melatih keseimbangan kita.",
  str_item_intro_5241004 = "Main layang-layang adalah kegiatan seru saat cuaca cerah dan berangin. Setelah menerbangkan layang-layang ke langit, asalkan benangnya diikatkan ke rak, layang-layangnya tak akan kabur terbawa angin.",
  str_item_intro_5241005 = "Penyangga kanvas berbobot ringan yang dirancang untuk menggambar di luar ruang. Sudut dan ukurannya pas agar kamu tetap fokus selama menggambar.",
  str_item_intro_5241006 = "Panggung dan pengeras suara ditempatkan dengan cermat sehingga penonton bisa menikmati pertunjukan dari semua sisi. Menurut kabar, teater ini juga punya teknologi luar biasa, dan kadang menampilkan efek spesial yang berbeda-beda untuk berbagai program.",
  str_item_intro_5241007 = "Konon, patung ini dibangun untuk memperingati seorang wanita Caelestite yang mengunjungi semua gunung dan sungai yang terkenal di seantero benua. Namun, tak seorang pun mengingat namanya lagi, dan hanya patung ini yang tersisa sebagai memorial untuk generasi mendatang.",
  str_item_intro_5241008 = "Setiap kali melihatnya, kamu pasti jadi ingin meninjunya sedikit... Sayangnya, kamu tak akan pernah bisa menumbangkannya. Walau begitu, tetap saja samsak ini bagus sebagai sasaran luapan emosi.",
  str_item_intro_5241016 = "Koridor besar. Tiang-tiangnya tampak seperti tulang belulang dari makhluk kuno... Sebagian orang bilang bahwa koridor ini sebenarnya merupakan komponen penting dari Colossus.",
  str_item_intro_5242101 = "Walaupun tampak luarnya aneh, strukturnya yang unik membuat ruang di dalamnya mendapatkan banyak cahaya dan udara, sehingga sangat nyaman untuk dihuni.",
  str_item_intro_5243001 = "Lahan subur yang bisa memberikan nutrisi cukup untuk segala jenis tanaman.",
  str_item_intro_5234008 = "Kepala orang-orangan sawah ini terbuat dari linen. Jika Anda melihatnya dari dekat, itu terlihat seperti orang dengan banyak bopeng di wajahnya dan merupakan alat yang cukup efektif untuk menakut-nakuti orang.",
  str_item_intro_5234015 = "Sebuah gambar bernilai seribu kata. Tanda kayu ini dapat dipahami hanya dengan pandangan sekilas: \"Tolong jangan sakiti pangalo!\"",
  str_item_intro_5234016 = "Sebuah perangkat yang dapat digunakan untuk memberitahu waktu dengan proyeksi sinar matahari, bentuk primitif dari sebuah jam. Kelemahannya adalah jam matahari tidak berfungsi pada hari berawan dan hujan atau pada malam hari.",
  str_item_intro_5234017 = "Alat yang digunakan untuk menentukan arah angin. Ini cukup sensitif sehingga bahkan angin sepoi-sepoi dapat diukur secara akurat. Jika angin terlalu kencang dan berubah arah dari waktu ke waktu, ingatlah untuk menurunkannya! Jangan sampai berputar terlalu cepat dan pecah.",
  str_item_intro_5234026 = "Sebuah penggilingan batu yang tampaknya membutuhkan banyak usaha untuk bermanuver. Dikatakan telah digunakan untuk menggiling tepung di zaman kuno. Meskipun telah kehilangan efisiensinya di era modern, itu masih bagus untuk latihan kekuatan sesekali.",
  str_item_intro_5234027 = "Tong kayu yang ringan namun kokoh. Pegangannya memiliki desain anti slip sehingga tidak tumpah dan tidak ada usaha yang sia-sia.",
  str_item_intro_5234028 = "Meski terbuat dari keramik, namun ujung-ujungnya telah diperkuat sehingga tahan jatuh dan pecah, serta terdapat pegangan untuk memudahkan pemindahan.",
  str_item_intro_5234029 = "Mesin yang hanya membutuhkan satu operator untuk memutar kain. Satu-satunya downside dari itu adalah perawatan yang rumit. . .",
  str_item_intro_5234030 = "Sebuah pot berisi rumput hijau yang rimbun. Ini sangat berat dan membutuhkan tingkat kekuatan fisik tertentu untuk bergerak.",
  str_item_intro_5234033 = "Rak tertutup tanaman merambat. Ini dapat memberikan keteduhan di musim panas dan tetap hijau bahkan di akhir musim gugur.",
  str_item_intro_5234036 = "Sebuah petak bunga yang terdiri dari tiga tingkat batu memastikan bahwa bunga dapat ditanam di tingkat paling atas untuk menarik perhatian paling banyak, sedangkan dua tingkat bawah dapat menampung fauna hijau untuk menambah kontras.",
  str_item_intro_5241015 = "Perangkat menarik yang dapat Anda tempatkan rekaman untuk memutar musik. Loudspeaker telah memungkinkan untuk mengirimkan musik sehingga bergema jauh ke kejauhan.",
  str_item_intro_5241017 = "Aquarium",
  str_item_intro_5251001 = "Hyacinth Tower",
  str_item_intro_5252001 = "Museum",
  str_item_intro_5253001 = "Store",
  str_item_intro_5254001 = "Fountain of Hope",
  str_item_intro_5255001 = "Kotak besar, kokoh, tahan air, dan tahan debu yang mampu menyimpan banyak barang.",
  str_item_intro_5256001 = "Petualangan bersama teman-teman kita penuh dengan tantangan, sensasi, dan banyak kegembiraan dan tawa. Untuk memperingati momen-momen tak terlupakan selama perjalanan kami, teman-teman kami telah membuat lencana ini dan meletakkannya di sini sebagai hadiah untuk Caelestites dan diri mereka sendiri dan sebagai kenang-kenangan.",
  str_item_intro_5270001 = "Breeding Plot",
  str_item_intro_5275001 = "Demi cinta dan harapan, mari sebarkan lagu kita ke seluruh benua!\nPanggung ini khusus dibangun untuk tur—menampilkan berbagai fungsi, dapat didirikan dalam waktu singkat, dan juga sangat kokoh, mampu menahan segala macam kekacauan nyanyian dan tarian di atas permukaannya yang kokoh.",
  str_item_intro_5275002 = "Hanya diperlukan beberapa ketukan untuk menambahkan suasana ekstra istimewa itu ke sebuah pertunjukan! Jika Anda yakin sebuah band memiliki pemimpin alami, itu pasti drummernya. Itu sebabnya ini penting untuk setiap tahap tur.",
  str_item_intro_5275003 = "Bahkan musik dansa membutuhkan pengetahuan tentang komposisi musik, dan dengan keyboard yang mudah digunakan ini, dengan beragam suara dan efek, setiap pemain keyboard yang layak dapat menjadi mesin pembuat musik solo.",
  str_item_intro_5275004 = "Berharap pada bintang! Tidak ada yang tahu kapan rumor ini mulai menyebar di kalangan penggemar idola, namun ternyata, ketika Anda menginginkan dekorasi bintang seperti ini, dorongan tulus Anda akan disampaikan langsung kepada idola favorit Anda!",
  str_item_intro_5275005 = "Jika Anda ingin menyemangati idola favorit Anda, Anda memerlukan beberapa merchandise resmi untuk melambai di udara, jadi menempatkan meja seperti ini di dekat panggung cukup masuk akal—dengan begitu, penggemar bisa mendapatkan semua jenisnya. peralatan pendukung saat mereka sangat membutuhkannya.",
  str_item_intro_5275006 = "Sebagian besar tur membutuhkan berbagai gitar untuk disiapkan sebelumnya. Stand gitar ini tidak hanya memungkinkan gitaris untuk memilih gitar apa pun yang sesuai dengan gaya mereka, tetapi juga memungkinkan banyak gitaris untuk menyambungkan dan bermain bersama, memberikan tingkat keseruan tambahan pada penampilan apa pun.",
  str_item_intro_5275007 = "Perangkat amplifikasi semacam ini sangat diperlukan untuk artis tur — tidak peduli seberapa besar tempat itu, dan tidak peduli seberapa besar penontonnya, ini akan memastikan suara idola dapat didengar oleh semua orang... dan itu juga sangat lucu!",
  str_item_intro_5275008 = "Dekorasi ini biasanya diletakkan di dekat tempat wisata. Ketika Anda melihat mereka melayang di langit dan terbang tertiup angin, Anda pasti akan merasa bahwa mereka benar-benar menari dengan idola mereka yang terhormat.",
  str_item_intro_5275009 = "Lampu hias ini sering dijumpai di dekat panggung-panggung touring dan sepertinya digunakan oleh para penggemar untuk menyemangati idola mereka. Meskipun itu bukan merchandise resmi, ternyata dibuat dengan sangat baik.",
  str_item_intro_5275010 = "Bagaimana tur apa pun bisa lengkap tanpa standees idola? Bahkan jika Anda tidak dapat berfoto dengan idola Anda, atau bahkan melihat idola Anda dari dekat, selama Anda memiliki ini, Anda dijamin akan mendapatkan selfie yang layak.",
  str_item_intro_5275011 = "Bunga mewakili keinginan kebahagiaan, jadi tentu saja, banyak bunga mewakili banyak keinginan kebahagiaan. Jika Anda tidak hati-hati, seluruh tempat tur bisa dibanjiri oleh keranjang bunga yang dikirim oleh penggemar yang bersemangat untuk mendoakan idola favorit mereka.",
  str_item_intro_5275012 = "Rupanya, hiasan bintang di dinding ini ditempel oleh kipas satu per satu. Ini bukan sekadar dekorasi—ini adalah bukti pengabdian fanbase, simbol harapan tulus mereka agar tur idola mereka sukses.",
  str_item_intro_5275013 = "Kursi ini diatur khusus untuk tur, meskipun banyak penggemar lebih suka berdiri di atasnya untuk menyemangati idola mereka daripada duduk di atasnya. Ada alasan lain penggemar berdiri di kursi ini, tentu saja — agar idola mereka dapat melihat mereka di antara kerumunan.",
  str_item_intro_5234043 = [[
Karena salju sangat lembut, mengapa tidak membuat sofa?
Mungkin banyak orang yang memiliki ide ini sebelumnya. Tentu saja sofa ini terbuat dari bahan biasa, hanya saja bagian belakangnya terlihat seperti gunung bersalju, dan dengan bantalannya yang empuk, benar-benar membuat Anda serasa sedang berbaring di atas salju.]],
  str_item_intro_5234044 = "Legenda mengatakan bahwa makhluk luar biasa ini tidak pernah menjadi tua, dan tampilan yang indah ini mencerminkan inti dari legenda tersebut. Jika Anda menatapnya sebentar, Anda mungkin akan kecanduan.",
  str_item_intro_5234045 = "Serikat Kurir membawa pikiran dan keinginan dunia, bahkan sampai ke ujung Astra! Kotak surat ini konon dibuat khusus untuk tujuan ini, mengurangi jarak antara orang yang dicintai.",
  str_item_intro_5234046 = "Jika ada sesuatu yang tidak berani Anda katakan di hadapan seseorang, tulislah dalam surat dan taruh di sini. Seseorang tertentu itu mungkin hanya melihatnya dan mempelajari perasaan Anda.",
  str_item_intro_5276001 = "Venue seremonial yang biasanya disiapkan untuk Mooncrown Day ini sangat cocok untuk menggelar berbagai acara, terutama pernikahan.",
  str_item_intro_5276002 = "Baik untuk parade festival atau pernikahan, ini akan menjadi pilihan terbaik untuk gaya, dekorasi, dan kenyamanan.",
  str_item_intro_5276003 = "Penemuan baru yang menyenangkan. Jika pasangan masih saling menjaga setelah melakukan ini, itu hanya menunjukkan betapa mereka saling mencintai.",
  str_item_intro_5276004 = "Mawar di paviliun ini dibudidayakan khusus untuk festival, dan hanya mekar pada Hari Mooncrown untuk memberkati pengantin baru yang datang ke sini.",
  str_item_intro_5276005 = "Cokelat pada dasarnya pahit, dan hanya menjadi manis dengan tambahan gula. Mungkin... ini melambangkan seperti apa cinta itu? Bagaimanapun, itu telah menjadi salah satu hadiah simbolis dari Mooncrown Day, mungkin karena kebanyakan orang hanya mengingat manisnya dan mengabaikan pahitnya.",
  str_item_intro_5276006 = "Lengkungan ini dengan bentuknya yang unik dihiasi dengan bunga berbagai warna sehingga sangat cocok untuk pasangan baru untuk berfoto atau membuat keinginan di bawah.",
  str_item_intro_5276007 = "Dekorasi yang sering digunakan pada Hari Mahkota Bulan. Terdiri dari beberapa gelas tinggi berisi minuman, khusus digunakan untuk menjamu tamu.",
  str_item_intro_5276008 = "Bentuk tempat lilin yang tinggi ini enak dipandang mata dan mampu menyebarkan cahaya yang dipancarkan oleh lilin secara merata, menambahkan sentuhan romansa pada prosesi pernikahan yang lembut.",
  str_item_intro_5276009 = "Dicintai oleh semua petugas pernikahan. Perangkat ini memungkinkan semua tamu yang hadir untuk mendengar sumpah kedua pengantin baru dengan jelas, dan juga dapat memainkan musik untuk mengisi tempat dengan suasana yang sempurna.",
  str_item_intro_5276010 = "Sempurna untuk pasangan tempat duduk, bahkan saat itu bukan Hari Mooncrown. Hampir pasti dijamin akan ditempati pada Hari Mahkota Bulan.",
  str_item_intro_5276011 = "Hah? Mereka pasangan? Ah, itu hanya pakaian khusus yang dibuat untuk festival. Cukup pas untuk acara itu, kok.",
  str_item_intro_5276012 = "Cocok untuk Hari Mooncrown sebagai dekorasi dan hadiah untuk orang lain. Ini memberi perayaan warna-warni dan mengisi udara dengan aroma lembut.",
  str_item_intro_5276013 = "Karpet yang terbuat dari kelopak mawar! Benar-benar menunjukkan betapa seriusnya tuan rumah melakukan upacara tersebut. Saat pengantin baru melangkah ke atasnya, mata semua tamu yang hadir melihat ke arah mereka.",
  str_item_intro_5276101 = "Sebuah meja dengan kursi yang serasi dengan desain antik kuno yang untungnya juga sangat nyaman untuk diduduki, dan sepertinya cocok untuk pertemuan tertentu, terutama saat membahas kasus-kasus rumit. Mungkin tren ini adalah pengaruh dari seorang detektif terkenal tertentu.",
  str_item_intro_5276102 = "Mereka mengatakan bahwa detektif terkenal itu sering mengumpulkan intelijen, mengatur petunjuk, dan melakukan berbagai analisis pada papan jenis ini, bahkan hanya mengandalkan metode ini untuk menemukan pelakunya.",
  str_item_intro_5276103 = "Sejak detektif terkenal itu menjadi terkenal, kendaraan pilihannya juga semakin populer. Lagi pula, siapa yang tidak menikmati kendaraan yang begitu kokoh, cepat, dan mudah dioperasikan?",
  str_item_intro_5276104 = "Jika pikiran Anda terasa tersumbat, minum saja secangkir kopi. Dan jika Anda masih tidak bisa mengetahuinya, minumlah secangkir lagi. Sebagai pendamping terbaik untuk kontemplasi, detektif terkenal ini tidak pernah pelit dalam memilih perangkat kopi.",
  str_item_intro_5276105 = "Kejahatan tampaknya sering terjadi pada malam yang dingin, jadi detektif hebat perlu melengkapi diri mereka dengan mantel dan topi tahan angin. Ini secara alami membuat rak mantel ini penting dalam domisili detektif mana pun.",
  str_item_intro_5276106 = "Troli kecil dan ringan tempat kopi, makanan ringan, dan barang-barang lain untuk teh sore ditempatkan. Saat menjamu tamu, akan sangat nyaman bagi pelayan untuk mengatur berbagai makanan di atasnya secara tepat waktu.",
  str_item_intro_5276107 = "Ketika inspirasi deduktifnya mengering, atau dia terjebak dalam labirin pemikiran, detektif terkenal itu suka menggunakan instrumen ini untuk bersantai, memenuhi seluruh jalan dengan suara lagu-lagu pendeknya. Untungnya, yang dipedulikan orang bukanlah tingkat kemahiran musiknya, melainkan hasrat mereka terhadap legenda detektif hebat itu. Inilah mengapa begitu banyak orang berbondong-bondong untuk membeli instrumen ini.",
  str_item_intro_5276108 = "Sandaran punggung yang tinggi dan bantalan empuk memberikan kenyamanan maksimal sekaligus membantu menjaga postur duduk yang baik. Sangat cocok untuk detektif yang suka bersantai dan merenung.",
  str_item_intro_5276109 = "Rak berdesain unik ini dapat menampung banyak pipa dan menghadirkan nuansa detektif sejati di rumah Anda. Tentu saja, ini semua karena popularitas detektif terkenal di kalangan penggemar fiksi kriminal, jadi bahkan mereka yang tidak merokok juga dapat membelinya untuk dekorasi.",
  str_item_intro_5276110 = "\"Jangan biarkan satu petunjuk pun lolos darimu!\" Berkali-kali, detail terkecil mengungkapkan kebenaran. Kaca pembesar semacam ini sangat diperlukan sebagai aksesori standar untuk detektif terkenal.",
  str_item_intro_5276111 = "Lampu tahan angin dan ringan dengan kecerahan dan masa pakai superior yang dapat dibawa dengan mudah dengan satu tangan. Secara alami, itu juga bisa diletakkan di tanah.",
  str_item_intro_5276112 = "Papan tulis kecil ini tingginya relatif rendah. Bahkan ketika detektif terkenal duduk di kursinya, dia dapat menggunakannya untuk mengatur kasusnya saat ini, menjadikannya alat bantu yang berguna untuk analisis cepat.",
  str_item_intro_5276113 = "Bentuk penyangga buku berkaki dua ini cukup istimewa, tetapi sangat populer di kalangan detektif terkenal tertentu. Berbeda dari kebanyakan orang, estetika penahan bukunya juga berbeda dengan estetika umum lainnya. Tentu saja, sebagai penggila detektif, Anda pasti harus memiliki pasangan di rumah.",
  str_item_intro_5276114 = "Baik saat hujan atau cerah, payung selalu menjadi perisai yang baik dan dapat digunakan sebagai senjata dalam keadaan darurat. Oleh karena itu, menempatkan keranjang payung seperti ini di depan pintu sepertinya perlu untuk menyimpan berbagai macam payung.",
  str_item_intro_5234047 = "\"Ketika seorang penulis terjebak oleh badai salju di manor gunung, efisiensi menulis mereka meningkat sepuluh kali lipat.\" Hal ini tampaknya menjadi kepercayaan bersama di antara banyak editor Umbraton, dan telah menyebabkan popularitas mesin tik merek ini, yang untuk sementara waktu menjadi mesin tik pilihan para penulis kota.",
  str_item_intro_5234048 = "Sofa ini sangat penting jika Anda ingin membuka perusahaan besar di Umbraton. Para direktur akan duduk di sofa ini untuk mengurus bisnis mereka.",
  str_item_intro_5223003 = "Ubin lantai kecil bulat yang cocok untuk halaman rumput dan dekorasi pinggir jalan.",
  str_item_intro_5223004 = "Ubin bulat berukuran relatif besar yang tidak hanya dapat digunakan untuk jalan setapak tetapi juga dapat digunakan sebagai komponen utama dalam pengaspalan jalan.",
  str_item_intro_5351001 = "Ini adalah bangunan dan landmark yang paling menarik di Cloud Gardens. Banyak informasi yang digunakan untuk rekonstruksi Cloud Gardens tersimpan di sini.",
  str_item_intro_5351002 = "Ini adalah bangunan dan landmark yang paling menarik di Cloud Gardens. Banyak informasi yang digunakan untuk rekonstruksi Cloud Gardens tersimpan di sini.",
  str_item_intro_5351003 = "Ini adalah bangunan dan landmark yang paling menarik di Cloud Gardens. Banyak informasi yang digunakan untuk rekonstruksi Cloud Gardens tersimpan di sini.",
  str_item_intro_5352001 = "Tempat untuk memajang berbagai benda sekaligus merekam dan menyebarkan ilmu pengetahuan.",
  str_item_intro_5352002 = "Ruangannya tidak hanya lebih luas dari sebelumnya, tetapi juga sedikit dihias sehingga pameran bisa dilihat dengan mudah.",
  str_item_intro_5352003 = "Museum yang ditingkatkan dengan lebih banyak kamar. Tidak hanya memiliki banyak ruang, tetapi juga memfasilitasi penyortiran pamerannya.",
  str_item_intro_5353001 = "Tempat perdagangan di Cloud Gardens. Bukan hanya tempat untuk melakukan perdagangan umum, tetapi juga untuk menangani pesanan misterius!",
  str_item_intro_5353002 = "Terlihat jauh lebih bergaya sekarang berkat penambahan sejumlah dekorasi eksterior sederhana.",
  str_item_intro_5353003 = "Toko dengan banyak ruangan. Sekarang, toko ini beralih fungsi menjadi rumah besar yang didedikasikan untuk berdagang.",
  str_item_intro_5354001 = "Lihatlah mata air yang jernih ini. Kamu tak hanya bisa mengagumi ikan yang indah, tetapi juga bisa melempar koin untuk membuat permintaan.",
  str_item_intro_5354002 = "Kolam yang berukuran cukup besar. Kamu bisa melihat ikan yang berenang di dalam air yang jernih berkilau. Tak hanya itu, mimpimu juga bisa menjadi kenyataan.",
  str_item_intro_5354003 = "Mata air yang tak hanya menyediakan air bersih untuk ikan, tetapi juga bisa mengabulkan permintaanmu.",
  str_item_intro_5355001 = "Kotak besar, kokoh, tahan air, dan tahan debu yang mampu menyimpan banyak barang.",
  str_item_intro_5276201 = "Tempat duduk yang sopan biasanya disemarakkan oleh ujung belakang bangsawan Lumopolis yang paling mulia. Desainnya yang mewah secara efektif memancarkan intisari dari sikap mulia kelas atas, membuat kagum penduduk yang ternganga, sambil memaksa penghuninya untuk secara tidak sadar membatasi perilaku mereka sendiri. Tentu saja, penghuni ini memang perlu memiliki temperamen yang tepat untuk memulainya.",
  str_item_intro_5276202 = "\"Dunia di dalam dunia.\" Orang bilang bola kristal ini berisi hantu dari kota tertentu, tapi bagi sebagian orang, itu dianggap kenangan yang sangat berharga.",
  str_item_intro_5276203 = "\"Bersikaplah baik kepada yang lemah dan berani dalam menghadapi agresi.\" Ksatria membentuk landasan Lumopolis, dan juga panji negara kota, terbang tinggi di angin dunia. Meski nama patung ini tidak diketahui, bahkan orang awam pun terhanyut dalam semangat kesatria saat melihat sosoknya yang menjulang tinggi.",
  str_item_intro_5276204 = "Lemari pajangan ini tidak hanya mewah dalam desain, tetapi juga struktur yang kokoh, membuatnya praktis dan cukup cantik untuk menampung koleksi apa pun.",
  str_item_intro_5234049 = "\"Terukir di tablet batu, kata-kata bisa bertahan selama ribuan tahun.\" Lama setelah pemahatnya meninggalkan gulungan fana ini, kota itu terbengkalai, peradaban menjadi debu, namun monumen ini masih berdiri tegak, memungkinkan generasi mendatang untuk melihat sekilas dunia masa lalu. Mungkin inilah tujuan keberadaannya.",
  str_item_intro_5276206 = "Perlengkapan umum di kediaman bangsawan Lumopolis, yang sering digunakan sebagai meja panjang. Luas, tegas, dan elegan, cocok untuk menjamu tamu, teman, kumpul keluarga, bahkan untuk membicarakan hal-hal penting.",
  str_item_intro_5276207 = "Kursi bersandaran tinggi ini biasa ditemukan di rumah bangsawan Lumopolis. Pastikan kenyamanan seseorang sambil membantu menjaga postur tubuh yang lebih baik, menghindari potensi kecerobohan setiap saat.",
  str_item_intro_5276208 = "Bendera putih untuk kota putih. Simbol Lumopolis, yang memandanginya mengingatkan semua yang membuat kota itu seperti apa adanya — para ksatria, bangsawan, langit biru jernih, dan kemuliaan peradabannya.",
  str_item_intro_5276209 = "Dalam kesadaran kolektif massa, ini adalah cahaya yang tidak pernah padam, dan berkat Luminatics Lumopolis yang kuat, ini benar-benar tidak pernah padam.",
  str_item_intro_5276210 = "Pagar rendah yang elegan ini tidak dirancang untuk mencegah orang luar masuk, melainkan untuk menentukan rumah bangsawan dan batas perkebunan.",
  str_item_intro_5276211 = "Bahkan jika menyangkut tanaman pot seperti ini, Lumopolis berdiri terpisah dari keramaian. Tidak hanya potnya yang tinggi dan indah, tetapi tanaman hijau di dalamnya juga subur dan megah. Tampaknya terletak begitu tinggi di langit, pasti telah menyerap banyak sinar matahari.",
  str_item_intro_5276212 = "Sekumpulan tanaman merambat yang tumbuh terlalu tinggi terbentang di atas kepala. Meskipun mereka merambat dalam arah yang tersebar, ada keseragaman dalam susunannya, dengan celah di antara mereka yang tidak besar maupun kecil, gugusan yang tidak jarang atau padat, memungkinkan sinar matahari masuk dengan santai tanpa menyebabkan gangguan mendadak. Ketika angin sepoi-sepoi bertiup, itu menjadi tempat yang ideal untuk bersantai dan menikmati teh sore.",
  str_item_intro_5234050 = "Mungkin tidak sebanding dengan keagungan bianglala yang sebenarnya, tetapi tetap cukup besar. Kita tidak bisa naik, kita hanya menatap dari jauh dan menghidupkan kembali perasaan naik bianglala dalam pikiran kita.",
  str_item_intro_5234052 = "Di gurun, casing biru dan tangki air massalnya berubah dari simbol konflik menjadi kehadiran ilahi. Mereka mengguyur hujan dan embun, membawa kelegaan menyegarkan bagi mereka yang kehausan akibat kekeringan.",
  str_item_intro_5234053 = "Patung realistis yang menyerupai burung halus yang terbungkus pasir ini dapat dengan mudah mengecoh mata. Berhati-hatilah untuk tidak membuatnya basah; jika tidak, patung tersebut akan \"menghilang\" menjadi genangan pasir.",
  str_item_intro_5234054 = "Bisakah siapa pun benar-benar duduk di kursi ini? Meskipun bunga-bunga menambah keindahan, duri yang menghiasi tempat duduk menjadi pengingat konstan untuk \"Duduk tegak, atau berisiko bertemu duri yang tajam.\"",
  str_item_intro_5400001 = "Cairan misterius yang bisa membuat durasi budi daya Unique Tree menjadi jauh lebih singkat. Cairan ini sangat tidak stabil sehingga harus disimpan di dalam botol.",
  str_item_intro_5400002 = [[
Cairan lengket kemungkinan besar terbuat dari campuran getah Pohon Unik utama. Direbus dan dilengkapi dengan formulasi rahasia. Mampu mengubah genus Pohon Unik.
Penampilan: Cairan kental berwarna hijau dengan sisa-sisa lumpur kuning.]],
