  str_item_intro_5421111 = "Persilangan Quinlan Tree merah biasa dengan Rose Crystalloids ini tampak sangat cerah.",
  str_item_intro_5421112 = "Quinlan Tree I yang baru saja kamu tanam terlihat biasa saja, tapi pohon itu mengeluarkan suara yang indah jika tertiup embusan angin.",
  str_item_intro_5421113 = "Quinlan Tree kuning biasa yang disilangkan dengan Rose Crystalloids sedikit memberikan kesan sedih.",
  str_item_intro_5421211 = "Genus Dwarf Leaf Quinlan Tree, yang telah mengalami sedikit mutasi, disilangkan dengan Rose Crystalloids dan memiliki warna yang mirip dengan batu akik merah.",
  str_item_intro_5421212 = "Quinlan Tree II yang telah mengalami sedikit mutasi. Namanya berasal dari daunnya yang kecil dan lebat.",
  str_item_intro_5421213 = "Genus Dwarf Leaf Quinlan Tree, yang telah mengalami sedikit mutasi, disilangkan dengan Rose Crystalloids. Daun kuningnya melambai anggun saat tertiup angin.",
  str_item_intro_5421221 = "Genus Giant Leaf Quinlan Tree, yang telah mengalami sedikit mutasi, disilangkan dengan Rose Crystalloids, dan setiap daunnya terlihat seperti sepotong kristal merah tipis.",
  str_item_intro_5421222 = "Quinlan Tree II yang telah mengalami sedikit mutasi. Daunnya sangat lebar dan kuat sampai-sampai bisa langsung dijadikan pakaian.",
  str_item_intro_5421223 = "Genus Giant Leaf Quinlan Tree yang telah mengalami sedikit mutasi. Pohon ini disilangkan dengan Rose Crystalloids dan memiliki nuansa musim gugur.",
  str_item_intro_5421311 = "Quinlan Tree III yang telah mengalami mutasi berulang kali. Kanopinya lebat sementara daunnya lembut, rimbun, dan sangat unik.",
  str_item_intro_5421312 = "Genus berharga Good-Natured Quinlan Tree yang telah mengalami mutasi berulang kali. Pohon ini disilangkan dengan Rose Crystalloids. Kanopinya yang berwarna kebiruan tampak indah dipandang mata.",
  str_item_intro_5421313 = "Genus berharga Good-Natured Quinlan Tree, yang telah mengalami mutasi berulang kali, disilangkan dengan Rose Crystalloids. Daun kuningnya saling bertumpuk, dan bahkan tak akan terpencar saat angin bertiup kencang.",
  str_item_intro_5421321 = "Genus berharga Sunburst Quinlan Tree, yang telah mengalami mutasi berulang kali, disilangkan dengan Rose Crystalloids. Tajuk merahnya kini terlihat jauh lebih intens.",
  str_item_intro_5421322 = "Quinlan Tree III yang telah mengalami mutasi berulang kali. Kanopinya lebat, sedangkan cabangnya tebal dan tampak sangat kokoh.",
  str_item_intro_5421323 = "Genus berharga Sunburst Quinlan Tree yang telah mengalami mutasi berulang kali. Pohon ini disilangkan dengan Rose Crystalloids. Dari kejauhan, kanopinya yang berwarna kebiruan tampak seperti perairan yang tenang.",
  str_item_intro_5421331 = "Genus berharga Icy Blue Quinlan Tree yang telah mengalami mutasi berulang kali. Pohon ini disilangkan dengan Rose Crystalloids. Daun pohon yang berwarna merah jambu ini serasi dengan kanopi dan batangnya, memancarkan nuansa musim semi yang kental.",
  str_item_intro_5421332 = "Genus berharga Icy Blue Quinlan Tree, yang telah mengalami mutasi berulang kali, disilangkan dengan Rose Crystalloids. Tajuk merah pohon ini membentuk kontras kuat dengan citra aslinya yang dingin dan indah.",
  str_item_intro_5421333 = "Quinlan Tree III yang telah mengalami mutasi berulang kali. Dedaunannya tidak beraturan serta memancarkan nuansa permai.",
  str_item_intro_5421341 = "Genus berharga Mistral Quinlan Tree, yang telah mengalami mutasi berulang kali, disilangkan dengan Rose Crystalloids. Kanopi birunya memberikan kesan dingin pada nuansa yang memang sudah memancarkan aura dingin.",
  str_item_intro_5421342 = "Quinlan Tree III yang telah mengalami mutasi berulang kali. Tepi daunnya tajam, memancarkan pantulan yang tak beraturan. Saat kanopi tertiup angin, dedaunan ini menari-nari bagaikan belati, memancarkan nuansa kelam.",
  str_item_intro_5421343 = "Genus berharga Mistral Quinlan Tree, yang telah mengalami mutasi berulang kali, disilangkan dengan Rose Crystalloids. Daun kuning mudanya melembutkan aura aslinya yang dingin dan memberikan sedikit kesan hangat.",
  str_item_intro_5421411 = "Genus langka Sungazing Quinlan Tree, yang telah mengalami mutasi kompleks, disilangkan dengan Rose Crystalloids. Tajuk biru pohon ini seperti mereka yang berhati murni, menengadah ke langit biru dan berdoa. Oleh karena itu, ia juga disebut \"Praying Quinlan Tree\".",
  str_item_intro_5421412 = "Quinlan Tree IV yang telah mengalami mutasi kompleks. Pohon ini berbentuk seperti trompet yang ditengadahkan ke langit. Sulit untuk membayangkan bagaimana bisa batang sekecil ini mampu menopang kanopi pohon yang begitu lebat. Pasti itu berkat kekuatan misterius.",
  str_item_intro_5421413 = "Genus langka Sungazing Quinlan Tree, yang telah mengalami mutasi kompleks, disilangkan dengan Rose Crystalloids. Tajuk kuningnya yang berbentuk trompet itu terlihat seperti trompet kuningan. Konon pada zaman kuno, para raksasa menggunakannya untuk bermain musik! Karena itulah, pohon itu juga dinamai \"Horn Quinlan Tree\".",
  str_item_intro_5421421 = "Genus langka Monolith Quinlan Tree, yang telah mengalami mutasi kompleks, disilangkan dengan Rose Crystalloids. Saat berdiri di atas tajuk hijau pohon itu, kamu akan merasa sedang berada di atas perbukitan, sehingga pohon ini juga disebut \"Hillock Quinlan Tree\".",
  str_item_intro_5421422 = "Genus langka Monolith Quinlan Tree, yang telah mengalami mutasi kompleks, disilangkan dengan Rose Crystalloids. Tajuk putihnya tampak sangat halus, dan kamu bahkan bisa tidur dengan nyenyak di atasnya.",
  str_item_intro_5421423 = "Quinlan Tree IV yang telah mengalami mutasi kompleks. Kanopi pohonnya mengeras hingga berubah menjadi mimbar batu kecil! Konon, di dalam batang pohon, ada tongkat batu yang menopang kanopi yang diselimuti oleh kulit kayu yang keras... Apakah Unique Tree ini bisa dikategorikan sebagai tanaman? Masih menjadi perdebatan.",
  str_item_intro_5421431 = "Quinlan Tree IV yang telah mengalami mutasi kompleks. Dedaunannya berserabut, lembut, halus, dan tergulung. Tampak seperti jiwa membara yang tercatat dalam legenda. Beberapa orang mengatakan bahwa genus ini memiliki kesadarannya sendiri, bahkan jiwa...",
  str_item_intro_5421432 = "Genus langka Psyche Quinlan Tree, yang telah mengalami mutasi kompleks, disilangkan dengan Rose Crystalloids. Tajuk merahnya terlihat menakutkan, tetapi punya daya tarik yang membius siapa pun yang melihatnya. Saat daunnya yang lembut itu menari tertiup angin, kamu bisa langsung terpesona dan memandanginya siang dan malam.",
  str_item_intro_5421433 = "Genus langka Psyche Quinlan Tree, yang telah mengalami mutasi kompleks, disilangkan dengan Rose Crystalloids. Daun kuningnya membentuk berbagai jalinan kecil yang berayun di tajuk pohon, seolah-olah sedang menyambut seseorang. Dari situlah ia mendapat sebutan \"Welcoming Quinlan Tree\".",
  str_item_intro_5421441 = "Pohon Quinlan IV yang telah mengalami mutasi kompleks. Daun konvergen telah berkumpul untuk membentuk kanopi besar dan padat. Dari waktu ke waktu, daun-daun beterbangan, tampak seperti daun-daun yang berjatuhan.",
  str_item_intro_5421442 = "Genus langka dari Blooming Quinlan Tree, yang telah mengalami mutasi kompleks, dibiakkan dengan Rose Crystalloids. Mahkota hijau terlihat penuh vitalitas. Jika Anda mendekati cabang-cabang yang menggantung, mereka akan sedikit bergetar, dan seluruh pohon akan berdesir seperti merespons seseorang ...",
  str_item_intro_5421443 = "Genus langka dari Blooming Quinlan Tree, yang telah mengalami mutasi kompleks, dibiakkan dengan Rose Crystalloids. Ketika daun biru jatuh satu sama lain, itu memberi orang ilusi bahwa mereka berada di sungai atau laut, karena itu juga disebut \"Pohon Quinlan di darat.\"",
  str_item_intro_5421451 = "Pohon Quinlan IV yang telah mengalami mutasi kompleks. Ini sangat langka dan kuat. Seperti namanya, rumor mengatakan bahwa pohon itu terus tumbuh setelah ditebang.",
  str_item_intro_5421452 = "Genus langka dari Pohon Quinlan pantang menyerah yang dibiakkan dengan Kristaloid Mawar. Daunnya yang cokelat memberi kesan menua, tetapi bahkan lebih hidup. Dikatakan dapat bertahan hidup tanpa air.",
  str_item_intro_5421453 = "Genus langka dari Pohon Quinlan pantang menyerah yang dibiakkan dengan Kristaloid Mawar. Tumbuh sangat cepat sehingga mahkota biru hampir terbentuk dalam semalam, demikian julukannya, Samudra Daun yang Tak Berujung.",
  str_item_intro_5421461 = "Pohon Quinlan IV yang telah mengalami mutasi kompleks. Ini sangat langka. Ini bercabang dari akarnya ke kedua sisi dan loop ke atas dalam lingkaran, tampak seperti kusen pintu yang dibuat dengan pohon, maka nama informalnya, The Quinlan Doorway.",
  str_item_intro_5421462 = "Genus langka dari Archway Quinlan Tree yang dibiakkan dengan Rose Crystalloids. Lengkungan biru pohon terkadang berkabut dan tertutup es di musim dingin. Dari kejauhan, tampak seperti pohon yang terbentuk dari salju dan es.",
  str_item_intro_5421463 = "Genus langka dari Archway Quinlan Tree yang dibiakkan dengan Rose Crystalloids. Alih-alih mengintimidasi mereka yang memandangnya, pintu merah ini menghasilkan perasaan hangat dan nyaman. Ada yang mengatakan bahwa itu membawa keberuntungan bagi penanamnya.",
  str_item_intro_5421471 = "Pohon Quinlan IV yang telah mengalami mutasi kompleks. Pohon yang sangat langka ini memiliki efek yang sangat menenangkan bagi semua orang yang melihatnya, karena batang dan mahkotanya yang bercabang bergoyang tertiup angin, dan bagaimana ia berkilau dengan tetesan embun. Inilah mengapa dikenal sebagai \"Carefree Quinlan.\"",
  str_item_intro_5421472 = "Genus langka dari Winsome Quinlan Tree yang telah mengalami mutasi kompleks setelah dibiakkan dengan Rose Crystalloids. Karena embun biru yang menumpuk di daunnya, Quinlan ini terlihat seperti terendam di laut dangkal jika dilihat dari jauh, oleh karena itu dijuluki Mercusuar Winsome.",
  str_item_intro_5421473 = "Genus langka dari Winsome Quinlan Tree yang telah mengalami mutasi kompleks setelah dibiakkan dengan Rose Crystalloids. Embun ungu memberi pesona pada keseluruhan pohon unik ini. Saat bergoyang tertiup angin, terlihat riang dan puas sambil memancarkan daya pikat yang mempesona.",
  str_item_intro_5421481 = "Pohon Quinlan IV yang telah mengalami mutasi kompleks. Batang tegak pohon yang sangat langka ini dan mahkota berbentuk api membuatnya berdiri tegak seperti mercusuar yang menyala. Ada kemungkinan bahwa mereka yang memandang bentuknya mungkin salah mengartikannya sebagai sumber penerangan yang sebenarnya!",
  str_item_intro_5421482 = "Genus langka dari Pohon Blazing Quinlan yang telah mengalami mutasi kompleks setelah dibiakkan dengan Rose Crystalloids. Mahkota besar berwarna merah muda dari pohon ini seperti awan kabut misterius yang mengapung di batang dan dahan. Saat angin bertiup, mahkota \"Kabut Air Mawar\" menjadi tidak beraturan, menginfeksi orang yang melihatnya dengan sensasi yang aneh.",
  str_item_intro_5421483 = "Genus langka dari Pohon Blazing Quinlan yang telah mengalami mutasi kompleks setelah dibiakkan dengan Rose Crystalloids. Mahkota merahnya membuatnya menjadi obor yang nyata, terutama saat menari tertiup angin, menciptakan ilusi api padang rumput yang mengamuk.",
  str_item_intro_5422111 = "Persilangan Mint Green Arthur Tree dengan Rose Crystalloids ini tinggi dan memberikan nuansa musim semi.",
  str_item_intro_5422112 = "Persilangan Dark Green Arthur Tree dengan Rose Crystalloids ini kokoh dan menenangkan.",
  str_item_intro_5422113 = "Arthur Tree I yang kamu tanam belum lama ini tampak biasa saja. Namun, batangnya yang tinggi dan lurus, cabang-cabangnya yang kokoh, dan dedaunannya yang berbentuk jarum dan tumbuh ke atas ini membuatnya tampak istimewa.",
  str_item_intro_5422211 = "Genus Short Leaf Arthur Tree, yang telah mengalami sedikit mutasi, disilangkan dengan Rose Crystalloids. Dedaunan jarum merahnya berukuran sangat pendek. Gugurannya yang tampak seperti karpet merah yang membentang di bawah pohon itu begitu memanjakan mata.",
  str_item_intro_5422212 = "Genus Short Leaf Arthur Tree, yang telah mengalami sedikit mutasi, disilangkan dengan Rose Crystalloids. Jarum pendeknya bertekstur hijau seperti zamrud berbintik.",
  str_item_intro_5422213 = "Arthur Tree II yang telah mengalami sedikit mutasi ini sangat berbeda dari jenis aslinya. Karena cabang-cabangnya menjulur keluar, kanopinya jarang dan daunnya menjadi pendek dan tebal. Kalau bukan karena catatan khusus yang disertakan, mungkin kita tak akan tahu bahwa ini adalah Arthur Tree.",
  str_item_intro_5422221 = "Genus Long Leaf Arthur Tree, yang telah mengalami sedikit mutasi, disilangkan dengan Rose Crystalloids. Daunnya cepat mengering setelah gugur, dan menimbulkan suara \"gemeresak\" yang menyenangkan jika diinjak.",
  str_item_intro_5422222 = "Genus Long Leaf Arthur Tree, yang telah mengalami sedikit mutasi, disilangkan dengan Rose Crystalloids. Daun rampingnya lembut, tetapi keras, dan banyak orang yang suka memakainya untuk membuat badan pena.",
  str_item_intro_5422223 = "Arthur Tree II yang telah mengalami sedikit mutasi. Bentuknya berubah drastis. Cabangnya tumbuh tak beraturan dan dedaunannya tumbuh memanjang. Sulit untuk membayangkan bahwa pohon ini berasal dari Arthur Tree yang tinggi itu.",
  str_item_intro_5422311 = "Arthur Tree III yang telah mengalami mutasi berulang kali. Kanopi dan batang pohonnya bergabung menjadi satu, membuatnya tampak seperti gunung batu. Permukaannya keras sementara dalamnya berongga. Jika dipukul, pohon ini mengeluarkan gema yang indah.",
  str_item_intro_5422312 = "Genus berharga Ridge Arthur Tree, yang telah mengalami mutasi berulang kali, disilangkan dengan Rose Crystalloids. Tekstur hijau di satu sisi cabangnya sering disalahartikan sebagai lumut yang menempel padanya.",
  str_item_intro_5422313 = "Genus berharga Ridge Arthur Tree yang telah mengalami mutasi berulang kali dan disilangkan dengan Rose Crystalloids. Sebagian kulit kayunya menunjukkan warna merah terang, yang menjadi inspirasi beberapa cerita horor. Namun, semuanya hanya mitos belaka.",
  str_item_intro_5422321 = "Arthur Tree III yang telah mengalami mutasi berulang kali. Kanopinya rendah sementara batangnya yang panjang dan tidak keras menggantung ke bawah. Dari kejauhan, pohon ini tampak seperti hutan kecil. Oleh karena itu, pohon ini terkenal dengan julukan \"Hutan Pohon Tunggal.\"",
  str_item_intro_5422322 = "Genus berharga Banyan Arthur Tree, yang telah mengalami mutasi berulang kali, disilangkan dengan Rose Crystalloids. Tajuk merahnya yang besar seperti payung, yang mampu menghalangi terik matahari dan menjadi tempat untuk berteduh.",
  str_item_intro_5422323 = "Genus berharga Banyan Arthur Tree, yang telah mengalami mutasi berulang kali dan disilangkan dengan Rose Crystalloids. Memiliki kanopi hijau besar dan cabang-cabang kuat yang menggantung. Siapa pun yang berjalan di dekatnya mungkin akan mengira mereka telah tersesat sampai ke dalam hutan kecil.",
  str_item_intro_5422331 = "Genus berharga Heath Arthur Tree, yang telah mengalami mutasi berulang kali, disilangkan dengan Rose Crystalloids. Kanopinya yang agak pucat serasi dengan batangnya yang retak, dan membuat banyak orang mengira pohon ini sudah layu. Namun, mereka pasti berubah pikiran setelah menyadari pohon itu sudah lama sekali berdiri di sana.",
  str_item_intro_5422332 = "Arthur Tree III yang telah mengalami mutasi berulang kali. Bentuknya menyerupai pohon lapuk yang biasa ada di alam liar, dan dari situlah asal nama pohon ini. Namun, kanopi kecil yang tumbuh di batangnya yang bengkok menunjukkan kemampuan bertahan hidupnya yang teguh, seakan-akan memberi tahu semua orang bahwa \"Aku masih hidup.\"",
  str_item_intro_5422333 = "Genus berharga Heath Arthur Tree, yang telah mengalami mutasi berulang kali dan disilangkan dengan Rose Crystalloids. Kanopi hijau dan cabangnya yang layu menjadi kontras yang kuat. Beberapa orang bahkan akan menduga keduanya berasal dari satu tanaman, tetapi kanopi dan cabang itu sebenarnya memang berasal dari Heath Arthur Tree yang sama. Mungkin itulah yang menjadi pesona Unique Tree.",
  str_item_intro_5422341 = "Genus berharga Lake Arthur Tree, yang telah mengalami mutasi berulang kali, disilangkan dengan Rose Crystalloids. Getahnya berwarna kuning muda dan rasanya agak pahit di awal, tetapi rasa yang tertinggal sedikit manis. Konon getahnya bisa memulihkan kekuatan fisik, dan beberapa orang mengatakan bahwa jika diminum terlalu banyak akan membuat pusing.",
  str_item_intro_5422342 = "Arthur Tree III yang telah mengalami mutasi berulang kali. Namanya berasal dari kolam alami yang terbentuk di bagian akar pohon dan kanopinya yang selalu meneteskan air. Tak ada seorang pun yang dapat memahami cara kerja dan makna siklus misterius ini. Orang-orang hanya bisa meminum air dari kolam akarnya dan mengagumi kekuatan mutasi.",
  str_item_intro_5422343 = "Genus berharga Lake Arthur Tree yang telah mengalami mutasi berulang kali dan disilangkan dengan Rose Crystalloids. Air di kolamnya berwarna hijau. Sekilas tampak beracun, tetapi sebenarnya sangat dingin dan secara mengejutkan beraroma menyegarkan.",
  str_item_intro_5422411 = "Genus berharga Inkstone Arthur Tree, yang telah mengalami mutasi berulang kali, disilangkan dengan Rose Crystalloids. Sebagian batang dan tajuknya akan mengeluarkan cahaya hijau, seolah-olah ada sungai yang mengalir di dalamnya, yang terlihat luar biasa sekali.",
  str_item_intro_5422412 = "Arthur Tree IV yang telah mengalami mutasi kompleks. Akarnya menyembul ke permukaan tanah, batangnya gembung dan keras, dan kanopinya berkilau dengan dedaunan yang rimbun! Dari kejauhan, pohon ini tampak seperti mercusuar kecil, dan karenanya dijuluki \"Lighthouse Arthur Tree.\"",
  str_item_intro_5422413 = "Genus langka Inkstone Arthur Tree, yang telah mengalami mutasi berulang kali, disilangkan dengan Rose Crystalloids. Batangnya berbentuk batu dan tajuknya bersinar seperti emas. Mereka yang tidak mengenalnya mungkin akan mengira bahwa mereka telah tiba di sebuah istana megah, dan itu membuat pohon ini juga dikenal sebagai \"Palace Arthur Tree\".",
  str_item_intro_5422421 = "Arthur Tree IV yang telah mengalami mutasi kompleks. Sebagian batangnya menyatu dengan kanopi yang mengeras dan membentuk pelat batu berongga! Bagian luar pelat batu ini keras, tetapi tipis. Akan menghasilkan berbagai macam suara ketika dipukul. Bahkan, beberapa orang mengatakan bahwa pohon ini bisa bicara melalui kanopinya...",
  str_item_intro_5422422 = "Genus langka Boulder Arthur Tree, yang telah mengalami mutasi kompleks, disilangkan dengan Rose Crystalloids. Tajuk hijaunya yang besar tampak seperti permata hijau. Ketuklah dengan lembut, dan ia akan menghasilkan segala jenis suara yang jernih dan merdu, yang membuatnya dijuluki \"Arthur Tree Musician\".",
  str_item_intro_5422423 = "Genus langka Boulder Arthur Tree, yang telah mengalami mutasi kompleks, disilangkan dengan Rose Crystalloids. Lempengan batu biru itu menghasilkan suara yang merdu dan sedikit bergetar, membentuk bayangan biru berkedip yang samar.",
  str_item_intro_5422431 = "Genus langka Shutter Arthur Tree, yang telah mengalami mutasi kompleks dan disilangkan dengan Rose Crystalloids. Saat jantung pohon yang berwarna kuning itu bersinar, tekstur batangnya akan menghasilkan ilusi daun kuning muda, yang membuat orang merasa Unique Tree ini kembali dipenuhi kehidupan! Oleh karena itu, pohon ini dijuluki \"Resurrected Arthur Tree.\"",
  str_item_intro_5422432 = "Arthur Tree IV yang telah mengalami mutasi kompleks. Batangnya berongga sementara bagian tengah pohonnya berbentuk jamur yang aneh dan memancarkan cahaya yang menakjubkan. Konon, saat mendeteksi bahaya, kulit kayu terluarnya akan menutup dan menghalangi cahaya yang akan masuk. Dengan demikian, pohon ini juga dikenal dengan nama \"Lightblocker Arthur Tree.\"",
  str_item_intro_5422433 = "Genus langka Shutter Arthur Tree, yang telah mengalami mutasi kompleks, disilangkan dengan Rose Crystalloids. Memancarkan cahaya biru dari jantung pohonnya. Setelah terpantul di batang berongganya, cahaya itu akan membuat ilusi seolah-olah pohon ini dikelilingi aliran air, dan mereka bahkan bisa salah mengira sedang berada di bawah air...",
  str_item_intro_5422441 = "Pohon Arthur IV yang telah mengalami mutasi kompleks. Beberapa cabang dan daun pohon ini telah bergabung dan bermutasi menjadi \"lentera.\" Cabang-cabang yang bertindak sebagai \"sumbu\" bahkan dapat memancarkan cahaya hangat! Tidak diragukan lagi bahwa ini adalah suar bagi para pelancong yang berjalan di hutan belantara yang gelap.",
  str_item_intro_5422442 = "Genus langka dari Brightness Arthur Tree, yang telah mengalami mutasi kompleks, dibiakkan dengan Rose Crystalloids. Dikatakan bahwa \"lenteranya\" memancarkan cahaya biru lembut karena batangnya berisi Lumina.",
  str_item_intro_5422443 = "Genus langka dari Brightness Arthur Tree, yang telah mengalami mutasi kompleks, dibiakkan dengan Rose Crystalloids. Daunnya berwarna merah, tetapi \"lenteranya\" memancarkan cahaya merah samar yang memantul pada batang putihnya, memberikan pesona yang unik.",
  str_item_intro_5422451 = "Pohon Arthur IV yang telah mengalami mutasi kompleks. Kanopi pohon telah menghilang, dan batangnya ditutupi tanaman merambat yang seluruhnya terdiri dari kelopak bunga yang cerah. Dengan beberapa tanaman merambat yang terjalin erat dan yang lainnya menggantung longgar, pohon ini menyerupai gerbang bunga dari kejauhan.",
  str_item_intro_5422452 = "Genus langka dari Pohon Arthur yang dibiakkan dengan Kristaloid Mawar. Kelopak putihnya sangat dingin saat disentuh tetapi terasa agak hangat setelah dipetik dari pohonnya.",
  str_item_intro_5422453 = "Genus langka dari Pohon Arthur yang dibiakkan dengan Kristaloid Mawar. Kelopak bunganya yang hijau dan cerah terlihat jelas seperti daun; perbedaannya hanya terlihat jika dilihat dari dekat.",
  str_item_intro_5422461 = "Pohon Arthur IV yang telah mengalami mutasi kompleks. Di tempat kanopi adalah bola energi kolosal yang tumbuh dari ujung cabangnya! Bola ini, yang dikenal sebagai \"fluorofor\", tampaknya terdiri dari Lumina; ketika angin sepoi-sepoi bertiup, cahayanya mengalir melalui dedaunan yang jatuh dan membawa cahaya lembut ke sekelilingnya.",
  str_item_intro_5422462 = "Genus langka dari Pohon Arthur yang dibiakkan dengan Kristaloid Mawar. Fluorofornya yang bercahaya berwarna biru seperti laut, dan ketika melayang tertiup angin, ia memberi orang perasaan bahwa bola air berputar-putar di atas pohon. Di beberapa tempat, ia dikenal sebagai Penari Air Pohon Unik.",
  str_item_intro_5422463 = "Genus langka dari Arthur Tree yang dibiakkan dengan Rose Crystalloids. Fluorofor kuningnya penuh dengan vitalitas yang nyata dan bahkan dapat membuat flora di sekitarnya berkembang dengan energinya.",
  str_item_intro_5422471 = "Arthur Tree IV yang telah mengalami mutasi kompleks. Mahkotanya telah sepenuhnya bermutasi, ke titik di mana sekarang pada dasarnya adalah massa padat yang terkulai di semua sisi, membentuk bentuk mangkuk yang aneh. Cabang-cabangnya yang indah menonjol dari tengah \"mangkuk\" ini, berkelap-kelip seperti obor untuk menarik perhatian semua orang yang melihatnya.",
  str_item_intro_5422472 = "Genus langka dari Pohon Arthur yang Sedang Berkembang yang mengalami mutasi kompleks setelah dibiakkan dengan Kristaloid Mawar. Mahkotanya yang berbentuk mangkuk berwarna biru menenangkan, dan cahaya yang dipantulkan dari bagian tengah ini menghasilkan sensasi yang mirip dengan berada di air yang dalam, oleh karena itu nama lainnya, \"Illusion of the Abyss\".",
  str_item_intro_5422473 = "Genus langka dari Pohon Arthur yang Sedang Berkembang yang mengalami mutasi kompleks setelah dibiakkan dengan Kristaloid Mawar. Berdiri di bawahnya, Anda dapat melihat bahwa mahkota merah itu seperti matahari terbenam berwarna merah darah yang menghalangi langit, menciptakan ilusi terbungkus senja.",
  str_item_intro_5422481 = "Arthur Tree IV yang telah mengalami mutasi kompleks. Seluruh pohon telah mengeras dan bermutasi menjadi platform batu. Gemericik air yang jatuh dari atas kebetulan mengalir ke dalam lubang pohon, menciptakan pemandangan yang cukup indah.",
  str_item_intro_5422482 = "Genus langka dari Radiant Arthur Tree yang dibiakkan dengan Rose Crystalloids. Batangnya berwarna putih. Bersama dengan air terjun berwarna biru muda, membentuk pemandangan yang cukup menyegarkan. Cukup berdiri di bawah pohon dan mendengarkan suara aliran air saja sudah menyenangkan, oleh karena itu disebut \"Tetesan Kesenangan\".",
  str_item_intro_5422483 = "Genus langka dari Radiant Arthur Tree yang dibiakkan dengan Rose Crystalloids. Batang dan \"cabang\" teratas berwarna biru yang menarik. Dilihat melalui aliran kuning, seluruh pohon mengeluarkan getaran aneh, oleh karena itu dinamai \"kabur ungu-biru\".",
  str_item_intro_5423111 = "Pohon Mekar dasar yang baru-baru ini dipelihara hingga dewasa dan sudah menunjukkan karakteristik uniknya, yaitu bunganya yang mekar.",
  str_item_intro_5423112 = "Sebuah Pohon Mekar Ungu yang telah dipelihara menggunakan Kristaloid Mawar. Memancarkan cahaya yang redup dan mempesona.",
  str_item_intro_5423113 = "Pohon Yellow Arthur yang dibesarkan dengan Rose Crystalloids berjemur dalam cahaya lembutnya, mengingatkan kehangatan matahari terbenam.",
  str_item_intro_5423211 = "Pohon Mekar II yang telah mengalami beberapa mutasi kecil. Sudah menyerupai varietas yang sama sekali berbeda, ia memiliki banyak batang yang mencuat dari satu akar bawah tanah; ini memberi kesan bahwa itu sebenarnya adalah sekelompok beberapa tanaman. Meskipun sangat berbeda dalam penampilan dari Pohon Mekar dasar, bunganya cukup untuk menunjukkan bahwa itu adalah turunan yang terkait erat tetapi bermutasi.",
  str_item_intro_5423212 = "Sebuah genus dari Pohon Mekar Meriah, yang telah mengalami beberapa mutasi kecil, dibiakkan dengan Kristaloid Mawar. Rona kuning muda dari bunganya menyerupai beberapa matahari kecil, menawarkan pemandangan yang menakjubkan untuk dilihat semua orang.",
  str_item_intro_5423213 = "Sebuah genus dari Pohon Mekar Meriah, yang telah mengalami beberapa mutasi kecil, dibiakkan dengan Kristaloid Mawar. Bunganya yang berwarna biru pucat bergoyang lembut tertiup angin seperti awan yang melayang di langit.",
  str_item_intro_5423221 = "Pohon Mekar II yang telah mengalami beberapa mutasi kecil. Meskipun batangnya jauh lebih tebal daripada Pohon Mekar biasa, perbedaan yang paling mencolok terletak pada bunganya. Memanjang dan berbentuk seperti terompet yang tak terhitung jumlahnya, mereka juga merupakan alasan mengapa pohon ini diberi nama.",
  str_item_intro_5423222 = "Sebuah genus dari Pohon Mekar nyaring, yang telah mengalami beberapa mutasi kecil, dibiakkan dengan Kristaloid Mawar. Bunganya yang berwarna biru mengandung kadar air yang tinggi dan dapat digunakan untuk menghilangkan dahaga atau bahkan menyeduh minuman spesial!",
  str_item_intro_5423223 = "Sebuah genus dari Pohon Mekar nyaring, yang telah mengalami beberapa mutasi kecil, dibiakkan dengan Kristaloid Mawar. Bunganya berwarna merah menyala, dan akan melunak dan mengering dengan cepat setelah dikeluarkan dari pohon. Ini membuat mereka menjadi bahan kayu bakar yang sangat cocok.",
  str_item_intro_5423311 = "Pohon Mekar III yang sering mengalami mutasi. Bunganya hanya tumbuh di batangnya, sementara banyak cabang muncul dari akarnya dan mengelilinginya. Penampilan misteriusnya telah disamakan dengan sekelompok penjaga kekaisaran yang melindungi ratu mereka.",
  str_item_intro_5423312 = "Genus langka dari Sheltered Blooming Tree yang dibiakkan dengan Rose Crystalloids. Bunganya telah berubah warna menjadi hampir keemasan, dan bahkan tampak memantulkan sinar matahari saat terlihat bergoyang di kejauhan.",
  str_item_intro_5423313 = "Pohon Mekar Terlindung yang telah sering mengalami mutasi. Bunganya yang biru muda menawarkan kontras yang tajam dengan daun dan batangnya, yang sangat menyenangkan bagi para pengagumnya.",
  str_item_intro_5423321 = "Pohon Mekar Wistful yang telah sering mengalami mutasi. Batangnya melengkung menjadi lingkaran yang hampir sempurna, dan kanopinya dibentuk oleh bunganya yang lebat dan menggantung. Strukturnya yang unik dan hampir tidak logis sama menakjubkannya dengan membingungkan.",
  str_item_intro_5423322 = "Genus langka dari Wistful Blooming Tree yang dibiakkan dengan Rose Crystalloids. Bunga biru yang menggantung rendah dan bentuk melingkar membentuk pintu masuk alami. Bahkan ketika ditempatkan di pintu masuk taman buatan, taman ini sangat cocok dengan lingkungan sekitarnya sambil tetap menawarkan pemandangan yang menakjubkan.",
  str_item_intro_5423323 = "Pohon Mekar Wistful yang telah sering mengalami mutasi. Bunganya telah berubah menjadi warna putih pucat dan lembut, dan aroma bunga yang segar dapat terlihat saat berdiri di bawah kanopinya. Dengan demikian, bunganya telah menjadi bahan baku penting untuk banyak parfum.",
  str_item_intro_5423331 = "Pohon Mekar III yang sering mengalami mutasi. Batangnya telah terpelintir dan berkerut menjadi bentuk bunga raksasa, yang dapat dilihat dari jarak yang cukup jauh. Bunganya yang sebenarnya, bagaimanapun, terletak di dalam batang dan cabangnya yang keriput, membuat para peneliti berteori bahwa bentuknya yang unik dimaksudkan untuk melindungi mereka dari calon pemangsa.",
  str_item_intro_5423332 = "Genus langka dari Iris Blooming Tree yang dibiakkan dengan Rose Crystalloids. Ujung cabangnya diwarnai biru muda, dan meneteskan cairan yang lebih gelap. Menurut beberapa orang, cairan ini dapat digunakan sebagai jenis tinta, atau bahkan sebagai pewarna kain.",
  str_item_intro_5423333 = "Pohon Iris Mekar yang sering mengalami mutasi. Ujung cabangnya berwarna hijau muda, sedangkan genangan air di dasarnya memancarkan cahaya biru tua, memberikan aura energi alam yang kuat.",
  str_item_intro_5423341 = "Pohon Mekar III yang sering mengalami mutasi. Dikatakan menyerupai pohon dari negeri yang jauh, bunga-bunganya yang mekar indah dan dipenuhi dengan keharuman yang ringan. Dengan menatap pohon ini untuk waktu yang lama, pelangi dikatakan akan muncul di depan mata Anda. Meskipun ini hanya legenda, namun itulah alasan mengapa pohon ini diberi nama.",
  str_item_intro_5423342 = "Genus langka dari Iridescent Blooming Tree yang dibiakkan dengan Rose Crystalloids. Bunga ungunya sangat mempesona. Faktanya, warnanya sangat cerah sehingga harus digunakan secukupnya saat digunakan sebagai dekorasi atau aksen, agar tidak mengalahkan indra.",
  str_item_intro_5423343 = "Pohon Mekar Warna-warni yang telah sering mengalami mutasi. Bunga kuningnya penuh dengan kehidupan, dan tampaknya tetap mekar siang dan malam. Bahkan ada desas-desus bahwa bunganya dapat digunakan untuk meramu ramuan vitalitas; sebagai hasilnya, ia dikenal oleh beberapa orang sebagai \"Pohon Kehidupan Pelangi\".",
  str_item_intro_5423411 = "Pohon Mekar IV yang telah mengalami mutasi kompleks. Meskipun kanopinya hanya memiliki satu bunga, bunga itu berukuran sangat besar, warnanya cemerlang, dan aromanya sangat manis; bahkan ada yang mengatakan bahwa benang sari bunganya bisa dijadikan bumbu masakan yang sangat baik. Seringkali menjadi objek fiksasi bagi banyak orang, bunga pohon ini seolah bisa memikat setiap makhluk hidup dengan mata untuk melihatnya.",
  str_item_intro_5423412 = "Genus langka dari Pohon Mekar yang Memukau yang dibiakkan dengan Kristaloid Mawar. Bunganya yang berwarna biru muda tertiup angin seperti ombak di lautan, dan bahkan mengeluarkan bau amis yang sedikit astringen. Oleh karena itu, mereka yang tinggal jauh dari laut mengaku masih bisa merasakan keceriaan musim panas di pantai hanya dengan mengagumi bunga pohon ini.",
  str_item_intro_5423413 = "Genus langka dari Bewitching Blooming Tree yang dibiakkan dengan Rose Crystalloids. Bunganya telah berubah menjadi warna merah muda yang sangat menawan. Hanya dengan melihatnya dapat membuat seseorang melupakan semua kesengsaraan mereka, membuatnya sangat sulit untuk mengalihkan pandangan darinya. Bahkan, beberapa bahkan akan menyetel jam alarm untuk mengingatkan mereka tentang bahaya menikmati pemandangan yang begitu indah.",
  str_item_intro_5423421 = "Pohon Mekar IV yang telah mengalami mutasi kompleks. Bunganya memiliki kelopak yang tak terhitung banyaknya, yang masing-masing lembut dan ramping seperti sehelai sutra. Mereka mengatakan beberapa bahkan mencoba menggunakannya untuk menenun kain, tetapi bunga-bunga halus ini dengan cepat menjadi rapuh setelah dikeluarkan dari pohon, yang menyebabkan pemborosan keindahan alamnya yang memalukan.",
  str_item_intro_5423422 = "Genus langka dari Silken Blooming Tree yang dibiakkan dengan Rose Crystalloids. Kanopinya yang biru sering mengingatkan kita akan gambaran \"Putri Laut\", sosok legendaris yang dikatakan memiliki rambut sebiru lautan itu sendiri. Bahkan ada yang mengatakan bahwa bunga pohon ini mengeluarkan aroma samar semburan laut...",
  str_item_intro_5423423 = "Genus langka dari Silken Blooming Tree yang dibiakkan dengan Rose Crystalloids. Bunga-bunganya yang menghijau konon menampung jiwa semua bunga, dan melihatnya dengan mata kepala sendiri akan menjamin cinta sejati pada pandangan pertama...",
  str_item_intro_5423431 = "Pohon Mekar IV yang telah mengalami mutasi kompleks. Corolla bunganya yang sangat besar berbentuk cakram, dan tampak menghadap ke sesuatu yang tinggi di atas. Setelah diperhatikan oleh orang-orang, bunganya tampak berpaling dari pandangan mereka; akibatnya, ini dikenal sebagai \"Mekar Malu\" di kalangan tertentu.",
  str_item_intro_5423432 = "Genus langka dari Pohon Mekar Skygazer yang dibiakkan dengan Kristaloid Mawar. Bunganya cerah dan merah seperti api yang tak terkendali. Legenda mengatakan bahwa bunga yang kuat ini melihat ke langit untuk berbagi kekayaan vitalitasnya dengan dunia.",
  str_item_intro_5423433 = "Genus langka dari Pohon Mekar Skygazer yang dibiakkan dengan Kristaloid Mawar. Kelopak bunganya berwarna putih seperti salju dan memancarkan cahaya aneh. Beberapa orang mengatakan bahwa itu menghasilkan berbagai ilusi tergantung pada arah di mana ia menghadap, memberinya julukan \"Penenun Mimpi.\"",
  str_item_intro_5423441 = "Pohon Mekar IV yang telah mengalami mutasi kompleks. Kelopaknya rapi dan indah, berlapis-lapis satu sama lain. Sekilas saja sudah membuat hati pusing, oleh karena itu disukai banyak gadis.",
  str_item_intro_5423442 = "Genus langka dari Virtuous Blooming Tree yang dibiakkan dengan Rose Crystalloids. Kanopi birunya memabukkan, dan banyak penonton merasa segar di sekitarnya, seperti langit cerah setelah hujan, oleh karena itu disebut juga \"Langit Cerah\".",
  str_item_intro_5423443 = "Genus langka dari Virtuous Blooming Tree yang dibiakkan dengan Rose Crystalloids. Bunga ungunya terlihat berbahaya, dan konon bunganya bergoyang sedikit genit saat seseorang melihatnya, membuat mereka kesurupan. Bagaimanapun, harap berhati-hati di sekitarnya.",
  str_item_intro_5423451 = "Pohon Mekar IV yang telah mengalami mutasi kompleks. Kanopi besar membentuk corong alami, dan dinding bagian dalam yang dibentuk oleh kelopaknya begitu halus sehingga mengumpulkan embun pagi di batangnya untuk menyehatkan dirinya sendiri.",
  str_item_intro_5423452 = "Genus langka dari Dawn Blooming Tree yang dibiakkan dengan Rose Crystalloids. Kanopi ungu mewarnai embun yang dikumpulkannya menjadi warna yang sama. Beberapa sarjana percaya embun ini memiliki kekuatan mistik dan menggunakannya untuk menulis buku-buku tertentu.",
  str_item_intro_5423453 = "Genus langka dari Dawn Blooming Tree yang dibiakkan dengan Rose Crystalloids. Embun yang terkumpul dari tajuknya tampak kebiruan dan dapat menyegarkan orang yang memandangnya. Embun ini juga sepertinya mampu membersihkan kotoran dari dalam tubuh, sehingga disebut juga dengan “Dawn's Detox”.",
  str_item_intro_5423461 = "Pohon Mekar IV yang telah mengalami mutasi kompleks. Mahkotanya terbagi menjadi beberapa segmen panjang dan halus, yang terhuyung-huyung di sekitar pusatnya. Konon setelah melihatnya, seorang desainer pernah terinspirasi untuk mendesain rangkaian rok berdasarkan bentuk kelopaknya, sehingga mendapat julukan \"Skirted Beauty\".",
  str_item_intro_5423462 = "Genus langka dari Aureate Blooming Tree yang dibiakkan dengan Rose Crystalloids. Kelopak oranyenya tampaknya memiliki sentuhan godaan, dan dengan keharumannya yang unik, itu adalah pengingat yang kuat akan semua yang memikat namun berbahaya di dunia.",
  str_item_intro_5423463 = "Genus langka dari Aureate Blooming Tree yang dibiakkan dengan Rose Crystalloids. Kelopaknya menjadi warna langit, dihiasi dengan daun putih yang menyebarkan sensasi segar dan bersih, membuatnya populer di kalangan anak-anak.",
  str_item_intro_5423471 = "Pohon Mekar IV yang telah mengalami mutasi kompleks. Mahkota dan benang sarinya membentuk bentuk kupu-kupu yang tidak hanya memukau mereka yang melihatnya, tetapi juga menarik kupu-kupu yang sebenarnya, yang menari mengelilinginya seolah-olah itu adalah dewa mereka.",
  str_item_intro_5423472 = "Genus langka dari Fluttering Blooming Tree yang dibiakkan dengan Rose Crystalloids. Jika dilihat dari kejauhan, benang sari kuningnya yang besar terlihat seperti kupu-kupu yang hinggap di atasnya. Setiap kali angin sepoi-sepoi bertiup, semakin sulit untuk membedakan ...",
  str_item_intro_5423473 = "Genus langka dari Fluttering Blooming Tree yang dibiakkan dengan Rose Crystalloids. Benang sari biru dan bentuk kupu-kupu bawaannya meninggalkan kesan pertama yang aneh bagi orang-orang. Setelah akhirnya menemukan bentuk aslinya, orang hanya bisa menghela nafas pada keajaiban pohon ini, sehingga juga dikenal sebagai \"Kupu-Kupu Misterius\".",
  str_item_intro_5424111 = "Melihat akarnya yang bulat, orang dapat melihat perbedaan antara Pohon Jeruk Dasar dan varietas lainnya, dan tidak dapat tidak mengagumi keunikannya.",
  str_item_intro_5424112 = "Pohon Yellow Strangefruit yang dibiakkan dengan Rose Crystalloids. Ini menghasilkan buah dan daun berwarna kuning yang tampaknya melambangkan pelukan musim gugur.",
  str_item_intro_5424113 = "Pohon Strangefruit Ungu yang dibiakkan dengan Kristaloid Mawar. Anda mungkin menemukan baunya aneh pada awalnya, namun getahnya sama sekali tidak berasa, sampai mirip dengan air murni.",
  str_item_intro_5424211 = "Sebuah Strangefruit Tree II yang telah mengalami beberapa mutasi kecil. Akarnya kuat, dan buahnya memiliki duri tajam di bagian luarnya, yang berfungsi sebagai pertahanan yang tangguh. Tanaman merambat di sekitarnya juga tampaknya memperingatkan orang asing untuk menjaga jarak.",
  str_item_intro_5424212 = "Sebuah genus dari Pohon Strangefruit Mekar yang dibiakkan dengan Rose Crystalloids. Tanaman rambat, batang, dan daun berwarna biru menunjukkan bahwa itu berbeda dari varietas aslinya, tetapi tampaknya buahnya masih sama.",
  str_item_intro_5424213 = "Sebuah genus dari Pohon Strangefruit Mekar yang dibiakkan dengan Rose Crystalloids. Tanaman merambat dan batangnya memberikan perasaan layu, tetapi buah di dalamnya kaya dan subur, membuat penampilannya tampak seperti penyamaran.",
  str_item_intro_5424221 = "Sebuah Strangefruit Tree II yang telah mengalami beberapa mutasi kecil. Buah di akarnya telah dibengkokkan menjadi bentuk yang sama sekali berbeda. Kelopak buah dan daun yang dipisahkan diyakini dapat menyerap nutrisi masing-masing sehingga jika ada bagian pohon yang rusak, bagian lain dapat tetap tumbuh untuk menjamin kelangsungan hidupnya.",
  str_item_intro_5424222 = "Genus Pohon Buah Aneh Berkembang yang dibiakkan dengan Kristaloid Mawar. Penampilannya yang merah dikatakan karena getahnya yang mengandung bahan kimia langka.",
  str_item_intro_5424223 = "Genus Pohon Buah Aneh Berkembang yang dibiakkan dengan Kristaloid Mawar. Buahnya memiliki warna kuning yang khas, yang tampaknya diakibatkan oleh kehilangan air dari kulitnya. Begitu kulitnya terkelupas, segera menjadi rapuh, dan kemudian pecah menjadi tumpukan sumbu.",
  str_item_intro_5424311 = "Pohon Jeruk III yang sering mengalami mutasi. Bagian luar buah mengeras, menjadi bola seperti batu yang sangat sulit dimakan.",
  str_item_intro_5424312 = "Genus langka dari Thriving Strangefruit Tree yang dibiakkan dengan Rose Crystalloids. Meskipun tidak jelas apakah buahnya juga telah bermutasi, samar-samar Anda dapat merasakannya dari daun. Mungkin bukan ide yang baik untuk mencicipi buahnya.",
  str_item_intro_5424313 = "Pohon Strangefruit Berkembang yang telah sering mengalami mutasi. Mahkota dan daun pohon itu menampilkan warna-warna cerah, yang sangat kontras dengan buahnya yang seperti batu. Beberapa orang menyebut buahnya sebagai \"batu berbunga\".",
  str_item_intro_5424321 = "Pohon Strangefruit Arcadian yang sering mengalami mutasi. Batangnya bengkok, dan buahnya terbelah menjadi dua bagian, membentuk wadah alami. Selama Anda memilikinya, Anda tidak perlu khawatir akan haus.",
  str_item_intro_5424322 = "Genus Pohon Buah Aneh Arcadian yang dibiakkan dengan Kristaloid Mawar. Getahnya di \"kolam buah\" memiliki rasa yang tak terlukiskan, yang konon disebabkan oleh unsur misterius yang belum ditemukan.",
  str_item_intro_5424323 = "Pohon Strangefruit Arcadian yang sering mengalami mutasi. Ini membanggakan jus yang lebih jernih di bagian tengahnya yang dapat tetap dingin untuk waktu yang lama, menjadikannya sempurna untuk hari-hari musim panas yang terik.",
  str_item_intro_5424331 = "Pohon Jeruk III yang sering mengalami mutasi. Batangnya bengkok, tetapi ini sebenarnya disebabkan oleh buah di dalamnya. Menurut beberapa penelitian, itu karena buahnya sudah bengkok, dan yang disebut \"batang\" sebenarnya melindungi kulit buah.",
  str_item_intro_5424332 = "Genus langka dari Mellifluous Strangefruit Tree yang dibiakkan dengan Rose Crystalloids. Kanopi putihnya terlihat seperti awan besar di langit.",
  str_item_intro_5424333 = "Pohon Strangefruit Mellifluous yang sering mengalami mutasi. Variasi warna batang pohonnya sangat jelas, yang juga menandakan bahwa rasa buahnya telah banyak berubah. Menurut para petualang, rasanya agak pedas dan asam.",
  str_item_intro_5424341 = "Pohon Jeruk III yang sering mengalami mutasi. Bentuknya paling mencerminkan esensi Pohon Unik ini. Tumpukan buah yang sangat besar, cabang-cabang yang menjulur darinya... Inilah mengapa ia dikenal sebagai \"Raksasa Buah\".",
  str_item_intro_5424342 = "Genus langka dari Pohon Buah Jeruk yang Dibiakkan dengan Kristaloid Mawar. Buahnya yang besar berwarna biru terlihat sangat montok, membuktikan bahwa ia memang pantas mendapatkan namanya. Jus yang terkandung di dalamnya dikatakan cukup untuk menyediakan air bagi seluruh desa. Inilah mengapa beberapa orang menyebutnya \"Pohon Tangki Air\".",
  str_item_intro_5424343 = "Genus langka dari Pohon Buah Jeruk yang Dibiakkan dengan Kristaloid Mawar. Buah merah besar itu sangat cerah, sehingga tidak ada yang bisa mengabaikan keberadaannya. Inilah mengapa beberapa legenda mengklaim bahwa jusnya dapat meremajakan, tetapi itu mungkin hanya legenda.",
  str_item_intro_5424411 = "Genus langka Pohon Jeruk IV yang telah mengalami mutasi kompleks. Buahnya besar dan menawarkan warna yang indah. Selain itu, cabang-cabang dengan strukturnya yang rumit dapat dengan mudah mengilhami seseorang dengan keinginan untuk mendominasi setelah melihatnya dalam waktu lama, bahkan menyebabkan perselisihan dengan kerabat dan teman. Inilah mengapa ia juga dikenal sebagai \"Pohon Berlawanan\".",
  str_item_intro_5424412 = "Genus langka dari Enduring Strangefruit Tree yang dibiakkan dengan Rose Crystalloids. Buahnya yang berwarna hijau memiliki rasa alami yang kuat. Jika Anda menatapnya terlalu lama, Anda mungkin akan tenggelam di dalamnya, seolah-olah Anda berada di hutan. Anda bahkan dapat mendengar kicauan serangga dan burung, dan merasakan dedaunan yang tertiup angin...",
  str_item_intro_5424413 = "Genus langka dari Enduring Strangefruit Tree yang dibiakkan dengan Rose Crystalloids. Buahnya menjadi merah muda cerah dan menawan. Jika Anda menatapnya dalam waktu yang lama, Anda bahkan mungkin tiba-tiba melihat ritme lompatan muncul dari dalamnya, yang merupakan pemandangan yang sangat aneh untuk dilihat.",
  str_item_intro_5424421 = "Genus langka Pohon Jeruk IV yang telah mengalami mutasi kompleks. Buahnya banyak, dengan ukuran berbeda, dan ditumpuk dalam formasi berselang-seling. Dikatakan bahwa ini adalah salah satu Pohon Unik yang paling kuno, dan bahkan ada catatan keberadaannya di alam liar! Inilah mengapa ia juga dikenal sebagai \"Pohon Primordial\".",
  str_item_intro_5424422 = "Genus langka Pohon Buah Aneh yang dikawinkan dengan Kristaloid Mawar. Buahnya yang berwarna merah muda membuat orang ingin meminum jus yang dihasilkannya. Konon dapat digunakan untuk menyeduh minuman lezat yang sangat dipuji oleh keluarga kerajaan, oleh karena itu, pohon ini juga dikenal sebagai \"Pohon Regal\".",
  str_item_intro_5424423 = "Genus langka Pohon Buah Aneh yang dikawinkan dengan Kristaloid Mawar. Dari kejauhan, buahnya tampak seperti bola-bola cair yang terkondensasi dari air laut biru, dan Anda bahkan dapat melihat riak menyebar di atasnya. Namun, tidak diketahui apakah ini hanyalah ilusi.",
  str_item_intro_5424431 = "Genus langka Pohon Jeruk IV yang telah mengalami mutasi kompleks. Buahnya yang besar mengeluarkan bau yang harum setiap saat. Beberapa orang mengatakan bahwa itu dapat membawa keberanian yang tak dapat dijelaskan kepada mereka yang menciumnya, membuat mereka ingin menaklukkan semua yang mereka lihat.",
  str_item_intro_5424432 = "Genus langka Pohon Strangefruit Tranquil yang dibiakkan dengan Rose Crystalloids. Buahnya yang berwarna hijau dapat menenangkan prajurit yang paling ganas, sehingga cocok untuk meditasi dan berpikir mendalam. Dikatakan bahwa banyak orang bijak telah mencapai pencerahan di bawah pengaruhnya, yang menyebabkan julukannya— \"Pohon Wahyu.\"",
  str_item_intro_5424433 = "Genus langka Pohon Strangefruit Tranquil yang dibiakkan dengan Rose Crystalloids. Buahnya yang besar berwarna merah jambu tidak hanya dapat mengilhami orang dengan keberanian, tetapi juga dapat memberi mereka ambisi yang kuat dan keinginan kuat sehingga mereka dapat memulai jalan tanpa jalan kembali untuk berjuang demi supremasi. Inilah mengapa ia juga dikenal sebagai \"Kingmaker.\"",
  str_item_intro_5424441 = "Genus langka Pohon Jeruk IV yang telah mengalami mutasi kompleks. Buahnya tersembunyi di dalam batang, tetapi menurut beberapa ahli, batang adalah kulit luar buah yang mengeras dan bukan lapisan luar yang membungkus buah! Tampaknya Pohon Unik ini berusaha keras untuk melindungi buahnya.",
  str_item_intro_5424442 = "Genus langka dari Wonder Strangefruit Tree yang dibiakkan dengan Rose Crystalloids. Dikatakan bahwa buah hijau ini mengandung esensi kehidupan, yang bila diekstrak dengan benar, dapat membuat tanaman tumbuh lebih cepat, meningkatkan hasil panen, bahkan memperbaiki tanah tandus dan tanah alkali yang keras! Karena itulah, banyak orang menyebutnya sebagai buah kehidupan.",
  str_item_intro_5424443 = "Genus langka dari Wonder Strangefruit Tree yang dibiakkan dengan Rose Crystalloids. Buahnya yang besar berwarna biru mengandung air yang manis, dan lapisan \"kulit kayu\" bagian luarnya juga memiliki efek pelembab yang kuat yang melindungi air di dalam buah agar tidak hilang, pada dasarnya membuatnya menjadi reservoir ...",
  str_item_intro_5424451 = "Genus langka Pohon Jeruk IV yang telah mengalami mutasi kompleks. Meski buahnya yang besar terlihat biasa saja, untuk jangka waktu tertentu mengeluarkan aroma yang sangat memikat yang konon tak terlupakan! Mungkin itu sebabnya banyak kupu-kupu beterbangan di sekitarnya meskipun biasanya tidak berbau.",
  str_item_intro_5424452 = "Genus langka dari Distinguished Strangefruit Tree yang dibiakkan dengan Rose Crystalloids. Menurut beberapa legenda, buah ungu ini mengeluarkan aroma yang menyebar ke seluruh negeri setiap beberapa ratus tahun sekali! Ada juga legenda tentang seorang \"raja\" yang akan muncul di dunia ini ketika keharumannya menyebar...",
  str_item_intro_5424453 = "Genus langka dari Distinguished Strangefruit Tree yang dibiakkan dengan Rose Crystalloids. Berbeda dengan buah Pohon Strangefruit Terkemuka lainnya, buah biru ini memiliki sedikit kesegaran dan menetralkan bau lainnya! Ini sangat populer di kalangan tukang kebun karena alasan ini, tetapi ketidakmampuannya untuk ditransplantasikan membuat tukang kebun biasa mengeluh.",
  str_item_intro_5424461 = "Genus langka dari Pohon Strangefruit yang telah mengalami mutasi kompleks. Cangkang luarnya telah berubah menjadi sangkar yang menampung buah-buahan yang lezat. Buah ini diketahui mengeluarkan kabut yang mempesona dari waktu ke waktu, yang konon dapat menangkal calon pencari makan.",
  str_item_intro_5424462 = "Genus langka dari Misty Strangefruit Tree yang dibiakkan dengan Rose Crystalloids. Buahnya yang berwarna hijau cerah menawarkan rasa asam dan aroma yang sangat menyengat, membuat banyak orang percaya bahwa itu beracun. Padahal, buah ini sangat aman untuk dimakan.",
  str_item_intro_5424463 = "Genus langka dari Misty Strangefruit Tree yang dibiakkan dengan Rose Crystalloids. Bagian berdaging dari buah birunya telah mengalami transformasi misterius, yang membuatnya sangat kenyal dan elastis. Bahkan setelah ditabrak kendaraan berat, buah ini akan cepat kembali ke bentuk semula...",
  str_item_intro_5424471 = "Genus langka dari Pohon Strangefruit yang telah mengalami mutasi kompleks. Buahnya terbagi menjadi dua bagian—bagian utama buah sebenarnya terbungkus oleh cangkangnya yang tebal, sedangkan buah yang berkilauan menggantung di ujung cabangnya konon merupakan hasil dari mutasi kanopinya! Namun, bentuk, bau, dan rasa buah tidak banyak menguatkan teori ini...",
  str_item_intro_5424472 = "Genus langka dari Sparkling Strangefruit Tree yang dibiakkan dengan Rose Crystalloids. Cahaya birunya konon berbau seperti lautan, membuatnya mendapat julukan \"utusan angin laut\". Namun, yang lain mengklaim bahwa ini hanyalah efek halusinogen yang disebabkan oleh aroma buah.",
  str_item_intro_5424473 = "Genus langka dari Sparkling Strangefruit Tree yang dibiakkan dengan Rose Crystalloids. Cahaya hijau lembut yang dipancarkan oleh buahnya memiliki efek menenangkan, yang konon membuat hewan yang paling ganas sekalipun menjadi jinak saat didekati. Apakah ini benar atau tidak belum dapat dikonfirmasi.",
  str_item_intro_5425111 = "Pohon Unik ini memang selalu berbeda dengan pohon lainnya. Bahkan, orang pasti bertanya-tanya apakah itu bisa dihitung sebagai pohon ... Menurut penelitian banyak sarjana, itu memang pohon, jadi hanya bisa dikatakan bahwa ini benar-benar Pohon Unik yang terlihat dan terasa indah.",
  str_item_intro_5425112 = "Pohon Jamur Merah yang dibiakkan dengan Kristaloid Mawar. Kanopi merahnya membuat orang merasa gelisah dan tidak sabar, jadi itu mungkin bukan pohon terbaik untuk berteduh.",
  str_item_intro_5425113 = "Pohon Jamur Biru yang dibiakkan dengan Kristaloid Mawar. Kanopi birunya menciptakan ilusi langit yang luas; bahkan ada yang mengatakan mereka bisa mencium aroma awan di bawahnya.",
  str_item_intro_5425211 = "Pohon Jamur II yang telah mengalami beberapa mutasi kecil. Kanopinya telah mengalami banyak perubahan, menjadi lunak dan keras pada saat yang sama, dan cabang-cabangnya menggantung rendah karena beratnya, menciptakan ilusi sebuah lengkungan. Jika Anda menambahkan beberapa balok kayu untuk menopang dan mendirikan dinding, Anda mungkin dapat mengubahnya menjadi rumah kecil.",
  str_item_intro_5425212 = "Genus Pohon Jamur Fuzzy, yang telah mengalami beberapa mutasi kecil, dibiakkan dengan Kristaloid Mawar. Bagian dalam kanopi berwarna biru langit, yang menciptakan ilusi berada di laut.",
  str_item_intro_5425213 = "Genus Pohon Jamur Fuzzy, yang telah mengalami beberapa mutasi kecil, dibiakkan dengan Kristaloid Mawar. Bagian dalam kanopi yang merah menakutkan bagi sebagian orang. Ada juga desas-desus bahwa pohon ini beracun. Namun, ini adalah kata-kata dari prasangka.",
  str_item_intro_5425221 = "Pohon Jamur II yang telah mengalami beberapa mutasi kecil. Dengan batang yang tebal dan tajuk yang mengecil, pohon ini terasa seperti seember air, dan batangnya yang tebal memang dapat menyerap air dan menyimpannya, itulah sebabnya disebut juga jamur air.",
  str_item_intro_5425222 = "Genus Pohon Jamur Stoic, yang telah mengalami beberapa mutasi kecil, dibiakkan dengan Kristaloid Mawar. Meski berwarna merah, air yang tersimpan di dalamnya belum terpengaruh. Anda bahkan dapat mendengar suara air yang mengalir di dalam jika Anda cukup dekat.",
  str_item_intro_5425223 = "Genus Pohon Jamur Stoic, yang telah mengalami beberapa mutasi kecil, dibiakkan dengan Kristaloid Mawar. Beberapa orang menyebut kanopi birunya sebagai \"kanopi laut\" karena dipengaruhi oleh air yang tersimpan di dalamnya. Beberapa orang mengatakan Anda dapat mendengar suara ombak yang deras dari batang yang tebal jika Anda berdiri di atas kanopi dan menempelkan telinga Anda di atasnya.",
  str_item_intro_5425311 = "Pohon Jamur II yang sering mengalami mutasi. Kanopi mempertahankan ukuran aslinya dan bahkan menjadi lebih tebal dari sebelumnya. Baunya juga luar biasa...",
  str_item_intro_5425312 = "Genus langka dari Pohon Jamur Memikat yang dibiakkan dengan Kristaloid Mawar. Karena kanopinya benar-benar biru, Anda akan merasa seperti berada di dasar laut yang dangkal meskipun hanya menatapnya dari kejauhan.",
  str_item_intro_5425313 = "Genus langka dari Pohon Jamur Memikat yang dibiakkan dengan Kristaloid Mawar. Kanopi merah cerah sangat menarik bagi sebagian orang dan memiliki kekuatan magis yang memikat pemirsa semakin dekat. Namun, tidak ada alasan jahat untuk ini, dan tidak ada yang tahu mengapa efek ini terjadi.",
  str_item_intro_5425321 = "Pohon Jamur II yang sering mengalami mutasi. Tidak hanya menjadi lebih kecil, tetapi juga mulai tumbuh berkelompok. Untungnya, sebagian besar bentuknya sama. Fitur terbesarnya adalah kanopi yang bersinar cemerlang dengan segala jenis cahaya, menciptakan pemandangan indah saat cahaya memantul dari bubuk yang dilepaskannya ke udara.",
  str_item_intro_5425322 = "Genus langka dari Pohon Jamur Lambent yang dibiakkan dengan Rose Crystalloids. Warna merah menyala dari pohon ini membuat tajuknya terlihat seperti lautan api, sedangkan titik terangnya disalahartikan sebagai bunga api. Oleh karena itu, pohon ini juga dikenal sebagai jamur yang menyala.",
  str_item_intro_5425323 = "Genus langka dari Pohon Jamur Lambent yang dibiakkan dengan Rose Crystalloids. Kanopi berwarna ungu terlihat mesra dan juga mengeluarkan debu berpendar yang konon sangat mempesona. Beberapa sarjana juga mengklaim bahwa pohon ini adalah varian atau kerabat jauh dari Pohon Jamur Penggoda, tetapi ini hanya spekulasi.",
  str_item_intro_5425331 = "Pohon Jamur II yang sering mengalami mutasi. Batang pohon ini tumbuh miring dan memiliki dua tajuk. Beberapa sarjana berspekulasi bahwa pohon ini menyedot air dalam jumlah yang sangat banyak dari tanah untuk menjaga kedua kanopi tetap hidup, yang menyebabkan air dikeluarkan dari kanopi dan jatuh seperti tetesan air hujan.",
  str_item_intro_5425332 = "Genus langka dari Moist Mushroom Tree yang dibiakkan dengan Rose Crystalloids. Benar-benar menguning, rintik hujan yang jatuh dari pohon ini juga menciptakan suasana matahari terbenam. Ketika rintik-rintik hujan turun dengan cepat, bahkan seolah-olah pohon itu terbungkus tirai hujan senja.",
  str_item_intro_5425333 = "Genus langka dari Moist Mushroom Tree yang dibiakkan dengan Rose Crystalloids. Pohon ini menyerupai makhluk laut karena warnanya yang biru, dan rintik hujan yang jatuh dari pohon ini seperti percikan ombak biru, sehingga disebut juga sebagai pengontrol air laut.",
  str_item_intro_5425341 = "Pohon Jamur II yang sering mengalami mutasi. Dicirikan oleh banyaknya cabang yang lunak dan terkulai, sekilas pohon ini terlihat seperti janggut tetua yang bijak, sehingga disebut juga jamur bijak.",
  str_item_intro_5425342 = "Genus langka dari Lush Mushroom Tree yang dibiakkan dengan Rose Crystalloids. Janggut kuning membuat pohon ini terlihat lebih bijaksana, bahkan ada yang mengklaim bahwa pohon ini memiliki perlindungan cahaya. Saat angin berdesir melalui batangnya yang lentur, sinar matahari tampak bersinar melalui celah-celahnya.",
  str_item_intro_5425343 = "Genus langka dari Lush Mushroom Tree yang dibiakkan dengan Rose Crystalloids. Batang hijaunya yang fleksibel terlihat seperti tanaman merambat. Mereka yang menikmati keteduhan dan pemandangan di bawah kanopi akan merasa seperti berada di hutan primer.",
  str_item_intro_5425411 = "Pohon Jamur IV yang telah mengalami mutasi kompleks. Setelah tumbuh sangat besar dan sangat tipis, kanopi ini bahkan dikatakan hampir transparan jika dilihat dari sudut tertentu! Secara alami, banyak yang mengatakan bahwa perasaan transparan ini tidak berasal dari kanopi tipis tetapi berasal dari udara dingin yang dipancarkan oleh pohon setiap saat dan mengingatkan mereka pada es transparan.",
  str_item_intro_5425412 = "Genus langka Pohon Jamur Encer yang dibiakkan dengan Kristaloid Mawar. Kanopi kuning dan angin dingin sesekali menciptakan ilusi perasaan dingin bahkan di bawah terik matahari, sehingga beberapa orang menyebutnya \"pohon ajaib negeri matahari beku\".",
  str_item_intro_5425413 = "Genus langka Pohon Jamur Encer yang dibiakkan dengan Kristaloid Mawar. Kanopi merah yang menyilaukan dan perasaan transparannya yang alami membuat orang bertanya-tanya apakah ini adalah karya seni yang dibuat oleh manusia, bukan ciptaan alam.",
  str_item_intro_5425421 = "Pohon Jamur IV yang telah mengalami mutasi kompleks. Meskipun kanopi pohon ini tampak biasa saja, terkadang ia mengeluarkan semburan udara yang menciptakan ilusi bahwa ia sedang bernapas. Pohon ini juga sebagian besar hidup berkelompok dan menciptakan kabut tipis ketika mereka semua melepaskan semburan udara satu demi satu, karena itulah namanya.",
  str_item_intro_5425422 = "Genus langka dari Misty Mushroom Tree yang dibiakkan dengan Rose Crystalloids. Saat kanopi merah pohon ini bernafas, lubang-lubang kecil yang sesekali terbuka dan tertutup membuat orang berpikir tentang luka. Selain itu, semburan udara yang dikeluarkan memberi kesan kabut darah pada saat-saat tertentu, memberinya nama tragis kembalinya medan perang.",
  str_item_intro_5425423 = "Genus langka dari Misty Mushroom Tree yang dibiakkan dengan Rose Crystalloids. Kabut yang dipancarkan oleh kanopi biru mengingatkan orang yang melihatnya akan musim dingin, membuat banyak orang salah mengira bahwa pohon itu berasal dari Northland. Namun mereka semua salah, karena semburan udara yang dikeluarkan dari pohon ini sedikit hangat dan tidak dingin sama sekali.",
  str_item_intro_5425431 = "Pohon Jamur IV yang telah mengalami mutasi kompleks. Kanopi telah tumbuh sangat besar sehingga orang bertanya-tanya apakah batangnya dapat menahan beratnya. Karena kanopinya terlalu besar, hal itu menghalangi pandangan langit sepenuhnya bagi mereka yang berada di bawahnya. Karena itulah, ada yang menyebutnya pohon yang menutupi langit.",
  str_item_intro_5425432 = "Genus langka dari Dome Mushroom Tree yang dibiakkan dengan Rose Crystalloids. Dari waktu ke waktu, kanopi hijau memancarkan aroma tanaman air, memberikan ilusi aneh kepada penonton bahwa mereka berada di sebelah badan air. Dikatakan bahwa pohon ini memberikan nutrisi bagi tanaman air terdekat untuk tumbuh subur, namun belum ada yang mengkonfirmasi hal ini.",
  str_item_intro_5425433 = "Genus langka dari Dome Mushroom Tree yang dibiakkan dengan Rose Crystalloids. Kanopi merah cerah menciptakan ilusi panen yang baik, dan beberapa bahkan mengatakan mereka bisa mencium aroma manis buah di sekitarnya. Namun, Pohon Unik ini sama sekali tidak bisa dimakan, terutama kanopinya yang sulit dimasak dan tidak memiliki nilai gizi.",
  str_item_intro_5510001 = "Badannya yang tambun bukanlah halangan baginya untuk bertahan hidup, karena perutnya besar dan penuh berisi racun. Tapi, dagingnya yang lezat tetap saja menarik bagi para penggemar kuliner yang tak takut mati.",
  str_item_intro_5510002 = "Terkenal berkat warnanya yang cerah, jumlahnya yang banyak, dan dagingnya yang empuk, sehingga menjadi primadona di meja makan.",
  str_item_intro_5510003 = "Namanya berasal dari bentuk badannya yang ramping dan menyerupai pisau, dan ia selalu bergerak berkelompok.",
  str_item_intro_5510004 = "Sepintas tampak seperti ular, tetapi sebenarnya ini adalah ikan berbadan ramping dengan sirip yang sangat kecil. Ia suka bersembunyi di antara bebatuan di dalam air, dan tiba-tiba melesat keluar untuk mengagetkan orang-orang.",
  str_item_intro_5510005 = "Jenis ikan yang suka hidup di air jernih. Jumlahnya melimpah dan tersebar merata sehingga bisa ditemukan di banyak tempat.",
  str_item_intro_5510006 = "Konon, ikan ini adalah predator puncak di perairan. Tetapi, karena dagingnya lezat, ia jadi buruan para penggemar kuliner, dan kini menjadi sajian \"rutin\" dalam perjamuan makan papan atas.",
  str_item_intro_5510007 = "Ikan berbadan ramping yang berkumpul di sepanjang tepi sungai, entah untuk beristirahat atau berenang-renang santai. Makanannya adalah berbagai organisme kecil di air. Daging ikan ini aman dikonsumsi, dan minyak ikannya juga bisa dimanfaatkan untuk membuat beragam pigmen.",
  str_item_intro_5510008 = "Makaira suka berenang secara berkelompok, dan jumlahnya banyak. Sifatnya agresif dan suka membenturkan kepalanya ke badan musuh saat bertarung sengit, tak ubahnya seperti lembing. Dagingnya padat cenderung alot, sementara sisik-sisik kecilnya biasanya dikeringkan dan dijadikan camilan.",
  str_item_intro_5520001 = "Kura-kura yang berenang perlahan di air biasanya kesulitan bergerak di darat. Mungkin karena gerakannya sangat lambat, tubuhnya pun dilapisi tempurung keras untuk melindunginya dari musuh.",
  str_item_intro_5520002 = "Organisme akuatik langka ini tumbuh subur di perairan yang sangat dingin, dan biasanya dapat ditemukan hidup jauh di bawah lautan beku. Tubuhnya transparan, dan menawarkan berbagai warna cantik dan pelengkap seperti sayap, itulah namanya. Pemandangan yang sangat langka di perairan hangat, kemungkinan besar mereka tersesat...",
  str_item_intro_5520004 = "Makhluk air ini memiliki tubuh yang rata dan berenang dengan sangat lambat. Mereka juga suka menjelajah dan beristirahat di dasar sungai dan sungai. Karena banyaknya titik indah di punggungnya, para nelayan sering salah mengira mereka sebagai kelompok besar mutiara yang tersebar saat melihat ke bawah ke sungai dan aliran air, karena itulah namanya.",
  str_item_intro_5520005 = "Makhluk yang suka merangkak di bawah ombak dan dikenal dengan bentuknya yang unik. Dikatakan bahwa ketika pertama kali ditemukan, orang mengira itu adalah jenis ganggang atau karang yang aneh. Mereka tidak menyadari itu hidup sampai mulai bergerak sangat lambat...",
  str_item_intro_5520006 = "Ikan luar biasa yang suka hidup di antara ganggang, karang, dan bahkan anemon. Memiliki tampilan yang cerah dan wajah lucu yang membuat orang yang melihatnya tertawa. Beberapa orang berkomentar bahwa tumbuhan air menari setiap kali ikan ini ada di sekitar mereka, itulah namanya.",
  str_item_intro_5520007 = "Ini tampaknya merupakan organisme air yang baru ditemukan. Dengan kulit halus dan otot lembut, ia berenang melalui kedalaman laut dengan ketenangan yang elegan yang menyebabkannya dengan cepat mendapatkan popularitas di kalangan pecinta hewan. Beberapa pengagumnya bahkan dikatakan merasakan kesenangan fisik dan mental setiap kali melihatnya berlayar tanpa tujuan di air, menyapu kekhawatiran dan perselisihan mereka dengan gelombang tentakelnya.",
  str_item_intro_5520016 = "Ikan ini suka hidup di perairan yang luas, dan entah bagaimana telah muncul di sini... Dulu orang takut karena tubuhnya yang hitam dan bentuknya yang aneh, tetapi sebenarnya sangat lembut dan suka berenang dengan santai di air. Ia bahkan berusaha keras untuk menghindari hewan air kecil lainnya yang ditemuinya.",
  str_item_intro_5520101 = "Berkat warnanya yang cerah, Red and White Marbled Eel menjadi salah satu jenis ikan hias paling mahal. Selain dijuluki \"permata hidup di dalam air\", ikan ini juga dipercaya bisa membawa keberuntungan bagi pemiliknya.",
  str_item_intro_5520102 = "Tricolor Marbled Eel digemari jutaan orang karena polanya sangat beragam, dan dijuluki \"si ikan anggun\". Setiap kali melihatnya, kita akan merasa rileks. Banyak orang meyakini bahwa ikan ini bisa membawa keharmonisan bagi keluarga.",
  str_item_intro_5520103 = "Ikan hias berkualitas tinggi. Dijuluki \"karya seni bawah air\" karena gerakannya saat berenang tampak anggun. Kabarnya, ikan ini bisa menangkal kemalangan bagi pemiliknya.",
  str_item_intro_5520104 = "Black and White Marbled Eel cenderung jinak dan tubuhnya berhias pola alami. Sifatnya ramah kepada orang-orang, terutama anak-anak, sehingga dipercaya bisa memperlancar pertumbuhan anak.",
  str_item_intro_5520105 = "Saat terkena sinar matahari, sisiknya akan berkilau keemasan. Karenanya, Golden Marbled Eel dipercaya bisa membawa keberuntungan, dan banyak pengusaha suka memelihara belut ini.",
  str_item_intro_5520201 = "Ikan hias ini tampak gemerlap kemerahan di dalam air. Sisiknya juga sangat kentara, sehingga air di sekitarnya jadi tampak berwarna merah muda. Sungguh suatu pemandangan yang menakjubkan.",
  str_item_intro_5520202 = "Walau tampak agak \"jahat\", sisiknya yang berwarna merah darah akan berkilau merah terang saat terkena sinar matahari, sehingga orang akan mengira ikan ini mengenakan zirah yang terbuat dari batu rubi.",
  str_item_intro_5520203 = "Sisiknya yang berwarna biru berkilau menghadirkan aura sejuk saat ia berenang perlahan di dalam air, terutama di tengah musim panas.",
  str_item_intro_5520204 = "Sisik-sisik keemasannya yang tersusun rapi membuatnya tampak seperti jenderal legendaris, dan posturnya saat berenang juga tampak sangat berwibawa, sampai-sampai ikan-ikan kecil pun terpaksa mundur begitu ia melintas.",
  str_item_intro_5520205 = "Dibandingkan dengan jenis-jenis lain yang serupa, penampilannya tampak anggun dan kalem, dan sisiknya yang berwarna putih keperakan serta bentuk badannya yang ramping membuatnya tampak seperti bangsawan.",
  str_item_intro_5520301 = "Dengan badan gepeng dan warna-warni mencolok, ikan ini tampak seperti kupu-kupu yang tercebur ke dalam air lalu berenang dengan anggun di dalamnya.",
  str_item_intro_5520302 = "Ikan hias yang kepalanya berwarna keputihan dan sebagian besar badannya berwarna hitam. Sifatnya lumayan jinak. Kalau diamati baik-baik, titik-titik di pertemuan antara bagian hitam dan putih di badannya tampak agak berbeda. Bisa dibilang, setiap Black Butterflyfish punya keunikan sendiri-sendiri.",
  str_item_intro_5520303 = "Badannya kuning dan putih, yang terbagi menjadi tiga bagian besar, dan dari situlah namanya berasal. Ikan ini berisik dan suka mengusik ikan-ikan lainnya. Karenanya, kehadirannya akan membuat kolam jadi tampak hidup.",
  str_item_intro_5520304 = "Dengan warna biru tua yang indah, kilau dari badan ikan hias ini sangat beragam. Ia pemalu dan tak suka menampakkan diri. Ia sering bersembunyi di antara bebatuan dan tanaman air, dan karenanya dijuluki \"si gadis pemalu\".",
  str_item_intro_5520401 = "Selaras dengan warnanya yang cerah serta matanya yang besar dan memancarkan semangat, ia suka mendekati ikan-ikan lain dan hampir tidak pernah mendapat penolakan oleh kawanan ikan itu. Karenanya, di antara ikan-ikan hias lainnya, ia dijuluki \"si gaul\".",
  str_item_intro_5520402 = "Namanya berasal dari bintik-bintik di punggungnya, dan kalau dipadukan dengan tanaman air yang warnanya mirip dengannya... hasilnya adalah kamuflase alami yang sempurna. Karenanya, saat menghias, kita harus memperhatikan keselarasan warnanya dengan lingkungannya, sehingga kehadirannya akan tampak menonjol.",
  str_item_intro_5520403 = "Sebagian besar badannya berwarna hitam, dengan sirip berwarna kuning dan putih di punggungnya. Sifatnya tenang, tapi begitu amarahnya terpancing, ia akan melawan musuhnya sampai titik penghabisan, tak ubahnya seperti duri yang menusuk—jadi, jangan disentuh.",
  str_item_intro_5520501 = "Hanya sedikit orang yang memelihara ikan hias ini karena wujudnya memang sangat... jelek. Yang membuatnya unik hanyalah jenggotnya yang berkilau.",
  str_item_intro_5520502 = "Anglerfish putih itu sepertinya lebih jinak, tapi kilaunya juga tampak agak redup. Mungkin ini gara-gara kontrasnya.",
  str_item_intro_5520601 = [[
Dikatakan bahwa kuda laut ini hidup sangat dalam di laut, dan tidak ada yang tahu mengapa ia datang ke sini. Karena terbiasa hidup di laut dalam, biasanya bersembunyi di dasar laut dan sulit ditemukan.
Biasanya bersembunyi dari pandangan, hanya muncul ketika Lumina ada di sekitarnya dan akan ketakutan jika Lumina terlalu kuat.]],
  str_item_intro_5520602 = [[
Kuda laut ini suka hidup di celah-celah batu di sungai. Diberi nama ini karena bergerak sangat cepat, membuat orang mengira batu-batu itu telah diwarnai kuning.
Biasanya bersembunyi dari pandangan, hanya muncul ketika Lumina ada di sekitarnya dan akan ketakutan jika Lumina terlalu kuat.]],
  str_item_intro_5520603 = [[
Kuda Laut Sungai Putih biasanya hidup di sungai dan aliran sungai. Warna tubuh mereka adalah perlindungan alami, dan gaya renang vertikal mereka memungkinkan mereka bersembunyi di gelembung air sungai dan tidak ditemukan oleh musuh alami mereka.
Kurang sensitif terhadap Lumina, biasanya bersembunyi dari pandangan dan hanya muncul ketika tertarik oleh Lumina yang lebih kuat, tetapi akan takut jika Lumina di sekitarnya terlalu kuat.]],
  str_item_intro_5520701 = "Makhluk bawah laut yang suka tinggal di tikungan sungai. Itu terlihat sangat ganas dengan banyak pelengkapnya. Namun, ini hanya penyamaran, karena sangat jinak dan hidup menyendiri di antara ganggang, sehingga sulit dikenali.",
  str_item_intro_5520702 = "Ia suka berdiam di tikungan sungai yang jernih dan menyembunyikan sebagian besar tubuhnya di pasir kuning dasar sungai. Karena warna kulitnya hampir sama dengan pasir, hampir tidak ada makhluk lain yang memperhatikannya, membuatnya sangat mudah untuk menyergap orang lain.",
  str_item_intro_5520801 = "Jangan terkecoh dengan ukurannya yang sangat kecil. Beratnya 1 kilo dan merupakan jenis Bighead Carp terkecil di dunia. Kecil dan terlihat biasa saja, ikan kecil ini memiliki potensi yang sangat besar untuk berkembang...",
  str_item_intro_5520802 = "Ikan Mas Bighead yang sedikit lebih besar. Beratnya 5 kilogram, jauh lebih sulit untuk ditangkap meskipun warnanya lebih cerah. Tampaknya dengan berat yang lebih besar datang kewaspadaan yang lebih besar.",
  str_item_intro_5520803 = "Ikan Mas Bighead seberat 10 kilogram. Dengan tubuh yang lebih bulat dan berisi, matanya yang melotot seolah berkata, \"Aku bisa menjadi lebih besar lagi, lho!\"",
  str_item_intro_5520804 = "Yang terkuat dari semua Bighead Carp, datang dengan berat 20 kilo. Itu melayang perlahan dan damai melalui air, mengisi penonton dengan rasa ketenangan yang mendalam secara misterius.",
  str_item_intro_5520805 = "Monster Bighead Carp yang beratnya mencapai 50 kilogram! Seorang raja di antara ikan mas. Perutnya tampaknya menjadi sumber ketebalannya yang mengesankan. Secara alami, ikan ukuran ini cukup agresif. Makhluk bawah laut lainnya cenderung menghindarinya.",
  str_item_intro_5520806 = "Ikan Mas Bighead ini memiliki ukuran yang layak, tetapi popularitas liarnya berasal dari tubuhnya yang disepuh emas, yang ditutupi oleh sisik berbentuk bintang yang mempesona. Keberadaan ikan yang begitu menakjubkan pasti benar-benar merupakan anugerah dari Tuhan.",
  str_item_intro_5520811 = "Meskipun mungkin terlihat seperti makhluk air yang sangat ganas dan ganas, penjepitnya hanya digunakan untuk menyingkirkan rintangan, seperti batu dan tanaman air yang mencegahnya menjalankan bisnisnya. Nyatanya, penggunaan cakar ini dalam pertempuran hanyalah fungsi sekunder, karena makhluk ini sangat lembut, dan hanya menampilkan wajah agresif tanpa rasa takut saat mempertahankan diri.",
  str_item_intro_5520812 = "Makhluk ini dikenal bersembunyi di antara bebatuan bawah air, karena suka membawa batu untuk membangun \"kastil\" sendiri, dan menyergap makhluk yang tidak beruntung atau hanya ingin tahu untuk mendapatkan makanan yang lezat.",
  str_item_intro_5520014 = "Terkenal dengan cincin biru di tubuhnya, gurita ini jarang terlihat di sungai. Namun saat muncul, banyak makhluk air yang menjauhinya, terutama karena racun kuat di tubuhnya yang konon bisa membunuh dengan satu tetes. Racunnya adalah mengapa ia sangat menarik perhatian dan tidak takut menarik perhatian makhluk lain.",
  str_item_intro_5520901 = "Ikan yang sangat langka yang dibedakan oleh tubuhnya yang sangat berwarna-warni, serta tubuhnya yang kecil namun lincah. Sangat waspada, ia mampu menyembunyikan warnanya pada tanda pertama gerakan di sekitarnya; karena itu, menangkap ikan yang sulit ditangkap membutuhkan kesabaran dan tekad yang tidak sedikit. Namun demikian, kerja keras seseorang terbayar segera setelah melihat \"pita\" warna-warninya mengapung dengan anggun di atas air.",
  str_item_intro_5530001 = "Rezeki nomplok! Di dalam kerang ini ternyata ada mutiara. Warna dan bentuknya bagus, dan bisa dijual mahal.",
  str_item_intro_5530101 = "Kaleng timah lawas. Entah siapa yang melemparkannya ke air, tetapi pelakunya jelas tak peduli dengan pelestarian lingkungan...",
  str_item_intro_5530201 = "Sepatu ini pasti sudah bertahun-tahun \"hidup\" di dalam air, sampai-sampai rumput laut pun tumbuh di dalamnya.",
  str_item_intro_5601101 = "Suatu hari nanti, aku pasti bisa melindungi negeriku di bawah langit luas ini.",
  str_item_intro_5601201 = "Saya harap saya dapat memahami kekuatan luar biasa yang disalurkan melalui Colossus...",
  str_item_intro_5602101 = "Ingatan akan bertahan selama kita hidup, tetapi catatan akan bertahan hingga ribuan tahun. Jadi, aku akan mengingatnya, mencatatnya, dan menyimpannya sampai ada orang yang menemukannya.",
  str_item_intro_5602201 = "Saya bersumpah saya akan menemukan cetak biru itu bahkan jika saya harus melakukan perjalanan ke ujung bumi.",
  str_item_intro_5602202 = "Orang luar pernah berkata bahwa segala sesuatu memiliki biaya. Nah, apa biaya pengetahuan?",
  str_item_intro_5602203 = "Otak dipelihara dengan belajar, dan kehidupan dipelihara oleh emosi.",
  str_item_intro_5603101 = "Jangan mudah menyerah. Bahkan jika eksperimennya gagal 99 kali, yang berikutnya mungkin akan berhasil.",
  str_item_intro_5603201 = "Apa prinsip utama yang mampu mengubah suatu benda menjadi benda lain? Pasti menyenangkan seandainya kita bisa mencari cara untuk mengetahui asal muasal pengetahuan.",
  str_item_intro_5603202 = "Inspirasi ibarat percikan api yang hanya bertahan sekejap. Aku rela menghabiskan seumur hidupku untuk mencari cara agar percikan itu bisa bertahan selamanya.",
  str_item_intro_5603301 = "Bilah paling tajam tidak selalu merupakan pilihan terbaik. Terkadang, yang tumpul bisa menghasilkan keajaiban. Mungkin juga demikian ketika berinteraksi dengannya...",
  str_item_intro_5604101 = "Setiap pohon memiliki takdirnya sendiri. Apa aku juga punya? Semoga saya segera menemukan jawabannya...",
  str_item_intro_5604201 = "Adakah daun berwarna perak? Dia bilang tak ada. Tapi, aku tak percaya kepadanya, maka aku pun kemari.",
  str_item_intro_5604202 = "Lingkaran tahun yang terukur pada batang pohon menunjukkan umur pohon, sejarahnya, dan ingatannya. Bicaralah dengan mereka. Mungkin saja kamu bisa mengetahui masa lalu yang tidak kita ketahui—lingkaran itu juga adalah lingkaran tahun kita.",
  str_item_intro_5604203 = "Di antara bayang-bayang dedaunan dan pepohonan yang terjalin, profilnya muncul. Apakah ini desain takdir?",
  str_item_intro_5604301 = "Mereka tumbuh dan layu dengan tenang. Cara hidup menyendiri ini patut dipelajari.",
  str_item_intro_5604302 = "Dimana akar kita? Saya harap saya akan mengetahuinya dalam hidup ini ...",
  str_item_intro_5605201 = "Riak air ini membuatku teringat kepada ayahku, yang dulu mengajariku memancing.",
  str_item_intro_5605301 = "Alat pancing putih itu adalah peninggalan ibuku, dan kelak akan kuwariskan kepada anak-anakku.",
  str_item_intro_5605302 = "Satu-satunya hal yang menghubungkan kita adalah seutas benang yang tipis ini. Kuharap benang ini tak akan pernah putus.",
  str_item_intro_5605303 = "Bahkan jika hadiahnya adalah umpan, aku akan bersedia menerimanya.",
  str_item_intro_5605304 = "Terkadang memancing bukanlah tentang hasil tangkapan—ini tentang melihat secercah cahaya di atas ombak.",
  str_item_intro_5605305 = "Aku tahu ke arah mana air mengalir, tapi kapan aku bisa tahu apa yang dia pikirkan?",
  str_item_intro_5605306 = "Gerakan kail yang halus menandakan ikan telah mengambil umpan. Andai saja kehidupan memiliki tanda yang sama untuk menunjukkan kepada kita ketika peluang muncul.",
  str_item_intro_5606201 = "Semoga aku tak jadi seperti ayahku, yang tak berhasil mencapai apa pun. Semoga aku berhasil!",
  str_item_intro_5606301 = "Pada akhirnya, ketololanku akan tertutup oleh ketekunanku, dan semua orang akan dengan sepenuh hati menyebutku si genius pertambangan.",
  str_item_intro_5606302 = "Jangan meremehkan kerikil. Beberapa dari mereka mungkin menyembunyikan harta terpendam di dalamnya.",
  str_item_intro_5606303 = "Selalu ingat untuk mempertajam ujung beliung Anda!",
  str_item_intro_5606304 = "Sama seperti cinta, menambang tidak hanya membutuhkan kekuatan, tetapi juga keterampilan!",
  str_item_intro_5606305 = "Vena mineral memiliki bau tertentu! Hidungku sangat sensitif, tapi akan lebih baik jika aku bisa mengetahui keberadaannya...",
  str_item_intro_5606306 = "Jika kita bertekun, kita pasti akan menemukan nadi itu apakah itu di lembah ini atau tidak.",
  str_item_intro_5607201 = "Dia adalah keranjang, dan di dalamnya adalah hatiku.",
  str_item_intro_5607301 = "Pasti senang rasanya seandainya saja dia bisa merasakan niat baikku.",
  str_item_intro_5607302 = "Sebuah buah jatuh ke kepala saya ketika saya masih kecil, dan saya telah diberkati dengan keberuntungan sejak itu. Saya berharap keberuntungan saya akan bertahan jauh di masa depan.",
  str_item_intro_5607303 = "Seringkali, Anda hanya perlu mengikuti lebah untuk menemukan nektar yang baik. Andai saja aku bisa mengerti mereka...",
  str_item_intro_5607304 = "Jika hati kita bisa memakai sarung tangan, mungkin tidak akan mudah terluka oleh duri...",
  str_item_intro_5607305 = "Anda membutuhkan mata yang baik untuk menemukan semua buah sekaligus. Ya, saya ingin mempertahankan level ini sepanjang hidup saya.",
  str_item_intro_5608101 = "Saya harap dia bisa menerima saya karena tanaman merangkul sinar matahari.",
  str_item_intro_5608201 = "Kita tidak hanya menabur benih untuk dipanen kelak, melainkan juga menanam harapan.",
  str_item_intro_5608301 = "Aku suka memandangi kincir angin itu berputar perlahan, karena aku tak perlu memikirkan apa pun. Kita bisa memandanginya saja sepanjang hari...",
  str_item_intro_5608302 = "Biji-bijian sungguh luar biasa. Sedikit biji saja sudah cukup untuk menanam begitu banyak tanaman pangan! Jadi... selama masih ada biji-bijian, berarti masih ada harapan!",
  str_item_intro_5608303 = "Aku membutuhkannya, seperti bagaimana tanaman membutuhkan matahari.",
  str_item_intro_5608304 = "Ketika matahari terlalu kuat, itu akan membakar semua tanaman. Hal yang sama berlaku untuk merawat orang lain.",
  str_item_intro_5608305 = "Tanaman tidak boleh ditanam terlalu berdekatan—mereka harus dipisahkan oleh alur, dengan cara yang sama aku harus menjaga jarak tertentu darinya.",
  str_item_intro_5609201 = "Jika memungkinkan untuk menumbuhkan rumput yang tidak perlu dipotong, itu dapat digunakan sebagai permadani besar yang nyaman untuk tidur!",
  str_item_intro_5609301 = "Bunyi tetesan air terdengar lembut sekaligus keras. Bisakah aku menjadi seperti itu?",
  str_item_intro_5609302 = "Untuk membudidayakan tanaman yang kuat dan sehat, kita butuh tanah yang subur. Sama halnya dengan diri kita sendiri, 'kan? Berterima kasihlah kepada para leluhur kita karena mereka menyediakan lahan yang berbeda bagi kita. Dengan begitu, kita pun bisa tumbuh menjadi orang yang berbeda-beda, sesuai keinginan kita.",
  str_item_intro_5609303 = "Saya ingin nektar termanis untuk anak-anak masa depan saya.",
  str_item_intro_5609304 = "Ah... Kapan kita bisa bebas berdansa seperti lebah?",
  str_item_intro_5609305 = "Anda tidak bisa hanya memandangi bunga-bunga indah itu—daun-daun hijau juga patut mendapat perhatian, bukan?",
  str_item_intro_5610101 = "Saya bisa menggiring kawanan besar, tapi saya tidak bisa memahami hati keluarga saya. Saya berharap anak-anak saya di masa depan tidak akan seperti itu.",
  str_item_intro_5610201 = "Dikatakan bahwa jika Anda melihat wajah tersenyum ketika Anda menuangkan secangkir susu, Anda akan diberkati untuk sisa tahun ini!",
  str_item_intro_5610202 = "Kudengar desa lain menggunakan anjing patroli untuk membantu mereka menggembalakan hewan, tapi hanya dia yang kumiliki.",
  str_item_intro_5610203 = "Konon ada makhluk yang disebut \"unta\" yang tinggal di gurun yang jauh, dan susunya konon cukup enak!",
  str_item_intro_5610204 = "Suatu hari, saya akan melihat rumput bertunas sekali lagi, dan ladang akan terlahir kembali.",
  str_item_intro_5610301 = "Kudengar ada padang rumput yang lebih luas di luar lembah ini, tapi aku suka rerumputan hijau di sini.",
  str_item_intro_5610302 = "Keju adalah makanan terbaik di dunia. Jadi, kalau kita bisa menyantapnya setiap hari seumur hidup, berarti kita sedang berada di tempat yang layak disebut surga.",
  str_item_intro_5610303 = "Mereka mengatakan bahwa orang-orang gurun menetap di kota mereka berdasarkan di mana sumber air berada. Melihat betapa aku tidak tahan berada satu yard darinya, mungkin dia adalah sumber airku...?",
  str_item_intro_5611101 = "Menurut orang-orang di tepi laut, ada kapal besar yang bentuknya hampir mirip pulau. Saya sangat ingin melihatnya!",
  str_item_intro_5611201 = "Saya bisa tetap bertugas jaga sepanjang hari jika saya tidak harus tidur.",
  str_item_intro_5611202 = "Aku tidak akan pernah membiarkan kejahatan mendekati sini. Apalagi tidak apa-apa yang bisa membahayakan anak-anak...",
  str_item_intro_5611203 = "Setelah menjadi penjaga tempat ini, aku tidak bisa istirahat bahkan di malam hari.",
  str_item_intro_5611204 = "Tidak ada detail yang dapat diabaikan, jika tidak, bencana kemungkinan besar akan terjadi.",
  str_item_intro_5611301 = "Aku bisa terus berjalan tiga hari tiga malam tanpa merasa lelah. Akan kumanfaatkan bakat ini untuk berpatroli di lembah ini dan mengawasi kalau-kalau ada orang luar yang datang.",
  str_item_intro_5611302 = "Aku akan menjadi tameng bagi kaumku! Haha, aku tahu ini dari Knight's Oath of Lumopolis, dan ini keren! Akan kulakukan seperti yang kukatakan!",
  str_item_intro_5611303 = "Jika kita benar-benar menyalakan pohon-pohon besar yang terlihat seperti obor, dapatkah kita menggunakannya sebagai suar penjaga?",
