  str_item_intro_6500001 = "Latar belakang kartu nama awal. Dapat dipilih melalui Kartu Nama - Latar Belakang!",
  str_item_intro_6500002 = "Latar belakang kartu nama awal. Dapat dipilih melalui Kartu Nama - Latar Belakang!",
  str_item_intro_6500003 = "Latar belakang kartu nama awal. Dapat dipilih melalui Kartu Nama - Latar Belakang!",
  str_item_intro_6500004 = "Latar belakang kartu nama awal. Dapat dipilih melalui Kartu Nama - Latar Belakang!",
  str_item_intro_6500005 = "Latar belakang kartu nama awal. Dapat dipilih melalui Kartu Nama - Latar Belakang!",
  str_item_intro_6500008 = "Bukit-bukit yang berbukit-bukit, diselimuti selimut putih. Meski suram dan tenang, mereka tampaknya memancarkan vitalitas tertentu.",
  str_item_intro_6500011 = "Kesepakatan teduh yang dibuat di lorong-lorong gelap di bawah kabut di jantung Umbraton adalah pemandangan umum bagi penghuninya.",
  str_item_intro_6500014 = "Pabrik perawatan di Illumina Undercity. Itu dapat memperbaiki banyak perangkat yang rusak dengan sangat cepat, bahkan mesin besar itu.",
  str_item_intro_6500015 = "Perayaan di Lumopolis semegah biasanya.",
  str_item_intro_6500016 = "Sumber air yang melimpah, persimpangan, dan fitur geografis dan topografi yang nyaman semuanya berkontribusi pada kemakmuran Umbraton.",
  str_item_intro_6500017 = "Saat matahari diliputi kegelapan yang tak bisa dijelaskan, perubahan besar apa yang menanti dunia?",
  str_item_intro_6500018 = "Northland, alam beku abadi. Tanah ini diperintah oleh Betlehem, dan itu juga tempat yang ingin dia lindungi.",
  str_item_intro_6500020 = "Apapun yang terjadi, aku tidak akan membiarkan penjahat itu merusak konser! Inilah keadilan!",
  str_item_intro_6500021 = "Northland, alam beku abadi. Tanah ini diperintah oleh Betlehem, dan itu juga tempat yang ingin dia lindungi.",
  str_item_intro_6500024 = "Pada saat itu, kewaspadaannya tampak mencair, dan senyum bahagianya berseri-seri dengan kenakalan kekanak-kanakan, menyembunyikan rahasia hanya untuk dua orang.",
  str_item_intro_6500026 = "Perjamuan Rediesel Wrench yang klasik mengundang—pesta perayaan penuh semangat yang telah menjadi campuran makanan lezat padang pasir yang terkenal.",
  str_item_intro_6500033 = "Saat lelah karena perjalanan, Anda selalu dapat meluangkan waktu untuk duduk bersama teman-teman Anda ini sambil bersantai, berbicara, dan mendengarkan cerita satu sama lain.",
  str_item_intro_6500035 = "Sinar matahari di kastil di ketinggian tetap tidak berubah selama bertahun-tahun. Berdiri di depan sebuah lukisan cat minyak besar, dia mengenakan gaun tua dan menghabiskan waktu lama di sana, tenggelam dalam pemikiran yang dalam, mungkin mengenang.",
  str_item_intro_6500036 = "Dengan Florine di sisimu, bahkan perairan yang paling berbahaya pun akan menjadi aman.",
  str_item_intro_6500037 = "Seseorang telah tinggal di sini lebih dari seratus tahun, hanya untuk menunaikan misi yang lama terlupakan.",
  str_item_intro_6500038 = "Saat angin lembut mengusir kegelapan masa lalu, sinar terang fajar akan menghanguskan semua kesedihan untuk menyambut masa depan yang baru bagi kamu.",
  str_item_intro_6500039 = "Seperti mercusuar, dia akan menerangi samudra yang luas dan gelap, membimbing para petualang menuju rumah.",
  str_item_intro_6500041 = "Meski dingin membeku dan bumi tertutup es dan salju, hatimu akan selalu hangat jika bersama teman-temanmu. Selamat liburan, Navigator!",
  str_item_intro_6500042 = "Sheol melompat tinggi ke udara untuk menangkis musuh yang menyerang. Pada saat ini, dia menunjukkan sisi dirinya yang tidak diketahui oleh orang lain.",
  str_item_intro_6500043 = "Banyak stasiun pengamatan didirikan di sepanjang perbatasan gurun. Di sinilah mereka menolak musuh dan mempertahankan tanah air mereka yang jauh.",
  str_item_intro_6500044 = "Toko-toko berlimpah, dipenuhi dengan suara riuh, dan pusat kota Twin Pavilions Bay yang ramai dipenuhi oleh penduduk dan turis, memilih barang dengan minat yang besar di tengah hiruk pikuk.",
  str_item_intro_6500045 = "\"Terima kasih atas penghargaanmu. Demi White Night!\"",
  str_item_intro_6500046 = "\"Saya menikmati melamun sendirian, tapi sekarang... dengan kamu di sini, ini adalah jenis kebahagiaan yang berbeda.\"",
  str_item_intro_6500047 = "\"Dunia ini masih penuh dengan perang. Maukah kamu bergabung denganku untuk menyelesaikan konflik-konflik ini di hari-hari yang akan datang?\"",
  str_item_intro_6500049 = "\"Krok! Krok!\"",
  str_item_intro_6500051 = [[
Saat sekelompok drone mengelilinginya, gadis itu berbalik dan menatap kamu.
"Semuanya baik-baik saja sekarang."]],
  str_item_intro_6500053 = [[
Gemilang dan cerah, dia tersenyum dan melompat ke dalam jurang.
"Jangan biarkan siapa pun mengambil kekuatan atau kebahagiaanmu."]],
  str_item_intro_6500054 = "Jalan mana yang harus kamu pilih ketika berada di persimpangan takdir?",
  str_item_intro_6500056 = "Semua yang kamu alami akan membimbing True Order menuju masa depan yang lebih hebat. ",
  str_item_intro_6500057 = "Angin laut, es serut, becak. Kenangan dari musim panas pertama yang dihabiskan bersama gadis itu masih tetap jelas seperti sedia kala.",
  str_item_intro_6500058 = "Janji reuni, tempat jiwa-jiwa bertemu.",
  str_item_intro_9993001 = "Seorang Aurorian yang bertahan secara acak dalam tim meregenerasi 20% HP setelah memenangkan pertempuran.",
  str_item_intro_9993002 = "Supporter Aurorian +25% efek regenerasi dari Chain Combos dan Active Skills dalam pertempuran.",
  str_item_intro_9993003 = "+80% pemulihan HP saat menggunakan perban yang diambil dalam pertempuran.",
  str_item_intro_9993004 = "Sniper Aurorians +10% efek penghitung elemen.",
  str_item_intro_9993005 = "Detonator Aurorian +30% Chain Combo damage saat menyambungkan 15+ tile.",
  str_item_intro_9993006 = "+50% kerusakan Poison, Burn, dan Bleeding yang diterima oleh Eclipsites.",
  str_item_intro_9993007 = "Sniper Aurorians +15% kerusakan Chain Combo.",
  str_item_intro_9993008 = "Detonator Aurorian +30% kemungkinan serangan normal menghasilkan 150% kerusakan.",
  str_item_intro_9993009 = "Konverter Aurorian +15% HP maks.",
  str_item_intro_9993010 = "Sniper Aurorian +15% HP maks.",
  str_item_intro_9993011 = "Detonator Aurorian +25% maks HP.",
  str_item_intro_9993012 = "Supporter Aurorian +25% max HP.",
  str_item_intro_9993013 = "Meningkatkan HP Maks sebanyak 5% untuk semua Aurorian.",
  str_item_intro_9993014 = "+5% ATK untuk Fire Aurorian.",
  str_item_intro_9993015 = "+5% ATK untuk Fire Aurorian.",
  str_item_intro_9993016 = "+5% ATK untuk Fire Aurorian.",
  str_item_intro_9993017 = "+5% ATK untuk Fire Aurorian.",
  str_item_intro_9993018 = "+5% ATK untuk Fire Aurorian.",
  str_item_intro_9993019 = "+5% ATK untuk Water Aurorian.",
  str_item_intro_9993020 = "+5% ATK untuk Water Aurorian.",
  str_item_intro_9993021 = "+5% ATK untuk Water Aurorian.",
  str_item_intro_9993022 = "+5% ATK untuk Water Aurorian.",
  str_item_intro_9993023 = "+5% ATK untuk Water Aurorian.",
  str_item_intro_9993024 = "+5% ATK untuk Forest Aurorian.",
  str_item_intro_9993025 = "+5% ATK untuk Forest Aurorian.",
  str_item_intro_9993026 = "+5% ATK untuk Forest Aurorian.",
  str_item_intro_9993027 = "+5% ATK untuk Forest Aurorian.",
  str_item_intro_9993028 = "+5% ATK untuk Forest Aurorian.",
  str_item_intro_9993029 = "+5% ATK untuk Thunder Aurorian.",
  str_item_intro_9993030 = "+5% ATK untuk Thunder Aurorian.",
  str_item_intro_9993031 = "+5% ATK untuk Thunder Aurorian.",
  str_item_intro_9993032 = "+5% ATK untuk Thunder Aurorian.",
  str_item_intro_9993033 = "+5% ATK untuk Thunder Aurorian.",
  str_item_intro_9993034 = "Meningkatkan HP sebesar 3% untuk Konverter dan Aurorian Pendukung setelah setiap kemenangan, hingga 30%.",
  str_item_intro_9993035 = "Meningkatkan ATK sebanyak 1,5% untuk Aurorian Sniper dan Detonator setiap kali menang, maks 15%.",
  str_item_intro_9993036 = "Aurorian mana saja yang berhasil bertahan dalam tim akan memperoleh 1,5% damage reduction yang bisa ditumpuk setelah menang dalam pertempuran, hingga akhir Secret Territory Exploration ini.",
  str_item_intro_9994001 = "HP Aurorian yang berhasil bertahan dalam tim akan beregenerasi sebesar 10% setiap kali ada Eclipsite yang terbunuh.",
  str_item_intro_9994002 = "Aurorian Pendukung meregenerasi 100% kerusakan racun di HP setiap kali Racun dipicu pada Eclipsite Beracun.",
  str_item_intro_9994003 = "Detonator Aurorian +30% damage untuk Eclipsite dengan debuff.",
  str_item_intro_9994004 = "Menimbulkan 3 tumpukan Racun ke semua musuh saat Eclipsite yang Diracuni, Terbakar, atau Berdarah mati.",
  str_item_intro_9994005 = "Setiap putaran Eclipsite, Eclipsites Beracun, Terbakar, atau Berdarah menimbulkan Poison pada Eclipsites di 2 cluster sekitarnya.",
  str_item_intro_9994006 = "Sniper Aurorian +30% damage saat tim terpengaruh oleh debuff.",
  str_item_intro_9994007 = "Detonator Aurorian +5% damage bonus setiap kali damage diterima (direset pada akhir pertempuran).",
  str_item_intro_9994008 = "Mengisi ulang Bandage di medan saat pertempuran dimulai.",
  str_item_intro_9994009 = "+20% damage untuk semua Sniper Aurorian dengan lebih dari 70% HP.",
  str_item_intro_9994010 = "Detonator Aurorian memperoleh damage bonus setara dengan 10% of HP yang hilang saat menyerang.",
  str_item_intro_9994011 = "Lumina Spring meregenerasi 5 MS lagi.",
  str_item_intro_9994012 = "+1 karakter yang dipulihkan oleh Lumina Spring.",
  str_item_intro_9994013 = "Detonator Aurorian +10% ATK di Area Berbahaya.",
  str_item_intro_9994014 = "Detonator Aurorian di Area Letal mendapatkan +10% ATK.",
  str_item_intro_9994015 = "Menunda putaran melarikan diri untuk Scrounger sebanyak 4 putaran.",
  str_item_intro_9994016 = "Mengurangi 1 putaran cooldown untuk semua Aurorian setelah membunuh Eclipsite besar.",
  str_item_intro_9994017 = "Sniper Aurorian +20% ATK saat membunuh Eclipsite besar.",
  str_item_intro_9994018 = "Regenerasi HP sebesar 20% untuk Aurorian dengan HP terendah setelah satu Eclipsite besar terbunuh.",
  str_item_intro_9994019 = "Memberikan Slow kepada semua monster kecil.",
  str_item_intro_9994020 = "-20% HP awal untuk semua monster kecil.",
  str_item_intro_9994021 = "-10% ATK semua monster kecil.",
  str_item_intro_9994022 = "-1 cooldown untuk semua Converter Aurorian Active Skill yang belum lengkap saat pertandingan dimulai.",
  str_item_intro_9994023 = "Melayang-layang di sekitar Aurorian dan menimbulkan satu Fire damage saat Kapten menyerang.",
  str_item_intro_9994024 = "Melayang-layang di sekitar Aurorian dan menimbulkan satu Water damage saat Kapten menyerang.",
  str_item_intro_9994025 = "Melayang-layang di sekitar Aurorian dan menimbulkan satu Forest damage saat Kapten menyerang.",
  str_item_intro_9994026 = "Melayang-layang di sekitar Aurorian dan menimbulkan satu Thunder damage saat Kapten menyerang.",
  str_item_intro_9995001 = "Membangkitkan kembali Aurorian yang terbunuh dengan 50% HP (hanya untuk Aurorian pertama yang menerima damage mematikan dalam pertempuran)",
  str_item_intro_9995002 = "Kerusakan dari satu serangan yang diberikan kepada Konverter Aurorian yang memakai relik tidak akan pernah melebihi 20% dari Max HP.",
  str_item_intro_9995003 = "Kelebihan Healing Support dari Aurorian diubah menjadi Shield untuk satu putaran di satu level.",
  str_item_intro_9995004 = "50% peluang untuk melepaskan Gelombang Kejut yang akan mengakibatkan Stun pada semua musuh selama satu putaran di setiap pertempuran.",
  str_item_intro_9995005 = "Serangan normal Sniper Aurorians dan Chain Combo damage segera menghilangkan perisai Eclipsite.",
  str_item_intro_9995006 = "4 dari 8 tile berdekatan secara acak menjadi tile berwarna saat pertandingan dimulai.",
  str_item_intro_9995007 = "Menyegarkan MS Luminameter ekstra saat pertempuran dimulai.",
  str_item_intro_9995008 = "Saat pertandingan dimulai, 10 ubin 2x2 acak disambar petir yang memberikan kerusakan statis pada unit dalam jangkauan. Aurorian tidak terpengaruh.",
  str_item_intro_9995009 = "Meninggalkan bom di titik awal gerakanmu. Bom ini akan meledak mengikuti aksimu dan rekan-rekanmu.",
  str_item_intro_9995010 = "Normal Attack Combo dalam kelipatan 5 akan menimbulkan satu damage ledakan.",
  str_item_intro_9995011 = "Mengalahkan Eclipsites di bawah 7% HP.",
  str_item_intro_9995012 = "Menghasilkan gambar Detonator Aurorian yang mengeluarkan skill di titik permulaan, sambil mengeluarkan Chain Combo.",
  str_item_intro_9995013 = "Pakai Fate Dice untuk mendapatkan sembarang Secret Territory Relic baru.",
  str_item_intro_9995014 = "Memberikan 40% peluang bagi Sniper Aurorian untuk melepaskan Chain Combo tambahan.",
  str_item_intro_9995015 = "-1 cooldown untuk sembarang Converter Aurorian saat Aurorian memakai Active Skill.",
  str_item_intro_9995016 = "Normal attack dari Sniper Aurorian menimbulkan Slow dan -1 Movement terhadap Eclipsite.",
  str_item_intro_9995017 = "Menimbulkan Wounded dan 3% damage terhadap semua Eclipsite setiap kali berpindah tile saat match dimulai.",
  str_item_intro_9995018 = "Normal attack dari Aurorian Support memberikan Blindness terhadap Eclipsite dan 30% peluang meleset saat menyerang.",
  str_item_rpintro_9993001 = "Lilin yang memancarkan sinar hangat yang bisa menyembuhkan Aurorian yang terluka.",
  str_item_rpintro_9993002 = "Cat zaman dahulu yang mampu menyerap Lumina.",
  str_item_rpintro_9993003 = "Tambahan untuk ramuan pemulihan yang membantu menyembuhkan luka.",
  str_item_rpintro_9993004 = "Sepertinya ditulis oleh kaum intelektual zaman dahulu, dan berisi detail tentang perbedaan Element Counter Effect dan saran strategi yang efektif.",
  str_item_rpintro_9993005 = "Emblem dari zaman dulu dengan cetak biru menakjubkan untuk menampung sedikit Lumina dan meningkatkan daya tempur.",
  str_item_rpintro_9993006 = "Relik dari zaman kuno, mungkin sangat terkutuk. Pemakainya dapat meluncurkan serangan beracun yang mematikan.",
  str_item_rpintro_9993007 = "Jimat zaman dahulu, bisa menyimpan sedikit Lumina untuk menimbulkan damage besar terhadap musuh.",
  str_item_rpintro_9993008 = "Pedang pendek tajam yang terbuat dari superalloy kuno.",
  str_item_rpintro_9993009 = "Armor kulit berisi Lumina. Ringan dan tahan lama, cukup untuk menambah resistansi terhadap serangan.",
  str_item_rpintro_9993010 = "Armor kulit berisi Lumina. Ringan dan tahan lama, cukup untuk menambah resistansi terhadap serangan.",
  str_item_rpintro_9993011 = "Armor kulit berisi Lumina. Ringan dan tahan lama, cukup untuk menambah resistansi terhadap serangan.",
  str_item_rpintro_9993012 = "Armor kulit berisi Lumina. Ringan dan tahan lama, cukup untuk menambah resistansi terhadap serangan.",
  str_item_rpintro_9993013 = "Armor kulit berisi Lumina. Ringan dan tahan lama, cukup untuk menambah resistansi terhadap serangan.",
  str_item_rpintro_9993014 = "Permata merah gaib. Dengan permata ini, Fire Aurorian akan memperoleh power boost.",
  str_item_rpintro_9993015 = "Permata merah gaib. Dengan permata ini, Fire Aurorian akan memperoleh power boost.",
  str_item_rpintro_9993016 = "Permata merah gaib. Dengan permata ini, Fire Aurorian akan memperoleh power boost.",
  str_item_rpintro_9993017 = "Permata merah gaib. Dengan permata ini, Fire Aurorian akan memperoleh power boost.",
  str_item_rpintro_9993018 = "Permata merah gaib. Dengan permata ini, Fire Aurorian akan memperoleh power boost.",
  str_item_rpintro_9993019 = "Permata biru gaib. Dengan permata ini, Water Aurorian akan memperoleh power boost.",
  str_item_rpintro_9993020 = "Permata biru gaib. Dengan permata ini, Water Aurorian akan memperoleh power boost.",
  str_item_rpintro_9993021 = "Permata biru gaib. Dengan permata ini, Water Aurorian akan memperoleh power boost.",
  str_item_rpintro_9993022 = "Permata biru gaib. Dengan permata ini, Water Aurorian akan memperoleh power boost.",
  str_item_rpintro_9993023 = "Permata biru gaib. Dengan permata ini, Water Aurorian akan memperoleh power boost.",
  str_item_rpintro_9993024 = "Permata hijau gaib. Dengan permata ini, Forest Aurorian akan memperoleh power boost.",
  str_item_rpintro_9993025 = "Permata hijau gaib. Dengan permata ini, Forest Aurorian akan memperoleh power boost.",
  str_item_rpintro_9993026 = "Permata hijau gaib. Dengan permata ini, Forest Aurorian akan memperoleh power boost.",
  str_item_rpintro_9993027 = "Permata hijau gaib. Dengan permata ini, Forest Aurorian akan memperoleh power boost.",
  str_item_rpintro_9993028 = "Permata hijau gaib. Dengan permata ini, Forest Aurorian akan memperoleh power boost.",
  str_item_rpintro_9993029 = "Permata kuning gaib. Dengan permata ini, Thunder Aurorian akan memperoleh power boost.",
  str_item_rpintro_9993030 = "Permata kuning gaib. Dengan permata ini, Thunder Aurorian akan memperoleh power boost.",
  str_item_rpintro_9993031 = "Permata kuning gaib. Dengan permata ini, Thunder Aurorian akan memperoleh power boost.",
  str_item_rpintro_9993032 = "Permata kuning gaib. Dengan permata ini, Thunder Aurorian akan memperoleh power boost.",
  str_item_rpintro_9993033 = "Permata kuning gaib. Dengan permata ini, Thunder Aurorian akan memperoleh power boost.",
  str_item_rpintro_9993034 = "Patung kecil kuno yang hilang, terbuat dari bahan bermutu tinggi. Tahan lama, ringan, dan membawa berkat bagi mereka yang membawanya.",
  str_item_rpintro_9993035 = "Senjata zaman dahulu yang terbuat dari bahan bermutu tinggi dan diisi dengan Lumina agar penggunanya menjadi tangguh.",
  str_item_rpintro_9993036 = "Shield kuno dari zaman kuno, bentuknya oval sempurna dan konon diisi dengan kekuatan matahari untuk menangkis semua serangan mematikan.",
  str_item_rpintro_9994001 = "Pedang besar yang menakutkan. Tampaknya digunakan dalam duel kematian di zaman kuno. Saat dihunus, akan terjadi pertumpahan darah.",
  str_item_rpintro_9994002 = "Masker yang dipakai para dokter zaman dahulu, tetapi menjadi simbol kutukan pada masa perang.",
  str_item_rpintro_9994003 = "Pedang kuno yang terkenal. Penggunanya bisa merasakan kekuatan setara dengan dewa.",
  str_item_rpintro_9994004 = "Konon item terkutuk yang dibuat oleh seorang kesatria perkasa untuk memastikan semua musuh binasa.",
  str_item_rpintro_9994005 = "Lukisan kuno yang dibuat oleh pelukis tak dikenal dan menggambarkan keganasan wabah. Sang seniman turut meninggal saat pandemi itu. Setelahnya, lukisan tersebut dihinggapi kekuatan mengerikan...",
  str_item_rpintro_9994006 = "Pedang kuno terkenal yang diayunkan oleh seorang pemberontak jahat, dan punya kekuatan magis yang berasal dari jeritan kematian pemberontak itu.",
  str_item_rpintro_9994007 = "Armor kuno berukir kata \"Vengeance.\" Penggunanya bisa merasakan amukan abadi tersembunyi di dalam armor itu.",
  str_item_rpintro_9994008 = "Patung seorang dewi yang kondisinya masih sempurna, memberikan kekuatan Healing kepada para pengikut Light.",
  str_item_rpintro_9994009 = "Bawalah, maka kamu akan dilindungi oleh Dewi Kemenangan sehingga bisa memenangkan semua pertempuran.",
  str_item_rpintro_9994010 = "Belati ini, yang konon berasal dari suatu perang sipil dari zaman dahulu sekali, mengeluarkan aura seram dan pasti akan menimbulkan pertumpahan darah ketika dihunuskan.",
  str_item_rpintro_9994011 = "Teknologi zaman kuno. Walau ukurannya kecil, item ini mampu menyimpan banyak Lumina.",
  str_item_rpintro_9994012 = "Kantong tidur yang hilang dan terlupakan. Membantu memulihkan kekuatan.",
  str_item_rpintro_9994013 = "Senjata api yang diberkati kekuatan matahari. Laju tembakannya lambat, tetapi cukup kuat untuk melawan musuh tangguh.",
  str_item_rpintro_9994014 = "Dulu pernah dimiliki oleh banyak orang, meski tidak pernah lama...",
  str_item_rpintro_9994015 = "Senjata jarak jauh yang menembakkan sinar pelumpuh. Jarak terbatas, tidak terlalu kuat, dan biasanya dipakai untuk menangkap pencuri kelas teri.",
  str_item_rpintro_9994016 = "Radiance Relic dari para kesatria zaman dahulu, berukir simbol sakral dan sangat efektif untuk melawan musuh yang kuat. (Efeknya menjadi ganda jika memiliki ketiga Radiance Relic.)",
  str_item_rpintro_9994017 = "Radiance Relic dari para kesatria zaman dahulu, berukir simbol sakral dan sangat efektif untuk melawan musuh yang kuat. (Efeknya menjadi ganda jika memiliki ketiga Radiance Relic.)",
  str_item_rpintro_9994018 = "Radiance Relic dari para kesatria zaman dahulu, berukir simbol sakral dan sangat efektif untuk melawan musuh yang kuat. (Efeknya menjadi ganda jika memiliki ketiga Radiance Relic.)",
  str_item_rpintro_9994019 = "Senjata klasik kuno yang berukir simbol sakral dan sangat efektif untuk melawan musuh yang kuat. (Efeknya menjadi ganda jika memiliki ketiga Silvermoon Relic.)",
  str_item_rpintro_9994020 = "Senjata klasik kuno yang berukir simbol sakral dan sangat efektif untuk melawan musuh yang kuat. (Efeknya menjadi ganda jika memiliki ketiga Silvermoon Relic.)",
  str_item_rpintro_9994021 = "Senjata klasik kuno yang berukir simbol sakral dan sangat efektif untuk melawan musuh yang kuat. (Efeknya menjadi ganda jika memiliki ketiga Silvermoon Relic.)",
  str_item_rpintro_9994022 = "Koin kuno misterius yang terkadang menambah kecepatan Aurorian yang memilikinya, sehingga mereka menjadi lebih gesit.",
  str_item_rpintro_9994023 = "Colossus miniatur yang tampaknya berasal dari zaman kuno dan bertugas membantu dalam pertempuran. Aurorian yang memiliki floater dari keempat elemen dapat melepaskan satu serangan kuat setelah satu Chain Combo.",
  str_item_rpintro_9994024 = "Colossus miniatur yang tampaknya berasal dari zaman kuno dan bertugas membantu dalam pertempuran. Aurorian yang memiliki floater dari keempat elemen dapat melepaskan satu serangan kuat setelah satu Chain Combo.",
  str_item_rpintro_9994025 = "Colossus miniatur yang tampaknya berasal dari zaman kuno dan bertugas membantu dalam pertempuran. Aurorian yang memiliki floater dari keempat elemen dapat melepaskan satu serangan kuat setelah satu Chain Combo.",
  str_item_rpintro_9994026 = "Colossus miniatur yang tampaknya berasal dari zaman kuno dan bertugas membantu dalam pertempuran. Aurorian yang memiliki floater dari keempat elemen dapat melepaskan satu serangan kuat setelah satu Chain Combo.",
  str_item_rpintro_9995001 = "Kerajinan tangan yang memiliki hubungan misterius dengan negeri ini. Membangkitkan pemakainya begitu jantungnya berhenti berdetak.",
  str_item_rpintro_9995002 = "Armor kuat yang diberkati oleh matahari sehingga pemakainya bisa bertahan dalam pertempuran demi pertempuran yang meletihkan.",
  str_item_rpintro_9995003 = "Perangkat tidak dikenal dari zaman dahulu yang bisa merasakan dan mengubah Lumina yang meluap menjadi medan kekuatan pelindung bagi penggunanya.",
  str_item_rpintro_9995004 = "Kristal kasar dengan permukaan agak retak yang menandakan Lumina berlebih di dalamnya. Sentuhan lembut saja bisa melepaskan cukup banyak Lumina untuk mengakibatkan stun pada musuh dalam pertempuran.",
  str_item_rpintro_9995005 = "Senjata yang kuat dari zaman kuno. Tak seorang pun tahu bahannya, mereka hanya tahu bahwa senjata ini sangat tajam sehingga sebagian besar armor tidak mampu membendungnya.",
  str_item_rpintro_9995006 = "Permata yang memancarkan semua warna, sangat indah dan selalu berubah.",
  str_item_rpintro_9995007 = "Perangkat untuk menyimpan dan menambah Lumina.",
  str_item_rpintro_9995008 = "Pedang tersohor dari zaman dahulu, diliputi kekuatan guntur. Auranya yang menggentarkan terpancar saat dihunus.",
  str_item_rpintro_9995009 = "Item zaman dahulu yang diciptakan khusus untuk menghadapi pengejar. Menyisakan Lumina di jejak yang kemudian meledak untuk membunuh pengejar.",
  str_item_rpintro_9995010 = "Kreasi zaman dahulu yang tampak sangat cantik tetapi memiliki kekuatan mengerikan, menjatuhkan musuh seperti bunga berguguran dengan ledakan.",
  str_item_rpintro_9995011 = "Bisa merasakan energi kehidupan musuh dan, saat dipegang erat, bisa mengakhiri nyawa orang yang sekarat.",
  str_item_rpintro_9995012 = "Perangkat kuat dari zaman dahulu yang bisa menghasilkan ilusi untuk membingungkan musuh.",
  str_item_rpintro_9995013 = "Relik kuno yang membuat seseorang bisa melihat nasib semua orang... Atau, mungkin pula hanya halusinasi.",
  str_item_rpintro_9995014 = "Anggrek merah langka yang khusus dibudidayakan pada zaman dahulu. Selalu muncul, mekar, dan layu berpasangan. Sepertinya membentuk ikatan dengan penggunanya dan membantu dalam pertempuran.",
  str_item_rpintro_9995015 = "Item zaman dahulu yang membuat ikatan misterius antara dua petarung.",
  str_item_rpintro_9995016 = "Produk dari perang zaman dahulu. Konon bisa menimbulkan penuaan dan langkah tersendat-sendat.",
  str_item_rpintro_9995017 = "Dengar-dengar, ini adalah item misterius dari perang besar terdahulu. Item ini membawa kutukan kuat hingga sanggup melukai lawan.",
  str_item_rpintro_9995018 = "Lensa yang berkilau dalam pertempuran, membutakan lawan sekaligus melindungi penggunanya. Peralatan tambahan.",
  str_item_gift_open_cond_1003 = "Capai Lv. 10 untuk membuka Gift Pack",
