  str_item_1502031 = "Jakine",
  str_item_1602041 = "Yosua",
  str_item_1502051 = "Blanc: Pura Cordis",
  str_item_1602061 = "Lorelei",
  str_item_1602071 = "Cena",
  str_item_1502081 = "Bopper",
  str_item_1501871 = "Li Tianxian",
  str_item_1601881 = "Dantang",
  str_item_1602371 = "Maya",
  str_item_1602381 = "Mithra",
  str_item_intro_1600011 = "Juru bicara wanita untuk Northland. Dia membawa cermin besar yang memantulkan penampilannya yang luar biasa, dan menyembunyikan banyak rahasia...",
  str_item_intro_1600021 = "Commander Illumina Federation yang ketat, serius, tegas, dan percaya diri. Ia meraih banyak kemenangan dengan pedang panjang di tangannya.",
  str_item_intro_1600031 = "Menjadi kepala pelayan untuk bangsawan Uptown hingga diusir ke Lower Lumopolis karena menyinggung bangsawan lain. Namun, menurut beberapa orang, itu cuma kedok misi rahasianya...",
  str_item_intro_1600041 = "Sepasang binatang aneh yang terdiri dari dua pengembara. Kini mereka bekerja sebagai tentara bayaran lepas yang dikenal karena keahlian tempur dan selera humornya.",
  str_item_intro_1600051 = "Gadis yang berkeliaran di Umbraton dengan tawa agak gila. Dia suka memainkan permainan mematikan bersama orang lain; tak heran kalau dia dijauhi.",
  str_item_intro_1600061 = "Putri kedua Lumopolis Lord. Mandiri sejak muda, dia bangkit menjadi Kapten para Guardian karena bakat dan upayanya.",
  str_item_intro_1400071 = "Gadis assassin dari Rediesel Wrench. Dia bekerja sendirian dan mengkhususkan diri dalam misi yang sulit.",
  str_item_intro_1400081 = "Teknisi Rediesel Wrench, penemu proyektor sinar matahari, yang membanggakan mode tempur unik.",
  str_item_intro_1500091 = "Pemuda tampan dari True Order. Dia memancarkan hawa pengetahuan dengan senyumnya yang cukup menawan dan suka berbicara panjang lebar tentang gagasan akademiknya.",
  str_item_intro_1600101 = "Gadis ceria dari Northland bercita-cita ingin keliling dunia dan melihat semuanya lewat kacamata berwarna mawar.",
  str_item_intro_1600111 = "Legion Commander dari Illumina Federation dengan Dragon Power. Meskipun dia tampak acuh tak acuh dan mandiri, dia pasti seseorang yang bisa diandalkan.",
  str_item_intro_1500121 = "Gadis pemberani dari Illumina Federation yang berjuang menegakkan dan melaksanakan keadilan dengan gagasan mulia.",
  str_item_intro_1500131 = "Gadis Northland dengan magic es yang kuat dan bisa menutupi suatu daerah dengan es musim dingin.",
  str_item_intro_1600141 = "Lord of Lumopolis, yang terus menegakkan hukum dan ketertiban di kota tanpa berpuas diri.",
  str_item_intro_1400171 = "Gadis pendek dan captain di Rediesel Wrench, gesit dengan reflek kilat. Sedikit sekali musuh yang bisa mendesaknya.",
  str_item_intro_1500181 = "Rocker dari Rediesel Wrench yang sangat terkenal. Bukan saja bisa menginspirasi pasukan, tapi dia juga bisa memimpin mereka berperang.",
  str_item_intro_1600191 = "Wanita dewasa dengan jimat mematikan, dan anggota True Order dengan suatu pengetahuan terlarang. Dia suka menyarankan suatu kebenaran...",
  str_item_intro_1500201 = "Northwind",
  str_item_intro_1500211 = "Pemuda biasa dari Illumina Federation. Master ilmu alam, mahir berkebun, dan suka menghukum musuh dengan kekuatan alam.",
  str_item_intro_1300221 = "Pemberontak muda yang lear dengan handgear kelinci. Terobsesi dengan disel dan kekerasan, dia merupakan salah satu penjahat nekat dari Rediesel Wrench.",
  str_item_intro_1600231 = "Gadis yang sangat antisosial, bergantung pada klarinet dan kemampuan khususnya untuk mengontrol para makhluk air untuk membuat peran unik di Umbraton yang kacau.",
  str_item_intro_1500241 = "Duo dari Illumina. Benny suka bersikap kurang ajar dan sembrono, sedangkan Curo dingin dan tenang. Terlepas dari perbedaan mereka, keduanya sangat serasi dan termasuk petarung elite untuk Illumina.",
  str_item_intro_1600251 = "Petugas logistik untuk Illumina Federation, juga pemilik dan mitra dekat dalam hidup atau pertempuran di kereta, Other End.",
  str_item_intro_1600261 = "Salah satu Four Angels di Lumo Knights. Dia tetap pesimis, yang sangat bertolak belakang dengan penampilannya yang temperamental...",
  str_item_intro_1600271 = "Kesatria Lumopolis dan salah satu dari Four Angels yang terkenal. Dia jujur dan jarang tersenyum. Dia diubah oleh Illumina setelah terluka parah, sehingga kehilangan sebagian emosinya.",
  str_item_intro_1600281 = "Salah satu Four Angels di Lumo Knights. Dia punya kekuatan penyembuh yang unik dan optimisme besar...",
  str_item_intro_1600291 = "Salah satu Four Angels di Lumo Knights. Dia pendiam, tenang, dan kalem sampai-sampai tak ada yang bisa mengganggunya.",
  str_item_intro_1600301 = "Pemimpin Rediesel Wrench yang blak-blakan, sangat dekat dengan anggotanya, dan sangat protektif terhadap adik perempuannya. Dia selalu memastikan kelangsungan hidup gengnya.",
  str_item_intro_1500311 = "Schumann",
  str_item_intro_1400321 = "Seorang staf Lumo Hall of Justice dan malaikat bersayap satu. Dia orang yang sensitif dan memiliki harga diri tinggi. Meskipun masih muda, Angel sebenarnya sudah ditempa oleh pertempuran selama bertahun-tahun.",
  str_item_intro_1500331 = "Masih sangat muda tapi berpengalaman di usianya. Pekerja keras dan antusias, dia adalah bakat pemula yang sangat dihargai oleh Illumina Federation.",
  str_item_intro_1500341 = "Sonnet",
  str_item_intro_1400351 = "Kurir gila kerja yang sering bepergian dan tak bisa tidur hingga semua tugasnya selesai.",
  str_item_intro_1500361 = "Pria yang suka menyendiri dari Umbraton. Pemberontak yang sangat membenci Lumopolis dan entah kenapa memusuhi para bangsawan.",
  str_item_intro_1600381 = "Pilot wanita dari mecha raksasa dan sekarang menjadi Tech Officer di Illumina Federation. Katanya dia akan menjadi pensiunan genius dari militer.",
  str_item_intro_1400401 = "Gadis kecil dari Rediesel Wrench, yang tertarik dengan ledakan, dan menjadi sangat bersemangat ketika sesuatu meledak.",
  str_item_intro_1400411 = "Pemandu bagi para pendatang di Lumopolis. Dia tetap tenang bahkan di tengah bencana, mengisyaratkan masa lalu yang luar biasa.",
  str_item_intro_1400441 = "Tegas, kaku, dan sebagai Chief of Staff Illumina Federation, dia mampu merencanakan dan mengatur segalanya hingga ke detail terkecil.",
  str_item_intro_1300461 = "Empat anak bertugas sebagai Broadcast Team Lumopolis... Sebagai anggota Academy's Choir, mereka benar-benar senang mengejek orang lain tanpa ampun daripada menjadi anak kecil yang tak bersalah seperti seharusnya...",
  str_item_intro_1300471 = "Peneliti jenius Illumina Federation. Kehausannya akan pengetahuan...dan seorang Legion Commander menarik seluruh perhatiannya.",
  str_item_intro_1400481 = "Sudah menjadi pemimpin para Spearow meskipun usianya masih muda, dia memerintah Umbraton dengan tekadnya yang tak tertandingi dan senjata licik yang kejam.",
  str_item_intro_1300491 = "Warrior tinggi dan kuat yang sering berkelana ke seluruh Umbraton dengan armor lengkap serta pedang besar. Pria yang tak banyak bicara, dia tidak pernah melepas helmnya dan lebih suka menyelesaikan masalah dengan kekerasan.",
  str_item_intro_1200501 = "Dia adalah hiu yang menakutkan bahkan saat tersenyum! Pelindung suatu pemukiman kecil. Meskipun penampilannya ganas dan menakutkan, sebenarnya dia sangat lembut.",
  str_item_intro_1300511 = "Pasangan Rediesel Wrench yang aneh ini adalah grenadier buaya yang pendiam dan sniper burung berisik serta sepasang tentara bayaran tepercaya.",
  str_item_intro_1300521 = "Kuris penyedia layanan pos Illumina Federation, benar-benar pemalas yang tak profesional. Dia bersedia melakukan apa saja untuk menunda atau meninggalkan pekerjaan...",
  str_item_intro_1300531 = "Pedagang dari Rediesel Wrench. Tipikal pedagang pengumpul uang, dia tidak pernah melewatkan peluang untuk meraih keuntungan.",
  str_item_intro_1300741 = "Petugas junior Illumina Legion. Dia antisosial dan tak cocok dengan teman sebayanya—katanya sifat dari garis keturunan misteriusnya...",
  str_item_intro_1300581 = "New Knight Lumopolis yang sungguh-sungguh dan bersemangat. Rentan terhadap stres berlebihan dari tekanan tanggung jawab berat yang diberikan sejak dini.",
  str_item_intro_1400161 = "Sniper Rediesel Wrench yang membawa super railgun kuat untuk memusnahkan semua musuh yang melawan.",
  str_item_intro_1400541 = "Kapten Lumo Nightwatch Recruit. Keren, tenang, fokus, dan dikagumi karena melakukan segala hal dengan serius.",
  str_item_intro_1400611 = "Peneliti Illumina Federation yang optimis dan ceria, dengan kemampuan khusus untuk menyerap emosi negatif orang lain dan menyembuhkan luka batin mereka.",
  str_item_intro_1400731 = "Anggota baru Istvan Guild di Umbraton. Mereka selalu hiperaktif, jadi berhati-hatilah!",
  str_item_intro_1500421 = "Legion commander di Illumina Federation. Penghasut perang yang tak tahan dengan masa damai yang monoton dan akan berusaha untuk menang dengan cara apa pun.",
  str_item_intro_1500761 = "Seorang pria yang sopan, santun, dan santai, tapi suka berbohong. Ternyata dia juga seorang seniman penipu terkenal di Umbraton.",
  str_item_intro_1500781 = "Anggota Spearow Umbraton. Pendiam dan jarang bergaul. Dia dan Dayna saling mengandalkan untuk bertahan hidup di Umbraton.",
  str_item_intro_1600771 = "Penguasa Northland dengan banyak pengalaman dan bijaksana. Bisa mengatasi apa pun dengan tenang tanpa keraguan.",
  str_item_intro_1300591 = "Anggota Courier Union yang bertanggung jawab atas korespondensi dengan True Order. Terlepas dari kekurangannya, semua orang menerimanya karena dia terus terang dan tak menyembunyikan apa pun.",
  str_item_intro_1300801 = "Peneliti Illumina Federation. Dia orang jenius yang fanatik dengan mesin dan model serta sulit bersosialisasi. Namun, dia bisa berbicara tanpa henti ketika membicarakan sesuatu yang sangat disukainya.",
  str_item_intro_1300821 = "Fae yang polos dan imut dari Northland Pine yang tak tahu apa-apa tentang dunia. Dia punya sepasang Gemstone Horn yang berharga dan selalu dilindunginya sejak kecil.",
  str_item_intro_1400451 = "Cadre member True Order dan pengikut Victoria. Dia pendiam dan sangat meyakini visi True Order. Tujuan hidupnya adalah menyebarkan visi True Order.",
  str_item_intro_1400571 = "Intel Chief Illumina Federation. Dia biasanya lembut, mudah didekati, dan sedikit malas, tetapi kepribadian alternatifnya cukup memberontak bahkan berbahaya.",
  str_item_intro_1400681 = "Anggota Courier Union yang bertanggung jawab atas area Rediesel Wrench. Dia percaya diri, imut, berani, dan berani menerima tantangan. Dia suka mengacau saat mengirim surat dan seorang penjahat kecil yang lucu.",
  str_item_intro_1400791 = "Lumo Tax Collector yang rasional, adil, dan mandiri. Dia punya kebiasaan mengubah nilai segala sesuatu menjadi emas sebagai perbandingan.",
  str_item_intro_1400811 = "Anggota Rediesel Wrench Loose Screws. Dia percaya diri, bersemangat, naif, dan tak mampu berbuat licik. Dia ingin menjadi nomor satu dalam segala hal.",
  str_item_intro_1400831 = "Anggota rombongan Lembaga Penelitian Ilmiah Illumina Federation. Dia berbicara seperti pelayan mekanik, tapi dia sebenarnya adalah Replicant dari suatu makhluk hidup yang kuat.",
  str_item_intro_1601231 = "Sheriff Illumina ini sering menahan diri untuk menumpahkan air mata, bahkan dalam keadaan darurat sekecil apa pun, dia tetap optimis dan bekerja keras dalam pekerjaannya atas nama keadilan.",
  str_item_intro_1601201 = "Seorang gadis bangsawan yang lahir dari keluarga kaya, dia cerdas dan gemar membaca sendirian di kamarnya. Teman satu-satunya adalah baju besi raksasa bernama Pompey yang dia kendalikan sendiri.",
  str_item_intro_1500151 = "Sebagai seorang pedagang seni Umbraton, Hachi tahu semua yang perlu diketahui tentang seni rupa, sementara Gin adalah pelukis dengan keterampilan yang tak tertandingi. Mereka berbagi ikatan yang tidak bisa dipisahkan dan bekerja sama sebagai tentara bayaran.",
  str_item_intro_1501321 = "Penduduk Pine Frost Valley di Northland. Mencintai semua hal yang ada madunya. Bunga sulur di tubuhnya tidak hanya cantik, tetapi juga memiliki kemampuan khusus.",
  str_item_intro_1601311 = "Seorang Northlander yang memiliki hubungan dekat dengan Betlehem. Ramah dan berpengalaman dalam sejarah. Ia percaya bahwa Northland adalah surga terakhir bagi Aurorian, dan ia ingin melindunginya dengan kekuatannya.",
  str_item_intro_1601331 = "Tohru adalah naga sangat kejam yang melawan dewa dalam pertarungan satu lawan satu dan hampir tewas. Setelah jatuh hati pada Kobayashi di dunia asing, Tohru memilih untuk tinggal bersamanya sebagai pelayannya.",
  str_item_intro_1601341 = "Seekor naga seperti Tohru, dengan penampilan dan kepribadian seperti anak-anak. Dia diusir dari rumahnya karena lelucon yang dia lakukan dan mengikuti Tohru sejak saat itu.",
  str_item_intro_1501351 = "Seekor naga yang berjuang untuk menyelesaikan konflik fana. Pernah disebut Witch of the Holy Sea. Dia jujur dan pekerja keras dan menyukai makanan enak dan tidak bisa menolak makanan manis.",
  str_item_intro_1501361 = "Dahulu kala, dia adalah dewa yang bertanggung jawab atas budaya dan peradaban kuno. Meskipun sangat kuat, dia juga sangat pemalas dan santai.",
  str_item_intro_1401371 = "Teman Tohru yang menjaga gua harta karun di dunia lain. Karena sudah melihat terlalu banyak orang serakah, dia menjadi sangat agresif dan sinis.",
  str_item_intro_1601381 = "Seorang peneliti dari Illumina Federation. Dia rasional dan sangat efisien di tempat kerja, tetapi malas dan santai secara pribadi. Karena terpesona oleh teknologi kuno, dia berkeliling Astra sepanjang tahun untuk menyelidiki segala jenis reruntuhan.",
  str_item_intro_1501391 = "Dia lahir di Lumopolis dan merupakan anggota OSIS di Dawn Academy. Dia mengikuti Florine ke mana pun dan memiliki ide-ide fantastis. Terkadang, dia mengejutkan orang dengan perkataannya.",
  str_item_intro_1601401 = "Lahir di Lumopolis, dia adalah ketua OSIS di Dawn Academy. Meskipun tampak dingin, sebenarnya hatinya hangat. Dia menjaga teman-temannya dengan baik dalam perjalanannya untuk menjadi seorang kesatria yang hebat.",
  str_item_intro_1601411 = "Ruby yang lahir di Rediesel Wrench selalu menyukai cerita petualangan saat masih kecil. Dengan sifatnya yang ceria dan bersemangat, dia memulai petualangannya sendiri tak lama setelah mempelajari cukup banyak pengetahuan dan keterampilan.",
  str_item_intro_1501421 = "Anggota Rediesel Wrench yang satu ini sangat bergantung pada Ruby. Meskipun mungkin terlihat kejam, kasar, dan suka mengkritik, dia adalah orang yang bijaksana dan berhati lembut.",
  str_item_intro_1601431 = "Penyihir Cloud Island yang berwawasan luas dan bijaksana. Ia dibesarkan oleh jenderal yang memerintah Cloud Island dan berharap dapat membantu orang banyak dengan kekuatannya.",
  str_item_intro_1501441 = "Seorang wanita bertubuh jangkung dari Cloud Island yang pernah diselamatkan Rinne. Dia mengaku bisa melihat \"sesuatu\" dan takut pada orang asing.",
  str_item_intro_1601451 = "Dia lahir di Cloud Island, lalu kehilangan rumahnya karena perang dan kemudian diselamatkan dan diajarkan ilmu Ninjutsu. Masa lalunya telah membuatnya terlihat dingin, tetapi jauh di lubuk hatinya, dia sangat setia kepada teman-temannya.",
  str_item_intro_1601461 = "Dia lahir di Cloud Island dan mempelajari \"Seni Bela Diri Tai Chi\" dari Lin Guild. Dia memiliki kemampuan tempur yang kuat, kepribadian yang hidup, dan senang berjuang untuk keadilan dalam perjalanannya.",
  str_item_intro_1501471 = "Terlahir di Cloud Island, si kembar sering terlihat menjual Ramen Kaniya dari gerobak mereka dan bisnisnya berkembang pesat. Mereka berharap menghasilkan uang sambil mengeksplorasi semua makanan lezat.",
  str_item_intro_1201631 = "Makhluk misterius dari utara yang menyukai permainan, dan setiap kali menemukan seseorang, ia akan selalu bertanya, \"Kamu punya ide?\".",
  str_item_intro_1601481 = "Anggota tim eksplorasi Rediesel Wrench yang berjiwa bebas dan selalu bekerja seorang diri dalam penyelidikan berbagai macam informasi yang bisa menguntungkan Rediesel Wrench. Dahulu, dia dianggap sebagai pembalap legendaris.",
  str_item_intro_1501491 = "Manajer logistik Rediesel Wrench. Meskipun dia tampak berantakan, sebenarnya dia sangat memedulikan dan protektif terhadap semua orang di Rediesel Wrench.",
  str_item_intro_1601501 = "Anggota True Order yang tak banyak bicara, tapi sangat cakap. Tampak tidak memiliki pemikiran sendiri maupun ambisi. Hidupnya hanya dihabiskan untuk menerima dan menyelesaikan perintah.",
  str_item_intro_1601511 = "Anggota True Order yang kerap bertingkah malas jika tidak diberi dorongan. Dia memegang teguh keyakinan bahwa dia diutus ke dunia ini untuk menyebarkan lagu anak-anak itu.",
  str_item_intro_1501521 = "Seorang gadis paranoid penyandang autisme yang berupaya keras menyenangkan sekumpulan orang dewasa di sekitarnya di True Order. Haus akan perhatian, dia tak pernah merasa kasih sayang yang diterimanya cukup baginya.",
  str_item_intro_1601551 = "Setelah menggunakan perangkat \"Chord Link\", meskipun penampilan dan kemampuan Legion Commander dari Illumina Federation telah berubah, kegemarannya akan berperang masih tak luput dari hatinya.",
  str_item_intro_1601541 = "Expedition Captain dari Illumina yang berkepribadian lembut. Bagai digariskan takdir, dia menyelamatkan keturunan Caelestite terakhir yang terperangkap di bawah tanah yang menjadi awal mula petualangan yang baru dan menarik.",
  str_item_intro_1601531 = "Seorang Grand Marshal sejati dari Illumina Federation. Tak hanya berjiwa kesatria dan mahir bertempur, dia juga merupakan sosok yang jujur dan pemimpin cakap yang sangat dihormati di seantero Illumina.",
  str_item_intro_1601561 = "Terlahir dari keluarga Lumo Noble di Umbraton. Meski tampak payah bersosialisasi, sebenarnya tak sulit mengakrabkan diri dengannya... Yah, kurang lebih begitu.",
  str_item_intro_1501571 = "Terlahir di Cloud Island, ia mengalami lika-liku kehidupan saat masih belia. Setelah merantau ke Astra demi kehidupan yang lebih baik, entah bagaimana ia tersandung utang yang menggunung. Ia hanya mengharapkan pekerjaan yang bertahan lama, itu saja.",
  str_item_intro_1601581 = [[
Seorang pemuda dari dunia lain dengan kekuatan khusus bernama Persona.
Tersembunyi di balik topeng, dia hanya dikenal dengan nama kode, dan mengeluarkan aura khusus.
Di dunianya, dia adalah pemimpin Phantom Thieves of Hearts yang sensasional.]],
  str_item_intro_1601591 = [[
Anggota Pencuri Phantom dari dunia lain.
Jenius taktik geng, dia merencanakan tindakan rekan-rekannya.
Mampu menggunakan kekuatan khusus Persona.]],
  str_item_intro_1501601 = [[
Anggota Pencuri Phantom dari dunia lain.
Dari wataknya yang eksentrik, pemuda ini sering kali terlihat tidak peduli dan acuh tak acuh.
Mampu menggunakan kekuatan khusus Persona.]],
  str_item_intro_1501611 = [[
Seorang gadis muda dari dunia yang sama dengan Pencuri Phantom.
Bekerja sementara dengan mereka karena berbagai alasan.
Mampu menggunakan kekuatan khusus Persona.]],
  str_item_intro_1501621 = [[
Makhluk misterius dari dunia lain. Terlihat seperti kucing tapi berbicara seperti manusia.
Ini memandu Pencuri Phantom di berbagai kesempatan.
Mampu menggunakan kekuatan khusus Persona.]],
  str_item_intro_1601641 = "Carleen de Schwartz. Dalam perjalanannya ke Harbour City, kekuatannya berubah, memberinya pemahaman yang lebih mendalam tentang kepemimpinan.",
  str_item_intro_1501651 = "Seorang insinyur jenius dari Illumina. Introvert, pemalu, tetapi ingin berkomunikasi dengan orang lain, mimpinya adalah menciptakan mekanisme dinamis yang kuat.",
  str_item_intro_1601661 = "Extrozoologist mungil yang penuh tekad dan keras kepala, tapi ternyata cengeng. Ia berusaha sekuat tenaga untuk menjadi extrozoologist yang lebih hebat dari Vic.",
  str_item_intro_1601671 = "Pemimpin sirkus The Illusionist & Old Bill's Circus, serta anggota True Order. Misterius, seram, dan pendiam, ambisinya adalah menjadi pesulap terhebat.",
  str_item_intro_1501681 = "Gadis kecil yang terpaksa meninggalkan kampung halamannya akibat serangan Eclipsite. Berhati bersih dan penuh semangat, ia bersedia menjalankan misi utamanya, yakni melindungi Emerald. Sering kali, ia tampil sebagai bintang tamu di sirkus untuk menghangatkan suasana.",
  str_item_intro_1501301 = "Seorang anggota keluarga Troy dari Lumopolis. Tapi mengapa tempat duduknya begitu rendah untuk seseorang yang terlahir begitu tinggi? Mungkin jawabannya terletak pada kepribadiannya.",
  str_item_intro_1501711 = "Terlihat menyendiri, tapi sebenarnya sangat bertanggung jawab. Bekerja sama dengan Pollux untuk membentuk duo tentara bayaran yang dijuluki \"Darah Raven\" untuk membela anak-anak yang tinggal di gereja dengan lebih baik.",
  str_item_intro_1601701 = "Mengesankan dan kompeten, dia memiliki masa lalu yang ingin dia tinggalkan. Sekarang menjadi penjaga setia sebuah gereja yang menaungi anak-anak tunawisma di Euforia yang tertindas.",
  str_item_intro_1401691 = "Seorang gadis muda yang sangat kuat yang berasal dari Umbraton. Di balik penampilan luarnya yang keren dan karismatik, terdapat hati yang murni dan teguh, dan dia menganggap setiap tugas yang diberikan kepadanya sebagai bagian dari pelatihannya untuk menjadi seorang jagoan sejati.",
  str_item_intro_1601721 = "Gadis yang manis, ceria, dan optimis. Untuk mengejar mimpinya bekerja di film, dia menetap di Alleywood Umbraton sendirian dan menemukan pekerjaan di industri film yang sedang booming. Meskipun dia telah melalui banyak kesulitan, dia tidak pernah mempertimbangkan untuk menyerah.",
  str_item_intro_1601731 = "Kepala pelayan keluarga Andersen di Umbraton. Anggun, sopan, dan perfeksionis untuk suatu kesalahan, dia telah bersumpah untuk membalas kebaikan tuannya dengan melayani dia dengan setiap ons kekuatan dan kesetiaannya.",
  str_item_intro_1601751 = "\"Combat Cyborg\" yang dikenal sebagai Axelia berafiliasi dengan Illumina Federation. Terlepas dari reputasinya, kondisi fisiknya mengkhawatirkan secara pribadi.",
  str_item_intro_1501761 = "Seorang petugas medis tempur Lumopolis yang pernah diselamatkan oleh seorang dokter bernama John; setelah itu, dia memutuskan untuk menjadi dokter yang baik.",
  str_item_intro_1601771 = "Lahir di Umbraton, idola muda terkenal ini diberkati dengan keberuntungan, menyebarkan optimisme dan kepositifannya kepada semua orang yang ditemuinya.",
  str_item_intro_1601781 = "Seorang ahli ekstrozoologi yang hidup mengasingkan diri di hutan. Meskipun dia sering membuat marah orang dengan kata-kata dan tindakannya dan menggertak muridnya Fia, dia baik kepada semua binatang buas yang menakjubkan.",
  str_item_intro_1501801 = "Meskipun saat ini dia hanya seorang reporter magang untuk sebuah agen surat kabar kecil, dia antusias mewawancarai siapa saja yang dia bisa dan memiliki telinga untuk semua gosip terbaru. Cita-citanya adalah menjadi jurnalis paling terkenal di Umbraton.",
  str_item_intro_1601811 = "Pernah menjadi Kepala Jenderal kerajaan Zhao di Longzhou, sekarang menjadi pengembara. Tidak peduli kapan atau di mana, dia tidak peduli apa pun selain tujuan pribadinya sendiri.",
  str_item_intro_1601821 = "Kapten Shadowind. Menyendiri, tegas, apa-yang-Anda-lihat-adalah-yang-Anda-dapatkan. Tujuannya adalah membangun kapal jarak jauh terhebat dan merintis rute pelayaran teraman.",
  str_item_intro_1501831 = "Seorang dokter muda yang belajar di bawah bimbingan dokter besar Bucunzi. Perawakannya kecil tapi ambisius, dia adalah seorang dokter handal dengan lidah yang tajam. Konon, satu pujian sudah cukup untuk membuatnya bangga.",
  str_item_intro_1601841 = "Seorang anggota senior divisi Rediesel Wrench Serikat Kurir. Dia santai dan tidak teratur, tetapi juga seorang pengamat yang sangat cerdik.",
  str_item_intro_1501851 = "Meskipun dia hanya pemula, dia juga salah satu dari sedikit orang yang teliti dan bertanggung jawab di Courier Union. Namun, kepatuhannya yang terlalu ketat terhadap aturan serikat terkadang menyebabkan kesalahan.",
  str_item_intro_1601861 = "Seorang gadis bangsawan yang mewarisi gelarnya, dan dia juga seorang hakim di Hall of Justice. Dia juga memiliki konstitusi khusus yang membuatnya tidur sepanjang waktu.",
  str_item_intro_1601891 = "Seorang hakim Lumopolis yang jujur yang membenci semua kejahatan, dan dia selalu memperlakukan orang lain dengan setara. Pada saat yang sama, dia memiliki sisi keras kepala dan menyendiri.",
  str_item_intro_1501901 = "Seorang hakim yang sangat berbakat dari Lumo Hall of Justice yang tidak memiliki banyak ambisi dan hanya ingin menjalani kehidupan biasa yang bahagia dan kaya.",
  str_item_intro_1601911 = "Seorang serigala dari Umbraton keturunan demi-human, yang sering berakhir dengan kesalahpahaman yang tidak perlu karena kurangnya kebijaksanaannya.",
  str_item_intro_1501931 = "Meskipun lahir dari keluarga bangsawan, dia selalu menempuh jalannya sendiri dan mengikuti kata hatinya untuk menjadi hakim percobaan di Lumopolis.",
  str_item_intro_1601921 = "Kapten Ironthorn Knights, dia memiliki kepribadian yang tegas dan bermartabat serta ramah. Dia berusaha mengubah Lumopolis yang membusuk menjadi hidup kembali.",
  str_item_intro_1601991 = "Dia dilahirkan dalam keluarga tentara Illumina dan sekarang menjadi perwira intelijen senior Komite. Banyak rencana tersembunyi jauh di dalam matanya.",
  str_item_intro_1502001 = "Petugas intelijen yang tenang dan andal dari Federasi Illumina yang sesekali membuat keluhan tak terduga. Tidak ada yang tahu apakah pengaduan tersebut dibuat secara sengaja atau tidak sengaja.",
  str_item_intro_1602011 = "Seorang kesatria Lumopolis yang hidup menyendiri di Umbraton, dia sebenarnya adalah putri sulung yang jarang disebutkan. Schwartz keluarga — seorang gadis murni dan baik hati yang merindukan pengakuan ayahnya.",
  str_item_intro_1602021 = "Di masa jayanya, Schwartz, menghunus pedang dan melakukan perang salib melawan Eclipsites, bukan hanya penguasa Lumopolis yang baru naik, dia juga seorang pejuang gagah berani yang bertempur di garis depan untuk menahan musuh peradaban.",
  str_item_intro_1502031 = "Utusan Utara Jakine pada dasarnya antusias dan bersemangat, tetapi ramalannya yang tidak terampil dan kepribadiannya yang ceroboh sering kali membuatnya dalam masalah yang tidak terduga.",
  str_item_intro_1602041 = "EveSemua orang mengatakan dia sangat mirip dengan istri almarhum Tuan Kota, tetapi sepertinya dia bukan dia juga. Joshua berharap untuk pergi ke lebih banyak tempat di dunia dengan cita-cita...",
  str_item_intro_1502051 = "Blanc, yang pensiun sebagai kapten Nightwatch Guard bertahun-tahun yang lalu, kembali mengenakan seragam tempurnya. Nona Rot telah kembali!",
  str_item_intro_1602061 = "Lahir dalam kemakmuran di Umbraton, dia bisa menjalani kehidupan yang bebas kekhawatiran dalam kenyamanan rumahnya. Namun, dia memilih untuk menjelajah dengan tekad yang tidak goyah untuk mewujudkan mimpinya.",
  str_item_intro_1602071 = "Manajer Denuo Valley Resort yang hidup dengan motto \"hidup di saat ini.\" Dia mungkin terlihat ringan di luar, tetapi mengejutkan, dia sangat dapat diandalkan dalam urusan bisnis.",
  str_item_intro_1502081 = "Dia bukan hanya navigator dari Lepidoz tetapi juga ahli strategi di balik Rediesel Wrench. Namun, di mata setiap orang, dia lebih tampak seperti maskot yang ceria daripada hal lainnya...",
  str_item_intro_1400861 = "Anggota Dawn Academy of Lumopolis dan Funeral MC. Dia orang yang positif dan berani, tapi lembut dan halus, serta menghadapi segala sesuatu dengan tenang dan tersenyum.",
  str_item_intro_1400911 = "Musisi Lumopolis yang lembut dan ramah serta mudah tenggelam dalam kenangan sedihnya. Dia kehilangan keluarganya karena perang, sehingga dia hidup dalam kesedihan dan merasa sulit melepaskannya.",
  str_item_intro_1500701 = "Pemberontak Umbraton yang punya Dragon Power. Dia orang yang sombong dan arogan, serta selalu murung. Dia selalu merasa bahwa nasib keluarganya ada di pundaknya.",
  str_item_intro_1500751 = "Pegawai teknisi Rediesel Wrench yang sangat percaya diri dengan teknologi komunikasinya. Dia suka mengeluh dan meneriaki orang lain di Comm Channel, tapi dia kebingungan saat ada masalah.",
  str_item_intro_1500841 = "Underground Leader Umbraton. Dia tegas, riang, dan sangat setia pada orang terdekatnya. Dia melewati serangkaian cobaan dan kesengsaraan, sehingga bisa memperoleh prestise serta statusnya saat ini.",
  str_item_intro_1500881 = "Anggota Rediesel Wrench yang biasanya bertanggung jawab atas pekerjaan pengintaian. Dia penakut, pemalu, dan canggung, tetapi tak bisa mengontrol kekuatan besarnya dalam pertempuran karena terlalu bersemangat. Maggie juga cukup tertekan dengan hal ini.",
  str_item_intro_1500901 = "Penyanyi idola Rediesel Wrench. Barbara tampak lembut dan baik di permukaan, tapi menunjukkan sikapnya yang mudah tersinggung saat bertemu penggemar yang terlalu mengganggu.",
  str_item_intro_1500921 = "Anggota True Order yang jujur dan tak fleksibel. Dia punya pikiran searah, sehingga akan terus fokus untuk mencapai tujuan apa pun yang telah ditetapkannya. Dia punya selera yang unik dan sering berdebat dengan orang lain.",
  str_item_intro_1600601 = "Jona yang pernah menjadi pemburu hadiah, adalah anggota Rediesel Wrench dan ahli penembak jitu. Dia sulit diatur dan cuek, tapi tak berbelas kasihan kepada para musuhnya. Tak ada yang pernah melihatnya tanpa borgol.",
  str_item_intro_1600641 = "Guard Legion Commander Illumina Federation yang ambisius dan membuat tantangan nyata bagi kepemimpinan Illumina Federation. Dia energik, bekerja keras tanpa lelah untuk memperoleh kekuatan yang lebih besar, dan punya keinginan yang kuat untuk memonopoli sesuatu.",
  str_item_intro_1600891 = "Lumo Hall of Justice Chief Judge. Dia baik, lembut, jujur dan tangguh, serta punya semangat pengabdian diri. Sisi paranoid ada dalam hatinya, tapi dia menekannya.",
  str_item_intro_1601031 = "Seorang interogator dari True Order dan pengikut setia Victoria, dengan murid-murid yang ditekan karena \"Power of Doom\" mereka.",
  str_item_intro_1500871 = "Salah satu bangsawan militan di Lumopolis, menikmati gengsi dan kekuasaan besar. Orang yang tradisional dan sangat bertanggung jawab, tapi agak arogan--meskipun dia perlahan membaik.",
  str_item_intro_1401011 = "Petugas Illumina yang bertanggung jawab atas komunikasi. Dia memperlakukan pekerjaannya dengan penuh ketekunan dan rasa hormat, meskipun sesekali dia memainkan lelucon.",
  str_item_intro_1401021 = "Sekutu para Spearow di Umbraton, dia adalah roh bebas yang dikenal dengan permen lolipopnya dan tembakan listrik dari tangannya.",
  str_item_intro_1500991 = "Pedagang pengembara di Umbraton. Lahir dengan kutukan yang membuatnya sakit anemia, dan harus memakai pedang ajaibnya untuk bertahan hidup.",
  str_item_intro_1501001 = "Anggota True Order. Lahir dalam keluarga bangsawan kuno, dia dipilih untuk menjaga makam rahasia di usia yang sangat muda. Terdidik dengan baik, dia orang yang pandai, tapi dingin.",
  str_item_intro_1600931 = "Petugas penelitian Illumina yang bertanggung jawab atas ilmu hayat. Dia tampak malas, tapi menunjukkan sisi yang tenang di saat penting.",
  str_item_intro_1500981 = "Tak punya emosi karena kutukan, tapi tampaknya akan memercayai orang pertama yang dilihatnya pada hari itu. Kini tinggal di pengasingan di Umbraton dan bekerja untuk Istvan sebagai assassin.",
  str_item_intro_1400621 = "Penjaga hutan dari Northland. Seorang pemuda tampan dengan sikap penyendiri, tapi berhati emas dan mendambakan persahabatan. Masih relatif muda, tampak agak kekanak-kanakan.",
  str_item_intro_1400951 = "Lahir dengan tubuh hewan, dia tentara bayaran yang mengembara dan mengoceh tentang segala hal.",
  str_item_intro_1300941 = "Petugas patroli yang polos, baik, dan naif dari Northland. Dulu dia berpatroli sendirian dalam hawa dingin, serta membawa musim semi dan harapan bagi banyak orang.",
  str_item_intro_1600961 = "Lahir di Illumina, dia mengembara ke Umbraton untuk mencari kakeknya. Dia agak linglung dan sering tertipu.",
  str_item_intro_1500971 = "Assassin di Umbraton yang melakukan tugas \"khusus\" untuk Istvan. Sebelum ini, dia adalah ahli bedah yang terampil.",
  str_item_intro_1500561 = "Pemburu Eclipsite yang menyendiri dan mengelilingi Astra dengan pikiran jernih. Dia membawa senapan berburu dan buku catatan ke mana pun dia pergi, siap untuk memburu para Eclipsite dan mencatat keberhasilannya dalam tulisan.",
  str_item_intro_1701071 = "Pahlawan kuno yang dibuang. Bertransformasi karena kebenciannya terhadap para Eclipsite. Pernah menjadi orang yang ganas, tapi sudah kembali tenang dan positif.",
  str_item_intro_1701081 = "Pahlawan kuno yang dibuang. Berubah dan memperoleh kekuatan yang besar, tapi membuat bencana karena tak mampu mengontrolnya. Dia masih tenggelam dalam rasa bersalah hingga saat ini.",
  str_item_intro_1701091 = "Pahlawan kuno yang dibuang. Kehilangan sebagian besar emosinya setelah berubah. Katanya ditinggalkan oleh negara yang dia layani setelah menyelesaikan sebuah misi.",
  str_item_intro_1701101 = "Pahlawan kuno yang dibuang. Melawan para Eclipsite di garis depan sejak kecil. Bawel dan keras kepala. Dia telah berubah, tapi masih polos.",
  str_item_intro_1501041 = "Kekuatan gelap membuatnya kehilangan penglihatan. Meskipun terlihat penyendiri dan pendiam di luar, sebenarnya dia orang yang suka berterus terang jika sudah mengenal seseorang.",
  str_item_intro_1601051 = "Adik perempuan Sinsa yang dipengaruhi Eclipsite dan kehilangan kendali saat kecil. Dia telah mendapatkan kembali kepolosannya setelah disembuhkan.",
  str_item_intro_1500711 = "Pemilik Odd Jobs yang berkelana dari Far East, yang akhirnya menetap di Umbraton. Seorang sekutu Istvan, dia nonkonformis angkuh yang melakukan sesuatu dengan efisiensi maksimal.",
  str_item_intro_1400671 = "Gadis muda Demi-human yang cantik dari Northland dengan rambut hitam dan putih. Naif, ceria, agak keras kepala, penuh rasa ingin tahu tentang lingkungannya. Kini berkeliling dunia dengan dua boneka sihir.",
  str_item_intro_1601111 = "Seorang anggota True Order yang bisa meengendalikan Crystal Domain yang kuat untuk menjebak musuhnya. Akan tetapi, kristal optimisnya juga sangat memengaruhi pikirannya, membuatnya jauh, pendiam, dan sering pesimistis.",
  str_item_intro_1601121 = "Seorang agen bebas yang tinggal di Umbraton dan memiliki kekuatan api nan dahsyat. Liar dan tidak suka basa-basi, dia gemar akan hal-hal yang baru dan menarik.",
  str_item_intro_1501131 = "Seorang musisi dan anggota True Order. Meskipun tampak hangat dan menggemaskan di luar, dia akan melakukan apa pun untuk mencapai tujuannya, yaitu menemukan gerakan pemungkas. Dia sangat percaya diri dengan pemahaman musiknya dan membenci praktik musik di Lumopolis.",
  str_item_intro_1501141 = "Meskipun tampak seperti Bounty Hunter biasa, sebenarnya dia adalah anggota True Order. Elegan dan selalu dalam suasana hati yang baik, dia sangat suka minum jus dan saat ini sedang mencoba membangun jaringan intelijen untuk True Order sambil mencoba melacak keberadaan seseorang.",
  str_item_intro_1601151 = "Anggota Courier Union yang bertugas secara khusus di wilayah Lumopolis. Selain tenang dan elegan, dia juga memiliki kekuatan misterius untuk berkomunikasi dengan hewan dan tumbuhan, dan diikuti oleh beberapa hewan serta kunang-kunang yang tak terhitung banyaknya ke mana pun dia pergi.",
  str_item_intro_1601161 = "Seorang teknisi dari Rediesel Wrench yang tenang dan tidak bisa menolak—sifat kepribadian yang sering membuatnya berada dalam berbagai kesulitan yang menyebalkan. Selain ahli dalam memperbaiki segala jenis mesin, dia juga berusaha untuk membangun Mecha-nya sendiri.",
  str_item_intro_1401271 = "Awalnya seorang penghuni di Rediesel Desert, dia kemudian bergabung dengan True Order. Di antara kemampuannya adalah mengendalikan sobekan kertas magis untuk menyerang dalam pertempuran. Walau biasanya terlihat cukup penakut, keyakinannya akan keberadaan jiwa dapat dianggap fanatik yang berlebihan.",
  str_item_intro_1601191 = "Seorang anggota baru di Illumina. Meskipun genius dalam pertempuran, dia suka menyendiri, impulsif, dan komunikator yang buruk. Dia sangat ingin meraih kemenangan dalam pertempuran dan membuktikan dirinya.",
  str_item_intro_1601221 = "Seorang penembak jitu bayaran dari Umbraton dengan keahlian menembak yang patut dicontoh. Cermat dan sadar akan anggaran, dia adalah kolektor barang antik yang bersemangat dan ingin membuka toko barang antiknya setelah mendapatkan cukup dana.",
  str_item_intro_1601171 = "Seorang veteran yang pernah aktif di garis pertahanan Illumina, yang kini telah pensiun dari medan perang dan melayani federasi sebagai petugas logistik. Dia mungkin sedikit kasar di pinggiran, tetapi penampilan luarnya yang kasar menyembunyikan hati yang mulia dan sentimental. Salah satu kawan paling andal yang bisa kamu harapkan. Mereka mengatakan bahwa dia tenggelam dalam depresi karena masa lalunya yang berdarah. Sekarang, dia muncul dari kegelapan kekalahan, bahkan lebih kuat dari sebelumnya.",
  str_item_intro_1601211 = "Seorang anggota True Order yang memberontak, rasional, dan tidak menerima omong kosong dari siapa pun. Meskipun awalnya merupakan seorang biarawati dari Lumopolis Temple, dia pergi setelah ketidakadilan yang tragis mengubah hidupnya dan membuatnya menyadari kemunafikan yang lazim di Lumopolis. Sejak saat itu, dia telah mengabdikan dirinya untuk mengungkap wajah asli kota tersebut.",
  str_item_intro_1300651 = "Anggota Courier Union yang bertanggung jawab atas pengiriman ke Northland. Meskipun agak canggung, penampilan dan aksennya yang unik membuat sosok yang energetik ini terlihat imut dan polos.",
  str_item_intro_1500551 = "Seorang hakim dari Lumo Hall of Justice. Dia agak kaku, pragmatis, dan tegas dalam keyakinannya. Sekarang, atas nama keadilan, dia menggali lebih dalam kasus-kasus masa lalu untuk mengungkap kebenaran yang tersembunyi.",
  str_item_intro_1601261 = "Ketua dari Financial Guild Umbraton dan putri angkat Istvan. Dia adalah wakilnya yang paling tepercaya. Dengan sikapnya yang serius dan tabah, dia memberi pengaruh secara profesional setiap waktu.",
  str_item_intro_1601291 = "Deputy Commander pasukan tentara bayaran Umbraton, dan seorang pria terhormat yang tahu segala seluk-beluk kota. Sekarang dia bekerja keras untuk memperluas pasukan tentara bayarannya.",
  str_item_intro_1602371 = "Konon dia adalah keturunan dari klan Mirage, dia memiliki kesulitan dalam mempertahankan ingatan, namun tetap optimis dan baik hati. Sebagai rasa terima kasih karena telah diterima oleh Harbour City, dia berkomitmen untuk membantu orang lain.",
  str_item_intro_1602381 = "Mithra, yang lahir dalam klan Longinus, menjalankan tugas berabad-abad untuk melindungi rahasia bintang-bintang. Meskipun penampilannya yang tenang dan bulu hitamnya, dia menyembunyikan sisi tajam di bawah sifatnya yang pendiam.",
  str_item_intro_1702361 = "Claymore adalah tangan kanan raja dan kapten dari Pemburu Silent. Dia menjunjung tinggi keadilan dengan kehendak yang tidak goyah. Bahkan tanpa keberuntungan Lumina, dia membentuk masa depan dengan Star Power.",
  str_item_get_discovery = "{0}",
