  str_item_get_cloudgardensitem25 = "Dapatkan dalam percakapan rahasia yang dibuat secara acak ketika Aurorian hidup relatif nyaman di Cloud Gardens.",
  str_item_get_cloudgardensitem26 = "Dapatkan dalam percakapan rahasia yang dibuat secara acak ketika Aurorian hidup dengan sangat nyaman di Cloud Gardens.",
  str_item_get_cloudgardensitem27 = "Dapatkan dalam percakapan rahasia yang dibuat secara acak ketika Aurorian hidup cukup nyaman di Cloud Gardens.",
  str_item_get_cloudgardensitem28 = "Diperoleh dari event Symphony: The Obelisk's Shackles.",
  str_item_get_cloudgardensitem29 = "Diperoleh dari event \"Trees, Fish and A Slow Life\"",
  str_item_get_cloudgardensitem30 = "Diperoleh dari acara Heist Under a Moonlit Night",
  str_item_get_cloudgardensitem31 = "Diperoleh setelah mengumpulkan sejumlah Koin Wish.",
  str_item_get_cloudgardensitem32 = "Dibuat di Hyacinth Tower setelah mendapatkan cetak biru dari hadiah level Cloud Gardens.",
