  str_item_5234040 = "\"Festival Makanan Rediesel\"",
  str_item_5234041 = "\"Ke Rumah Hantu\"",
  str_item_5234042 = "\"Keagungan Illumina!\"",
  str_item_5234031 = "Thorny Beast Statue",
  str_item_5234032 = "Three-Horned Beast Statue",
  str_item_5241014 = "Colorful Hot Air Balloon",
  str_item_5232007 = "Floating Shell Seat",
  str_item_5234035 = "Monument of Lines",
  str_item_5222001 = "Low Shrub Fence",
  str_item_5222002 = "High Shrub Fence",
  str_item_intro_5212001 = "“Sekarang setelah aku menenggelamkan kapal ini, kamu yang selanjutnya pergi! Argh! Kenapa kamu meluncur ke bawah tentakelku? Baiklah, aku akan melepaskanmu kali ini karena kamu terlihat seperti sedang bersenang-senang! \"\nSeharusnya, slide ini dimodelkan setelah tentakel monster laut. Menyenangkan, bukan?",
  str_item_intro_5212002 = "Aku ingin tahu siapa yang memindahkan tiang kapal ke sini. Either way, Anda akan dapat melihat sangat jauh ke kejauhan jika Anda memanjatnya. Anda bahkan dapat berteriak: \"Cap'n! Land ahoy!\" seolah-olah Anda sedang berlayar di laut.",
  str_item_intro_5212003 = "Tenda ringan yang berdiri kokoh di atas pasir pantai yang lembut. Bahkan terbuat dari bahan tahan api, mungkin karena turis suka menyalakan api di tenda untuk bersenang-senang.",
  str_item_intro_5212004 = "Ayunan yang cukup lebar untuk diayunkan oleh dua orang ini sangat bagus untuk bermain di pantai. Anda akan memiliki kenangan indah tentang angin laut yang lembut membelai wajah Anda saat Anda duduk di atasnya.",
  str_item_intro_5212005 = "Kursi berjemur ini terbuat dari setengah perahu yang ditinggalkan. Sepertinya ciptaan aneh beberapa pelaut.",
  str_item_intro_5212006 = "Sebuah penunjuk arah menuju pantai. Anda dapat menggambar berbagai pola di atasnya atau meninggalkan pesan di atasnya, dan banyak bendera warna-warni dapat diikat ke stand untuk menarik perhatian wisatawan.",
  str_item_intro_5212007 = "Dengan semangat mendaur ulang, beberapa pelaut membongkar setengah perahu dan menggunakan papannya untuk membuat meja dan kursi. Lunas digunakan untuk membuat bingkai pohon anggur yang unik untuk memberikan keteduhan dari matahari.",
  str_item_intro_5212008 = "Payung yang agak berat yang sulit dibawa kemana-mana. Ujung gagangnya runcing sehingga bisa ditusukkan ke tanah dan diamankan dengan kuat di sana.",
  str_item_intro_5212009 = "Kursi ini dirancang untuk memeluk tubuh, sehingga sangat nyaman untuk berbaring dengan banyak ruang untuk meregangkan tangan dan kaki Anda dengan memuaskan.",
  str_item_intro_5212010 = "Meja yang ringan dan praktis sehingga wisatawan dapat bergerak bebas sehingga mereka dapat dengan mudah menemukan tempat yang bagus di pantai untuk bersenang-senang bersama teman-teman mereka.",
  str_item_intro_5212011 = "Kursi ini akan berguna ketika Anda perlu istirahat dari semua permainan Anda! Duduk di atasnya dan minum untuk memulihkan energi Anda dengan cepat.",
  str_item_intro_5212012 = "Hah? Bukankah pilar batu ini dari bawah laut? Dan karang? Kapan ini dibawa ke darat? Setelah diperiksa lebih dekat, orang dapat melihat bahwa ini sebenarnya adalah pagar kayu yang dicat dengan terampil. Itu indah dan memancarkan suasana laut yang indah.",
  str_item_intro_5212013 = "Pasir halus yang diaspal di area ini menciptakan suasana tepi laut yang kuat yang membuatnya seolah-olah Anda sedang berada di pantai.",
  str_item_intro_5241018 = "Ada batu mini dan tanaman air dalam wadah raksasa ini, serta perangkat yang menjaga sirkulasi air, menciptakan lingkungan di mana ikan dapat berenang dengan aman.",
  str_item_intro_5241019 = "Saat melihat ornamen karang warna-warni di atas dasar batunya, Anda hampir merasa seperti berada di lautan dan dapat melihat kawanan ikan berenang di...",
  str_item_intro_5241020 = "Salah satu reruntuhan kuno yang misterius. Dikatakan menyerap Lumina di sekitarnya dan memancarkan cahaya yang tidak berbahaya, yang menjadikannya pilihan ideal untuk dekorasi, penerangan, atau pengiriman sinyal ke kejauhan.",
  str_item_intro_5212014 = "Apa cangkang besar! Itu terlihat sangat besar sehingga tampaknya tidak terjadi secara alami. Jika ada mutiara di dalamnya, itu pasti akan menjadi harta yang langka. Ini mungkin cangkang, tetapi dilengkapi dengan bantalan di bagian dalam, menjadikannya sofa yang indah.",
  str_item_intro_5212015 = "Saat balon berbentuk ubur-ubur ini melayang ke langit, pita-pitanya yang terkulai menjadi \"tentakel\"-nya, membuatnya tampak seperti ubur-ubur sungguhan yang mengambang di langit.",
  str_item_intro_5212016 = "Jangan biarkan penampilannya membuat Anda takut! Itu hanya ingin menerangi jalan untukmu. Melihat? Tidak ada gigi di dalam mulutnya.",
  str_item_intro_5212027 = "Bangku tinggi yang melengkapi meja yang lebih panjang dengan sempurna. Ketinggian yang dapat disesuaikan dan kursi putar membuatnya menjadi favorit banyak anak.",
  str_item_intro_5212028 = "Pot hijau yang sangat diperlukan yang melengkapi dekorasi meriah lainnya.",
  str_item_intro_5212029 = "Barisan pagar yang dicat khusus yang digunakan untuk partisi selama festival. Jangan ragu untuk meletakkan dekorasi lain di atasnya!",
  str_item_intro_5212030 = "Sebuah pembibitan khusus didirikan untuk Festival Windelion, dengan dandelion dewasa yang menunggu untuk dilepaskan pada malam perayaan.",
  str_item_intro_5212031 = "Strukturnya mungkin sederhana dan dibangun dengan kayu biasa, tetapi tahan lama karena bagian yang diperkuat. Selain digunakan untuk lampu gantung, juga dapat berfungsi sebagai tempat berteduh sementara bagi hewan-hewan kecil.",
  str_item_intro_5212032 = "Sejajarkan kolom rendah yang meriah ini, dan Anda mendapatkan pagar.",
  str_item_intro_5234034 = "Eksterior batu tampak agak kasar, tetapi interiornya sangat rumit, dengan ruang yang besar. Cukup buka tutupnya untuk mendaur ulang sampah di dalamnya dengan mudah.",
  str_item_intro_5212020 = "Sempurna untuk pinggir jalan. Orang yang lewat dapat menempatkan barang-barang kecil di atasnya atau memodifikasinya sesuai keinginan mereka dan mengubahnya menjadi tengara.",
  str_item_intro_5212021 = "Kelihatannya besar, tapi terbuat dari kayu dan bagian dalamnya berlubang. Sangat ringan dan dapat dipindahkan dengan cepat antar lokasi, sebagian besar digunakan sebagai dekorasi liburan sekunder.",
  str_item_intro_5212022 = "Tiang kayu sederhana dengan interior yang tampaknya diperkuat untuk banyak hewan kecil hinggap. Mungkin baik untuk orang lain untuk bersandar juga, mungkin...",
  str_item_intro_5212023 = "Ringan, dengan bentuk khusus untuk menangani beberapa lentera sekaligus. Digunakan untuk penerangan atau sebagai bagian pernyataan dalam festival.",
  str_item_intro_5212024 = "Terdiri dari tiang kayu dan kain putih yang dihias dengan berbagai tanaman merambat, daun hijau, dan bunga. Banyak digunakan di berbagai festival. Ini membawa keberuntungan jika tirai menyapu Anda, atau jika angin sepoi-sepoi meniup kelopak atau daun ke bahu Anda.",
  str_item_intro_5212025 = "Tidak diketahui siapa yang membangun sarang pertama untuk festival tersebut, tapi itu menarik banyak binatang kecil. Ini kemudian menjadi tradisi informal bagi orang-orang di festival-festival berikutnya. Desas-desus mengatakan bahwa semakin banyak hewan kecil yang ditarik, semakin banyak berkah yang akan diterima pembangunnya.",
  str_item_intro_5212026 = "Meja ini agak berat karena terbuat dari kayu solid dengan penyangga batu, seharusnya untuk mencegahnya runtuh sebaiknya dipilih untuk menari di atasnya.",
  str_item_intro_5234021 = "Itu dapat ditempatkan tidak hanya di ruangan tetapi juga di kabinet di pinggiran kota. Kayunya cukup kuat untuk menahan sinar matahari dan hujan. Biasanya berfungsi sebagai penyimpanan sementara untuk objek yang saat ini tidak digunakan.",
  str_item_intro_5212018 = "Boneka Windelion warna-warni yang menjuntai populer di kalangan anak-anak selama Festival Windelion. Berisi confetti yang tumpah setelah dibuka. Lonceng atau \"koin keberuntungan\" terkadang dimasukkan ke dalam untuk menarik lebih banyak anak.",
  str_item_intro_5212019 = "Sebuah drum raksasa yang cukup besar untuk memungkinkan orang menari di atasnya. Permukaannya tipis, tetapi cukup kuat untuk tidak pecah jika Anda melompat di atasnya! Karena konstruksinya yang khusus, suaranya dapat terdengar dari jarak yang sangat jauh. Drum juga cukup sensitif untuk merespon perubahan cara orang menginjaknya dan menghasilkan suara yang berbeda.",
  str_item_intro_5241021 = "Binatang bersisik tidak umum, dan Pangalo yang legendaris bahkan lebih langka! Cepat dan ambil foto! Anda bisa berpura-pura menjadi salah satu dari mereka sendiri!",
  str_item_intro_1601881 = "Lahir sebagai putri Kerajaan Ye, Dantang kini dijadikan sandera di Kerajaan Ji. Namun, ia tetap menjaga sikap tenang saat menekuni pelajaran, dengan diam-diam menunggu kesempatan untuk kembali ke tanah airnya.",
  str_item_intro_5212017 = "Tujuan khusus dari patung batu ini tidak diketahui, tetapi dikatakan sebagai peninggalan dari zaman kuno. Banyak Caelestites akan datang untuk meminta berkah dan membuat harapan selama Festival Windelion. Dikatakan bahwa lilin akan mendengarkan dan menyampaikan keinginan ke patung sehingga dapat membantu dengan kekuatan misteriusnya.",
  str_item_intro_5271001 = "Kolam renang besar yang menempati ruang besar dan memiliki kapasitas besar. Semakin banyak, semakin meriah.",
  str_item_intro_5272001 = "Sebuah bilik kecil dengan fasilitas shower, biasa ditemukan di kolam renang. Ini digunakan untuk membersihkan tubuh dan, yang lebih penting, mengganti pakaian.",
  str_item_intro_5272002 = "Berenang sangat melelahkan, jadi sebaiknya istirahatlah jika terlalu lelah. Mengapa tidak mengalami sukacita ilahi mendapatkan es krim dari mesin es krim otomatis yang menakjubkan ini?",
  str_item_intro_5272003 = "Musik itu penting! Sangat mudah untuk bosan bermain air, jadi datanglah ke sini untuk bersantai dan menari mengikuti beberapa lagu!",
  str_item_intro_5272004 = "Sofa tiup ini sangat nyaman untuk dibaringkan. Itu menjadi perahu kecil ketika ditempatkan di dalam air, dan menjadikannya pilihan yang sangat baik untuk bersantai dan tetap mengapung.",
  str_item_intro_5272005 = "Karena digelembungkan, kursi ini sangat ringan. Itu dapat dibawa kemana-mana dan bahkan ditempatkan di ransel Anda setelah kempis, di mana hampir tidak ada ruang.",
  str_item_intro_5272006 = "Ini adalah berkah bagi semua orang yang tidak bisa berenang! Bahkan pemilik tanah bisa mengapung di atas air dan mencoba berenang dengan ini.",
  str_item_intro_5272007 = "Mainan yang berfungsi baik di luar kolam maupun di dalam kolam. Ketika itu sepenuhnya meningkat, dapat diperlakukan sebagai bola melenting. Tapi yang paling penting adalah tidak tenggelam di air!",
  str_item_intro_5272008 = "Berenang adalah latihan yang sangat melelahkan, jadi berbaringlah di sana untuk memulihkan kekuatan Anda jika perlu. Bantal berbentuk ikan ini sangat nyaman dan memiliki getaran pantai yang kuat.",
  str_item_intro_5272009 = "Payung ini agak besar dan tidak nyaman untuk dibawa-bawa, tetapi tidak diragukan lagi layak untuk memilikinya karena payung ini menciptakan naungan berharga yang melindungi Anda dari sinar matahari langsung saat cuaca panas.",
  str_item_intro_5272010 = "Sebuah dekorasi yang dihiasi dengan berbagai kerang dari laut. Jika ditempatkan di tempat yang tepat, akan membuat seseorang merasa seperti sedang berada di pantai.",
  str_item_intro_5272011 = "Bintang laut sangat populer sehingga hanya beberapa ornamen ini saja sudah cukup untuk menarik perhatian banyak orang.",
  str_item_intro_5272012 = "Papan pajangan yang konon menggunakan teknologi kuno untuk menampilkan berbagai gambar secara otomatis! Tampaknya juga ada perangkat misterius yang dapat digunakan untuk mengubah konten yang ditampilkan di dalamnya. Itu pasti digunakan untuk sesuatu yang penting...",
  str_item_intro_5271002 = "Dirancang oleh Caelestite tertentu yang mencintai lautan. Ada patung-patung serasi yang konon membawa berkah lautan! Jika Anda ingin bepergian melalui laut, datanglah ke sini sebentar. Mungkin itu akan membantu!",
  str_item_intro_5272013 = "Melihatnya di lautan berarti perjalanan Anda akan melimpah! Tapi apakah makhluk ini benar-benar ada? Atau apakah itu hanya fantasi seorang pelaut? Bagaimanapun, setidaknya patung ini indah dan akan menarik perhatian para pemuda.",
  str_item_intro_5272014 = "Di laut, beberapa gurita yang hilang naik ke kapal secara tidak sengaja dan tidak dapat kembali ke perairan. Ketika para pelaut yang baik hati melepaskannya, mereka sering kembali beberapa hari kemudian untuk memberi mereka hadiah kecil, seperti mutiara kecil atau koin yang hilang di laut. Patung ini melambangkan persahabatan dan memberi.",
  str_item_intro_5272015 = "Banyak orang mengatakan bahwa melihat lumba-lumba melompat saat berlayar berarti pelayaran Anda akan aman. Saya bertanya-tanya apakah mereka memberkati mereka yang melakukan perjalanan di darat?",
  str_item_intro_5271003 = "Dengan alat peraga, peralatan, dan sudut kamera yang tepat, visi artistik sutradara bahkan dari tempat yang paling luar biasa pun bisa menjadi kenyataan. Dari ruang bawah tanah yang berbahaya hingga negeri ajaib yang aneh, kisah-kisah terbesar diwujudkan di depan latar belakang yang dibuat dengan sangat baik.",
  str_item_intro_5273001 = "Meskipun hanya sebagai latar belakang, namun tetap mencerminkan kemegahan istana kerajaan yang mewah saat diabadikan dalam film. Sempurna untuk syuting drama periode yang berlangsung di pengadilan penguasa.",
  str_item_intro_5273002 = "Sepintas, itu tampak seperti lantai batu yang dibuat dengan ahli, tetapi pada kenyataannya, itu tidak lebih dari selembar kertas! Sebagai \"lantai\" gaya penyangga, itu dapat dimatikan dengan relatif cepat.",
  str_item_intro_5273003 = "Meski menjadi penyangga, \"cermin ajaib\" ini sebenarnya cukup berat (mengingat terbuat dari besi). Secara alami, pelapisan emas dan batu permata itu palsu, tetapi cermin memang memiliki satu sifat khusus: permukaannya tidak memantulkan apa pun! Tapi bagaimana ini bisa terjadi? Mungkin itu benar-benar cermin ajaib!",
  str_item_intro_5273004 = "Sebuah prop sederhana, dan tidak lebih. Lagi pula, kita tidak bisa mengangkut pohon secercah nyata dari Northland; ini hanya penyangga yang terbuat dari kayu, kertas, dan pita dan tidak boleh diberikan kepada penduduk Northlanders.",
  str_item_intro_5273005 = "Gantungan kayu keras di nama saja, sebenarnya terbuat dari kayu lapis murah. Pengganti yang dapat diterima, mengingat jarang menyimpan pakaian dalam bentuk apa pun.",
  str_item_intro_5273006 = "Sosok tanah liat tertutup lapisan pasir putih bersih. Sepintas, terlihat seperti manusia salju sungguhan, hanya yang satu ini yang mempertahankan bentuknya di bawah panasnya lampu panggung.",
  str_item_intro_5273007 = "Penyangga kayu berkualitas tinggi yang dibuat oleh pengrajin terampil. Itu terlihat tidak berbeda dari patung batu asli. Konstruksinya yang ringan juga membuatnya mudah untuk bergerak di sekitar set.",
  str_item_intro_5273008 = "Boneka mainan tua tapi asli yang telah dicuci dan dikeringkan. Meskipun beberapa bagiannya tampak cukup tua dan usang, dari sudut tertentu, orang masih bisa mengatakan itu terlihat agak baru.",
  str_item_intro_5273009 = "I-Ini mengapung! Itu benar-benar mengapung! Apakah ini benar-benar hanya penyangga, atau sesuatu yang lebih menakutkan? Lagi pula, bagaimana ia berhasil mengapung tidak jelas, tetapi apakah sebuah film benar-benar membutuhkan sesuatu yang begitu menakutkan?",
  str_item_intro_5273010 = "Meskipun itu hanya latar belakang yang menempel di dinding, itu masih berhasil memenuhi orang dengan rasa takut. Mungkinkah gaya lukisan yang sangat realistis, atau kabin di latar belakang yang menakutkan? Bagaimanapun, mungkin aktor yang tampil di depannya tidak hanya berakting saat berteriak.",
  str_item_intro_5273011 = "Sebuah penyangga lantai yang digunakan bersama dengan latar belakang kabin berhantu. Tampaknya mengeluarkan bau apek dari papan lantai yang busuk saat dibuka. Sempurna untuk banyak film horor.",
  str_item_intro_5273012 = "Replika grimoire kuno yang sengaja didesain agar terlihat tua, lengkap dengan teks tertulis dan semuanya! Untuk mempertahankan suasana realisme, setiap halaman berisi teks yang sama persis dengan aslinya dalam format yang sama persis; bahkan sampulnya adalah salinan karbon satu sama lain! Mereka terlihat seperti bagian dari satu set. Namun, isinya tetap menjadi misteri.",
  str_item_intro_5273013 = "Sebuah prop dirancang untuk mengapung di udara. Mungkin itu rumah balon agar tetap mengudara? Itu diikat ke lantai dengan kawat untuk mencegahnya hanyut.",
  str_item_intro_5273014 = "Mainan yang sedikit digunakan dan tidak diubah yang digunakan sebagai penyangga di berbagai film. Biasanya akan memberikan kegembiraan dan hiburan bagi anak-anak, tetapi ketika digunakan dalam film horor... memiliki efek sebaliknya.",
  str_item_intro_5273015 = "Dari batu nisan hingga gundukan tanah tempat ia duduk, semuanya seluruhnya terbuat dari kayu dan kertas. Ringan dan portabel, dapat diproduksi dalam jumlah besar dengan sangat cepat dan menambahkan getaran suram dan angker ke adegan apa pun.",
  str_item_intro_5273016 = "Pemancar suara prop, biasanya terbuat dari kayu atau logam, sama sekali tidak berguna untuk berkomunikasi melalui. Saat Anda menonton film horor dan melihat adegan dengan pemancar suara, biasanya aktor yang memerankan karakter di kedua ujung perangkat itu sendiri! Yang pasti melelahkan.",
  str_item_intro_5273017 = "Bagian topeng hantu dari jubah itu sempurna untuk film horor, tapi topinya... Sepertinya sesuatu yang akan dipakai orang di gurun. Mungkin prop ini mencoba untuk berkembang menjadi peran yang berbeda juga?",
  str_item_intro_5273018 = "Pot dan tanah itu nyata, tetapi bunganya tidak; mereka dibuat menggunakan kain yang diwarnai. Murah dan mudah dibuat, \"tanaman\" yang semarak ini tidak akan pernah layu.",
  str_item_intro_5273019 = "Ketika diatur dengan benar, seseorang hampir dapat mencium aroma anggur yang baik atau mendengar dentingan gelas di atas musik lembut. Siapa yang tahu berapa banyak adegan terkenal yang difilmkan di \"bar\" seperti ini?",
  str_item_intro_5273020 = "Papan lantai kayu tampak jauh lebih tua dari yang sebenarnya, dan lubang hanya menambah efeknya. Tampilannya yang lusuh sebenarnya cukup cocok untuk pengaturan bar.",
  str_item_intro_5273021 = "Mungkin salah satu alat peraga paling mahal (mengingat itu sepenuhnya nyata). Ini menghasilkan musik yang indah ketika sebuah rekaman ditempatkan di atasnya. Karena harganya yang mahal, penulis skenario sering kali diminta untuk menghindari penulisan adegan yang merusak pemutar rekaman dengan cara apa pun. Ini sedikit membatasi kreativitas, tetapi setidaknya dapat digunakan untuk sinkronisasi bibir jika seorang aktor memiliki suara nyanyian yang buruk! Itu dua burung dengan satu batu!",
  str_item_intro_5273022 = "Sebuah bar counter terbuat dari kayu lapis. Kokoh dan andal, tetapi tidak pernah bisa dibandingkan dengan meja kayu solid di bar asli. Kursi, bagaimanapun, dibeli dari bar sungguhan! Dan dengan satu atau dua lapis cat baru, mereka terlihat bagus seperti baru!",
  str_item_intro_5273023 = "Meja dan kursi menonjolkan suasana bar. Dari desain mereka hingga perhiasan mereka, siapa pun akan setuju bahwa mereka termasuk dalam bar. Hanya dengan melihat alat peraga ini akan memberi tahu aktor bahwa adegan yang akan datang terjadi di sebuah bar, semua tanpa ada perintah dari sutradara.",
  str_item_intro_5273024 = "Rupanya beberapa sutradara meminjam furnitur seperti ini untuk memfilmkan adegan tertentu yang tidak biasa. Meskipun ini akan sangat normal untuk set kantor, apakah ini benar-benar cocok untuk set bar? Ini hampir seperti dipinjam dari studio lain karena kekurangan dana...",
  str_item_intro_5273025 = "Piano asli terlalu berat, dan seringkali jauh di luar anggaran studio, jadi sebaiknya lakukan dengan prop yang meyakinkan! Selain itu, mengingat tingkat keterampilan aktor terbaru saat ini, ada sedikit kebutuhan untuk memberi mereka piano yang sebenarnya...",
  str_item_intro_5273026 = "Panggung kayu yang dibangun dengan tergesa-gesa. Meskipun tidak sekokoh panggung nyata, pembangunannya membutuhkan sedikit usaha, dan dapat direkonstruksi dengan cepat jika rusak.",
  str_item_intro_5273027 = "Rak bilah kayu ini nyata, tetapi bilah di atasnya... tidak lebih dari alat peraga. Menggunakannya harus cukup aman, mengingat mereka tidak memiliki tepi yang tajam; dengan demikian, mereka dapat digunakan dalam adegan perkelahian tanpa menyebabkan cedera serius pada aktor yang terlibat.",
  str_item_intro_5273028 = [[
Di ruangan yang dipenuhi sinar matahari, meja dan kursi tertata rapi, dan Anda hampir bisa mencium aroma kapur.
Kursi dekat jendela di baris kedua hingga terakhir ini harus disiapkan untuk Anda.]],
  str_item_intro_5273029 = "Lantai kayu yang sangat umum yang telah diperlakukan secara khusus agar lebih tahan lama. Silakan ganti sepatu dalam ruangan sebelum berjalan di atasnya.",
  str_item_intro_5273030 = "Mesin memasak yang tampak aneh juga merupakan mesin gashapon. Sulit untuk mengatakan apa yang ada di dalamnya sampai Anda membuka barang yang jatuh dari dalamnya.",
  str_item_intro_5273031 = "Alat memasak misterius yang lebih sehat daripada menggoreng. Bahkan mereka yang belum pernah memasak pun bisa menggunakannya dengan mudah.",
  str_item_intro_5273032 = [[
Gelembung terus naik di dalamnya, dan itu perlu terus diaduk sepanjang waktu untuk mengintegrasikan bahan-bahan di dalamnya sepenuhnya.
Siapa yang tidak senang jika seorang gadis cantik melakukan pekerjaan ini?]],
  str_item_intro_5273033 = "Sebuah tong berisi cairan misterius yang memancarkan bau samar yang tidak menyenangkan.",
  str_item_intro_5273034 = "Sebuah mesin yang bekerja siang dan malam untuk mensuplai makanan dan minuman, penyelamat semua orang yang malas.",
  str_item_intro_5273035 = "Dibutuhkan banyak keterampilan untuk memainkan alat musik ini, tetapi alat musik ini terus mengeluarkan suara di malam hari meskipun tidak ada orang di sana.",
  str_item_intro_5273036 = "Ini hanya penyangga. Jangan memakannya!",
  str_item_intro_5273037 = "Sebuah penginapan yang penuh dengan kehidupan, kebisingan, dan segala macam orang. Tidak ada yang tahu siapa yang ada di sana atau apa yang akan terjadi di sana.",
  str_item_intro_5273038 = "Lantai kayu yang berderit saat diinjak.",
  str_item_intro_5273039 = "Konter tempat mesin kasir ditempatkan di penginapan. Bos selalu duduk di sini, jadi kamu bisa datang dan mengobrol dengan bos jika merasa kesepian.",
  str_item_intro_5273040 = "Piring porselen yang sangat indah. Terlihat bahwa bos memiliki selera dekorasi yang bagus.",
  str_item_intro_5273041 = "Ornamen yang aneh. Mungkin salah satu tamu memberikannya ke penginapan.",
  str_item_intro_5273042 = "Dilihat dari ukuran spesimen yang terbuat dari tulang ikan ini, ikan ini pasti sangat perkasa ketika masih hidup.",
  str_item_intro_5273043 = "Sepotong furnitur kayu yang dibuat dengan kasar. Perabotan selalu menjadi yang pertama menderita ketika ada tamu dengan temperamen buruk, jadi jangan membeli sesuatu yang terlalu mahal.",
  str_item_intro_5273044 = "Meja dan kursi familiar yang membuat Anda merasa seperti berada di rumah sendiri.",
  str_item_intro_5273045 = "Furnitur ini terlihat sangat hangat dan nyaman. Pasti terasa sangat menyenangkan berbaring di dalam ini sepanjang hari di musim dingin.",
  str_item_intro_5273046 = "Anggur yang diseduh oleh bos mengeluarkan aroma yang kuat saat tutupnya dibuka. Mereka yang menghirupnya sering jatuh ke dalam trans dan mulai menangisi hal-hal yang mereka sesali dalam hidup mereka.",
  str_item_intro_5273047 = "Suvenir dari suatu tempat yang memberi kesan eksotis pada toko. Mungkin sebagian orang akan bertanya-tanya apakah ada kisah kenangan antara bos lama dan cawan dari negeri lain ini.",
  str_item_intro_5273049 = "Burung gagak terus-menerus mengoceh dalam gemerisik angin dan lingkungan yang muram. Prajurit heroik yang berjalan sendirian di sini ditakdirkan untuk memulai perjalanan berbahaya.",
  str_item_intro_5273050 = "Ada banyak tempat tanpa nama seperti ini di masa-masa sulit. Saat menyelinap ke sini, cobalah untuk tidak mematahkan dahan yang layu di bawah kaki Anda atau meninggalkan jejak diri Anda sendiri.",
  str_item_intro_5273051 = "Ini terlihat seperti lemari biasa tidak peduli bagaimana kau melihatnya, tapi pedang berharga akan segera keluar begitu mekanismenya dipicu. Harap operasikan ini di bawah pengawasan seorang ahli.",
  str_item_intro_5273052 = "Lembar dekoratif dengan pola buluh di atasnya. Jika ini digunakan untuk mendekorasi satu set, orang akan terdorong untuk menunggang kuda dengan bebas di dalamnya.",
  str_item_intro_5273053 = "Lembar dekoratif yang menciptakan gambar ladang gandum. Jika ini digunakan untuk menghias satu set, apakah seorang samurai akan menyergap orang di dalamnya?",
  str_item_intro_5273054 = "Seprai dekoratif yang memiliki pola bunga matahari di atasnya. Jika ini digunakan untuk mendekorasi sebuah set, mungkin itu bahkan akan menarik sinar matahari ke sana.",
  str_item_intro_5273055 = "Pemutar video asal misterius yang memiliki kain yang tampak kuno di bawahnya. Tampaknya itu akan menampilkan beberapa informasi kunci jika kaset video dimasukkan ke dalamnya.",
  str_item_intro_5273056 = "Peta asal misterius. Sepertinya peta militer yang digunakan selama masa perang, dan sepertinya berisi beberapa informasi penting.",
  str_item_intro_5273057 = "Kotak surat asal misterius. Tidak ada yang tahu sudah berapa lama di sini. Jika Anda melihat lebih dekat pada goresan di kotak surat, Anda mungkin melihat beberapa informasi penting yang ditinggalkan oleh orang-orang di masa lalu.",
  str_item_intro_5234040 = "Penjual cerdik Rediesel Wrench, Jomu, bahkan memasang iklan di sini, di semua tempat. Mereka tampaknya mengundang semua orang untuk berpartisipasi dalam sesuatu yang disebut \"Festival Makanan Rediesel\", dan mengklaim bahwa ada banyak penawaran hebat yang dapat dimanfaatkan. Walaupun di tengah gurun... Semoga makanannya nggak terlalu eksotik ya?",
  str_item_intro_5234041 = "Rupanya \"Film Debut Menakjubkan oleh Produser/Sutradara/Aktris/Operator Kamera Termuda dan Tercantik dalam Sejarah.\" Itu seharusnya lucu dan mengerikan, yang bisa disimpulkan dari papan reklame. Bagaimana hasilnya di box office? Kita hanya harus menunggu dan melihat!",
  str_item_intro_5234042 = "Sebuah iklan rekrutmen untuk Federasi Illumina. Itu memancarkan kemewahan Illumina. \"Garis pertahanan terkuat dan terakhir. Berdiri bersama kami dalam perjuangan kami melawan momok Eclipsite!\" ia mengatakan. Banyak orang pasti terdorong untuk bertindak oleh seruan perang yang penuh gairah ini.",
  str_item_intro_5234031 = "Seekor binatang yang memiliki duri di kepalanya dan tampaknya sangat mudah tersinggung. Untungnya, itu hanya sebuah patung.",
  str_item_intro_5234032 = "Kelihatannya sangat lembut meskipun memiliki tanduk yang panjang... Entah kenapa, itu membuatmu ingin mengelusnya.",
  str_item_intro_5241014 = "Apa yang terjadi disini? Bagaimana itu bisa begitu membengkak? Meski begitu, ia tetap bisa terbang dan memungkinkan penggunanya merasakan sensasi melayang di angkasa.",
  str_item_intro_5232007 = "Teknologi kursi batu ini bekerja dengan cara yang misterius. Itu mengapung setelah Anda duduk di atasnya, dan bahkan menyeimbangkan dirinya sendiri. Jangan takut, cobalah!",
  str_item_intro_5234035 = "Ukiran yang berulang-ulang dan metodis pada monumen kuno ini membentuk pola-pola indah yang dikatakan mewakili semacam prinsip matematika, tetapi detail pastinya tidak diketahui.",
  str_item_intro_5222001 = "Semak yang mudah tumbuh yang telah tumbuh bersama membentuk dinding rendah. Ini melayani tujuan dekoratif dan juga dapat digunakan sebagai partisi.",
  str_item_intro_5222002 = "Dinding yang terbentuk dari semak-semak tinggi yang ditanam rapat. Biasanya digunakan sebagai dinding luar di halaman. Konon banyak semak tinggi yang ditanam bersama di beberapa tempat membentuk labirin tanaman.",
  str_item_condition_103 = "Buka kunci setelah eksplorasi utama Undercity",
