  str_item_3661026 = "Liburan Turki Panggang",
  str_item_intro_3661026 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Liburan adalah untuk berpesta! Kalkun panggang ini layak menjadi bintang hari ini baik dari segi penampilan maupun rasa. Apa yang kamu tunggu?]],
  str_item_3661181 = "Jam Raksasa",
  str_item_intro_3661181 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Jam dinding ini awalnya berbentuk burung hantu, tetapi seorang pedagang tertentu mengubahnya menjadi Colossus karena dianggap terlalu biasa. Kelihatannya sangat bagus, tapi sayangnya sayapnya tidak bergerak.]],
  str_item_3661182 = "Ksatria Sendok Logam",
  str_item_intro_3661182 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Ambil ini! Serangan sendok! Metal Spoon Knight terkenal rakus. Perutnya sangat besar bahkan baju zirahnya harus dibuat khusus! Lihatlah air liur yang menetes dari mulutnya. Apakah itu mengarahkan pandangannya pada makanan seseorang?]],
  str_item_3661027 = "Spanduk Penggemar Goldie",
  str_item_intro_3661027 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Ayo berikan segalanya untuk Goldie! Biarkan musiknya menyebar ke setiap sudut benua!]],
  str_item_3000289 = "EXP Penguasaan Bakat",
  str_item_3000290 = "Poin Penguasaan Bakat",
  str_item_3661183 = "Stan DJ",
  str_item_intro_3661183 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Gerai DJ dengan sistem speaker built-in, menampilkan serangkaian tombol yang memungkinkan operatornya mengeluarkan suara yang hampir tak terbatas. Dengan ritme yang terus berubah, hanya dibutuhkan satu DJ untuk mengobarkan suasana pesta dan membenamkan penonton dalam musik yang memukau.]],
  str_item_3661184 = "Poster Gadis Impian",
  str_item_intro_3661184 = "Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.\nIkuti mimpimu! Anda juga bisa seperti dia—seorang gadis yang memimpin panggung, menyebarkan cinta dan harapan ke seluruh benua! Jangan pernah menyerah pada impianmu!",
  str_item_3661185 = "Patung Anjing Tur",
  str_item_intro_3661185 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Selalu berdiri di garis depan tren terbaru Umbraton! Bahkan sebagai patung, Tourdog menampilkan estetika visionernya setiap saat. Rumor mengatakan bahwa sosok ini sangat populer di kalangan pengikutnya, jadi pastikan mereka tidak menyentuhnya!]],
  str_item_3661186 = "Mega Blaster",
  str_item_intro_3661186 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Dikatakan bahwa hanya yang paling berani yang berani memainkan alat musik yang kuat ini, karena suara yang dihasilkannya cukup kuat untuk mengalahkan konstitusi lemah individu yang lemah. Meskipun membuat keributan yang mengerikan, itu sempurna untuk orang banyak yang memukau di konser yang penuh sesak.]],
