  str_item_5259513 = "Armor Berserker",
  str_item_5259514 = "Patung Dewi Perang",
  str_item_intro_5259301 = "Meningkatkan Kerusakan Kombo Rantai saat menghubungkan 15 ubin atau lebih.",
  str_item_intro_5259302 = "Saat menghitung kerusakan, sekutu mengabaikan efek negatif dari serangan balik elemen mereka.",
  str_item_intro_5259303 = "Segera memberikan damage tambahan saat menimbulkan Poisoned/Burning/Bleeding pada musuh.",
  str_item_intro_5259304 = "Meningkatkan Max HP sekutu secara permanen.",
  str_item_intro_5259305 = "Setiap kali HP turun di bawah 50%, item pemulihan HP akan dibuat di lapangan.",
  str_item_intro_5259306 = "Memulihkan HP di awal setiap gelombang.",
  str_item_intro_5259307 = "Memberikan perisai di awal setiap gelombang.",
  str_item_intro_5259308 = "Memberikan kerusakan tinggi pada musuh non-bos di sekitar Anda setiap putaran.",
  str_item_intro_5259309 = "Mengurangi cooldown dari Special Caelestite Gear sebesar 1.",
  str_item_intro_5259310 = "Semua sekutu dan musuh kehilangan sebagian dari HP mereka setiap putaran.",
  str_item_intro_5259311 = "Memberikan Gear Caelestite Spesial tambahan secara acak.",
  str_item_intro_5259401 = "Meningkatkan kerusakan yang diterima musuh yang di-debug.",
  str_item_intro_5259402 = "Mengonversi persentase penyembuhan berlebih Aurorian menjadi perisai.",
  str_item_intro_5259403 = [[
Meracuni semua sekutu dan musuh di area saat musuh mati.
Mengurangi kerusakan Poison yang diambil oleh sekutu.]],
  str_item_intro_5259404 = "Meningkatkan damage Chain Combo saat terkena debuff.",
  str_item_intro_5259405 = "Memiliki peluang yang sangat rendah untuk langsung membunuh musuh non-bos.",
  str_item_intro_5259406 = "Mengembalikan HP sekutu saat Skill Aktif membunuh musuh.",
  str_item_intro_5259407 = "Meningkatkan semua kerusakan sekutu saat HP Maks.",
  str_item_intro_5259408 = [[
Memulihkan HP sekutu saat kerusakan Poison musuh terpicu.
Mengurangi kemungkinan sekutu terkena Racun.]],
  str_item_intro_5259409 = "Memantulkan kembali kerusakan pada musuh saat mereka memberikan kerusakan pada sekutu.",
  str_item_intro_5259410 = "Meningkatkan damage sekutu saat setidaknya ada 3 Aurorian dengan elemen utama berbeda di dalam tim.",
  str_item_intro_5259411 = "Elemen sekunder Aurorian menangani kerusakan tanpa pengurangan kerusakan.",
  str_item_intro_5259412 = [[
Kapten mengubah peluang +5.
Mengurangi cooldown Skill Aktif dari Aurorian yang menjadi Kapten pertama kali di ronde ini sebesar 1.]],
  str_item_intro_5259501 = "Kapten melepaskan Kombo Rantai tambahan di awal baris.",
  str_item_intro_5259502 = "Menghasilkan efek ledakan setiap 5 serangan normal.",
  str_item_intro_5259503 = "Menghasilkan sejumlah kecil ubin berwarna dalam 1 cluster di sekitarnya setiap putaran.",
  str_item_intro_5259504 = "Langsung mengalahkan musuh dengan HP di bawah 10%.",
  str_item_intro_5259505 = "Mempercepat cooldown Skill Aktif saat berdiri diam.",
  str_item_intro_5259506 = "Mengubah DEF semua sekutu Aurorian menjadi ATK.",
  str_item_intro_5259507 = "Ubin pertama dalam satu baris bisa menjadi warna yang berbeda dari ubin berikutnya. Dua elemen berbeda ini sama-sama akan memicu Aurorian untuk bertindak.",
  str_item_intro_5259508 = "Memperlakukan ubin Hijau sebagai ubin berwarna.",
  str_item_intro_5259509 = "Memperlakukan ubin Biru sebagai ubin berwarna.",
  str_item_intro_5259510 = "Memperlakukan ubin Merah sebagai ubin berwarna.",
  str_item_intro_5259511 = "Memperlakukan ubin Kuning sebagai ubin berwarna.",
  str_item_intro_5259512 = "Sangat meningkatkan kerusakan sekutu, tetapi setiap koneksi menghasilkan ubin yang rusak.",
  str_item_intro_5259513 = "Meningkatkan kerusakan Kombo Rantai saat HP sekutu berkurang.",
  str_item_intro_5259514 = [[
Kapten mengubah peluang +5.
Aurorian yang telah menjadi Kapten ronde ini akan menyerang dengan elemen utama mereka terlepas dari warna koneksinya.]],
  str_item_rpintro_5259301 = "Meningkatkan kerusakan Kombo Rantai sebesar 30% saat sekutu menghubungkan 15 petak atau lebih.",
  str_item_rpintro_5259302 = "Saat menangani kerusakan, sekutu mengabaikan efek pengurangan kerusakan karena elemen mereka dilawan. Saat menerima kerusakan, sekutu mengabaikan bonus karena elemen mereka dilawan.",
  str_item_rpintro_5259303 = "Saat memberikan Poisoned/Burning/Bleeding pada musuh, target langsung kehilangan HP sebesar 50% dari serangan mereka. Dapat dipicu sekali per putaran pada setiap target.",
  str_item_rpintro_5259304 = "Meningkatkan Max HP Aurorian dalam tim sebesar 100% tanpa mengubah HP saat ini.",
  str_item_rpintro_5259305 = "Saat HP sekutu turun di bawah 50%, Perban, yang memulihkan 20% dari Max HP saat sekutu melewatinya, akan dibuat di tempat acak di lapangan.",
  str_item_rpintro_5259306 = "Memulihkan 20% dari Max HP di awal setiap gelombang.",
  str_item_rpintro_5259307 = "Memberikan perisai setara dengan 40% dari Max HP yang berlangsung selama 1 putaran di awal setiap gelombang.",
  str_item_rpintro_5259308 = "Memberikan damage setara dengan 50% dari Max HP ke semua musuh non-bos dalam 1 cluster sekitar di awal setiap gelombang.",
  str_item_rpintro_5259309 = "Mengurangi cooldown dari Special Caelestite Gear sebanyak 1 di pertempuran berikutnya.",
  str_item_rpintro_5259310 = "Semua sekutu dan musuh (termasuk bos) kehilangan 7% dari HP mereka saat ini di awal setiap putaran.",
  str_item_rpintro_5259311 = "Memberikan Perlengkapan Caelestite Spesial acak yang belum Anda miliki. Ini dapat digunakan dalam pertempuran selanjutnya, dan cooldownnya dihitung secara terpisah.",
  str_item_rpintro_5259401 = "Semua damage yang diterima oleh musuh yang terkena debuff atau efek debuff meningkat sebesar 20%.",
  str_item_rpintro_5259402 = "Mengubah 100% penyembuhan berlebih Aurorian menjadi perisai yang bertahan selama 1 putaran.",
  str_item_rpintro_5259403 = "Menimbulkan 1 tumpukan Racun pada semua sekutu dan musuh di lapangan setiap kali musuh mati. Sekutu menerima -50% kerusakan Poison.",
  str_item_rpintro_5259404 = "Meningkatkan kerusakan Kombo Rantai sebesar 30% saat tim Anda terkena debuff.",
  str_item_rpintro_5259405 = "Musuh non-bos memiliki peluang 3% untuk mati seketika saat menerima damage.",
  str_item_rpintro_5259406 = "Sekutu memulihkan HP setara dengan 15% dari Max HP pengguna setiap kali musuh terbunuh oleh Skill Aktif.",
  str_item_rpintro_5259407 = "Meningkatkan semua kerusakan yang diberikan sebesar 20% saat tim Anda berada di Max HP.",
  str_item_rpintro_5259408 = "Setiap kali musuh menerima kerusakan Poison, sekutu memulihkan HP setara dengan 100% dari kerusakan Poison ini. Sekutu menerima -50% kerusakan Poison.",
  str_item_rpintro_5259409 = "Mencerminkan 100% kerusakan yang diambil kembali pada musuh saat mereka memberikan kerusakan pada sekutu.",
  str_item_rpintro_5259410 = "Meningkatkan semua kerusakan yang diberikan oleh sekutu sebesar 25% ketika setidaknya ada 3 Aurorian dengan elemen utama yang berbeda di tim Anda.",
  str_item_rpintro_5259411 = "Elemen sekunder Aurorian menangani kerusakan dengan pengganda yang sama dengan elemen utamanya.",
  str_item_rpintro_5259412 = [[
Kapten mengubah peluang +5 saat mendapatkan item ini.
Saat mengganti Kapten, cooldown Skill Aktif Kapten baru berkurang 1. Setiap Aurorian hanya dapat memicu efek ini sekali setiap putaran.]],
  str_item_rpintro_5259501 = "Menghasilkan gambar Kapten Aurorian di titik awal. Gambar ini juga mengeluarkan Chain Combo di babak ini.",
  str_item_rpintro_5259502 = "Menghasilkan ledakan yang menyerang musuh saat kombo serangan normal adalah kelipatan 5.",
  str_item_rpintro_5259503 = "Mengonversi 3 ubin dalam 1 cluster di sekitarnya menjadi ubin berwarna di awal setiap putaran.",
  str_item_rpintro_5259504 = "Musuh yang memiliki sisa HP kurang dari 10% akan langsung kalah.",
  str_item_rpintro_5259505 = "Mengurangi cooldown semua Skill Aktif Aurorian yang sedang cooldown sebanyak 1 jika tidak ada koneksi yang dibuat di ronde ini.",
  str_item_rpintro_5259506 = "Mengurangi DEF semua Aurorian di tim Anda menjadi 0 dan meningkatkan ATK Anda dengan jumlah total DEF yang dikurangi.",
  str_item_rpintro_5259507 = "Ubin pertama dalam satu baris bisa menjadi warna yang berbeda dari ubin berikutnya. Dua elemen berbeda ini sama-sama akan memicu Aurorian untuk bertindak.",
  str_item_rpintro_5259508 = "Saat menghubungkan warna lain, ubin Hijau juga bisa dihubungkan.",
  str_item_rpintro_5259509 = "Saat menghubungkan warna lain, ubin Biru juga bisa dihubungkan.",
  str_item_rpintro_5259510 = "Saat menghubungkan warna lain, ubin Merah juga bisa dihubungkan.",
  str_item_rpintro_5259511 = "Saat menghubungkan warna lain, ubin Kuning juga bisa dihubungkan.",
  str_item_rpintro_5259512 = "Meningkatkan semua kerusakan yang diberikan oleh sekutu sebesar 25%, tetapi titik awal dari setiap koneksi akan menjadi ubin rusak yang tidak dapat dipindahkan selama 5 putaran.",
  str_item_rpintro_5259513 = "Meningkatkan kerusakan Chain Combo hingga 80% sesuai dengan persentase HP yang hilang oleh sekutu.",
  str_item_rpintro_5259514 = [[
Kapten mengubah peluang +5.
Aurorian yang telah menjadi Kapten ronde ini akan menyerang dengan elemen utama mereka terlepas dari warna koneksinya.]],
  str_item_intro_9994027 = "Meningkatkan semua kerusakan yang diberikan oleh sekutu sebesar 25% ketika setidaknya ada 3 Aurorian dengan elemen utama yang berbeda di tim Anda.",
  str_item_intro_9994028 = "Elemen sekunder Aurorian menangani kerusakan tanpa pengurangan kerusakan.",
  str_item_intro_9994029 = [[
Kapten mengubah peluang +3.
Mengurangi cooldown Skill Aktif dari Aurorian yang menjadi Kapten pertama kali di ronde ini sebesar 1.]],
  str_item_intro_9995019 = "Mengurangi cooldown Skill Aktif sebanyak 1 dengan 2 ketukan sambil berdiri diam.",
  str_item_intro_9995020 = "Mengurangi DEF semua Aurorian di tim Anda menjadi 50% dan meningkatkan ATK dengan mengurangi jumlah DEF.",
  str_item_intro_9995021 = "Meningkatkan kerusakan Chain Combo hingga 80% sesuai dengan persentase HP yang hilang oleh sekutu.",
  str_item_intro_9995022 = [[
Kapten mengubah peluang +3.
Aurorian yang telah menjadi Kapten ronde ini akan menyerang dengan elemen utama mereka terlepas dari warna koneksinya.]],
  str_item_rpintro_9994027 = "Senjata yang sepertinya bisa menyatu dengan Lumina dengan sempurna... Ini memang langka...",
  str_item_rpintro_9994028 = "Dikatakan bahwa seorang pejuang kuno tertentu dikalahkan dalam pertempuran karena dia tidak dapat menggunakan kekuatan penuh dari tangannya yang tidak dominan. Setelah kekalahan, dia membuat sarung tangan khusus ini. Benar saja, dia tak terkalahkan dalam pertempuran yang akan datang.",
  str_item_rpintro_9994029 = "Tangan terhubung ke hatimu. Oleh karena itu, dapat dikatakan bahwa dua orang yang bergandengan tangan memiliki hubungan spiritual satu sama lain dan tidak akan pernah terpisah satu sama lain.",
  str_item_rpintro_9995019 = "Kekuatan luar biasa dalam peninggalan kuno ini memungkinkan pemakainya untuk mengeluarkan semua jenis Luminatics yang kuat lebih cepat, memberikan penggunanya kemampuan untuk menghadapi berbagai situasi berbahaya.",
  str_item_rpintro_9995020 = "Seperti kata pepatah lama, \"dia yang hidup dengan pedang akan mati oleh pedang.\" Meskipun ini memungkinkan untuk mengalahkan musuh yang sangat kuat, premisnya adalah Anda bertarung dengan berani tanpa memperhatikan keselamatan Anda sendiri...",
  str_item_rpintro_9995021 = "Menurut beberapa cerita yang disampaikan dari mulut ke mulut, baju zirah ini memiliki kekuatan yang besar dan menakutkan, menjadikannya harta bagi sebagian orang dan kutukan bagi yang lain.",
  str_item_rpintro_9995022 = "Ada yang mengatakan bahwa patung ini tidak menggambarkan dewa melainkan prajurit wanita legendaris yang dapat memberikan dukungan dalam pertempuran.",
  str_item_3661187 = "Simpul Berkat Longzhou",
  str_item_intro_3661187 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Tali yang telah dijalin dengan terampil menjadi simpul persegi, bukti kreativitas penenun. Diduga dari Longzhou, di mana orang menggantungnya di rumah mereka untuk melindungi keluarga mereka dari bahaya.]],
  str_item_3661188 = "Lentera Gantung Tinggi",
  str_item_intro_3661188 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Rak lentera dari Longzhou dengan struktur kayu yang unik, tempat menggantung lentera merah. Tampaknya memiliki kekuatan untuk menempatkan orang di dunia lain dalam sekejap.]],
  str_item_3661028 = "Ornamen Berbintang",
  str_item_intro_3661028 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Bintang dan elemen galaksi dirangkai pada sebuah string. Seseorang dapat mengagumi sekilas alam semesta saat menyala. Itu dapat ditempatkan di dinding atau digantung di pohon di luar ruangan untuk menciptakan ilusi langit berbintang di hari mendung.]],
  str_item_3010001 = "Suar Bintang (Terbatas)",
  str_item_intro_3010001 = "Perangkat yang mengirimkan sinyal perekrutan untuk menarik perhatian Aurorian dan memanggil mereka untuk menjadi mitra Anda. Ini adalah item waktu terbatas. Ini akan hilang setelah kedaluwarsa. Silakan gunakan tepat waktu. Waktu Kedaluwarsa: 04:00 pada 9 Februari 2023 (UTC +0), 23:00 pada 8 Februari 2023 (UTC -5).",
