Ini adalah item waktu terbatas. Ini akan hilang setelah kedaluwarsa. Silakan gunakan tepat waktu. Waktu Kedaluwarsa: 04:00 pada 16 Oktober 2024 (UTC +0), 23:00 pada 15 Oktober 2024 (UTC -5).]],
  str_item_intro_3010028 = [[
Perangkat yang mengirimkan sinyal perekrutan untuk menarik perhatian Aurorian dan memanggil mereka untuk menjadi mitra Anda.
Ini adalah item waktu terbatas. Ini akan hilang setelah kedaluwarsa. Silakan gunakan tepat waktu. Waktu Kedaluwarsa: 04:00 pada 16 Oktober 2024 (UTC +0), 23:00 pada 15 Oktober 2024 (UTC -5).]],
  str_item_intro_3020028 = [[
Perangkat yang mengirimkan sinyal gambar khusus untuk menarik perhatian Aurorian tertentu.
Ini adalah item waktu terbatas. Ini akan hilang setelah kedaluwarsa. Silakan gunakan tepat waktu. Waktu Kedaluwarsa: 04:00 pada 16 Oktober 2024 (UTC +0), 23:00 pada 15 Oktober 2024 (UTC -5).]],
  str_item_intro_3030028 = [[
Kotak kristal persegi dengan pusat bercahaya yang memasok lebih banyak energi ke Prism.
Gunakan untuk mendapatkan 60 Prism.
Ini adalah item waktu terbatas. Ini akan hilang setelah kedaluwarsa. Silakan gunakan tepat waktu. Waktu Kedaluwarsa: 04:00 pada 16 Oktober 2024 (UTC +0), 23:00 pada 15 Oktober 2024 (UTC -5).]],
  str_item_3000301 = "Paket Bahan",
  str_item_intro_3000301 = [[
Paket berisi berbagai bahan yang menumpuk.
Dapat digunakan untuk membuat makanan.]],
  str_item_3000302 = "Bulu Langka",
  str_item_intro_3000302 = "Bulu burung misterius yang tidak dikenal. Karena warnanya yang cerah, mereka dihargai oleh beberapa anggota Serikat Kurir. Mungkin Anda bisa menukarnya dengan sesuatu.",
  str_item_3661189 = "Mawar Lilin",
  str_item_intro_3661189 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Semoga bunga tidak pernah layu dan cahaya lilin tidak pernah padam, agar keindahan momen ini tetap ada di hatimu selamanya.]],
  str_item_3661190 = "Kotak Surat Pengakuan",
  str_item_intro_3661190 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Takut untuk menumpahkan rahasia hatimu? Apakah ada rahasia di dalam jiwa Anda? Jika demikian, kotak surat ini untuk Anda. Itu sabar, aman, dan dapat diandalkan, menjadikannya orang kepercayaan yang sangat baik.]],
  str_item_3661191 = "Boneka Mahkota Bulan",
  str_item_intro_3661191 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Siapa yang bisa menolak beruang yang begitu imut, terutama yang memiliki hati cinta! Jika seseorang memberi Anda hadiah ini, jelas bagaimana perasaan mereka terhadap Anda.]],
  str_item_3661192 = "Buket Mooncrown",
  str_item_intro_3661192 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Bunga merah dan putih adalah simbol cinta yang penuh gairah dan hati yang murni. Saat Anda memberikan karangan bunga ini kepada kekasih Anda, inilah saatnya untuk mengucapkan tiga kata kecil itu.]],
  str_item_3661029 = "Kursi Empuk Hati",
  str_item_intro_3661029 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Kursi empuk yang luas dan nyaman cocok untuk pasangan bersantai bersama. Jika Anda tidak memiliki siapa pun untuk duduk, tidak apa-apa juga. Perasaan terbungkus bantal empuk yang besar juga bisa membuat Anda merasa tidak sendirian...]],
  str_item_3661193 = "Sayap Putih Murni",
  str_item_intro_3661193 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Seperti yang dikatakan bahwa malaikat adalah penjaga cinta, beberapa menggantungkan sayap putih ini di dinding dengan harapan mereka akan segera menemukan cinta sejati mereka.]],
  str_item_3661194 = "Menara Kue Angsa",
  str_item_intro_3661194 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Kue yang dihias dengan angsa yang sangat indah. Ini lebih terlihat seperti karya seni daripada makanan... Apakah Anda yakin ingin memakannya?]],
  str_item_3661030 = "Bintang Mengambang",
  str_item_intro_3661030 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Ini sepertinya lebih cocok sebagai balon yang muncul di taman hiburan daripada hiasan di rumah, tetapi juga terlihat cukup istimewa di rumah. Namun, itu mungkin akan terbang kemana-mana jika Anda tidak mengikatnya pada sesuatu.]],
  str_item_3000308 = "Catatan Kasus",
  str_item_intro_3000308 = "Saya telah mencatat beberapa ciri pelakunya. Mari kita lihat apakah mereka akan membantu kita mengungkap kebenaran...",
  str_item_3661195 = "Gramofon Klasik",
  str_item_intro_3661195 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Sebuah gramofon klasik dikatakan populer di Umbraton beberapa dekade lalu, itu adalah perlengkapan umum di rumah banyak pebisnis kaya. Tampaknya dibuat oleh seorang pengrajin pada masa itu atau seseorang yang berusaha keras untuk meneliti dan merancang timbre dan dekorasinya, yang membenamkan anggota generasi yang lebih tua ke dalam musik dan zeitgeist masa lalu.]],
  str_item_3661196 = "Papan Petunjuk",
  str_item_intro_3661196 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Papan ini tidak hanya dapat digunakan untuk menggambar berbagai peta pikiran untuk menganalisis suatu kasus dari semua sudut, tetapi juga merupakan tempat yang tepat untuk menempelkan petunjuk penting dan foto saksi. Itu juga dengan mudah menunjukkan informasi yang dikumpulkan dari berbagai sumber, memfasilitasi akses mudah, deduksi, dan ringkasan dan memungkinkan Anda untuk mengungkap kebenaran dan pelakunya dengan cepat.]],
  str_item_3661197 = "Meja Kopi Detektif",
  str_item_intro_3661197 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Awalnya digunakan untuk minum teh sore dan bermain kartu, meja kopi ini sekarang ditumpuk dengan buku dan kertas yang berkaitan dengan kasus kriminal, bersama kaca pembesar, pipa, dan lentera yang diletakkan di sebelahnya. Tampaknya pemiliknya pasti seorang detektif atau setidaknya penggemar detektif.]],
  str_item_3661198 = "Rak Mantel Detektif",
  str_item_intro_3661198 = "Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.\nSaat keluar untuk melakukan penyelidikan, penting bagi seseorang untuk melihat bagiannya. Mantel tersebut dapat menahan udara malam yang dingin dan dapat menampung banyak barang yang digunakan saat mengendus petunjuk, seperti buku catatan, kaca pembesar, dan senjata kecil untuk pertahanan diri. Dan topi itu, tentu saja, tidak hanya bagus untuk melindungi seseorang dari angin—tetapi juga membuat pemakainya terlihat lebih seperti seorang detektif.",
  str_item_3661031 = "Sofa Penalaran Deduktif",
  str_item_intro_3661031 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Mereka mengatakan bahwa beberapa detektif dapat menyimpulkan kebenaran suatu kasus dengan duduk di sofa dan menggambar berbagai petunjuk yang dikumpulkan oleh orang lain. Tampaknya sofa ini tidak hanya memberikan relaksasi tetapi juga meningkatkan kekuatan pikiran seseorang.]],
  str_item_3661199 = "Rak pipa",
  str_item_intro_3661199 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Sebuah rak penuh dengan pipa. Bahkan jika Anda tidak menyukai bau tembakau, pipa berbentuk unik ini layak untuk dikoleksi.]],
  str_item_3661200 = "Teropong Berdiri di Lantai",
  str_item_intro_3661200 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Fitur terhebat dari teropong ini adalah kemampuannya untuk membiarkan Anda melihat segala sesuatu di lingkungan yang jauh. Lensanya sangat jernih, tetapi laras lensa logamnya membuatnya sangat berat sehingga harus diletakkan di atas tripod khusus agar tetap stabil.]],
  str_item_3661032 = "Aman Aman",
  str_item_intro_3661032 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
"Ini adalah penjara teraman dan terkuat untuk barang-barangmu di benua ini," kata pedagang itu. Benar saja, pegangan kunci yang besar terlihat kuat, dan casingnya yang berat terlihat tahan terhadap kerusakan.]],
  str_item_3661033 = "Bebek Juara",
  str_item_intro_3661033 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Bebek ini Gronru dirancang adalah hadiah untuk pemenang permainannya! Sangat lucu, penampilan emasnya melambangkan kehormatan seorang juara.]],
  str_item_3661207 = "Karpet Pesanan",
  str_item_intro_3661207 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Di atas awan di langit adalah kota terapung. Sebagai cahaya peradaban Astra, karpet ini merupakan simbol identitas dan status serta merepresentasikan tatanan dan ritual.]],
  str_item_3661208 = "Spanduk yang Tidak Jatuh",
  str_item_intro_3661208 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Simbol dari "kota abadi yang tak pernah jatuh", kemunculannya di benua berarti cahaya peradaban Lumopolis bersinar terang di sini.]],
  str_item_3661201 = "Harpa Penghormatan",
  str_item_intro_3661201 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Kecapi ini secara eksklusif digunakan selama perayaan akbar di Lumopolis. Diawetkan dengan bentuk Luminatics yang unik, nadanya tetap selaras dengan sempurna. Hanya musisi paling terampil yang dapat memainkan melodi yang membangkitkan semangat dengan alat musik ini, yang cocok untuk lagu pujian.]],
  str_item_3661202 = "Jam Pasir Berkedip",
  str_item_intro_3661202 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
"Di tengah pasang surut cahaya dan kegelapan, hanya artefak ini yang dapat mengukur waktu dengan tepat." Dikabarkan memiliki butiran pasir paling indah yang ditemukan di benua itu, dan melalui kalibrasi Luminatics yang unik, keakuratan jam pasir ini menyaingi jam terbaik.]],
  str_item_3661203 = "Air Mancur Di Atas Awan",
  str_item_intro_3661203 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Di halaman jauh di atas awan, dapatkah Anda merasakan suara lembut air yang mengalir? Jangan heran, karena berasal dari Teras Air Mancur Lumopolis. Diberkati oleh Luminatics yang mempesona, air muncul dari ketiadaan, dengan anggun turun dari satu tingkat ke tingkat berikutnya. Bahkan dari langit di atas, orang dapat menikmati pemandangan air terjun surgawi yang menawan ini.]],
  str_item_3661204 = "Pedang dan Perisai Terakhir",
  str_item_intro_3661204 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Sebagai kota yang pantang menyerah, Lumopolis berdiri sebagai benteng utama peradaban. Pedang dan perisai ini mewujudkan pilar terakhir dari pertahanan ini... Mereka melambangkan tugas, keberanian, dan tekad yang tak tergoyahkan untuk berjuang sampai akhir.]],
  str_item_3661034 = "Bola Kristal Masa Lalu",
  str_item_intro_3661034 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Pandangan sekilas ke kristal hanya mengungkapkan refleksi Anda sendiri, tetapi pemeriksaan yang cermat mengungkap pemandangan dari masa lalu. Inti dari kenangan berharga tetap ada di depan mata Anda, mengundang Anda untuk membenamkan diri dalam genggaman mereka...]],
  str_item_3000325 = "Tetesan air mata kristal",
  str_item_intro_3000325 = [[
Dikatakan bahwa ini adalah air mata yang ditumpahkan oleh dunia ini... Mereka hanya dapat diperoleh pada hari itu dan mengandung kebenaran dunia ini.
Penggunaan: Dapat ditukar dengan perlengkapan di Hall of Remembrance.
Sumber: Selesaikan tahapan Main Story atau Resource Raid yang membutuhkan Prism.]],
  str_item_3661205 = "Kandil Lengan Ganda",
  str_item_intro_3661205 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
"Cahaya harus dipancarkan dalam kegelapan untuk membantu orang menemukan jalan mereka." Tempat lilin ini menggunakan Luminatics khusus dari Lumopolis. Dapat dipasang ke dinding secara otomatis tanpa pengait, dan lilinnya tidak mudah padam oleh angin.]],
  str_item_3661206 = "Vas Elegan",
  str_item_intro_3661206 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Vas-vas besar, masing-masing cukup mahal bagi rakyat jelata untuk hidup mewah selama beberapa tahun, yang digunakan oleh Bangsawan Lumo dikenal karena bentuknya yang elegan. Namun, mereka hanyalah dekorasi yang berharga murah untuk selusin rumah mewah mereka.]],
  str_item_3661035 = "Busana Formal Bermartabat",
  str_item_intro_3661035 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Pakaian ini elegan dan cukup khidmat bahkan untuk upacara, festival, atau pesta termegah di Lumopolis di mana etiket dijunjung tinggi. Saat dikenakan oleh seseorang dengan penampilan dan selera yang baik, pemakainya pasti akan menarik perhatian semua orang dan menjadi bintang keramaian.]],
  str_item_3661209 = "Lounge Teduh Resort",
  str_item_intro_3661209 = [[
Item furniture. Dapat ditempatkan di ruangan di Colossus Anda.
Tidak ada tujuan liburan yang lengkap tanpanya, menyediakan relaksasi dan perlindungan dari matahari. Kehilangan salah satu dari dua bagian meredupkan semangat liburan.]],
  str_item_3661210 = "Dinding Iklan Taman Hiburan",
  str_item_intro_3661210 = "Item furniture. Dapat ditempatkan di ruangan di Colossus Anda.\nTampaknya wajib dimiliki di setiap taman hiburan—besar, menarik perhatian, dihiasi dengan pola menawan yang seolah-olah memanggil, \"Ayo dan lihat! Jangan lewatkan!\"",
  str_item_3661211 = "Truk Es Krim Resort",
  str_item_intro_3661211 = [[
Item furnitur. Bisa ditempatkan di ruangan-ruangan di Colossus-mu.
Gerobak semacam ini menawarkan camilan es di hari-hari terik musim panas. Mereka berfungsi sebagai stasiun pengisian mini yang tersebar di taman hiburan, selalu menarik anak-anak yang berkeliling di sekitarnya dan ingin lebih banyak lagi.]],
  str_item_3661212 = "Resort Spring Pony",
  str_item_intro_3661212 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Fitur hiburan yang sangat disukai anak-anak. Dengan pegas di bawahnya yang membuat pengendara melompat-lompat perlahan, selalu memicu teriakan gembira yang tak berujung dari anak-anak kecil.]],
  str_item_3661213 = "Jet Ski Oasis",
  str_item_intro_3661213 = [[
Item furniture. Bisa ditempatkan di ruangan-ruangan di Colossus-mu.
Balapan air bahkan mungkin dilakukan di tengah gurun! Siapa yang menyangka! Semua ini berkat air melimpah dari oasis yang luas sehingga Jet Ski menemukan panggilannya, terhindar dari menjadi peninggalan masa lalu.]],
  str_item_3661214 = "Tanaman Kaktus Gurun",
  str_item_intro_3661214 = "Item furnitur. Bisa diletakkan di ruangan-ruangan di Colossus.\nTanaman yang paling umum di gurun, sangat cocok untuk kondisi kering. Tanaman ini dianggap sebagai simbol keteguhan, sehingga banyak orang yang menanamnya dalam pot untuk dekorasi rumah. Namun ingat, jangan terlalu sering menyiraminya–tanaman ini bisa mati jika kebanyakan air.",
  str_item_level_2905111 = "Bidang Energi",
  str_item_10000100 = "Kotak Seleksi Air Aurorian",
  str_item_10000101 = "Kotak Seleksi Api Aurorian",
  str_item_10000102 = "Kotak Pemilihan Aurorian Hutan",
  str_item_10000103 = "Kotak Pilihan Thunder Aurorian",
  str_item_intro_10000100 = "Setelah digunakan, Anda dapat memilih salah satu dari Aurorian Bintang 5 berikut untuk bergabung dengan petualangan Anda. (<color=#ffffff>Noah, Hydrad, Barton, Kleken, Philyshy, Corax</color>)",
  str_item_intro_10000101 = "Setelah digunakan, Anda dapat memilih salah satu dari Aurorian Bintang 5 berikut untuk bergabung dengan petualangan Anda. (<color=#ffffff>Faust, Regina, Benny and Curo, Leona, Istvan, Maggie, Barbara</color>)",
  str_item_intro_10000102 = "Setelah digunakan, Anda dapat memilih salah satu dari Aurorian Bintang 5 berikut untuk bergabung dengan petualangan Anda. (<color=#ffffff>Louise, Robyn, Odi, Pact, Areia, Sikare, Cuscuta</color>)",
  str_item_intro_10000103 = "Setelah digunakan, Anda dapat memilih salah satu dari Aurorian Bintang 5 berikut untuk bergabung dalam petualangan Anda. (<color=#ffffff>Mia, Nemesis, Schwartz, Vivian, Keating, Dayna, Beverly</color>)",
  str_item_3000327 = "Token Mesin Cakar",
  str_item_intro_3000327 = "Token-token ini digunakan di Mesin Claw dan berbagai fasilitas permainan lainnya. Setiap token menampilkan senyum ceria Lorelei, membawa harapan terbaiknya agar setiap tamu dapat menikmati pengalaman yang menyenangkan.",
  str_item_3000328 = "Koin Denuo Pass",
  str_item_intro_3000328 = [[
Koin yang beredar di dalam Denuo Valley Resort. Karena keahlian tinggi dan kualitas atasan, koin ini dapat ditukar dengan mata uang faction lainnya.
Gunakan dengan bijak dalam mode manajemen untuk meng-upgrade bangunan.]],
