  str_item_intro_3410645 = "Berisi: Yellow Order Box II ×15, Yellow Order Box I ×25, Yellow Jasper II ×5, Yellow Jasper I ×8, Nightium ×35.000, Coalition Order Box I ×8",
  str_item_intro_3410646 = "Berisi: Yellow Order Box III ×15, Yellow Order Box II ×25, Yellow Jasper II ×30, Yellow Jasper I ×7, Nightium ×121.000, Coalition Order Box II ×8",
  str_item_intro_3410647 = "Berisi: Yellow Order Box IV ×15, Yellow Order Box III ×25, Yellow Jasper III ×25, Yellow Jasper II ×10, Yellow Jasper I ×6, Nightium ×331.000, Coalition Order Box III ×8",
  str_item_intro_3000900 = "Katun lembut yang sering digunakan sebagai isian atau dibuat menjadi ornamen dekoratif.",
  str_item_intro_3000901 = "Bahan pakaian yang umum ditemukan di Astra, dikenal karena kekuatan, daya tahan, dan kemudahan pewarnaannya.",
  str_item_intro_3000902 = "Pewarna. Sinsa hanya menunjukkan kepada Anda tong tunggal ini, tetapi dia menyebutkan bahwa sebenarnya ada lebih banyak tong dengan berbagai warna.",
  str_item_intro_3000903 = "Sebuah kancing yang umum digunakan dalam penjahitan. Rasanya dingin saat disentuh dan sering kali disalahartikan sebagai koin oleh anak-anak.",
  str_item_intro_3000904 = "Itu terlihat seperti bola benang biasa. Sinsa hanya menunjukkan yang hitam, takut Anda akan mengacaukan urutan warna jika Anda memainkannya.",
  str_item_7000100 = "Buku Sketsa Sobek",
  str_item_7000101 = "Fragmen Buku Sketsa: Dokter",
  str_item_7000102 = "Fragmen Sketchbook: Pot Kosong",
  str_item_7000103 = "Laporan Diagnostik",
  str_item_7000104 = "Cangkir teh",
  str_item_7000105 = "Katak Putih",
  str_item_7000106 = "Mainan usang",
  str_item_7000107 = "Surat Permintaan Maaf",
  str_item_7000108 = "Buku Besar Rusak",
  str_item_7000109 = "Catatan Peneliti",
  str_item_7000110 = "Kunci Inggris yang Menggemaskan",
  str_item_7000111 = "Pita Rambut Kecil",
  str_item_7000112 = "Katak Bimbingan",
  str_item_7000113 = "Benih",
  str_item_7000114 = "Fragmen Buku Sketsa: Dawn Bunga",
  str_item_7000115 = "Fragmen Buku Sketsa: Kunci Inggris",
  str_item_7000116 = "Fragmen Sketchbook: Rediesel Boss",
  str_item_7000117 = "Fragmen Buku Sketsa: Colossus",
  str_item_7000118 = "Fragmen Buku Skets: Pangeran Lilypad",
  str_item_7000119 = "Buku Sketsa Lengkap",
  str_item_intro_7000100 = "Buku sketsa dengan gambar-gambar sederhana, menampilkan halaman terbuka yang menggambarkan seorang gadis muda duduk dengan gembira dengan tiga orang di sekelilingnya. Anehnya, kepala orang-orang dalam gambar ini semuanya telah robek.",
  str_item_intro_7000101 = "Tampaknya selembar kertas ini robek dari buku bergambar. Itu samar-samar menggambarkan kepala seorang wanita misterius yang mengenakan jas putih.",
  str_item_intro_7000102 = "Di atas selembar kertas itu ada gambar pot bunga keramik berisi gundukan kecil tanah.",
  str_item_intro_7000103 = "Selembar kertas yang agak lapuk menyerupai laporan diagnostik.",
  str_item_intro_7000104 = "Cangkir teh yang dibuat dengan sangat indah, menunjukkan nilai yang signifikan.",
  str_item_intro_7000105 = "Makhluk kecil putih misterius dengan asal yang tidak diketahui. Ini menunjukkan kesukaan yang kuat untuk dandelion.",
  str_item_intro_7000106 = "Mainan dengan penampilan yang khas. Meskipun desain dasarnya tampak cukup biasa, ia memiliki keunggulan pengerjaan yang sangat indah.",
  str_item_intro_7000107 = "Selembar kertas kusut berisi tulisan tangan bengkok. Meski penampilannya ceroboh, orang bisa merasakan niat tulus penulisnya.",
  str_item_intro_7000108 = "Buku besar tua yang mengungkapkan kurangnya kebiasaan akuntansi pemilik. Alih-alih mencatat pendapatan dan pengeluaran, itu berfungsi sebagai wadah untuk menangkap pemikiran dan idenya yang berbakat.",
  str_item_intro_7000109 = "Buku catatan lapuk, milik seseorang yang sudah lanjut usia.",
  str_item_intro_7000110 = "Kunci pas besar yang dihiasi dengan stiker yang menggemaskan.",
  str_item_intro_7000111 = "Ikat kepala berpola rumit yang cukup kecil untuk dikenakan oleh makhluk seukuran boneka.",
  str_item_intro_7000112 = "Seekor katak berwarna putih memakai ikat kepala seperti selendang, menambah pesonanya.",
  str_item_intro_7000113 = "Benih yang kesepian, seperti sumpah yang khusyuk, menunggu penemuan di sudut.",
  str_item_intro_7000114 = "Seorang gadis bernama bunga yang menyambut fajar. Dia kecil dan bersinar seperti bunga.",
  str_item_intro_7000115 = "Selembar kertas yang menampilkan gambar kunci inggris yang terlalu besar. Alat sebesar itu pasti milik seseorang yang tinggi dan tampan.",
  str_item_intro_7000116 = "Pemimpin Rediesel Wrench, sosok yang melangkah melewati badai, menghadapi konspirasi, dan tertawa di hadapan keputusasaan. Di bawah eksterior besi, kelembutan masih ada.",
  str_item_intro_7000117 = "Colossus berbentuk naga yang legendaris, digambarkan dengan guratan menggemaskan menyerupai sosok yang elegan, namun orang tidak bisa tidak mengagumi sayapnya yang putih bersih.",
  str_item_intro_7000118 = "Utusan kulit putih dari dunia luar.",
  str_item_intro_7000119 = "Buku sketsa dengan gaya seni yang imut, menampilkan beberapa orang tertawa dengan gembira.",
  str_item_sub_intro_7000100 = "\"Ini dimaksudkan untuk menjadi kenangan indah, namun penuh dengan lubang... Siapa sebenarnya yang kugambar di atasnya saat itu?\"",
  str_item_sub_intro_7000101 = "\"Hei, siapa yang begitu ceroboh hingga merobek wajah dokter? Dia digigit binatang kecil? Nah, kalau begitu aku tidak bisa berbuat apa-apa.\"",
  str_item_sub_intro_7000102 = "\"Aku juga punya baskom keramik ini di rumah! Aku punya cukup banyak koleksi karena aku sangat menyukainya... meskipun aku tidak ingat alasan pasti mengapa aku menyukainya.\"",
  str_item_sub_intro_7000103 = "\"Ketakutan, kemarahan, rasa sakit... Semua faktor negatif yang memengaruhi kondisi fisik dan psikologis Anda telah berhasil dihilangkan. Selamat, Anda sekarang menjadi anak yang sehat.\"",
  str_item_sub_intro_7000104 = "\"Selain saya, dokter memiliki pasien lain yang harus dirawat. Ada seorang nona muda bangsawan dari Lumopolis yang menyukai teh hitam dan membawa cangkir teh kecil ke mana-mana... Saya harap dia sudah sembuh sekarang.\"",
  str_item_sub_intro_7000105 = "\"Ada apa dengan kodok? Aku paling suka kodok! ... Hah? Kamu bukan kodok?\"",
  str_item_sub_intro_7000106 = "\"Untuk kekasihku, ketika kita tidak bisa berada di sisinya, semoga pernak-pernik kecil ini bisa membawa kebahagiaan untuknya...\"",
  str_item_sub_intro_7000107 = "\"Kita harus menahan diri dari menggunakan bahasa kotor di depan ***. Mari kita semua meminta pertanggungjawaban satu sama lain. Siapa pun yang melanggar aturan ini harus makan delapan belas botol saus pedas mentah, dan saya tidak terkecuali.\"",
  str_item_sub_intro_7000108 = "\"Harus saya katakan, saya sangat terkejut dengan intensitasnya. Saya pernah percaya bahwa level ** mewakili batas dari apa yang dapat dicapai oleh benih, dan bahwa terobosan sebenarnya harus terletak pada pengaruh ** pada kepribadian seseorang. Namun, kekuatan ** yang mentah, keras, dan tak terbayangkan telah memikat saya. Saya heran bahwa benih dapat menggunakan kemampuan seperti itu. Kekuatan ini, kekuatan ini, persis seperti yang dibutuhkan ****. Sekarang saya merindukan kekuatan ** untuk membentuk kembali dunia.\"",
  str_item_sub_intro_7000109 = "\"Ketika kami sampai di tempat kejadian, kami benar-benar terkejut dengan jejak kehancuran yang menghancurkan. Kami berspekulasi bahwa seseorang melepaskan energi yang sangat besar, melenyapkan semua fasilitas dan bangunan dari bawah tanah ke permukaan... Sulit untuk memahami monster seperti apa yang bisa dimiliki kekuatan seperti itu...\"",
  str_item_sub_intro_7000110 = "\"Stiker bermotif bunga ini terlihat familier... Apa aku yang memakainya?\"",
  str_item_sub_intro_7000111 = "\"Ikat kepala putih dengan garis-garis hitam... di mana ya pernah aku lihat sebelumnya...\"",
  str_item_sub_intro_7000112 = "\"Pesan apa yang Anda miliki untuk saya? Maukah Anda membimbing saya, jiwa yang tersesat, di sepanjang jalan?\"",
  str_item_sub_intro_7000113 = "\"Jika kamu mengambil bunga dari duniaku, hatiku akan tenggelam lebih dalam ke jurang yang jauh, kurasa.\"",
  str_item_sub_intro_7000114 = "\"Aku ingin kembali dan menanam bunga di seluruh Jurang Mata Merah.\"",
  str_item_sub_intro_7000115 = "\"Dengan keterampilan seperti itu, dapatkah Anda benar-benar menangkap kehebatan kunci pas ini... Jika ada yang berani mengkritiknya, mereka mungkin benar-benar merasakan kekuatan kunci pas itu...\"",
  str_item_sub_intro_7000116 = "\"Dia selalu berhasil menemukanku!\"",
  str_item_sub_intro_7000117 = "\"Coba tebak orang seperti apa yang bisa mengendalikan Colossus yang luar biasa... Apakah kamu bercanda! Aku tidak mengejek Lepidoz sama sekali! Ini sangat tidak adilrrrrrr—\"",
  str_item_sub_intro_7000118 = "\"Tetap hidup, dan kita akan bertemu lagi.\"",
  str_item_sub_intro_7000119 = "\"Dunia nyata dan kebahagiaan sejati.\"",
