  str_item_7000200 = "Kaca Pembesar",
  str_item_7000201 = "Pena bulu",
  str_item_7000202 = "Laporan Nilai",
  str_item_7000203 = "Tongkat Penunjuk",
  str_item_7000204 = "Preseden Hukum (1)",
  str_item_7000205 = "Laporan Investigasi Rahasia",
  str_item_7000206 = "Preseden Hukum (2)",
  str_item_intro_7000200 = "Sebuah kaca pembesar dengan desain unik dan pewarnaan khas, alat yang sangat diperlukan dalam penyelidikan.",
  str_item_intro_7000201 = "Sebuah pena emas yang berkilau dan terasa berat di tangan Anda.",
  str_item_intro_7000202 = "Laporan nilai sempurna dari Akademi Dawn, menunjukkan kinerja yang sangat baik.",
  str_item_intro_7000203 = "Sebatang tongkat tersimpan di sudut, tampaknya tidak mencolok, membangkitkan kenangan masa kecil Irridon.",
  str_item_intro_7000204 = "Sebuah preseden yang ditinggalkan oleh Hakim Rodell Novek, mencerminkan sifatnya yang dingin dan tak kenal ampun.",
  str_item_intro_7000205 = "Sebuah laporan penyelidikan rahasia yang ditulis oleh ayah Irridon, jauh sebelum persidangan wasiat Baron, dia mengetahui maksud tersembunyi di balik wasiat tersebut.",
  str_item_intro_7000206 = "Sebuah preseden yang ditinggalkan oleh Hakim Rodell Novek, dengan putusan yang mengakibatkan pemusnahan seluruh keluarga.",
  str_item_sub_intro_7000200 = "\"Apakah ini hanya imajinasiku, atau kaca pembesar ini benar-benar memanggil namaku? Yah, itu tidak mungkin. Tapi kaca pembesar ini terlihat sangat akrab... Apakah ini milikku? Apa yang terjadi padaku? Bagaimana bisa aku tidak ingat sesuatu seperti ini?\"",
  str_item_sub_intro_7000201 = "\"Kenapa ya? Kenapa aku tidak pernah bisa mendapatkan persetujuan mereka, baik dari ayahku maupun teman-teman sebayaku...\"",
  str_item_sub_intro_7000202 = "\"Apakah aku tidak berusaha semampuku...?\"",
  str_item_sub_intro_7000203 = "\"Berapa banyak usaha yang diperlukan untuk melupakan momen suram dari masa kecilku?\"",
  str_item_sub_intro_7000204 = "\"Haruskah saya meneruskan pola pikir di balik putusan ini...\"",
  str_item_sub_intro_7000205 = "\"A-Apa yang telah kulakukan...?\"",
  str_item_sub_intro_7000206 = "\"Aku percaya... aku punya jawaban dari diriku sendiri.\"",
  str_item_7000300 = "Dapatkan Bukti",
