  str_item_7000311 = "Dapatkan Patung",
  str_item_7000312 = "Dapatkan Bukti",
  str_item_7000313 = "Dapatkan Bukti",
  str_item_7000314 = "Dapatkan Kesaksian",
  str_item_7000315 = "Dapatkan Kesaksian",
  str_item_7000316 = "Dapatkan Patung",
  str_item_7000317 = "Dapatkan Patung",
  str_item_7000318 = "Berat Emas",
  str_item_7000319 = "Berat Emas",
  str_item_7000320 = "Berat Emas",
  str_item_intro_7000300 = "Sepertinya Nodirri tidak memiliki lambang di dirinya.",
  str_item_intro_7000301 = "Kesaksian dari anggota dewan siswa: Keluarga Pam sedang menghadapi kesulitan finansial.",
  str_item_intro_7000302 = "Ada hubungan kompetitif antara Nodirri dan Pam.",
  str_item_intro_7000303 = "Kesaksian dari penjaga gerbang tua: Nodirri pernah mengunjungi ruang belajar mandiri sebelumnya.",
  str_item_intro_7000304 = "Kejahatan terhadap Properti",
  str_item_intro_7000305 = "Pelanggaran terhadap Ketertiban Umum",
  str_item_intro_7000306 = "Wasiat kakek telah dikonfirmasi sebagai asli.",
  str_item_intro_7000307 = "Sidik jari Jerry ditemukan pada alat yang digunakan oleh Kakek untuk bunuh diri.",
  str_item_intro_7000308 = "Kesaksian tetangga: Kakek menyebut ingin mewariskan segalanya kepada cucunya perempuan.",
  str_item_intro_7000309 = "Kesaksian saksi: Tidak ada keanehan yang diamati saat Kakek menyusun wasiatnya.",
  str_item_intro_7000310 = "Pemalsuan Dokumen",
  str_item_intro_7000311 = "Hukum Warisan Wasiat",
  str_item_intro_7000312 = "Lambang keluarga Pyrrhus yang ditemukan di kamar Gautier.",
  str_item_intro_7000313 = "Kutukan yang ditulis oleh Mirren Gautier di buku sketsanya.",
  str_item_intro_7000314 = "Keluarga Gautier menangkap anggota keluarga Pyrrhus untuk dijadikan bahan eksperimen.",
  str_item_intro_7000315 = "Keluarga Pyrrhus masih meneliti Kristal Sanguine.",
  str_item_intro_7000316 = "Pengkhianatan",
  str_item_intro_7000317 = "Kejahatan Menyebarkan Rumor",
  str_item_intro_7000318 = "Bukti ditemukan untuk Kasus Pencurian Emblem Dawn!",
  str_item_intro_7000319 = "Bukti ditemukan untuk Kasus Wasiat Kakek!",
  str_item_intro_7000320 = "Bukti ditemukan untuk Kasus Pengkhianatan Keluarga Gautier!",
  str_item_sub_intro_7000300 = "Setelah mendengar cerita Pam tentang kasus tersebut, Nodirri menjadi sangat marah. Dia mendekati Pam, mengajukan serangkaian pertanyaan tentang mengapa Pam mencemarkan nama baiknya dengan cara seperti itu. Untuk membuktikan bahwa dia tidak bersalah, Nodirri dengan sukarela mengizinkan Irridon untuk menggeledah dirinya, dan seperti yang diharapkan, tidak ditemukan bukti yang mencurigakan.",
  str_item_sub_intro_7000301 = "Dalam perjalanan ke ruang belajar mandiri, Irridon diam-diam didekati oleh anggota dewan siswa, yang dengan penuh semangat berbagi pandangannya, \"Keluarga Pam bukanlah keluarga bangsawan tingkat tinggi, dan orang tuanya tidak pernah menjabat posisi publik resmi. Akhir-akhir ini, tampaknya mereka menghadapi kesulitan keuangan karena alasan tertentu!\"",
  str_item_sub_intro_7000302 = "Di papan pengumuman sekolah, Irridon menemukan pengumuman dari Lumopolis Temple: tahun ini, mereka menerima dua calon biarawati, Pam dan Nodirri. Namun, hanya salah satu dari mereka yang pada akhirnya akan memiliki kesempatan untuk tinggal di kuil.",
  str_item_sub_intro_7000303 = "Irridon mencapai sekitar ruang belajar mandiri dan melihat seorang penjaga gerbang yang sudah tua tertidur di dekatnya. Jelas, penjaga gerbang belum melupakan Irridon, setelah menerima bantuan dari Irridon beberapa kali selama di sekolah. Penjaga gerbang menyebutkan bahwa hari ini, selain Pam, hanya Nodirri yang masuk ke ruang belajar. Dia merasa aneh saat itu mengapa Nodirri menggunakan sapu tangan untuk membuka pintu. \"Mungkin dia takut kuman; saya tidak terlalu memikirkannya saat itu.\"",
  str_item_sub_intro_7000304 = "Pencurian properti yang signifikan, ketika jumlah yang dicuri cukup besar, dapat dihukum dengan penjara mulai dari tiga hingga sepuluh tahun dan denda.",
  str_item_sub_intro_7000305 = "Menghina atau mencemarkan nama baik orang lain secara terbuka, dengan keadaan yang parah, dapat menyebabkan hukuman penjara hingga tiga tahun dan denda.",
  str_item_sub_intro_7000306 = "Jerry menyerahkan Irridon dengan surat wasiat yang ada di tangannya, dan setelah perbandingan dan analisis yang teliti, Irridon memastikan bahwa surat wasiat kakek Pam memang ditulis oleh dirinya sendiri. Dalam wasiat tersebut, kakek mewariskan gelar dan kekayaannya kepada Jerry, dengan menyatakan, \"Saya sudah hidup cukup lama, dan saya tidak menyesal.\" Irridon memperhatikan pernyataan ini dengan seksama, karena tampaknya kakek mengisyaratkan niatnya untuk bunuh diri saat menulis wasiat.",
  str_item_sub_intro_7000307 = "Irridon sampai di rumah kakek Pam dan menemukan bahwa dia mengakhiri hidupnya sendiri dengan menggunakan pisau buah kecil. Namun, setelah memeriksa lebih dekat pisau tersebut, Irridon mengidentifikasi sidik jari Jerry di atasnya. Jerry menjelaskan bahwa dia sering menyiapkan makanan, jadi memiliki sidik jari di peralatan makan tidaklah aneh. Irridon mengevaluasi ulang situasi dan memastikan bunuh diri kakek tersebut.",
  str_item_sub_intro_7000308 = "Irridon mengetuk pintu tetangga kakek, dan tetangga itu memberi tahu Irridon bahwa, meskipun kakek sering meratapi ketidakcukupan putranya, dia sering membanggakan cucu perempuannya. Kakek bahkan secara terbuka menyatakan bahwa dia berniat untuk mewariskan gelar dan kekayaannya kepada cucu perempuannya, tidak meninggalkan apa pun untuk putranya.",
  str_item_sub_intro_7000309 = "Saksi atas wasiat tersebut adalah seorang pelayan tua yang berpendidikan. Pelayan tua itu mengungkapkan rasa terhormat yang sangat besar karena diundang oleh kakek untuk menjadi saksi. Tepat ketika kata-kata meninggalkan mulut pelayan tua itu, dia tiba-tiba merasa seperti salah bicara. Sedikit malu, pelayan itu melanjutkan menjelaskan bahwa tidak ada yang aneh ketika kakek menyusun wasiat, dan dia telah berulang kali memastikan bahwa memang itulah keinginan sejati kakek.",
  str_item_sub_intro_7000310 = "Pemalsuan dokumen publik atau pribadi untuk kegiatan penipuan dapat dihukum dengan penjara mulai dari tiga hingga sepuluh tahun dan denda.",
  str_item_sub_intro_7000311 = "Surat wasiat yang sah secara hukum harus diikuti dalam mendistribusikan harta sesuai dengan isinya.",
  str_item_sub_intro_7000312 = "Irridon menyelinap ke dalam ruangan milik keluarga Gautier di Lumopolis Bawah, dengan hati-hati menggeledahnya. Tak disangka, ia menemukan lambang keluarga Pyrrhus tersembunyi di sudut. Kedua keluarga Gautier dan Pyrrhus diasingkan ke Lumopolis Bawah karena kasus Kristal Sanguine. Apakah mungkin kedua keluarga ini bekerja sama dalam pemberontakan? Irridon tidak berani memikirkannya lebih jauh. \"Pam juga anggota keluarga Pyrrhus...\"",
  str_item_sub_intro_7000313 = "Irridon menemukan rumah yang sudah lapuk lainnya, dan di dalamnya, dia menemukan sebuah buku sketsa bertanda tangan \"Mirren Gautier.\" Buku tersebut berisi beberapa pola abstrak yang Irridon temukan sulit untuk dipahami. Irridon mengerjapkan mata, dan di antara pola-pola tersebut, dia menemukan sebuah baris teks kecil: \"Kenapa kau perlakukan aku seperti ini... Kenapa, KENAPA?! Aku akan mengambil alih nasibku sendiri lagi... bahkan jika itu berarti aku harus menggunakan kekuatan mereka.\"",
  str_item_sub_intro_7000314 = "Seorang Eclipsite aneh tiba-tiba muncul di jalan. Tanpa ragu, Irridon maju dan menusuk dada Eclipsite, membuatnya roboh di tanah. Namun tiba-tiba, seolah terbangun dari lamunan, Eclipsite mengangkat tangannya ke arah kerumunan, seolah berjuang untuk mengatakan sesuatu. Irridon mendekat, mendengar gumaman Eclipsite, \"Gautier... mencari balas dendam... terhadap Pyrrhus... mereka... menangkap kami... untuk eksperimen... mereka merencanakan... pemberontakan!\"",
  str_item_sub_intro_7000315 = "Saat Irridon mempertimbangkan langkah selanjutnya untuk penyelidikan, seorang pejalan kaki berpakaian compang-camping mendekat secara diam-diam. Dia mengaku tahu segalanya tentang kejadian-kejadian terbaru di Lower Lumopolis, mengungkapkan bahwa keluarga Pyrrhus masih melakukan penelitian tentang Kristal Sanguine. Irridon bertanya mengapa dia membagikan informasi ini, dan pejalan kaki itu membuka bibirnya, memperlihatkan giginya yang menghitam dan berkata, \"Bisakah kamu membawaku kembali ke Halaman Lumopolis?\"",
  str_item_sub_intro_7000316 = "Sengaja merencanakan atau mencoba untuk menggulingkan pemerintahan Lumopolis akan mengakibatkan hukuman seumur hidup, dengan kemungkinan hukuman mati untuk kasus yang sangat parah.",
  str_item_sub_intro_7000317 = "Menyebarkan rumor palsu tentang orang lain secara sengaja akan mengakibatkan hukuman penjara hingga satu tahun dan denda.",
  str_item_sub_intro_7000318 = "Berdasarkan bukti dan pernyataan saksi, Irridon menyimpulkan bahwa Nodirri adalah pelaku yang mencuri Emblem Dawn.",
  str_item_sub_intro_7000319 = "Kamu menganggap wasiat tersebut sah, dan pelayan Jerry akan mewarisi gelar kakek Pam dan semua kekayaannya...",
  str_item_sub_intro_7000320 = "Kamu telah mengumpulkan bukti dan kesaksian yang komprehensif, yang mengkonfirmasi bahwa Mirren Gautier menculik anggota keluarga Pyrrhus untuk eksperimen dan memiliki niat pemberontakan.",
  str_item_7000400 = "Kunci Lama",
  str_item_7000401 = "Kue Kering Dayna",
  str_item_7000402 = "Denah Rumah Baru",
  str_item_7000403 = "Trombon Anggun",
  str_item_7000404 = "Lembar Musik Baru",
  str_item_7000405 = "Potret Dayna",
  str_item_7000406 = "Potret Robyn",
  str_item_7000407 = "Potret Lady dalam Teko Teh",
  str_item_7000408 = "Potret Lumba-lumba Putih",
  str_item_intro_7000400 = "Kunci loteng yang diberikan kepada Connolly oleh bibinya. Gunakan dengan hati-hati agar kunci kuno itu tidak berderit dan mengganggu orang lain.",
  str_item_intro_7000401 = "Kue yang dibawa Connolly untuk Dayna tetapi dicuri oleh pengawal merman. Kue ini tidak diberi gula sesuai dengan permintaan Dayna.",
  str_item_intro_7000402 = "Draf untuk benteng Aqua Lord. Mungkin itu tidak benar, tapi Queen Connolly memiliki semua hak interpretasi.",
  str_item_intro_7000403 = "Instrumen musik baru yang ditemukan oleh penduduk kota untuk Connolly ini dapat memainkan suara yang lebih keras dan lebih tegas untuk menyampaikan kemarahan.",
  str_item_intro_7000404 = "Skor Aqua yang Connolly temukan di loteng tua, kini ditandatangani dengan nama baru.",
  str_item_intro_7000405 = "Sebuah potret Dayna yang dilukis oleh seorang seniman di kota bawah laut, saat ini ditempatkan di kursi kosong oleh Queen Connolly sebagai alat bantu saat berlatih pidatonya.",
  str_item_intro_7000406 = "Sebuah potret Robyn yang dilukis oleh seorang seniman di kota bawah laut, saat ini ditempatkan di kursi kosong oleh Queen Connolly sebagai prop saat berlatih pidatonya.",
  str_item_intro_7000407 = "Potret konsultan misterius yang dilukis oleh seorang seniman di kota bawah laut, saat ini ditempatkan di kursi kosong oleh Queen Connolly sebagai prop saat berlatih pidatonya.",
  str_item_intro_7000408 = "Sebuah potret ikan yang ramah yang dilukis oleh seorang seniman di kota bawah laut, saat ini ditempatkan di kursi kosong oleh Queen Connolly sebagai prop saat berlatih pidatonya.",
  str_item_sub_intro_7000400 = "\"Dia tidur di loteng, memakan sisa makanan yang orang lain tolak. Berbicara dengan bisikan lembut, bersembunyi di sudut-sudut jauh! Menyapu kamar siang hari, memainkan instrumen di malam hari. Menghibur hatinya yang kesepian dengan musik!\"",
  str_item_sub_intro_7000401 = "\"Kue-kueku! Connolly memberikan itu padaku! Kenapa kaki tangan yang kotor itu tidak menyisakan kue-kue saja!\"",
  str_item_sub_intro_7000402 = "\"Estetika dunia lain yang hebat... nikmatilah!\"",
  str_item_sub_intro_7000403 = "\"Rasa sakit dan kesedihan... akan menemukan keselamatan dalam musik!\"",
  str_item_sub_intro_7000404 = "\"Itu pernah mengungkapkan keinginan agar aku memberinya nama baru. Aku memikirkannya dengan sungguh-sungguh. Rubinstein, Salieri, Leopold, Dvorak... Semua itu adalah favoritnya... Apa, sesuatu yang lebih akrab?\"",
  str_item_sub_intro_7000405 = "\"Aku terlalu keras, kata kamu? Bagaimana aku tidak bisa begitu saat aku membela saudara-saudaraku?\"",
  str_item_sub_intro_7000406 = "\"Iya, pernah ada ikan yang bilang aku datar dan sulit diperhatikan... Tapi itulah cara aku bertahan hidup...\"",
  str_item_sub_intro_7000407 = "\"Kamu ingin aku keluar dari masa pensiun? Yah, itu akan menelan biaya untukmu.\"",
  str_item_sub_intro_7000408 = "\"Siapa saya untuk Queen Connolly, kamu tanya? Itu rahasia!\"",
  str_item_7000801 = "Antik",
  str_item_intro_7000801 = "Barang antik dapat ditemukan di setiap sudut Twin Pavilions Bay. Artefak budaya Longzhou sangat dihargai di negara lain, tetapi beberapa diperoleh melalui transaksi jujur yang melibatkan pesanan dan pembayaran yang sesuai, sementara yang lain dicuri di bayangan oleh pencuri.",
