Apakah kehangatan yang saya rasakan sekarang ini adalah pancaran sinar matahari pagi atau kehangatan Anda setelah melewati duri tajam?]],
  str_item_intro_6030111 = [[
Stand By Me Medali.
Sangat sedikit orang yang tahu bahwa bunga pohon castus juga mekar. Namun, ukurannya lebih kecil dari bunga wisteria, berwarna lavender pudar, dan tampak seperti rok pendekar pedang.]],
  str_item_intro_6030112 = [[
Stand By Me Medali.
Ketika suatu hari dia melewati Sungai Emas yang gemericik, dia akan mengingat perjalanan naik perahu dalam mimpinya dan menantikan untuk berbagi perahu dengan seseorang tertentu.]],
  str_item_intro_6030113 = [[
Stand By Me Medali.
