Ini telah diberi kekuatan luar biasa melalui infusi cinta Regal. Mungkin ini adalah satu-satunya alasan mengapa dia bisa tetap berada di sisinya dalam bentuk yang berbeda.]],
  str_item_intro_6030116 = [[
