Ketika ia pergi, ia tampak seperti mesin yang dingin dan tidak berperasaan. Hanya ketika ia kembali, sifat manisnya menjadi jelas.]],
  str_item_intro_6030117 = [[
Sebuah Medali Stand By Me.
Karena membuangnya adalah hal yang mustahil... Mungkin juga bisa dijadikan aksesori fashion yang unik.]],
  str_item_intro_6030118 = "Medali Stand By Me. Pohon-pohon yang mengalir dengan krim tebal dan bunga-bunga yang menghasilkan buah paling manis... Tempat yang sempurna untuk piknik, jika ada kesempatan.",
  str_item_intro_6030119 = [[
