Siapa orang tua orang ini? Apakah orang ini memiliki anak atau saudara kandung? Nama yang terukir di batu tetap diam sambil mencerminkan jalan ke depan.]],
  str_item_intro_6030121 = [[
Stand By Me Medali. 
Banner bergerak dalam angin saat panggilan senjata terdengar. Pembela Astra yang paling tanpa pamrih maju tanpa rasa takut, tidak pernah mundur saat mereka menahan kegelapan.]],
  str_item_intro_6030122 = [[
Stand By Me Medali.
"Yang aku inginkan hanyalah tetap berada di samping saudara perempuanku..."]],
  str_item_intro_6030123 = [[
Stand By Me Medali.
"Yang aku inginkan hanyalah adik perempuan kecilku bisa bertahan hidup..."]],
  str_item_intro_6030124 = "Stand By Me Medali. Cermin ini telah menyaksikan jatuhnya terlalu banyak hal. Mungkin inilah saatnya untuk melihat sesuatu yang baru.",
