  str_item_intro_6130105 = [[
Papan Peringatan Stand By Me.
Meskipun seribu tahun mungkin telah memudar seperti debu, menghilang menjadi ketiadaan, hati saya tetap teguh.]],
  str_item_intro_6130106 = [[
Sebuah Papan Peringatan Stand By Me.
Klik-klak, klik-klak! Berpegang pada rel, kereta melaju melalui mimpi yang cerah. Ia melaju melewati Hutan Cream, melewati mata air madu, dan melewati penyesalan yang sedang diseduh oleh seorang pelancong yang sendirian...]],
  str_item_intro_6130107 = [[
Papan Peringatan Stand By Me.
"Saya bersedia untuk dibentuk berkali-kali, karena saya yakin percobaan ini akan membawa saya ke cahaya Illumina. Peluru logam penuh yang diasah mencakup aspirasi kita yang tidak goyah."]],
  str_item_intro_6130108 = [[
Papan Peringatan Stand By Me.
"Tubuhnya dikubur dalam salju, jiwanya terikat oleh cermin, dan wajahnya dimahkotai bunga yang layu, tetapi cintanya tidak pernah layu."]],
  str_item_3001000 = "Pecahan Mimpi",
  str_item_intro_3001000 = "Fragmen yang diperoleh dari cerita di mana kenyataan dan ilusi berjalin, menceritakan jejak dunia nyata. Mereka dapat ditukarkan dengan hadiah item di toko Authentic Dreamscapes.",
  str_item_get_3001000 = "Dream - Konversi Kedaluwarsa Token Toko Tema",
  str_item_3001001 = "Metamorf",
  str_item_intro_3001001 = "Sebuah kenang-kenangan yang tertinggal setelah menghadapi tantangan dan mengalami pertumbuhan. Itu dapat ditukar dengan hadiah item di Dream - Awakening in the Storm - Memory Workshop.",
  str_item_get_3001001 = "Dream - Kebangkitan di tahap Storm",
  str_item_3001002 = "Pecahan Sedimen",
  str_item_intro_3001002 = "Fragmen diperoleh setelah menghadapi tantangan dan mengalami pertumbuhan. Mereka dapat ditukar dengan hadiah item di Dream - Awakening in the Storm - Memory Workshop.",
  str_item_get_3001002 = "Dream - Kebangkitan di tahap Storm",
  str_item_3001003 = "Akal",
  str_item_intro_3001003 = "Faktor kunci agar Eve tetap rasional dan berpikiran jernih, yang memungkinkannya untuk menghadapi Omen dalam Awakening in the Storm. Poin Wit akan bertambah sebanyak 3 poin setiap hari pada pukul 05:00 (UTC+0) atau 00:00 (UTC-5) (Tidak ada poin yang diberikan jika batas tercapai).",
  str_item_get_3001003 = "Pemulihan otomatis dari waktu ke waktu",
  str_item_3001004 = "Riak Kegembiraan",
  str_item_intro_3001004 = "Cangkir favorit Eve hanya berisi air biasa, tetapi itu memberinya kekuatan. Kumpulkan dan tingkatkan level \"Senyum Membawa Kebahagiaan\".",
  str_item_get_3001004 = "Dapatkan dengan menyelesaikan tahapan Nightmare di Dream dengan 3-Bintang untuk pertama kalinya.",
  str_item_3001005 = "Kontra Berat Jiwa",
  str_item_intro_3001005 = "Berat yang diperoleh selama pencarian jati diri untuk menyeimbangkan timbangan kehidupan. Dapat digunakan untuk menukar hadiah item di Dream - Trials Amongst Golden Ripples - Trial Auction.",
  str_item_get_3001005 = "Mimpi - Tahap Ujian di Antara Riak Emas",
  str_item_3001006 = "Lilin Keadilan",
  str_item_intro_3001006 = "Sebuah nyala lilin berbintang yang tertinggal di jalan mengejar keadilan di hati seseorang. Dapat digunakan untuk menukar hadiah item di Dream - Trials Amongst Golden Ripples - Trial Auction.",
  str_item_get_3001006 = "Mimpi - Tahap Ujian di Antara Riak Emas",
  str_item_3001007 = "Akal",
  str_item_intro_3001007 = "Sebagai kunci untuk membantu seseorang menjaga rasionalitas dan kejelasan, benda ini akan terpakai selama eksplorasi tetapi dapat secara bertahap kembali terisi seiring waktu.",
  str_item_get_3001007 = "Pemulihan otomatis dari waktu ke waktu",
  str_item_3001008 = "Cahaya Keadilan",
  str_item_intro_3001008 = "Cahaya keadilan yang telah Irridon dapatkan melalui usaha sendiri. Kumpulkan untuk meningkatkan level Truth Focus.",
  str_item_get_3001008 = "Dapatkan dengan menyelesaikan tahapan Nightmare di Dream dengan 3-Bintang untuk pertama kalinya.",
  str_item_3001010 = "Kerang Bergema",
  str_item_intro_3001010 = "Di dalam kerang ini yang menggaungkan melodi, terdapat fragmen partitur musik kuno yang dapat ditukarkan dengan hadiah di Dream: Kafe Sea Bubbles Fantasia Bawah Air milik Connolly.",
  str_item_get_3001010 = "Mimpi: Panggung Fantasia Bawah Air Connolly",
  str_item_3001011 = "Fluorophora Lezat",
  str_item_intro_3001011 = "Alga yang bercahaya di sudut dasar laut ini digunakan untuk membuat minuman dalam laut yang sangat populer. Dapat ditukarkan dengan hadiah di Dream: Kafe Sea Bubbles Fantasia Bawah Laut Connolly.",
  str_item_get_3001011 = "Mimpi: Panggung Fantasia Bawah Air Connolly",
  str_item_3001012 = "Akal",
  str_item_intro_3001012 = "Sebagai kunci untuk membantu seseorang menjaga rasionalitas dan kejelasan, benda ini akan terpakai selama eksplorasi tetapi dapat secara bertahap kembali terisi seiring waktu.",
  str_item_get_3001012 = "Mimpi: Panggung Fantasia Bawah Air Connolly",
  str_item_3001013 = "Studi tentang Pact",
  str_item_intro_3001013 = "Upaya Connolly untuk memahami segala hal yang dijelaskan oleh Aqua Lord dan memahami kebijaksanaan mendalam. Akumulasi untuk meningkatkan level Koneksi Aqua.",
  str_item_get_3001013 = "Dapatkan dengan menyelesaikan tahapan Nightmare di Dream dengan 3-Bintang untuk pertama kalinya.",
  str_item_3001014 = "Jepit Rambut Wisteria",
  str_item_intro_3001014 = "Sebuah jepit rambut yang terbuat dari bunga-bunga kecil yang kuat yang dapat digunakan untuk menukarkan hadiah item di Dream - Sword Song Under a Canopy of Dreams - Verdant Exchange.",
  str_item_get_3001014 = "Mimpi - Lagu Pedang di Bawah Kanopi Mimpi Panggung",
  str_item_3001015 = "Koin Tembaga Kuno",
  str_item_intro_3001015 = "Sebuah koin kuno berkarat dari Timur yang tidak lagi digunakan sebagai bentuk mata uang seiring berjalannya waktu. Dapat digunakan untuk menebus hadiah item di Sword Song Under a Canopy of Dreams - Verdant Exchange.",
  str_item_get_3001015 = "Mimpi - Lagu Pedang di Bawah Kanopi Mimpi Panggung",
  str_item_3001016 = "Akal",
  str_item_intro_3001016 = "Sebagai kunci untuk membantu seseorang menjaga rasionalitas dan kejelasan, benda ini akan terpakai selama eksplorasi tetapi dapat secara bertahap kembali terisi seiring waktu.",
  str_item_get_3001016 = "Mimpi - Lagu Pedang di Bawah Kanopi Mimpi Panggung",
  str_item_3001017 = "Kemauan Membuat Pedang",
  str_item_intro_3001017 = "Setiap pertempuran adalah kesempatan untuk meningkatkan kemampuan berpedang seorang pendekar. Peningkatan yang terus menerus akan mengarah pada perubahan kualitatif. Akumulasi untuk meningkatkan level Sword Heart.",
  str_item_get_3001017 = "Dapatkan dengan menyelesaikan tahapan Nightmare di Dream dengan 3-Bintang untuk pertama kalinya.",
  str_item_3001018 = "Modal Kerja",
  str_item_intro_3001018 = "Seperti yang dikatakan oleh orang-orang Umbraton, Indigo Guild awalnya hanyalah sebuah guild kosong, tetapi bukan gaya pendirinya untuk menolak uang, jadi mengapa tidak menjalankannya seperti guild yang sebenarnya?",
  str_item_3001019 = "Energi Auspicious",
  str_item_intro_3001019 = "Energi Auspicious yang diperoleh dari transaksi moneter dan keuangan komersial dapat digunakan untuk meningkatkan Feng Shui dan membasmi kejahatan.",
  str_item_3001021 = "Silver Wreath",
  str_item_intro_3001021 = "Karangan bunga cabang zaitun melambangkan kemenangan dan perdamaian. Dapat ditukarkan dengan hadiah di Dream - A Thousand-Year Vigil - Northwind Market.",
  str_item_get_3001021 = "Mimpi - Pengawalan Seribu Tahun",
  str_item_3001022 = "Koin Pengamat",
  str_item_intro_3001022 = "Koin Perunggu yang dibuat untuk merayakan kemenangan Legiun Northwind. Dapat ditukarkan dengan hadiah di Dream - A Thousand-Year Vigil - Pasar Northwind.",
  str_item_get_3001022 = "Mimpi - Pengawalan Seribu Tahun",
  str_item_3001023 = "Akal",
  str_item_intro_3001023 = "Sebagai kunci untuk membantu seseorang menjaga rasionalitas dan kejelasan, benda ini akan terpakai selama eksplorasi tetapi dapat secara bertahap kembali terisi seiring waktu.",
  str_item_get_3001023 = "Pemulihan otomatis dari waktu ke waktu",
  str_item_3001024 = "Telinga Gandum Harum",
  str_item_intro_3001024 = "Aroma menghibur dari gandum, yang melambangkan janji untuk masa depan yang cerah, adalah pengingat konstan bagi jiwa dalam pedang—jangan pergi dulu. Akumulasi untuk meningkatkan level Jiwa Pedang.",
  str_item_3001025 = "Fragmen Kuil",
  str_item_intro_3001025 = "Dengan hentakan keras, satu sisi kuil runtuh, mengubah batu-batu yang diukir dengan rumit dan bejana berharga yang ditawarkan di dalamnya menjadi serpihan-serpihan. Namun, serpihan-serpihan ini masih memiliki beberapa nilai.",
  str_item_3001026 = "Permen Meletup Pop Rocks",
  str_item_intro_3001026 = "Sebuah permen aneh yang dibuat dari tanaman langka. Dapat digunakan untuk ditukar dengan hadiah di Dream - Weird & Wacky Foodie Paradise - Delicacy Delivery.",
  str_item_get_3001026 = "Dream - Panggung Surga Makanan Aneh & Aneh",
  str_item_3001027 = "Cream Wood",
  str_item_intro_3001027 = "Jenis kayu khusus yang dipanen dari pohon-pohon di Hutan Cream. Dapat digunakan untuk ditukar dengan hadiah di Dream - Weird & Wacky Foodie Paradise - Delicacy Delivery.",
  str_item_get_3001027 = "Dream - Panggung Surga Makanan Aneh & Aneh",
  str_item_3001028 = "Akal",
  str_item_intro_3001028 = "Sebagai kunci untuk membantu seseorang menjaga rasionalitas dan kejelasan, benda ini akan terpakai selama eksplorasi tetapi dapat secara bertahap kembali terisi seiring waktu.",
  str_item_get_3001028 = "Pemulihan otomatis dari waktu ke waktu",
  str_item_3001029 = "Hati yang Dicintai",
  str_item_intro_3001029 = "Sebuah produk dari kepedulian dan panggilan Pact yang tak tertutupi... Meskipun Hunting Stone tidak pernah memintanya. Kumpulkan lebih banyak untuk meningkatkan level Hunting Stone.",
  str_item_3001030 = "Peralatan Makan Mewah",
  str_item_intro_3001030 = "Sebuah karya seni yang indah yang dibuat oleh seorang maestro. Dapat digunakan untuk membuat hidangan berkualitas tinggi menjadi lebih menarik.",
  str_item_3001031 = "Lencana Phospherus",
  str_item_intro_3001031 = "Sebuah lencana Illumina kuno, barang koleksi yang sangat berarti. Medali itu sendiri tidak berharga, tetapi telah menjadi harta yang tak ternilai karena kejayaan pahlawan yang memperolehnya. Memberikan medali seperti itu kepada seorang pahlawan hanyalah tanda kecil rasa terima kasih. Dapat ditukarkan dengan hadiah barang di Dream - Evanescing Night By Starlight - Dream Distribution.",
  str_item_get_3001031 = "Mimpi: Malam yang Menghilang oleh Cahaya Bintang",
  str_item_3001032 = "Voucher Illumina",
  str_item_intro_3001032 = "Voucher yang populer di Illumina. Poin diperoleh tergantung pada durasi kerja dan layanan, yang dapat digunakan untuk menukarkan berbagai sumber daya. Dapat ditukarkan dengan hadiah item di Dream - Evanescing Night By Starlight - Dream Distribution.",
  str_item_get_3001032 = "Mimpi: Malam yang Menghilang oleh Cahaya Bintang",
  str_item_3001033 = "Akal",
  str_item_intro_3001033 = "Sebagai kunci untuk membantu seseorang menjaga rasionalitas dan kejelasan, benda ini akan terpakai selama eksplorasi tetapi dapat secara bertahap kembali terisi seiring waktu.",
  str_item_get_3001033 = "Pemulihan otomatis dari waktu ke waktu",
  str_item_3001034 = "Peluit",
  str_item_intro_3001034 = "Prajurit sangat terbiasa dengan suara peluit yang nyaring sehingga mereka sebenarnya tidak bisa merasa aman tanpanya. Kumpulkan cukup banyak untuk meningkatkan level Sharpened Round.",
  str_item_3001035 = "Permainan perang",
  str_item_intro_3001035 = "Bentuk hiburan langka di Illumina, mempertahankan elemen pertempuran. Gim perang yang luar biasa ini menyampaikan hati dari penciptanya.",
  str_item_3001036 = "Pembatas Buku Bunga Kering",
  str_item_intro_3001036 = "Sebuah pembatas buku buatan sendiri yang digunakan gadis itu saat membaca. Ditemani bunga, dia membuka berbagai buku dongeng, mencari jejak masa lalunya yang terfragmentasi. Dapat digunakan untuk menukar hadiah di Dream - Through the Looking Glass Winter Sonnet - Pasar Tanpa Nama.",
  str_item_get_3001036 = "Mimpi - Melalui Cermin Sonnet Tahap Musim Dingin",
  str_item_3001037 = "Shard Mirror",
  str_item_intro_3001037 = "Kepingan ini adalah perpanjangan dari kekuatan cermin ajaib, dan di dalamnya terletak esensi struktur dunia cermin. Setiap bagian membentuk domain yang retak kecil. Dapat digunakan untuk ditukar dengan hadiah di Dream - Through the Looking Glass Winter Sonnet - Pasar Tanpa Nama.",
  str_item_get_3001037 = "Mimpi - Melalui Cermin Sonnet Tahap Musim Dingin",
  str_item_3001038 = "Akal",
  str_item_intro_3001038 = "Sebagai kunci untuk membantu seseorang menjaga rasionalitas dan kejelasan, benda ini akan terpakai selama eksplorasi tetapi dapat secara bertahap kembali terisi seiring waktu.",
  str_item_get_3001038 = "Pemulihan otomatis dari waktu ke waktu",
  str_item_3001039 = "Mirror Dimension Blossom",
  str_item_intro_3001039 = "Kekuatan Nikinis seringkali muncul dalam bentuk bunga, dan Dimensi Cermin tidak terkecuali.",
  str_item_3001040 = "Koleksi Dongeng Northland",
  str_item_intro_3001040 = "Nikinis sedang mencari ingatan yang hilangnya, dan meskipun mencari bantuan dari orang lain, dia tidak pernah menyerah pada petunjuk di dalam dirinya sendiri.",
  str_item_not_enough_plm = "Buah Firethorn tidak mencukupi",
  str_item_3751396 = "Lingkaran Hitam di Balik Kacamata Hitam",
  str_item_3751397 = "Gadis Gereja di Twilight",
  str_item_3751551 = "Kesulitan Grand Marshal Baru",
  str_item_intro_3751396 = "Semoga cahaya menyinari Senja, menghalau bayang-bayang yang tertinggal di sana.",
  str_item_intro_3751397 = "Lingkaran hitam? Tidak sama sekali.",
  str_item_intro_3751551 = "Bisakah kita mengobrol tanpa membahas laporan pekerjaan?",
  str_item_3000131 = "Suar Bintang Spesial Simfoni Senja",
  str_item_intro_3000131 = [[
