Item ini akhirnya akan kedaluwarsa dan tidak akan diubah menjadi item lain; harap ingat untuk menggunakannya sebelum berakhirnya acara rekrutmen eksklusif Twilight Symphony.]],
  str_item_10000992 = "Kleken Kotak Bersatu",
  str_item_intro_10000992 = "Memungkinkan Kleken untuk bergabung dalam petualangan Anda.",
  str_item_1000099 = "Kleken Kotak Bersatu",
