  str_item_3661219 = "Potret Ksatria Fiat",
  str_item_intro_3661219 = [[
Item furnitur. Bisa diletakkan di ruang-ruang di Colossus-mu.
Sebuah potret yang dibuat dengan gambar Irridon saat masih menjadi seorang ksatria, tampaknya merupakan hadiah yang tidak bisa disampaikan oleh seorang gadis kecil.
"Lady Irridon, saya dengan tulus mengucapkan terima kasih atas bantuan dan perhatian yang terus-menerus. Saya berharap Anda akan terus memegang teguh nilai-nilai keadilan dan kasih sayang, membimbing Lumopolis menuju masa depan yang lebih cerah."]],
  str_item_3661220 = "Potret Biarawati Polos",
  str_item_intro_3661220 = [[
Item furnitur. Bisa diletakkan di ruangan-ruangan di Colossus-mu.
Sebuah potret yang dibuat dengan gambar Paloma saat ia masih menjadi seorang biarawati, tampaknya merupakan hadiah yang tidak bisa diberikan oleh seorang ayah.
"Pam, semoga kamu selalu tetap polos dan baik hati, dan semoga keluarga kita selalu menemukan kebahagiaan."]],
  str_item_3751039 = "Tekad yang Teguh",
  str_item_3751040 = "Akhir Cahaya",
  str_item_3751041 = "Himne Kemenangan",
  str_item_3751398 = "Dahaga akan Pengetahuan",
  str_item_3751399 = "Kekuatan Guardian",
  str_item_3751400 = "Apa katamu?",
  str_item_intro_3751039 = [[
Membuka avatar yang sesuai.
"Denier, Reinhardt... Apapun yang terjadi, semoga kita masing-masing menemukan jalan kita sendiri."]],
  str_item_intro_3751040 = "Membuka avatar yang sesuai.\n\"Saya tidak berniat dan tidak tertarik untuk membuat musuh—Mereka hanya penghalang di jalan saya.\"",
  str_item_intro_3751041 = "Membuka avatar yang sesuai.\n\"Pencerahan Illumina bisa menjadi siapa saja—kamu, aku, siapa pun—selama mereka membimbing Aurorian melalui tantangan.\"",
  str_item_intro_3751398 = [[
Membuka avatar yang sesuai.
"Oh, langit malam... itu seperti perpustakaan yang tak terbatas, menyimpan semua rahasia dunia."]],
  str_item_intro_3751399 = [[
Membuka kunci Avatar yang sesuai.
"Mungkin suatu hari nanti, aku bisa benar-benar menguasai kekuatan ini yang diberikan takdir dengan keahlian."]],
  str_item_intro_3751400 = [[
