Beberapa legenda mengatakan bahwa jika Anda duduk di atasnya, itu akan terbang tinggi ke udara. Darimana kira-kira ide seperti itu bisa muncul?]],
  str_item_5234055 = "Hiasan Perahu",
  str_item_intro_5234055 = "Sebuah perahu kecil berwarna cerah, didirikan tegak dan digunakan sebagai dekorasi. Dapatkah sekadar melihatnya benar-benar menginspirasi keinginan untuk berlayar ke negeri yang jauh?",
  str_item_3661052 = "Kunang-Kunang Sementara",
  str_item_intro_3661052 = [[
