Hanya bisa mengapung di udara dan sama sekali tidak bisa bergerak... Jadi, apa fungsinya? Untuk menggantung barang? Pegangan tangan?]],
  str_item_3000338 = "Peninggalan Kuno",
  str_item_intro_3000338 = "Fragmen dari relik kuno yang tersebar di seluruh negeri selama bertahun-tahun. Jika ada seseorang yang mau mengakui nilai mereka, mereka mungkin juga bersedia membayar sejumlah kompensasi untuk mendapatkannya.",
  str_item_3751401 = "Brock's Basketball",
