"Harap berikan dengan hati-hati kepada penerima, atau cintamu mungkin akan menghilang ke langit."]],
  str_item_3661222 = "Potret Gadis Klarinet",
  str_item_3661223 = "Potret Queen Aqua",
  str_item_intro_3661222 = [[
Item furniture. Bisa ditempatkan di ruangan-ruangan di Colossus-mu.
Item ini awalnya diproduksi sebagai teko khusus untuk kedai kopi, tetapi tidak mendapatkan ulasan yang baik karena desainnya yang membuat air keluar dari mulutnya.
"J-Jangan gunakan penampilanku untuk sesuatu seperti ini!"]],
  str_item_intro_3661223 = [[
