Sebuah potret indah sang ratu, diukir untuk mengurangi beratnya. Seseorang menyarankan bahwa desain ini bisa digunakan untuk mengembangkan wadah untuk jus Fluorophora, tetapi sang ratu menolaknya dengan tegas.
"Ugh, kenapa... ini selalu terjadi pada diriku...?"]],
