  str_item_5234056 = "Halaman Tenang",
  str_item_intro_5234056 = "Tempat yang indah untuk mendinginkan diri dan beristirahat. Kamu bisa datang ke sini jika merasa terganggu oleh sesuatu.",
  str_item_3000344 = "Guci Koleksi",
  str_item_intro_3000344 = "Berapa banyak lagi yang harus kumpulkan sebelum aku bisa berhenti...?",
  str_item_3000345 = "Voucher Seru",
  str_item_intro_3000345 = "Voucher undian yang tampak biasa ini, dibuat oleh Guild Umbraton, merupakan mata uang yang ditetapkan untuk permainan Blind Box Surprise.",
