  str_item_intro_3661229 = [[
Item furnitur. Bisa ditempatkan di ruangan-ruangan di Colossus-mu.
Di kapal keberuntungan yang orang Longzhou lepaskan ke laut, banyak harapan yang tertanam. Misalnya, koin tembaga dan cermin yang tertanam di sambungan menciptakan tata letak Tujuh Bintang mengikuti Bulan, melambangkan keberuntungan dan perjalanan yang makmur. Meskipun ini hanyalah model yang dibuat oleh Xuan Ji, tidak mengurangi detail yang diperlukan dan harapan yang tulus.]],
  str_item_3763035 = "Elixir Penyembuhan",
  str_item_intro_3763035 = [[
