Mampu menahan abrasi dan erosi dari air laut, dengan harapan suatu hari nanti dapat muncul kembali di daratan.]],
  str_item_3751408 = "Undangan dari Xuan Ji",
  str_item_intro_3751408 = [[
Membuka Avatar yang sesuai.
"Caelestite memiliki beberapa keyakinan yang mirip dengan orang-orang dari negeriku. Apakah kamu tertarik untuk mengunjungi Ye untuk pertukaran budaya?"]],
  str_item_3751556 = "Mekanisme Tembagaforge",
  str_item_intro_3751556 = [[
