  str_item_3751561 = "Gosokan Harimau",
  str_item_3751562 = "Tidak Pedas",
  str_item_3751563 = "Ringan",
  str_item_3751564 = "Sedang",
  str_item_3751565 = "Astra Pedas",
  str_item_intro_3751561 = [[
