  str_item_intro_3751563 = [[
Membuka avatar yang sesuai.
"Orang-orang Ye suka dengan hidangan pedas. Meskipun ultra pedas sedikit terlalu banyak untuk Dantang, dia adalah koki yang hebat dan dapat memahami keindahan rasa ini."]],
  str_item_intro_3751564 = [[
