"Kamu harus selalu makan dengan cara yang elegan! Carleen terus mengingatkan dirinya sendiri bahwa dia tidak boleh melupakan etiket makan malam Lumo Knights hanya karena rangsangan di mulutnya."]],
  str_item_intro_3751565 = [[
Membuka kunci avatar yang sesuai.
"Ahhhhhhhhh! Pedas Astra! Itu adalah hal pertama yang dikatakan jalak setelah memakan saus cabai."]],
