  str_item_9997045 = "Daybreak Dish",
  str_item_9997046 = "Stun Crystal",
  str_item_9997047 = "Magic Lumina Box",
  str_item_intro_9997004 = "Mengisi ulang Bandage di medan saat pertempuran dimulai.",
  str_item_intro_9997005 = "Memberikan perisai sebesar 20% dari Max HP yang berlangsung selama 2 putaran di awal pertempuran.",
  str_item_intro_9997008 = "Memulihkan HP menjadi 30% di awal pertempuran jika HP saat ini lebih rendah dari 30%.",
  str_item_intro_9997009 = "Kehilangan 7% HP saat ini di awal setiap putaran. Setelah itu, memberikan kerusakan sebesar 150% dari ATK rata-rata tim ke musuh dalam 2 cluster sekitarnya.",
  str_item_intro_9997010 = "Meningkatkan kerusakan Skill Aktif Aurorian sebesar 50%. Kehilangan 8% HP saat ini setiap kali Skill Aktif digunakan.",
  str_item_intro_9997011 = "Meningkatkan kerusakan Chain Combo hingga 40% sesuai dengan persentase HP yang hilang oleh sekutu.",
  str_item_intro_9997012 = "Meningkatkan kerusakan Aurorian sebesar 20% saat HP saat ini lebih tinggi dari 70%.",
  str_item_intro_9997013 = "Ketika menyerang 3 atau lebih musuh secara bersamaan, melemparkan petir yang menyerang semua musuh, menimbulkan damage sebesar 100% dari ATK rata-rata tim.",
  str_item_intro_9997014 = "Menghasilkan 1 ubin berwarna secara acak di lapangan pada awal setiap putaran.",
  str_item_intro_9997015 = "Ketika menghapus setidaknya 15 ubin sekaligus dengan sekali ketuk, meningkatkan kerusakan Chain Combo Aurorian sebesar 30%. Chain Combo tidak dapat dilepaskan jika kurang dari 8 ubin dihapus sekaligus.",
  str_item_intro_9997016 = "Semakin dekat mereka dengan musuh, semakin tinggi damage Chain Combo Aurorian, meningkat hingga 20%.",
  str_item_intro_9997017 = "Semakin jauh jaraknya dari musuh, semakin tinggi damage Chain Combo Aurorian, meningkat hingga 30%.",
  str_item_intro_9997018 = "Detonator Aurorian memiliki peluang 30% untuk melepaskan Chain Combo 1 kali tambahan.",
  str_item_intro_9997019 = "Meningkatkan jumlah target Chain Combo Sniper Aurorian sebanyak 1.",
  str_item_intro_9997020 = "Supporter Aurorians +25% regeneration effects from Chain Combos and Active Skills in battle.",
  str_item_intro_9997021 = "Di awal pertempuran, mengurangi cooldown Skill Aktif Aurorian Converter sebanyak 1.",
  str_item_intro_9997023 = "Ketika Active Skills atau Chain Combo Skills yang dikeluarkan oleh Aurorian menimbulkan kerusakan, ada kemungkinan 30% untuk segera mengakhiri efek Poisoned/Burning/Bleeding pada target sekali.",
  str_item_intro_9997024 = "Semua damage yang diterima oleh musuh yang terkena debuff atau efek debuff meningkat sebesar 20%.",
  str_item_intro_9997025 = "Mengalahkan musuh dengan HP di bawah 7%.",
  str_item_intro_9997026 = "Setelah mengetuk untuk menghapus ubin, jika Aurorian belum melakukan Chain Combo di putaran ini, mengurangi cooldown dari semua Skill Aktif Aurorian sebanyak 1.",
  str_item_intro_9997027 = "Mengonversi persentase penyembuhan berlebih Aurorian menjadi satu tumpuk Shield yang bertahan selama 1 putaran.",
  str_item_intro_9997028 = "Ketika musuh yang terkena Poisoned/Burning/Bleeding dikalahkan, memberikan 1 tumpukan Poisoned pada musuh acak lainnya di medan perang.",
  str_item_intro_9997029 = "Mengurangi jumlah tile yang perlu dihapus untuk mengaktifkan skill dukungan faksi sebanyak 5.",
  str_item_intro_9997030 = "Saat Aurorian menggunakan Skill Aktif, mengurangi cooldown Skill Aktif Aurorian yang memiliki ikatan dengannya sebanyak 1.",
  str_item_intro_9997031 = "Mengurangi cooldown dari Skill Aktif pertama yang digunakan dalam pertempuran sebanyak 2.",
  str_item_intro_9997033 = "Sebuah indikator muncul secara acak di medan perang pada awal setiap ronde. Setelah menghancurkan indikator ini, kerusakan Chain Combo meningkat sebesar 25% pada ronde ini.",
  str_item_intro_9997035 = "Aurorian mendapatkan 2% Life Drain saat memberikan damage dan kehilangan 15% dari HP saat ini di awal setiap putaran.",
  str_item_intro_9997003 = "Memulihkan 10% dari Max HP setelah memenangkan pertempuran.",
  str_item_intro_9997006 = "Meningkatkan Max HP semua Aurorian sebesar 3% setelah memenangkan pertempuran.",
  str_item_intro_9997007 = "Meningkatkan DEF semua Aurorian sebesar 1,5% setelah memenangkan pertempuran.",
  str_item_intro_9997032 = "Meningkatkan ATK semua Aurorian sebesar 1% setelah memenangkan pertempuran.",
  str_item_intro_9997022 = "Jumlah total putaran +10 saat mendapatkan item ini. ",
  str_item_intro_9997036 = "Ketika mengetuk untuk menghapus ubin, ada peluang 25% untuk meningkatkan jumlah percobaan penghapusan sebanyak 1.",
  str_item_intro_9997037 = "Saat mengetuk untuk menghapus tile, secara acak memberikan 1 tumpukan Poisoned, Bleeding, atau Burning pada musuh yang berada dalam jangkauan tile yang dihapus.",
  str_item_intro_9997038 = "Ketika mengetuk untuk menghapus ubin, memberikan kerusakan sebesar 120% dari ATK rata-rata tim kepada musuh yang berada dalam jangkauan ubin yang dihapus.",
  str_item_intro_9997034 = "Musuh menerima kerusakan sebesar 150% dari ATK rata-rata tim untuk setiap tile yang mereka tempuh di dalam area ubin yang telah diketuk dan akan dihapus pada putaran ini.",
  str_item_intro_9997039 = "Di awal pertempuran, 1 Gear Caelestite Spesial acak dapat digunakan sekali.",
  str_item_intro_9997040 = "Dapatkan Perlengkapan Caelestite Spesial: Mengonversi 2 ubin yang dipilih menjadi ubin berwarna. Ini dapat digunakan sekali setiap 60 ubin yang dihapus.",
  str_item_intro_9997041 = "Dapatkan Gear Caelestite Khusus: Memilih area 3x3 dan menghapus semua ubin Biru di dalamnya. Ini dapat digunakan sekali setiap 50 ubin yang dihapus.",
  str_item_intro_9997042 = "Dapatkan Gear Caelestite Khusus: Memilih area 3x3 dan menghapus semua ubin Merah di dalamnya. Ini dapat digunakan sekali setiap 50 ubin yang dihapus.",
  str_item_intro_9997043 = "Dapatkan Gear Caelestite Khusus: Pilih area 3x3 dan hapus semua Tile Hijau di dalamnya. Ini dapat digunakan sekali setiap 50 tile yang dihapus.",
  str_item_intro_9997044 = "Dapatkan Perlengkapan Caelestite Khusus: Pilih area 3×3 dan hapus semua Tile Kuning di dalamnya. Ini dapat digunakan sekali setiap 50 tile yang dihapus.",
  str_item_intro_9997045 = "Dapatkan Perlengkapan Caelestite Spesial: Mengatur ulang semua ubin di medan perang. Ini dapat digunakan sekali setiap 80 ubin yang dihapus.",
  str_item_intro_9997046 = "Dapatkan Gear Caelestite Spesial: Pilih 1 warna dan atur ulang semua ubin dengan warna ini dari medan perang. Ini dapat digunakan sekali setiap 80 ubin yang dihapus.",
  str_item_intro_9997047 = "Dapatkan Gear Caelestite Khusus: Pilih 1 tile dan hapus 4 tile terdekat dengan warna yang sama. Ini dapat digunakan sekali setiap 60 tile yang dihapus.",
  str_item_rpintro_9997004 = "Tambahan untuk ramuan pemulihan yang membantu menyembuhkan luka.",
  str_item_rpintro_9997005 = "Senjata klasik era kuno yang berukir simbol sakral dan sangat efektif melawan musuh yang lincah.",
  str_item_rpintro_9997008 = "Patung yang terawat dengan sempurna ini memberikan kekuatan penyembuhan bagi pemiliknya.",
  str_item_rpintro_9997009 = "Produk zaman dahulu yang mengutuk pengguna sekaligus memberikan kekuatan yang setara sebagai imbalannya.",
  str_item_rpintro_9997010 = "Dengar-dengar, ini adalah item misterius dari perang besar terdahulu. Item ini membawa kutukan kuat hingga sanggup melukai lawan.",
  str_item_rpintro_9997011 = "Kenakan ini untuk mengubah penderitaan menjadi kekuatan dan, pada akhirnya, meraih kemenangan.",
  str_item_rpintro_9997012 = "Bawalah, maka kamu akan dilindungi oleh Dewi Kemenangan sehingga bisa memenangkan semua pertempuran.",
  str_item_rpintro_9997013 = "Pedang tersohor dari zaman dahulu, diliputi kekuatan guntur. Auranya yang menggentarkan terpancar saat dihunus.",
  str_item_rpintro_9997014 = "Permata yang memancarkan semua warna, sangat indah dan selalu berubah.",
  str_item_rpintro_9997015 = "Pedang besar zaman dahulu yang ketika dipegang, kamu bisa merasakan kekuatan di dalam diri bertambah.",
  str_item_rpintro_9997016 = "Senjata klasik era kuno yang berukir simbol sakral dan sangat efektif melawan musuh yang lincah.",
  str_item_rpintro_9997017 = "Senjata klasik era kuno yang berukir simbol sakral dan sangat efektif melawan musuh yang lincah.",
  str_item_rpintro_9997018 = "Pedang pendek tajam yang terbuat dari superalloy kuno.",
  str_item_rpintro_9997019 = "The lenses glow in battle, blinding the opponent while protecting the wearer from it. Auxiliary equipment.",
  str_item_rpintro_9997020 = "Cat zaman dahulu yang mampu menyerap Lumina.",
  str_item_rpintro_9997021 = "Old-era creation that seems very pretty but carries terrifying power, dropping enemies like falling flowers with explosions.",
  str_item_rpintro_9997023 = "Relik dari zaman kuno, mungkin sangat terkutuk. Pemakainya dapat meluncurkan serangan beracun yang mematikan.",
  str_item_rpintro_9997024 = "Pedang kuno yang terkenal. Penggunanya bisa merasakan kekuatan setara dengan dewa.",
  str_item_rpintro_9997025 = "Bisa merasakan energi kehidupan musuh dan, saat dipegang erat, bisa mengakhiri nyawa orang yang sekarat.",
  str_item_rpintro_9997026 = "Sabuk yang sangat pas di tubuh yang memberikan pemakai Lumina yang diperlukan saat diaktifkan di bawah persyaratan tertentu.",
  str_item_rpintro_9997027 = "Perangkat tidak dikenal dari zaman dahulu yang bisa merasakan dan mengubah Lumina yang meluap menjadi medan kekuatan pelindung bagi penggunanya.",
  str_item_rpintro_9997028 = "Konon item terkutuk yang dibuat oleh seorang kesatria perkasa untuk memastikan semua musuh binasa.",
  str_item_rpintro_9997029 = "Jimat zaman dahulu, bisa menyimpan sedikit Lumina untuk menimbulkan damage besar terhadap musuh.",
  str_item_rpintro_9997030 = "Item zaman dahulu untuk menghasilkan kembali sejumlah Lumina bagi Aurorian yang terikat.",
  str_item_rpintro_9997031 = "Gunakan barang zaman dulu ini untuk segera mengembalikan sebagian Lumina yang hilang.",
  str_item_rpintro_9997033 = "Perangkat untuk menyimpan dan menambah Lumina.",
  str_item_rpintro_9997035 = "Pedang besar yang menakutkan. Tampaknya digunakan dalam duel kematian di zaman kuno. Saat dihunus, akan terjadi pertumpahan darah.",
  str_item_rpintro_9997003 = "Lilin yang memancarkan sinar hangat yang bisa menyembuhkan Aurorian yang terluka.",
  str_item_rpintro_9997006 = "Patung kecil kuno yang hilang, terbuat dari bahan bermutu tinggi. Tahan lama, ringan, dan membawa berkat bagi mereka yang membawanya.",
  str_item_rpintro_9997007 = "Shield kuno dari zaman kuno, bentuknya oval sempurna dan konon diisi dengan kekuatan matahari untuk menangkis semua serangan mematikan.",
  str_item_rpintro_9997032 = "Emblem dari zaman dulu dengan cetak biru menakjubkan untuk menampung sedikit Lumina dan meningkatkan daya tempur.",
  str_item_rpintro_9997022 = "Kantong tidur yang hilang dan terlupakan. Membantu memulihkan kekuatan.",
  str_item_rpintro_9997036 = "Sepertinya ditulis oleh kaum intelektual zaman dahulu, dan berisi detail tentang perbedaan Element Counter Effect dan saran strategi yang efektif.",
  str_item_rpintro_9997037 = "Lukisan kuno yang dibuat oleh pelukis tak dikenal dan menggambarkan keganasan wabah. Sang seniman turut meninggal saat pandemi itu. Setelahnya, lukisan tersebut dihinggapi kekuatan mengerikan...",
  str_item_rpintro_9997038 = "Senjata yang sepertinya bisa menyatu dengan Lumina dengan sempurna... Ini memang langka...",
  str_item_rpintro_9997034 = "Old-time item created specifically to deal with pursuers. Leaves Lumina on the trail that detonates later to kill the pursuers.",
  str_item_rpintro_9997039 = "Koin kuno misterius yang terkadang menambah kecepatan Aurorian yang memilikinya, sehingga mereka menjadi lebih gesit.",
  str_item_rpintro_9997040 = "Anggrek merah langka yang khusus dibudidayakan pada zaman dahulu. Selalu muncul, mekar, dan layu berpasangan. Sepertinya membentuk ikatan dengan penggunanya dan membantu dalam pertempuran.",
  str_item_rpintro_9997041 = "Colossus miniatur yang tampaknya berasal dari zaman kuno dan membantu pemiliknya dalam pertempuran.",
  str_item_rpintro_9997042 = "Colossus miniatur yang tampaknya berasal dari zaman kuno dan membantu pemiliknya dalam pertempuran.",
  str_item_rpintro_9997043 = "Colossus miniatur yang tampaknya berasal dari zaman kuno dan membantu pemiliknya dalam pertempuran.",
  str_item_rpintro_9997044 = "Colossus miniatur yang tampaknya berasal dari zaman kuno dan membantu pemiliknya dalam pertempuran.",
  str_item_rpintro_9997045 = "Item zaman dahulu yang membuat ikatan misterius antara dua petarung.",
  str_item_rpintro_9997046 = "Kristal kasar dengan permukaan agak retak yang menandakan Lumina berlebih di dalamnya. Sentuhan lembut saja bisa melepaskan cukup banyak Lumina untuk mengakibatkan stun pada musuh dalam pertempuran.",
  str_item_rpintro_9997047 = "Teknologi zaman kuno. Walau ukurannya kecil, item ini mampu menyimpan banyak Lumina.",
  str_item_3000349 = "Token Cloudrover",
  str_item_intro_3000349 = "Sebuah token yang dapat ditukarkan dengan manfaat dari Cloudrover Guild. Hanya pelanggan setia yang memiliki kesempatan untuk mendapatkan ini.",
  str_item_3000134 = "Avaricious Lachesis Special Star Flare",
  str_item_intro_3000134 = [[
Dapat digunakan untuk merekrut satu kali dari perekrutan eksklusif saat ini.
Item ini akan kedaluwarsa, jadi harap gunakan sebelum akhir perekrutan eksklusif Avaricious Lachesis saat ini, atau item ini akan hilang. Itu tidak akan diubah menjadi item lain ketika kedaluwarsa.]],
  str_item_3420133 = "Kit Rekrutmen 2,5 Tahun",
  str_item_intro_3420133 = "Pilih Aurorian dari daftar Aurorian bintang 6 berikut untuk bertarung di samping Anda: <color=#ffffff>Dantang, Zarya, Antony, Lorelei, Cena, Joshua, Schwartz: Almighty Clamor, Yingel, Leo, Hati, Tina, Leyn, Jeriah, Mu Yuebai, Zhong Xu, Vic, Axelia, Lilica, Minos, Pollux, Jeno, Fia, Carleen: Smoldering Soul, Nina, Barton: Deft Blades, Giles, Lenore, Azure, Yao, Amemori, Rinne, Florine, Ruby, Siobhan, Novio, Hedy, Bethel, Luke, Paloma, Gram, Revy, Smokey, Fleur, Beryl, Hiiro, Sinsa, Eve, Uriel, Carleen, Sharona, Sariel, Raphael, Connolly, Charon, Eicy, Victoria, Jona, Nikinis, Gabriel, Migard, Michael, Gronru, Irridon, Wrath.</color>.Catatan: Kit ini akan kedaluwarsa pada pukul 09:00, 28 Februari 2024 (UTC+0), 04:00, 28 Februari 2024 (UTC-5). Klaim tepat waktu, atau kit ini akan secara otomatis diubah menjadi 3.000 Lumamber dan dikirimkan kepada Anda melalui kotak surat dalam game Anda.",
  str_item_3661231 = "Takhta Bayangan",
  str_item_intro_3661231 = [[
Item furnitur. Bisa diletakkan di ruangan-ruangan di Colossus.
Guild Cloudrover secara khusus membuat kursi mewah dan dominan ini dari kulit yang kaku untuk Istvan. Karena ini adalah produk yang sangat gimmicky, tidak pernah kekurangan pembeli meskipun harganya mahal.]],
  str_item_3661232 = "Model Pesawat Cloudrover",
  str_item_intro_3661232 = [[
Item furniture. Bisa ditempatkan di ruangan-ruangan di Colossus-mu.
Mengingat popularitas Kapal Udara Cloudrover, destinasi satu atap yang memenuhi semua kebutuhan pariwisata, belanja, rekreasi, dan liburan Anda, wajar saja jika model kapal udara ini tersedia dalam berbagai ukuran untuk dibeli pelanggan. Meskipun model ini bukan yang terbesar, tetapi dibuat dengan kerajinan yang paling halus.]],
  str_item_3661233 = "Lampu Meriah",
  str_item_intro_3661233 = [[
Item furnitur. Bisa diletakkan di ruang-ruang di Colossus-mu.
Terangi ruangan gelap dengan barisan lampu berwarna ini. Semoga, cahaya redup mereka akan memberimu kehangatan di hari yang patut dirayakan ini.]],
  str_item_3661234 = "Kotak Hadiah Festif",
  str_item_intro_3661234 = [[
Item furnitur. Bisa diletakkan di ruang-ruang di Colossus-mu.
Para Aurorian telah memberikanmu hadiah yang penuh perhatian ini. Meskipun tidak bernilai banyak, nilai sebenarnya terletak pada kerja keras dan usaha yang diwakilinya. Semoga May hadiah ini membawamu keberuntungan di tahun yang akan datang.]],
  str_item_5234057 = "Kereta Es",
  str_item_intro_5234057 = "Sebuah kereta hias yang terbuat dari es. Penampilannya yang seperti kristal sangat menenangkan dan rileks.",
  str_item_3661236 = "Potret Pendekar Pedang Berganti Pakaian",
  str_item_3661237 = "Potret Pendekar Pedang Perahu",
  str_item_3661241 = "Kipas Bool",
  str_item_3661242 = "Lampu Tanaman",
  str_item_intro_3661236 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Karya seorang pengrajin, boneka ini dapat berubah menjadi pakaian acak lainnya dengan cepat hanya dengan menekan tombol. Dikatakan bahwa boneka ini terinspirasi oleh jenis seni pertunjukan dari Longzhou.
"Jika saya ingin memainkan peran sebagai orang dari Longzhou... apakah saya juga perlu belajar bagaimana mengubah pakaian saya secara instan seperti ini?"]],
  str_item_intro_3661237 = [[
Item furnitur. Bisa diletakkan di ruangan-ruangan di Colossus-mu.
Untuk memperingati kerjasama sukses dengan pendekar pedang, pengrajin membuat potret berdasarkan sikap pendekar pedang saat menyelesaikan sebuah quest.
"Kamu ingin meninggalkan kursi di sisi lain perahu kosong? Tentu, beri tahu saya kapan kamu ingin menambahkan seseorang di sana."]],
  str_item_intro_3661241 = [[
Item furnitur. Bisa ditempatkan di ruangan-ruangan di Colossus-mu.
Kipas ini digunakan secara eksklusif di laboratorium para ilmuwan Illumina. Kakinya bisa ditekuk dengan fleksibel atau ditempelkan ke permukaan. Beberapa orang mengatakan bahwa kipas ini terinspirasi oleh robot bernama Bool.]],
  str_item_intro_3661242 = [[
Item furnitur. Bisa diletakkan di ruangan-ruangan di Colossus-mu.
Sebuah lampu yang dirancang dengan indah yang memberikan tanaman cahaya yang mereka butuhkan untuk tumbuh dan menciptakan suasana hangat dan alami di dalam ruangan.]],
  str_item_3000352 = "Bulu Caelestite",
  str_item_intro_3000352 = "Bulu unik ini dikatakan sangat berharga bagi Caelestite.",
  str_item_3661243 = "Sofa Dumpling",
  str_item_3661244 = "Karya Seni Tahun Baru: Sang Naga",
  str_item_3661238 = "Dekorasi Petasan",
  str_item_3661239 = "Liontin Tahun Baru",
  str_item_3661240 = "Rak Antik",
  str_item_intro_3661243 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Sofa malas berbentuk siomay, dengan kotak suara yang pernah hidup dengan sorakan:
"Siomay, berbagai macam siomay!"
"Ayo kita semua membuat siomay bersama!"
Sekarang, perangkat suara telah dilepas oleh Aurorians yang lelah dengan kebisingan, mengembalikan ketenangan di dalam Colossus.]],
  str_item_intro_3661244 = [[
Item furnitur. Bisa diletakkan di ruangan-ruangan di Colossus.
Sebuah lukisan Tahun Baru dari Dragon Maiden, barang perayaan populer di Kerajaan Ji. Namun, "potret artistik" yang diberikan oleh Chen'ni ini adalah satu-satunya yang menggambarkan penampilan Dragon Maiden dengan akurat.]],
  str_item_intro_3661238 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Seiring mendekatnya festival tradisional Longzhou, untuk membiarkan teman-teman Longzhou kami di Colossus merasakan suasana pesta, semua orang di Colossus menggantung dekorasi petasan yang dibuat bersama, dengan harapan dapat mengusir kesialan dan mengundang keberuntungan.]],
  str_item_intro_3661239 = [[
Item furnitur. Bisa ditempatkan di ruangan-ruangan di Colossus-mu.
Saat ini menjadi barang terlaris di Teluk Twin Pavilions, ini adalah hiasan Longzhou yang wajib dimiliki saat perayaan, melambangkan harapan untuk masa depan yang cerah.]],
  str_item_intro_3661240 = [[
Item furnitur. Bisa ditempatkan di ruangan-ruangan di Colossus-mu.
Dibuat oleh pengrajin Twin Pavilions Bay, rak kayu ini diukir dengan rumit dan dirancang untuk penyimpanan sekaligus pengagungan, memperkaya ruangan di Colossus dengan sentuhan elegansi klasik.]],
  str_item_intro_3763039 = [[
Membuka bingkai avatar yang sesuai.
"Bunga persik yang lembut dan anggun, memancarkan keindahan mereka yang cemerlang. Dan keberuntungan datang, dalam pelukan mereka yang penuh semangat."]],
  str_item_intro_3751417 = [[
Membuka avatar yang sesuai.
"Caelestite menerima topi spesial sebagai hadiah Tahun Baru dan dengan senang hati memakainya!"]],
  str_item_intro_3751566 = [[
Membuka avatar yang sesuai.
"Chen'ni memberikan berkah, memberikan kekayaan dan kemakmuran!"
Apakah Sang Gadis Naga, yang dihormati sebagai dewi laut, benar-benar dapat memberikan kebahagiaan kepada dunia duniawi? Chen'ni mungkin tidak tahu, tetapi dia bertekad untuk mencoba!]],
  str_item_intro_3751567 = [[
Membuka avatar yang sesuai.
"Lidahku adalah standarnya!"
Sebagai utusan Astra, Navigator sangat berpengalaman dalam mencicipi makanan, dengan lidah yang sangat peka.]],
  str_item_intro_3763038 = [[
Membuka bingkai avatar yang sesuai.
"Kumpulkan semua Kartu Musim Semi untuk memanggil naga ilahi!"
Tidak yakin apakah ini benar, tetapi kegilaan mengumpulkan kartu ini membuat Tahun Baru Longzhou menjadi lebih menyenangkan.]],
  str_item_intro_3751413 = "Membuka avatar yang sesuai.\n\"Saya punya daftar panjang hal yang ingin saya lihat—baju besi mekanis raksasa di Azurite, pertunjukan ramai di gurun, pertarungan intens di bawah tanah...\"\nBahkan dewa pun memiliki banyak harapan untuk Tahun Baru.",
  str_item_intro_3751414 = [[
Membuka avatar yang sesuai.
Hati-hati dengan binatang Nian dari Umbraton, pemakan manusia dengan tanduk panjang! Lihat "Forbidden Temple Fair," film horor terbaru Alleywood, yang akan datang musim semi ini!
"Jadi... apa peran saya lagi...?"]],
  str_item_intro_3751415 = [[
Membuka avatar yang sesuai.
"Ini dia, hanya sesuatu yang saya buat... Saya bisa membuat hal lain selain es lilin, tahu!"
Satu-satunya hal yang berhasil dibuat Zarya setelah banyak kegagalan, dengan kelebihan manis untuk menunjukkan perasaannya.]],
  str_item_intro_3751416 = [[
Membuka avatar yang sesuai.
Berharap reuni hari ini memberikanmu rasa rumah dan kekuatan. Ini adalah langit yang sama di atas kita, di mana pun kita berada.]],
  str_item_intro_3751568 = [[
Membuka avatar yang sesuai.
"Meski banyak yang mengungkapkan kecintaan mereka padaku, aku menemukan Navigator paling spesial. Kita benar-benar memiliki koneksi hati ke hati!"]],
  str_item_intro_3751569 = [[
Membuka avatar yang sesuai.
"Tanda hati dengan tangan, serius?... Baiklah, terimalah gerakan ini dariku dan bersyukurlah... tapi jangan terlalu berlebihan!"]],
