  str_item_3751420 = "Hari Ksatria Mooncrown",
  str_item_3751419 = "Membentang Seribu Malam",
  str_item_3751570 = "Limbo yang Terbakar",
  str_item_3763040 = "Api Final",
  str_item_3751421 = "Hati Seribu Hari",
  str_item_3751422 = "Panah Lovedrop",
  str_item_intro_3751421 = [[
Membuka avatar yang sesuai.
"Navigator, ke sini!"
Cinta telah menjadi teman setia Anda dalam perjalanan ini selama seribu hari. Teruslah maju dengan berkat dari semua orang!]],
  str_item_intro_3751422 = [[
Membuka avatar yang sesuai.
"Rebutlah momen ini; hari ini bisa menjadi titik balik dalam takdir kita!"]],
  str_item_intro_3763041 = [[
Membuka bingkai avatar yang sesuai.
"Orang-orang yang teguh akan diberi hadiah kemuliaan!"
Terima kasih atas bimbingan dan perlindunganmu selama seribu hari ketekunan dan persahabatan. Menantikan petualangan bersama di masa depan.]],
  str_item_intro_3751420 = [[
Membuka avatar yang sesuai.
"Apakah kamu juga ingin berpartisipasi dalam uji coba spesial Hari Mooncrown?"]],
  str_item_intro_3751419 = [[
Membuka avatar yang sesuai.
Navigator, terima kasih telah menemani saya selama seribu hari di bawah langit ini. Tolong terus membimbing saya di masa depan!]],
  str_item_intro_3751570 = [[
Membuka avatar yang sesuai.
"Kamu ingin berada di Limbo bersamaku? Ambillah tanganku, dan biarkan harapan kita bersinar terang!"]],
  str_item_intro_3763040 = [[
Membuka bingkai avatar yang sesuai.
"Pakaianku akan terbakar saat ramuan habis. Akankah kamu mengikuti jejak terakhir api itu kepadaku?"]],
