  str_item_3751043 = "Hasil Training",
  str_item_3751044 = "Truth Bertahan",
  str_item_3751045 = "Wali dalam Perjalanan",
  str_item_3751046 = "Pesta Teh Biasa",
  str_item_3751047 = "Cerita Saya",
  str_item_3751048 = "Saudara-saudara dalam Persenjataan",
  str_item_3751573 = "Menyembunyikan Fox",
  str_item_3763042 = "Kerapu Atas",
  str_item_intro_3751042 = [[
Membuka avatar yang sesuai.
"Saya mengerti betapa beratnya jalan yang harus dilalui oleh seorang Navigator. Tetap semangat."]],
  str_item_intro_3751043 = [[
Membuka kunci avatar yang sesuai.
"Berhasil bertahan selama ini sungguh patut diacungi jempol. Mari kita terus berlatih bersama di masa depan!"]],
  str_item_intro_3751044 = [[
Membuka kunci avatar yang sesuai.
"Selalu ingat: tidak peduli bagaimana waktu berubah, kebenaran tetap bertahan."]],
  str_item_intro_3751045 = [[
Membuka kunci avatar yang sesuai.
"Dalam perjalanan yang akan datang, aku akan selalu menjagamu."]],
  str_item_intro_3751046 = [[
Membuka avatar yang sesuai.
"Berapa kali aku sudah mengajakmu minum teh sore?"]],
  str_item_intro_3751047 = [[
Membuka kunci avatar yang sesuai.
"Aku sudah berbagi ceritaku denganmu; bagaimana dengan ceritamu?"]],
  str_item_intro_3751048 = [[
Membuka avatar yang sesuai.
"Setelah begitu lama bersama, kita sudah seperti saudara sejati!"]],
  str_item_intro_3751573 = [[
Membuka kunci avatar yang sesuai.
"Sudah selesai bersembunyi?" "Belum."]],
  str_item_intro_3763042 = [[
Membuka bingkai avatar yang sesuai.
"Tampak agak familiar."]],
  str_item_intro_3751423 = [[
Membuka avatar yang sesuai.
"Ribbit! Ribbit!! Ribbit!!!"]],
  str_item_intro_3751424 = [[
Membuka avatar yang sesuai.
"Apa yang harus aku lakukan... Jawabannya selalu ada di hatiku?"]],
  str_item_3751423 = "Pangeran Teratai",
  str_item_3751424 = "Jawaban di Bawah Mercusuar",
  str_item_3440014 = "Tas Ajaib",
  str_item_intro_3440014 = "Aku hanya seekor katak miskin yang telah memberikan semua tabunganku seumur hidup untukmu.",
  str_item_intro_3440015 = "Hadiah yang ditawarkan dalam kantong keberuntungan super nilai seringkali menipu.",
  str_item_intro_3440016 = "Keberuntungan naik secara bertahap, sangat mirip dengan hidup saya.",
  str_item_intro_3440017 = "Tarik satu kali lagi; rasanya kita semakin dekat dengan hadiah yang dijamin.",
  str_item_intro_3440018 = "Ini adalah upaya terakhirku! Lalu aku hanya akan mengetuk Kembali, menutup layar, dan keluar dari permainan.",
  str_item_3751574 = "Memperkenalkan: Goldie sang Idola",
  str_item_intro_3751574 = [[
Membuka kunci avatar yang sesuai.
"Semua mata tertuju padanya; dia adalah lambang kesempurnaan dan kilauan, idola utama."]],
  str_item_3751425 = "Kelelahan Idola",
  str_item_intro_3751425 = [[
Membuka avatar yang sesuai.
"Uap! Aku merasa sangat mengantuk sejak aku mengganti ke piyama ini."]],
  str_item_3763043 = "Marshmallow yang Kuambil",
  str_item_intro_3763043 = [[
Membuka bingkai avatar yang sesuai.
"Figur anggun yang mempesona dengan bulu-bulu yang menggemaskan, memikat orang lain dalam jaringan pesonanya."]],
  str_item_3751572 = "Dimana Ayah",
  str_item_intro_3751572 = [[
Membuka kunci avatar yang sesuai.
"Ayah, tolong beri tahu saya lokasi Anda saat ini."]],
  str_item_3751571 = "Berkat Senyuman",
  str_item_intro_3751571 = [[
Membuka avatar yang sesuai.
"Saya memberikan komponen ini kepada Ayah, berharap ekspresinya sesuai dengan yang ditampilkan di layar."]],
  str_item_3751429 = "Halo Toto",
  str_item_intro_3751429 = [[
Membuka avatar yang sesuai.
"Halo, Toto! Colossus yang hangat melindungi setiap pekerja yang patah hati."]],
  str_item_3751430 = "Lencana dan Kehormatan",
  str_item_3751577 = "Skuad Eagleeye, berkumpul!",
  str_item_3751578 = "Konfeti Karnaval",
  str_item_3751579 = "Kekal Bersama",
  str_item_3763046 = "Berkat Besar",
  str_item_3763047 = "Koinobori",
  str_item_intro_3751430 = [[
Membuka avatar yang sesuai.
"Sangat baik. Saya tidak mencoreng kehormatan saya hari ini."]],
  str_item_intro_3751577 = [[
Membuka kunci avatar yang sesuai.
"Pandanganmu harus tajam seperti pandangan elang, seranganmu harus setajam cakarnya, dan gerakanmu harus secepat sayapnya yang bergerak."]],
  str_item_intro_3751578 = [[
Membuka kunci avatar yang sesuai.
"Ucapkan bersamaku: SELAMAT KARNAVAL!"]],
  str_item_intro_3751579 = [[
Membuka avatar yang sesuai.
"May semua hal di dunia ini berkontribusi pada terwujudnya keinginanmu untuk selama-lamanya."]],
  str_item_intro_3763046 = [[
Membuka bingkai avatar yang sesuai.
"Saya berharap segalanya berjalan sesuai keinginanmu. Saya berharap kamu tak terhentikan. Saya berharap kamu mencapai segala yang kamu inginkan. Saya berharap kamu selalu bertahan. Saya berharap kamu selalu bersamaku sehingga kita bisa berbagi lebih banyak momen bahagia bersama!"]],
  str_item_intro_3763047 = [[
Membuka bingkai avatar yang sesuai.
Banner totem yang populer di seluruh Pulau Cloud ini adalah simbol pertumbuhan dan keberanian.]],
  str_item_3751581 = "Menyentuh Sensasi",
  str_item_3751582 = "Nyam-Nyam",
  str_item_3751580 = "Pemilik Hidden Fangs",
  str_item_intro_3751581 = [[
Membuka Avatar yang sesuai.
"Oh, apakah ini... rasanya dicintai oleh seseorang?"]],
  str_item_intro_3751582 = [[
Membuka kunci Avatar yang sesuai.
"Satu gigitan lagi... Ya, satu gigitan lagi!"]],
  str_item_intro_3751580 = [[
Membuka avatar yang sesuai.
"Saya adalah pemilik Hidden Fangs di Umbraton. Selamat datang di dunia game!"]],
  str_item_3751436 = "Tatapan Bertekad",
  str_item_3751583 = "Api Pemberontakan",
  str_item_3751584 = "Tamu Kehormatan",
  str_item_3751585 = "Toast untuk Persahabatan Kita",
  str_item_3763048 = "Prospek Masa Depan Illumina",
  str_item_3763049 = "Kunci Makam Rahasia",
  str_item_intro_3751436 = [[
Membuka avatar yang sesuai.
"Sungguh indah memiliki kalian semua di sini!"]],
  str_item_intro_3751583 = [[
Membuka avatar yang sesuai.
"Kamu perlu menjadi lebih kuat. Lebih kuat dari Aurorian terkuat di dunia."]],
  str_item_intro_3751584 = [[
Membuka kunci avatar yang sesuai.
"Bahkan jika aku mati hari ini, aku masih ingin melihat wajah aslimu."]],
  str_item_intro_3751585 = [[
Membuka avatar yang sesuai.
"Mendekatinya sangat diterima, tetapi saya meminta agar Anda bersikap dengan sedikit lebih bermartabat. Lagipula, dia di sini atas permintaan saya."]],
  str_item_intro_3763048 = [[
Membuka bingkai avatar yang sesuai.
"Tapi jangan khawatir. Tidak ada yang bisa tetap sama, dan meskipun beberapa perubahan bisa sangat membebani kita, lebih sering daripada tidak, perubahan itu menarik."]],
  str_item_intro_3763049 = [[
Membuka bingkai avatar yang sesuai.
"Apakah seseorang dapat mengungkap rahasia yang dijaga oleh Kotak Hitam dengan cahaya lilin yang redup?"]],
  str_item_3751438 = "Wawasan Truth",
  str_item_3751586 = "Yang Diterangi Cahaya",
  str_item_3763050 = "Jalan Bersinar",
  str_item_intro_3751438 = [[
Membuka kunci avatar yang sesuai.
"Pencari kebenaran seperti mereka yang mengejar bintang jauh; mereka membutuhkan mata yang tulus untuk melihat cahaya."]],
  str_item_intro_3751586 = [[
Membuka avatar yang sesuai.
"Aku mengaku! Aku bertobat! Aku... Aku adalah orang yang diberkati oleh kebenaran."]],
  str_item_intro_3763050 = [[
Membuka bingkai avatar yang sesuai.
"May semoga Kebenaran memberkatimu, dan May hidupmu dari sekarang brilas terang."]],
