  str_item_3751593 = "Gilded Ular",
  str_item_3751592 = "Pembaca Sumpah",
  str_item_3751591 = "Claymore",
  str_item_intro_3751594 = [[
Membuka avatar yang sesuai.
"Sayap hitam membelah langit di atas Acheron seperti sebilah pedang yang tajam."]],
  str_item_intro_3751593 = [[
Membuka avatar yang sesuai.
"Entah itu bisnis atau hanya untuk bersenang-senang, dengan cukup emas, saya siap melayani Anda!"]],
  str_item_intro_3751592 = [[
Membuka avatar yang sesuai.
"Sumpah ribuan tahun yang lalu tidak boleh dilupakan. Sebuah tanda penghargaan dari klan Longinus, hanya diberikan kepada mereka yang menyelesaikan perjalanan seorang pahlawan sejati."]],
  str_item_intro_3751591 = "Membuka avatar yang sesuai.\n\"Tunjukkan tidak ada belas kasihan—pedangku di sini untuk menjaga cerita tentang bintang-bintang.\"",
  str_item_intro_3763052 = [[
Membuka bingkai avatar yang sesuai.
"Emas itu membutakan!"]],
  str_item_intro_3763053 = [[
Membuka bingkai avatar yang sesuai.
"Sayap hitam adalah penjaga sumpah yang berusia ribuan tahun."]],
  str_item_intro_3751444 = [[
Membuka avatar yang sesuai.
"Lihatlah para pesaing, sepenuhnya terlibat dan berjuang untuk peringkat mereka. Silakan nikmati permainan ini dan tunjukkan dukunganmu!"]],
  str_item_intro_3751443 = [[
Membuka avatar yang sesuai.
"Saya suka air dan senang berenang. Haruskah saya ikut kompetisi dan bersenang-senang dengan setiap orang?"]],
  str_item_intro_3751589 = [[
Membuka avatar yang sesuai.
"Aku ingin memiliki mimpi indah, di mana tidak ada kesedihan dan kebahagiaan berlangsung selamanya..."]],
  str_item_intro_3751426 = [[
Membuka kunci avatar yang sesuai.
"Apa ini? Sangat menyentuh..."]],
  str_item_intro_3751427 = [[
Membuka kunci avatar yang sesuai.
"Selamat kembali. Bagaimana petualanganmu? Apakah kamu melihat sesuatu yang sangat menarik?"]],
  str_item_intro_3751428 = [[
Membuka avatar yang sesuai.
"Ah, maaf telah membiarkanmu melihat sisi memalukan dari diriku. Aku akan pastikan untuk menjaga sikapku di lain waktu."]],
  str_item_intro_3751575 = [[
Membuka avatar yang sesuai.
"Menuju petualangan baru!"]],
  str_item_intro_3751576 = [[
Membuka avatar yang sesuai.
"Menghabiskan musim panas bersama teman adalah yang terbaik!"]],
  str_item_intro_3751587 = [[
Membuka kunci avatar yang sesuai.
"Karena kegigihan ini bisa menaklukkan daratan, menghadapi laut seharusnya bukan masalah... benar?"]],
  str_item_intro_3751588 = [[
Membuka avatar yang sesuai.
"Beep-beep, mengaktifkan mode navigasi air..."]],
  str_item_intro_3763044 = [[
Membuka bingkai avatar yang sesuai.
"Setiap orang yang mandi dalam cahaya ini akan merasa hati mereka menjadi lebih terang."]],
  str_item_intro_3763045 = [[
Membuka bingkai avatar yang sesuai.
"Datang ke Astra adalah kejutan paling mengejutkan musim panas ini!"]],
  str_item_intro_3763051 = "Membuka bingkai avatar yang sesuai.\n\"Sebuah ban renang yang modis yang membuat seseorang merindukan laut pada pandangan pertama. Jangan lewatkan musim panas yang singkat—bertindaklah cepat dan gunakanlah untuk merangkul musim ini!\"",
  str_item_3661248 = "Patung Pahlawan Kuno",
  str_item_3661249 = "Patung Prajurit Kuno",
  str_item_intro_3661248 = [[
Item furnitur. Bisa diletakkan di ruangan-ruangan di Colossus-mu.
Sebuah patung kuno, baru-baru ini ditemukan dan diidentifikasi sebagai prajurit sipil yang dihormati pada zaman dahulu berdasarkan pakaian dan penutup kepalanya. Para arkeolog mencatat bahwa hanya bangsawan yang memiliki hak untuk memesan patung mereka selama era itu, yang berarti dia pasti telah meraih prestasi luar biasa sehingga orang-orang menciptakan patung ini dalam penghargaan.
"Aku akan melindungi dunia yang dia cintai!"]],
  str_item_intro_3661249 = [[
Item furnitur. Bisa ditempatkan di ruangan-ruangan di Colossus-mu.
Sebuah patung kuno yang baru-baru ini ditemukan dan diidentifikasi sebagai seorang perwira tinggi dalam militer berdasarkan pakaian dan topinya. Para arkeolog mencatat bahwa perwira militer hampir seluruhnya berasal dari kelahiran bangsawan pada era tersebut. Jadi, tidak seperti patung prajurit sipil, patung ini kemungkinan besar berasal dari tangan seorang pematung yang berdedikasi melayani kaum bangsawan.
"Sisanya serahkan padaku; aku akan mengurusnya."]],
  str_item_3661250 = "Patung Fox Salju",
  str_item_3661251 = "Lilin Pinus",
  str_item_3661252 = "Rak Buku Robyn",
  str_item_3661253 = "Stereo Kolektor",
  str_item_3661254 = "Meja Rendah Santai",
  str_item_intro_3661250 = [[
Item furnitur. Bisa diletakkan di ruangan-ruangan di Colossus kamu.
Sebuah patung yang disukai oleh penduduk Northland, konon dibuat menyerupai penjaga Northland, dibuat untuk menghormati seorang kawan yang penting yang gugur dalam pertempuran.]],
  str_item_intro_3661251 = [[
Item furnitur. Bisa diletakkan di ruang-ruang di Colossus-mu.
Dibuat dari kayu pinus terbaik, penyangga lilin ini mengeluarkan aroma pinus yang lembut, membantu dalam relaksasi dan tidur.]],
  str_item_intro_3661252 = [[
Item furnitur. Bisa diletakkan di ruangan di Colossus-mu.
Sebuah rak buku berbentuk sederhana yang terbuat dari kayu berkualitas tinggi, mengeluarkan aroma yang halus.]],
  str_item_intro_3661253 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Sebuah stereo elegan yang sempurna untuk acara-acara resmi. Warna tonnya lebih cocok untuk prosesi upacara daripada musik heavy metal yang Ansia sukai.]],
  str_item_intro_3661254 = [[
Item furnitur. Bisa diletakkan di ruang di Colossus-mu.
Sebuah meja yang modis dan hemat biaya, sempurna untuk momen santai penduduk kota, menjadi bestseller di mana saja.]],
  str_item_3661256 = "Jam Vintage",
  str_item_3661257 = "Lukisan Dekoratif Malam Bermandikan Cahaya Bulan",
  str_item_3661258 = "Boneka Harehound",
  str_item_3661260 = "Grill Rediesel",
  str_item_intro_3661256 = [[
Item furnitur. Bisa diletakkan di ruangan-ruangan di Colossus-mu.
Bingkai logam jam ini dibuat dengan elegan, dan wajahnya telah diperlakukan khusus untuk menghasilkan kilauan perunggu seiring berjalannya waktu.]],
  str_item_intro_3661257 = [[
Item furnitur. Bisa diletakkan di ruangan-ruangan di Colossus-mu.
Sebuah lukisan dekoratif indah dari bulan yang terlihat di langit malam. Dari tengah lukisan, ia memancarkan cahaya lembut dan halus.]],
  str_item_intro_3661258 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Boneka berbentuk beagle. Matanya seolah-olah berkata, "Aku melihatnya, aku menginginkannya, dan aku harus memilikinya!"]],
  str_item_intro_3661260 = "Item furnitur. Bisa diletakkan di ruangan-ruangan di Colossus.\nGrill paling umum yang ditemukan di perkemahan Rediesel Wrench. Meskipun sebagian besar dibuat dari logam bekas, grill ini memberikan rasa gosong yang tak tertahankan pada makanan—Setidaknya itu yang dipikirkan oleh Rediesel Wrench.",
  str_item_3661265 = "Potret Traveler yang Elegan",
  str_item_3661266 = "Statue Wortel Grotesk",
  str_item_intro_3661265 = [[
Item furnitur. Bisa ditempatkan di ruangan-ruangan di Colossus-mu.
Legenda berbicara tentang seorang pengembara yang membangun kota manis Folta di tanah susu dan madu yang tak ada habisnya...
"Di mana tepatnya kota ini? Bisakah itu... Di dunia yang sepenuhnya berbeda?"]],
  str_item_intro_3661266 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Untuk anak-anak yang benci makan wortel, mata hijau yang bercahaya dan cakar tajamnya lebih menakutkan daripada Eclipsite mana pun...
"Po... Tapi aku Popo, wortel kecil yang miskin..."]],
  str_item_3661267 = "Game Arcade Retro",
  str_item_intro_3661267 = [[
Item furnitur. Bisa ditempatkan di ruangan-ruangan di Colossus-mu.
"Jika aku akan tinggal di Colossus, maka aku harus membawa ini... Atau aku tidak akan bertahan."
Ketika mendapat permintaan seperti itu, Navigator lebih dari senang untuk merisikokan beberapa otot terkilir untuk mengakomodasi temannya.]],
  str_item_3661268 = "Dekorasi Dinding Kacamata Hitam Pixel",
  str_item_intro_3661268 = [[
Item furnitur. Bisa diletakkan di ruang di Colossus-mu.
"Kamu telah kalah, Yingel. Tinggalkan rampasanmu."
Hadiah yang diperoleh dengan susah payah setelah mengalahkan Yingel. Sepertinya beberapa barang dagangan dari sebuah game.]],
  str_item_3661271 = "Box Penyimpanan Boneka",
  str_item_intro_3661271 = [[
Item furnitur. Bisa diletakkan di ruang di Colossus-mu.
Untuk kolektor boneka yang cenderung kehilangan jejak barang-barang mereka, ini mungkin adalah penemuan terhebat di dunia.]],
  str_item_3661272 = "Jam Kaki Kucing",
  str_item_intro_3661272 = [[
Barang furnitur. Dapat ditempatkan di kamar di Colossus Anda.
Jam dinding yang sangat menggemaskan berbentuk cakar kucing. Hampir sayang harus menggantung sesuatu yang begitu lembut di dinding.]],
  str_item_3661273 = "Podium Mahasiswa Baru",
  str_item_intro_3661273 = [[
Item furnitur. Bisa diletakkan di ruang-ruang di Colossus-mu.
Sebuah rumor sedang menyebar di Illumina: siswa baru yang meneriakkan impian mereka dari podium akan menjadi pahlawan yang dihormati suatu hari nanti.]],
  str_item_3661274 = "Perapian Besi Cor",
  str_item_intro_3661274 = [[
Item furnitur. Bisa ditempatkan di ruang-ruang di Colossus-mu.
Sebuah perapian besi cor yang diproduksi di Illumina Federation. Selain kemampuan pemanasannya yang mengesankan, penampilannya yang kuno dan api yang hangat memberikan kenyamanan yang tak terbantahkan di setiap ruangan.]],
  str_item_3661275 = "Mat Enlightenment",
  str_item_intro_3661275 = [[
Item furnitur. Bisa diletakkan di ruangan-ruangan di Colossus-mu.
Tempat tidur mewah dari Kota Varaki. Nyaman dan hangat, memiliki aura klasik yang khas. Murid-murid dari True Order menganggapnya sebagai tempat tidur wahyu ilahi.]],
  str_item_3661276 = "Cermin Esok Hari",
  str_item_intro_3661276 = [[
Item furnitur. Bisa diletakkan di ruangan-ruangan di Colossus.
"Orang-orang yang mencari kebenaran akan menatap ke dalam cermin kayu kuno ini dan melihat visi tentang apa yang akan datang." Serius, siapa yang bisa membuat hal seperti ini...?]],
  str_item_3661277 = "Potret Tentara yang Berani",
  str_item_intro_3661277 = [[
Item furniture. Bisa ditempatkan di ruangan-ruangan di Colossus kamu.
Dentuman keras serangan Eclipsite menenggelamkan bahkan sinyal terompet untuk menyerang. Tetapi ketika satu prajurit heroik mengibarkan standar dan maju, ribuan orang lainnya mengikuti di belakang.
"Didedikasikan untuk para pahlawan yang berani yang dengan gagah berani memberikan nyawa mereka."]],
  str_item_3661278 = "Patung Lonceng Kiamat",
  str_item_intro_3661278 = "Item furnitur. Bisa ditempatkan di ruangan-ruangan di Colossus kamu.\nSebuah patung yang menjijikkan dan menakutkan. Penampilannya yang jahat membuat orang percaya bahwa patung ini diciptakan sebagai musuh dunia.\nKonon, saat berjalan maju, baju besi logam yang dikenakannya berdenting-denting dengan tumpul — requiem penuh kebencian dari lonceng senja.",
  str_item_3661262 = "Model Penjaga Reruntuhan",
  str_item_intro_3661262 = [[
Item furnitur. Bisa ditempatkan di ruangan-ruangan di Colossus-mu.
Sebuah model yang dibuat oleh Fleur, yang selalu memikirkan penjaga reruntuhan.
"Ini mungkin bisa dianggap sebagai jenis mecha!"]],
  str_item_3661263 = "Kuali Alkimia",
  str_item_intro_3661263 = [[
Item furniture. Bisa ditempatkan di ruangan-ruangan di Colossus-mu.
Dengan ini, Atelier Ryza di Colossus akhirnya bisa dibuka untuk bisnis!]],
  str_item_3661264 = "Petualangan Afterimage",
  str_item_intro_3661264 = [[
Item furniture. Bisa ditempatkan di ruangan-ruangan di Colossus-mu.
Mari kita kenang musim panas ini setelah berakhir!]],
  str_item_3661279 = "Helm Angin Musim Panas",
  str_item_intro_3661279 = [[
Item furnitur. Bisa ditempatkan di ruangan-ruangan di Colossus-mu.
Dengan kedua tangan diletakkan di atasnya, seseorang hampir bisa merasakan belaian angin laut, menangkap esensi segar dari lautan musim panas dengan sempurna. Sebuah bagian furnitur yang esensial untuk setiap penggemar berlayar.]],
  str_item_3661280 = "Cincin Renang Angin Musim Panas",
  str_item_intro_3661280 = [[
Item furnitur. Bisa diletakkan di ruang-ruang di Colossus-mu.
Dirancang dengan skema warna klasik dan struktur yang kokoh, baik ditempatkan di rumah atau digunakan di laut, selalu menjadi pemandangan yang menyenangkan.]],
  str_item_3661281 = "Banner Angin Musim Panas",
  str_item_intro_3661281 = [[
Item furniture. Bisa ditempatkan di ruangan-ruangan di Colossus-mu.
Sebuah banner dekoratif yang sederhana namun elegan, cocok untuk ruangan mana pun yang membutuhkan sentuhan nautikal.]],
  str_item_3661282 = "Penjaga Burung Laut Conch",
  str_item_intro_3661282 = [[
Item furnitur. Bisa ditempatkan di ruangan-ruangan di Colossus-mu.
"Conch besar, toot-toot-toot. Burung camar mendengarnya dan jatuh dari langit."
Tidak yakin tentang asal-usulnya, tetapi lagu ini telah menyebar di Colossus.]],
  str_item_3661283 = "Breezy Bubble Blaster",
  str_item_intro_3661283 = [[
Item furniture. Bisa ditempatkan di ruangan-ruangan di Colossus-mu.
Sebuah pistol gelembung yang diletakkan pada sebuah dasar, sepertinya bisa meniup gelembung dengan sekali tekan.
"Apa properti yang santai! Semoga ini tidak membuat setiap orang tertidur."]],
  str_item_3661284 = "Potret White Narcissus",
  str_item_intro_3661284 = [[
Item furnitur. Bisa diletakkan di ruangan-ruangan di Colossus-mu.
Nikinis suka menanam bunga narsis. Dia sangat peduli pada tanamannya dan akan melempar siapa saja yang menginjak-injak mereka ke Danau Cermin.]],
  str_item_3661285 = "Potret Lily Murni",
  str_item_intro_3661285 = [[
Item furnitur. Bisa diletakkan di ruang-ruang di Colossus-mu.
Nepolis suka menanam lili. Dia sering memanennya untuk diberikan sebagai hadiah, hanya meninggalkan aroma manis mereka.]],
  str_item_3661286 = "Cahaya Stellar",
  str_item_intro_3661286 = "Item furnitur. Bisa diletakkan di ruangan-ruangan di Colossus-mu.\nLukisan Mithra—senyum singkat Achilles.\nBintang yang tak kenal menyerah, semoga kamu dan teman-temanmu bisa bersinar terang lagi.",
  str_item_3661287 = "Dual Blades",
  str_item_intro_3661287 = [[
Item furnitur. Bisa ditempatkan di ruangan-ruangan di Colossus-mu.
Replika senjata yang digunakan oleh kapten dan vice-kapten Silent Hunter.
Lihatlah! Ini adalah puncak dari inovasi dan tekad untuk menjaga! Itulah yang menjadi inti dari Silent Hunters.]],
  str_item_3661288 = "Stand Predator",
  str_item_intro_3661288 = [[
Item furnitur. Bisa diletakkan di ruangan-ruangan di Colossus Anda.
Sebuah tempat bertengger yang Mithra siapkan untuk predator.
Mereka mungkin terlihat santai di sana, tetapi cakar mereka bukanlah bercanda.]],
  str_item_3661289 = "Unity Starbound",
  str_item_intro_3661289 = [[
Item furnitur. Bisa diletakkan di ruangan-ruangan di Colossus-mu.
Sebuah potongan lama yang telah dipulihkan.
Jika bintang-bintang yang melintas di langit suatu hari nanti bisa menemukan tempat mereka dalam kelembutan waktu...
May kamu menerima kebahagiaan yang terlambat.]],
  str_item_3661290 = "Melodi Moonlit",
  str_item_intro_3661290 = [[
Item furnitur. Bisa diletakkan di ruang-ruang di Colossus-mu.
Melodi dari Ludweiss, seorang Caelestite.
Melodinya murni dan anggun seperti sinar bulan, dengan sedikit kesedihan yang tak tergoyahkan. May kamu menerima kebahagiaan yang terlambat.]],
