  str_item_9998074 = "Blaster",
  str_item_9998075 = "Caltrops Menyilaukan",
  str_item_9998076 = "Absorbent Paint",
  str_item_intro_9998002 = "Pada awal setiap putaran, secara acak memberikan 1 tumpukan Poison, Bleeding, atau Burning pada semua musuh di medan; efek ini diulang 4 kali. Mengurangi damage yang diberikan oleh Aurorian sebesar 15%.",
  str_item_intro_9998003 = "Semua damage yang diterima oleh musuh yang terkena debuff atau efek debuff meningkat sebesar 20%.",
  str_item_intro_9998004 = "Saat menghapus tile, secara acak memberikan 1 tumpukan Racun, Pendarahan, atau Terbakar pada musuh dalam jangkauan tile yang dihapus; efek ini diulang 5 kali.",
  str_item_intro_9998005 = "Saat musuh yang Diracuni/Terbakar/Berdarah dikalahkan, menimbulkan 1 tumpukan Racun, Pendarahan, dan Terbakar pada semua musuh yang tersisa di lapangan.",
  str_item_intro_9998006 = "Meningkatkan damage yang diterima musuh dari Poison, Bleeding, atau Burning sebesar 100%.",
  str_item_intro_9998007 = "Saat berhasil memberikan Poison, Burning, atau Bleeding pada musuh, target langsung kehilangan 1% dari HP mereka saat ini.",
  str_item_intro_9998008 = "Memberikan Gear Caelestite Khusus: Menghabiskan 2 ronde untuk segera menggunakan skill dukungan faksi Lv.2 sekali. Hanya dapat digunakan sekali setiap ronde.",
  str_item_intro_9998009 = "Semakin dekat dengan musuh, semakin tinggi damage dari Chain Combo Aurorian, dengan peningkatan maksimum sebesar 30%.",
  str_item_intro_9998010 = "Memberikan Detonator Aurorian peluang 30% untuk melakukan Chain Combo tambahan; untuk setiap ubin yang dihapus putaran ini, peluang pemicu meningkat 1%.",
  str_item_intro_9998011 = "Kapten bertarung berdasarkan elemen mereka sendiri saja, memberikan 100% lebih banyak damage.",
  str_item_intro_9998012 = "Ketika pemimpin tim melakukan Chain Combo, menghasilkan bayangan di posisi yang akan dihapus, dan melepaskan Chain Combo pada saat yang sama.",
  str_item_intro_9998013 = "Setelah kemenangan berikutnya, memberikan 2 kesempatan tambahan untuk memilih Gear Pencerahan dalam pertempuran berikutnya, efektif sekali.",
  str_item_intro_9998014 = "Memberikan kesempatan untuk mengacak ulang saat memilih Perlengkapan Pencerahan, dapat digunakan 8 kali.",
  str_item_intro_9998015 = "Menghapus Gear Caelestite Spesial awal dan langsung memberikan 2 kesempatan untuk pemilihan Gear Pencerahan.",
  str_item_intro_9998016 = "Ketika seorang Aurorian menyerang 3 atau lebih musuh dengan Active Skill secara bersamaan, melemparkan petir yang menyerang semua musuh, menimbulkan kerusakan setara dengan 200% dari rata-rata ATK tim.",
  str_item_intro_9998017 = "Setelah mengganti Kapten, cooldown Skill Aktif Kapten baru berkurang 1 putaran. Aurorian yang sama hanya dapat memicu ini maksimal sekali per putaran.",
  str_item_intro_9998018 = "Membuat tim menjadi tak terkalahkan selama 1 putaran saat HP tim berkurang menjadi 1%, kemudian memulihkan 20% dari HP Maks. Efek ini hanya bisa diaktifkan sekali dalam setiap pertempuran, hingga total maksimal 2 kali.",
  str_item_intro_9998019 = "Mengembalikan 35% dari HP tim yang hilang setelah memenangkan pertempuran.",
  str_item_intro_9998020 = "Mengisi ulang Bandage di lapangan pada awal pertempuran.",
  str_item_intro_9998021 = "Meningkatkan kerusakan Aurorian sebesar 15% ketika HP tim saat ini lebih tinggi dari 90%.",
  str_item_intro_9998022 = "Memberikan perisai setara dengan 40% dari Max HP yang berlangsung selama 2 putaran di awal setiap gelombang.",
  str_item_intro_9998023 = "Memulihkan HP menjadi 50% di awal pertempuran jika HP saat ini lebih rendah dari 50%.",
  str_item_intro_9998024 = "Supporter Aurorian +40% efek regenerasi dari Chain Combos dan Active Skills dalam pertempuran.",
  str_item_intro_9998025 = "Untuk setiap elemen utama Aurorian dalam tim, meningkatkan kerusakan yang diberikan oleh Aurorian sebesar 6%, dengan peningkatan maksimum sebesar 24%.",
  str_item_intro_9998026 = "Saat Aurorian menimbulkan kerusakan, mengabaikan efek pengurangan kerusakan karena elemen mereka dilawan. Saat menerima kerusakan, mengabaikan bonus karena elemen mereka dilawan.",
  str_item_intro_9998027 = "Elemen sekunder Aurorian menangani kerusakan dengan pengganda yang sama dengan elemen utamanya.",
  str_item_intro_9998028 = "Memungkinkan Aurorian yang Terikat untuk mengabaikan elemen ubin yang akan dihapus saat melakukan Chain Combo.",
  str_item_intro_9998029 = "Untuk setiap set Aurorian yang Terikat, memulihkan 5% dari Max HP tim di awal setiap putaran.",
  str_item_intro_9998030 = "Untuk setiap set Aurorian yang terikat, ada peluang 40% untuk mendapatkan 1 muatan tambahan untuk Special Caelestite Gear saat menghapus ubin. Dipicu secara independen ketika ada beberapa set ikatan.",
  str_item_intro_9998031 = "Aurorian yang terikat mewarisi 20% dari Basic ATK masing-masing.",
  str_item_intro_9998032 = "Saat Aurorian menggunakan Skill Aktif, mengurangi cooldown Skill Aktif Aurorian yang terikat sebanyak 1 putaran. Dapat diaktifkan hingga 5 kali per pertempuran.",
  str_item_intro_9998033 = "Mengurangi cooldown dari Skill Aktif pertama yang dilempar di setiap pertempuran sebanyak 2 putaran segera setelah dilempar.",
  str_item_intro_9998034 = "Setelah mengetuk untuk menghapus ubin, jika Aurorian belum melakukan Chain Combo di putaran ini, mengurangi cooldown dari semua Skill Aktif Aurorian sebanyak 1.",
  str_item_intro_9998035 = "Semakin jauh Aurorian dari musuh, semakin tinggi damage dari Chain Combo mereka, dengan peningkatan maksimum sebesar 50%.",
  str_item_intro_9998036 = "Meningkatkan jumlah target Chain Combo Sniper Aurorians sebanyak 2.",
  str_item_intro_9998037 = "Aurorian mendapatkan 3% Life Drain saat memberikan damage dan kehilangan 10% dari HP mereka saat ini di awal setiap putaran.",
  str_item_intro_9998038 = "Semakin rendah HP saat ini, semakin tinggi kerusakan Chain Combo Aurorian, dengan peningkatan maksimum sebesar 50%.",
  str_item_intro_9998039 = "Semua sekutu dan musuh kehilangan 7% dari HP mereka saat ini di awal setiap putaran.",
  str_item_intro_9998040 = "Ketika HP Aurorian saat ini berada di 50%, meningkatkan kerusakan yang diberikan oleh Aurorian sebesar 30%; untuk setiap 1% perbedaan HP, peningkatan ini berkurang sebesar 5%.",
  str_item_intro_9998041 = "Kehilangan 7% HP saat ini di awal setiap putaran. Setelah itu, memberikan kerusakan sebesar 150% dari ATK rata-rata tim ke musuh dalam 2 cluster sekitarnya.",
  str_item_intro_9998042 = "Di awal pertempuran, kehilangan 70% dari HP saat ini dan memberikan kerusakan kepada semua musuh sebesar 300% dari kerugian ini.",
  str_item_intro_9998043 = "Meningkatkan kerusakan Skill Aktif Aurorian sebesar 80%. Kehilangan 8% dari HP saat ini setiap kali Skill Aktif dilemparkan.",
  str_item_intro_9998044 = "Mengabaikan jumlah ubin yang diketuk dan dihapus dan memungkinkan Aurorian untuk melakukan Chain Combo level tertinggi mereka setiap kali setelah penghapusan.",
  str_item_intro_9998045 = "Di awal pertempuran, mendapatkan 1 kesempatan penggunaan untuk semua Perlengkapan Caelestite Khusus.",
  str_item_intro_9998046 = "Setiap penggunaan Gear Caelestite Spesial memicu skill Dukungan faksi Lv.1 sekali; efektif 2 kali per pertempuran.",
  str_item_intro_9998047 = "Mengembangkan jangkauan efektif dari Gear Caelestite Spesial awal menjadi 5×5; mendapatkan 1 kesempatan penggunaan setelah mengumpulkan 40 poin energi.",
  str_item_intro_9998048 = "Meningkatkan efisiensi pengisian ulang kesempatan penggunaan Gear Caelestite Spesial sebesar 50%.",
  str_item_intro_9998049 = "Mengalahkan musuh dengan HP di bawah 9%.",
  str_item_intro_9998050 = "Meningkatkan kerusakan yang diberikan oleh Aurorian sebesar 20%; menggandakan konsumsi putaran.",
  str_item_intro_9998051 = "Mengurangi DEF semua Aurorian di tim menjadi nol dan mengubah 50% dari DEF dasar mereka menjadi ATK.",
  str_item_intro_9998052 = "Meningkatkan Max HP semua Aurorian sebesar 2% untuk setiap bagian Gear Pencerahan yang dimiliki.",
  str_item_intro_9998053 = "Meningkatkan DEF semua Aurorian sebesar 1,5% untuk setiap bagian Gear Pencerahan yang dimiliki.",
  str_item_intro_9998054 = "Meningkatkan ATK semua Aurorian sebesar 1% untuk setiap bagian Gear Pencerahan yang dimiliki.",
  str_item_intro_9998055 = "Sebuah Jebakan Peningkatan Kerusakan muncul secara acak di medan perang pada awal setiap putaran. Setelah menghancurkan jebakan ini, kerusakan Chain Combo meningkat sebesar 35% di putaran ini.",
  str_item_intro_9998056 = "Di awal setiap gelombang, sebuah Toples Permen Energi muncul secara acak di medan perang, yang memberikan 1 kesempatan penggunaan untuk Perlengkapan Caelestite Spesial acak saat dihancurkan.",
  str_item_intro_9998057 = "Meningkatkan jumlah semua item yang dapat dihapus di medan pertempuran menjadi 2 saat muncul.",
  str_item_intro_9998058 = "Di awal setiap gelombang, sebuah Mobile Energizer muncul secara acak di medan perang, yang memberikan 3 putaran ekstra setelah dihilangkan.",
  str_item_intro_9998059 = "Di awal setiap putaran, menghancurkan ubin di bawah, meningkatkan kerusakan yang diberikan oleh Aurorian sebesar 15%.",
  str_item_intro_9998060 = "Setel ulang hitungan efektivitas semua Enlightenment Gear ke keadaan awal mereka.",
  str_item_intro_9998061 = "Memberikan Gear Caelestite Khusus: Mengubah semua ubin di lapangan menjadi ubin berwarna. Datang dengan 2 kesempatan penggunaan saat perolehan.",
  str_item_intro_9998062 = "Meningkatkan kerusakan Chain Combo ke musuh dalam jangkauan petak yang dihapus sebesar 35%.",
  str_item_intro_9998063 = "Ketika mengetuk untuk menghapus ubin, memberikan kerusakan setara dengan 150% dari ATK rata-rata tim kepada musuh dalam jangkauan ubin yang dihapus.",
  str_item_intro_9998064 = "Ketika mengetuk untuk menghapus ubin, memberikan perisai setara dengan 0,5% dari Max HP untuk setiap ubin yang dihapus, berlangsung selama 1 putaran.",
  str_item_intro_9998065 = "Ketika menghapus setidaknya 15 ubin sekaligus dengan sekali ketuk, meningkatkan kerusakan Chain Combo Aurorian sebesar 30%. Chain Combo tidak dapat dilepaskan jika kurang dari 7 ubin dihapus sekaligus.",
  str_item_intro_9998066 = "Meningkatkan ATK dasar Aurorian dengan ATK terendah dalam tim sebesar 60%.",
  str_item_intro_9998067 = "Mengurangi jumlah ubin yang diperlukan untuk memicu keterampilan dukungan faksi: mengurangi 5 untuk keterampilan dukungan faksi Lv.1; mengurangi 10 untuk keterampilan dukungan faksi Lv.2.",
  str_item_intro_9998068 = "Memungkinkan skill dukungan faksi untuk mendorong musuh mundur sebanyak 1 tile.",
  str_item_intro_9998069 = "Di awal setiap ronde, untuk setiap Aurorian dalam tim yang termasuk dalam faksi yang sama dengan skill dukungan faksi, semua Special Caelestite Gear mendapatkan 3 charge.",
  str_item_intro_9998070 = "Memberikan efek Life Drain pada skill dukungan faksi; untuk setiap Aurorian dari faksi tersebut dalam tim, memberikan tambahan 5% Life Drain.",
  str_item_intro_9998071 = "Ketika mengetuk untuk menghapus tile, setiap tile yang dihapus meningkatkan kerusakan akhir dari skill dukungan faksi sebesar 5% untuk putaran saat ini.",
  str_item_intro_9998072 = "Untuk setiap Aurorian dalam tim yang termasuk dalam faksi yang sama dengan skill dukungan faksi, meningkatkan kerusakan akhir dari skill dukungan faksi sebesar 25%.",
  str_item_intro_9998073 = "Untuk setiap Aurorian dalam tim yang termasuk dalam faksi yang sama dengan skill dukungan faksi, meningkatkan DEF Dasar dan HP Maks semua Aurorian sebesar 3%.",
  str_item_intro_9998074 = "Meningkatkan damage dari Active Skills Aurorian sebesar 100%; hanya Ascension I dari Chain Combo yang dapat dilemparkan.",
  str_item_intro_9998075 = "Di awal setiap putaran, ubah 1 ubin di bawah 2 musuh acak di lapangan menjadi berwarna.",
  str_item_intro_9998076 = "Ketika musuh dieliminasi, mengubah 1 Tile di bawahnya menjadi elemen yang sama dengan Kapten.",
  str_item_4090264 = "Mantra Malam yang Memikat",
  str_item_intro_4090264 = [[
Navigator, saya tidak ingin menjadi Aurorian lagi.
Tidak mampu menahan kekosongan, Uriel ingin mengubah bentuk keberadaannya dengan ramuan ajaib. Namun, ramuan tersebut tidak membawa perubahan yang diharapkan, melainkan membuatnya mabuk kepayang. Hilang sudah keputusasaan dan sifat dinginnya yang biasa, digantikan oleh semangat baru yang penuh semangat, menginginkan petualangan mendebarkan bersamamu. Bagaimana kamu akan menavigasi melalui perubahan tak terduga ini?]],
  str_item_3400132 = "Pikiran yang Terhubung, Ribbit",
  str_item_intro_3400132 = [[
Membuka latar belakang: Pikiran Terhubung, Ribbit
Kemampuan luar biasa katak terletak pada koneksi sadarnya ke semua hal, dan melalui karunia ini, katak mengambil tugas vital untuk menyembuhkan teman-temannya...]],
