  str_item_9011088 = "Lunar Horn",
  str_item_intro_9011001 = "Di awal putaran, memberikan 4,444 damage tetap kepada semua musuh dan mengeliminasi mereka yang memiliki kurang dari 6% HP.",
  str_item_intro_9011002 = "Menghasilkan ubin berwarna di area sekitarnya setiap putaran, dengan jumlah sama dengan jumlah tipe Elemen Primer dari Aurorian dalam tim. Kemampuan ini dieksekusi 2 kali lebih banyak di awal pertempuran.",
  str_item_intro_9011003 = "Mengubah semua ubin menjadi berwarna pada putaran ketiga pertempuran. Setelah koneksi ubin berakhir, semua ubin berwarna akan dihapus.",
  str_item_intro_9011004 = "Meningkatkan kerusakan yang diberikan oleh Aurorian dengan HP sama dengan maksimum mereka sebesar 15%.",
  str_item_intro_9011005 = "Setelah menyelesaikan tahap Dream Devourer, mendapatkan bunga setara dengan 30% dari kepemilikan Dream Coin Anda saat ini.",
  str_item_intro_9011006 = "Penggunaan sekali: Mendapatkan 2 Dream Bombs.",
  str_item_intro_9011007 = "Semakin banyak Dream Coins yang kamu miliki, semakin tinggi damage yang ditimbulkan oleh serangan normalmu.",
  str_item_intro_9011008 = "Ubin pertama dalam satu baris mungkin memiliki warna yang berbeda dari yang berikutnya, memungkinkan kedua jenis Aurorian untuk bergabung dalam pertempuran.",
  str_item_intro_9011009 = "Mengacak semua Dream Orb yang tidak dipakai menjadi yang baru (dengan level tidak lebih rendah dari aslinya) dan setiap Dream Orb memiliki peluang 30% untuk meningkat dalam peringkat.",
  str_item_intro_9011010 = "Ketika warna Tile yang terhubung cocok dengan elemen Kapten, Dream Orb mendapatkan 1 muatan untuk setiap 2 Tile yang terhubung.",
  str_item_intro_9011011 = "Ketika skill Dream Orb menimbulkan damage, lakukan dua perhitungan acak dalam jangkauan dan pilih nilai yang lebih tinggi sebagai damage yang ditimbulkan, melebarkan rentang fluktuasi damage sebesar 10%.",
  str_item_intro_9011012 = "Mengatur ulang peringkat Dream Orbs yang diperoleh selanjutnya menjadi 1-star.",
  str_item_intro_9011013 = "Ketika memilih Kartu Ramalan Mimpi, mengurangi pilihan yang tersedia sebanyak 1 tetapi menggandakan efek hadiah dari kartu.",
  str_item_intro_9011014 = "Mengurangi Max HP semua Aurorian sebesar 20% setelah memasuki pertempuran tetapi meningkatkan jumlah Kartu Divinasi Mimpi yang dapat dipilih sebanyak +1 selama aksi.",
  str_item_intro_9011015 = "Sebelum menghubungkan ubin, setiap kali Aurorian bergerak, memberikan kerusakan ke area berbentuk berlian di tempat pendaratan, rata-rata 150% dari ATK mereka. Selain itu, Dream Orb mendapatkan 1 muatan untuk setiap lingkaran gerakan.",
  str_item_intro_9011016 = "Ketika Chain Combo Aurorian Converter dan Supporter menimbulkan kerusakan, secara acak memberikan satu tumpukan Poisoned, Bleeding, atau Burning pada target.",
  str_item_intro_9011017 = "Saat menimbulkan damage pada musuh yang terkena Poison, Bleeding, atau Burning, meningkatkan damage untuk setiap efek.",
  str_item_intro_9011018 = "Setelah memberikan satu tumpukan Poisoned, Bleeding, atau Burning pada target, ada peluang untuk menerapkan tumpukan debuff acak lainnya. Efek ini dapat dipicu berulang kali, dengan probabilitas berkurang setengah setiap kali.",
  str_item_intro_9011019 = "Ketika musuh mati, secara acak memberikan satu tumpukan Poisoned, Bleeding, atau Burning ke semua musuh.",
  str_item_intro_9011020 = "Ketika meluncurkan serangan normal, Kapten memberikan kerusakan Api tambahan setara dengan 50% dari ATK keseluruhan tim.",
  str_item_intro_9011021 = "Ketika meluncurkan serangan normal, Kapten memberikan kerusakan Petir tambahan sebesar 50% dari total ATK tim.",
  str_item_intro_9011022 = "Ketika meluncurkan serangan normal, Kapten memberikan kerusakan Hutan tambahan sebesar 50% dari total ATK tim.",
  str_item_intro_9011023 = "Ketika meluncurkan serangan normal, Kapten memberikan kerusakan Air tambahan sebesar 50% dari total ATK tim.",
  str_item_intro_9011024 = "Di awal setiap putaran, mengubah 3 ubin merah terdekat menjadi ubin berwarna.",
  str_item_intro_9011025 = "Di awal setiap putaran, mengubah 3 ubin kuning terdekat menjadi ubin berwarna.",
  str_item_intro_9011026 = "Di awal setiap putaran, mengubah 3 ubin hijau terdekat menjadi ubin berwarna.",
  str_item_intro_9011027 = "Di awal setiap putaran, mengubah 3 ubin biru terdekat menjadi ubin berwarna.",
  str_item_intro_9011028 = "Di awal setiap putaran, ubah hingga 1 ubin di bawah setiap musuh menjadi berwarna.",
  str_item_intro_9011029 = "Ketika menerima damage, mengubah 3 ubin dalam 2 klaster di sekitar menjadi ubin berwarna.",
  str_item_intro_9011030 = "Di awal setiap putaran, Aurorian dengan HP lebih rendah pulih sebanding dengan HP yang mereka hilangkan.",
  str_item_intro_9011031 = "Setelah memenangkan pertempuran, semua Aurorian mengembalikan 20% dari HP mereka.",
  str_item_intro_9011032 = "Jika ada Tile Gelap yang diperoleh di putaran saat ini, mendapatkan 1 tumpukan Semangat Pertempuran.",
  str_item_intro_9011033 = "Aurorian Pendukung mendapatkan 1 tumpukan Semangat Pertempuran saat menggunakan Active Skills atau Chain Combos untuk menyembuhkan tim.",
  str_item_intro_9011034 = "Ketika Skill Aktif Aurorian menendang mundur atau menarik musuh, mendapatkan tumpukan Semangat Pertempuran berdasarkan jumlah target yang terpengaruh. Efek ini dapat dipicu hingga 3 kali per putaran.",
  str_item_intro_9011035 = "Mendapatkan 1 tumpukan Battle Spirit setiap kali monster terkena Poisoned, Bleeding, atau Burning. Efek ini dapat dipicu hingga 4 kali per putaran.",
  str_item_intro_9011036 = "Mendapatkan Koin Dream sebanyak 4 kali level setiap kali Level Dream meningkat.",
  str_item_intro_9011037 = "Mendapatkan Dream Coin sebanyak 7 kali lipat peningkatan setiap kali Dream Interest meningkat.",
  str_item_intro_9011038 = "Mendapatkan 4 Koin Mimpi untuk setiap Eclipsite yang dikalahkan dalam pertempuran.",
  str_item_intro_9011039 = "Penggunaan satu kali: Mengambil 5 Kartu Ramalan Mimpi dari dek Anda dan mendapatkan Bunga Mimpi yang sama dengan jumlah langkah mereka.",
  str_item_intro_9011040 = "Dapatkan dua hadiah sekaligus di Treasure Dream Realm.",
  str_item_intro_9011041 = "Mendapatkan 30 Dream EXP setiap kali melintasi Dangerous Dream Realm.",
  str_item_intro_9011042 = "Mengurangi harga barang yang dapat dibeli dan mengurangi biaya pengacakan ulang Dream Gear, Aurorian, dan barang sebesar 35%.",
  str_item_intro_9011043 = "Setelah diperoleh, Aurorian yang di-Dispatch di Realm Mimpi yang Belum Dieksplorasi akan segera kembali, dan pemberian Koin Mimpi dan Bunga Mimpi dari pengiriman tersebut digandakan.",
  str_item_intro_9011044 = "Mendapatkan 40 Dream EXP setiap kali melewati kamp.",
  str_item_intro_9011045 = "Penggunaan sekali: Semua Aurorian kehilangan 70% dari HP mereka saat ini; mendapatkan 25 Dream EXP untuk setiap Aurorian yang kehilangan HP.",
  str_item_intro_9011046 = "Penggunaan sekali: Menghabiskan setengah dari Dream Coins saat ini dan mendapatkan 2 Dream EXP untuk setiap Dream Coin yang digunakan.",
  str_item_intro_9011047 = "Secara signifikan meningkatkan damage dari Skill Aktif Aurorian; Aurorian kehilangan HP saat memberikan damage.",
  str_item_9011048 = "Blaster",
  str_item_9011049 = "Stomper",
  str_item_9011050 = "Kingslayer",
  str_item_9011051 = "Wallbreaker",
  str_item_9011052 = "Paralyzer",
  str_item_9011053 = "Thunderstriker",
  str_item_intro_9011048 = "Mengaktifkan <link=\"1005\"><color=#98500f><u>Modul Upgrade Algoritma</u></color></link>; semakin sedikit musuh di lapangan, semakin tinggi damage akhir.",
  str_item_intro_9011049 = "Mengaktifkan <link=\"1005\"><color=#98500f><u>Modul Peningkatan Algoritma</u></color></link>; Kapten mendapatkan 3 <link=\"1006\"><color=#98500f><u>Poin Overload</u></color></link> saat meluncurkan serangan normal.",
  str_item_intro_9011050 = "Mengaktifkan <link=\"1005\"><color=#98500f><u>Modul Upgrade Algoritma</u></color></link>; Skill Aktif Aurorian: menghasilkan 4 <link=\"1006\"><color=#98500f><u>Poin Overload</u></color></link> untuk setiap musuh yang terkena.",
  str_item_intro_9011051 = "Mengaktifkan <link=\"1005\"><color=#98500f><u>Modul Peningkatan Algoritma</u></color></link>; di awal putaran, semakin rendah HP tim, semakin banyak <link=\"1006\"><color=#98500f><u>Poin Overload</u></color></link> yang didapatkan.",
  str_item_intro_9011052 = "Mengaktifkan <link=\"1005\"><color=#98500f><u>Modul Peningkatan Algoritma</u></color></link>; mendapatkan 8 <link=\"1006\"><color=#98500f><u>Poin Overload</u></color></link> setiap kali menerima kerusakan.",
  str_item_intro_9011053 = "Mengaktifkan <link=\"1005\"><color=#98500f><u>Modul Peningkatan Algoritma</u></color></link>; meningkatkan ambang pemicu Data Bomb menjadi 120 <link=\"1006\"><color=#98500f><u>Poin Overload</u></color></link>, memberikan kerusakan lebih besar pada monster berukuran besar.",
  str_item_intro_9011054 = "Tidak lagi memasuki Aurora Time; sebaliknya, mendapatkan nilai +1ms setiap kali seharusnya memasuki Aurora Time, dan menerima 5 Emas (Aurora Time yang terganggu oleh gelombang monster atau kemenangan pertempuran juga dihitung).",
  str_item_intro_9011055 = "Ketika musuh mati, mengubah hingga 1 ubin di bawahnya menjadi Ubin Gelap.",
  str_item_intro_9011056 = "Pada awal putaran, ubah 2 ubin terdekat dengan elemen yang sama dengan Kapten menjadi Ubin Gelap.",
  str_item_intro_9011057 = "Meningkatkan jumlah opsi yang disediakan selama pemilihan Gear Impian sebanyak 1.",
  str_item_intro_9011058 = "Pembaruan pertama dari opsi Dream Gear gratis.",
  str_item_intro_9011059 = "Untuk setiap bagian Dream Gear yang dimiliki, meningkatkan ATK Detonator dan Sniper Aurorians sebesar 0,5%",
  str_item_intro_9011060 = "Untuk setiap bagian Dream Gear yang dimiliki, meningkatkan DEF dari Aurorian Converter dan Supporter sebesar 2%.",
  str_item_intro_9011061 = "Untuk setiap bagian Gear Impian yang dimiliki, meningkatkan Max HP semua Aurorian sebesar 1,5%.",
  str_item_intro_9011062 = "Di awal setiap putaran, menghasilkan 1 jam (hingga 1 dapat ada dalam satu waktu), mengurangi putaran cooldown dari skill Aurorian dengan cooldown tertinggi sebanyak 1.",
  str_item_intro_9011063 = "Menyebabkan <link=\"1010\"><color=#98500f><u>Blind</u></color></link> pada target yang menerima damage.",
  str_item_intro_9011064 = "Setiap kali menerima damage, semua Aurorian mendapatkan bonus damage 5%, hingga maksimum 30% (diatur ulang di akhir pertempuran).",
  str_item_intro_9011065 = "Meningkatkan kerusakan serangan normal sebesar 30%. Efek ini berakhir setelah menerima kerusakan.",
  str_item_intro_9011066 = "Mengurangi DEF semua Aurorian menjadi setengah dan meningkatkan ATK mereka sendiri sebesar jumlah DEF yang dikurangi.",
  str_item_intro_9011067 = "Menghasilkan gambar Kapten Aurorian di titik awal. Gambar ini juga mengeluarkan Chain Combo di babak ini.",
  str_item_intro_9011068 = "Meningkatkan kerusakan sebesar 3,5% untuk setiap Aurorian dengan Elemen Utama yang berbeda di dalam tim.",
  str_item_intro_9011069 = "Elemen Sekunder dapat menimbulkan kerusakan berdasarkan pengganda Elemen Utama, dengan peningkatan tambahan pada pengganda ketika elemen utama dan sekunder sama.",
  str_item_intro_9011070 = "Kapten sebelumnya dapat dikerahkan dalam pertempuran terlepas dari elemen Tile yang terhubung.",
  str_item_intro_9011071 = [[
Kapten mengubah peluang +2 di setiap pertempuran.
Saat mengganti Kapten, cooldown Skill Aktif Kapten baru berkurang 1. Setiap Aurorian hanya dapat memicu efek ini sekali setiap putaran.]],
  str_item_intro_9011072 = "Setelah setiap koneksi atau pergerakan Tile, Tile awal harus dari elemen yang sama dengan Captain.",
  str_item_intro_9011073 = "Meningkatkan kerusakan yang diberikan oleh semua sekutu sebesar 15% tetapi mengubah ubin awal dari setiap baris yang terhubung menjadi ubin rusak yang tidak dapat dilalui selama 8 putaran.",
  str_item_intro_9011074 = "Ketika Active Skills Aurorian memukul mundur atau menarik musuh, memberikan 3.000 kerusakan tetap untuk setiap tile yang dilalui target.",
  str_item_intro_9011075 = "Semua Level Breakthrough Aurorian +1 (Tidak berlaku untuk Aurorian yang Level Breakthrough-nya telah mencapai maksimum).",
  str_item_intro_9011076 = "Penggunaan sekali: Pilih Aurorian mana saja untuk bergabung dengan tim; naikkan Level Terobosan Aurorian ini ke maksimum.",
  str_item_intro_9011077 = "Detonator Aurorians menimbulkan 1 tumpukan <link=\"1003\"><color=#98500f><u>Meltdown</u></color></link> pada target yang terkena Chain Combos mereka.",
  str_item_intro_9011078 = "Kemampuan Aktif Detonator Aurorian memiliki 40% kesempatan untuk menginfeksi <link=\"1011\"><color=#98500f><u>Paralyzed</u></color></link> pada target.",
  str_item_intro_9011079 = "Mengembangkan jangkauan Chain Combo level tertinggi Detonator Aurorian menjadi 2 cluster.",
  str_item_intro_9011080 = "Serangan normal Detonator Aurorian menghasilkan kerusakan tambahan yang mengabaikan DEF dan juga menimbulkan kerusakan setara dengan 10% dari HP Aurorian yang hilang pada target.",
  str_item_intro_9011081 = "Serangan normal Detonator Aurorian memiliki peluang 30% untuk menghasilkan 150% kerusakan.",
  str_item_intro_9011082 = "Untuk setiap Detonator Aurorian yang dikerahkan, meningkatkan kerusakan yang ditimbulkan oleh semua Chain Combo Detonator Aurorian sebesar 4%.",
  str_item_intro_9011083 = "Serangan normal dari Sniper Aurorian memberikan <link=\"1004\"><color=#98500f><u>Wisdom</u></color></link> sebesar 20% dari ATK mereka pada target.",
  str_item_intro_9011084 = "Meningkatkan kerusakan yang ditimbulkan oleh Kombo Rantai dari Sniper Aurorians ke monster yang menduduki beberapa ubin.",
  str_item_intro_9011085 = "Mengembangkan jangkauan Kombo Rantai target tunggal Sniper Aurorians sebanyak 2 klaster dan meningkatkan jumlah target sebanyak 1.",
  str_item_intro_9011086 = "Meningkatkan kerusakan Kombo Rantai Sniper Aurorian berdasarkan HP yang mereka hilang, dengan peningkatan maksimum 50%.",
  str_item_intro_9011087 = "Kemampuan Aktif dari Sniper Aurorian memiliki peluang 30% untuk menginfeksi target dengan <link=\"1012\"><color=#98500f><u>Takut</u></color></link>.",
  str_item_intro_9011088 = "Untuk setiap Sniper Aurorian yang dikerahkan, meningkatkan damage yang diberikan oleh serangan normal semua Sniper Aurorian sebesar 5%.",
  str_item_9810702 = "Peningkatan Algoritma: Set Perlengkapan Impian 2",
