  str_item_intro_8800103 = "Embun yang diambil dari puncak puncak cedar, begitu murni sehingga tampaknya dapat membersihkan semangat seseorang.",
  str_item_intro_8800102 = "Sebuah bunga yang mekar di dingin, memancarkan aroma yang lembut dan halus.",
  str_item_intro_8800101 = "Potongan es yang ada di mana-mana ini menghasilkan dingin saat dikumpulkan dalam jumlah besar.",
  str_item_intro_8800203 = "Minyak pedas dan canggih yang mewujudkan semangat dan kegigihan Rediesel.",
  str_item_intro_8800202 = "Batu dengan minyak leleh mengalir di permukaannya.",
  str_item_intro_8800201 = "Butiran pasir oranye kasar, masih hangat dari gurun.",
  str_item_intro_8800303 = "Sebuah cabang yang subur, mengalir dengan vitalitas yang menakjubkan.",
  str_item_intro_8800302 = "Bulu halus dan ringan yang menyebarkan benih harapan bersama angin.",
  str_item_intro_8800301 = "Biji hijau polos, menunggu untuk bertunas.",
  str_item_intro_8800403 = "Sebuah kristal berharga dan langka, berkilau dengan kecemerlangan fajar.",
  str_item_intro_8800402 = "Sebuah permata kuning, berdenting dengan kekuatan guntur.",
  str_item_intro_8800401 = "Sebuah bijih yang tidak mencolok, sedikit lebih padat dari batuan biasa.",
  str_item_intro_8800113 = "Esensi bergizi yang merangsang baik tanaman maupun hewan.",
  str_item_intro_8800213 = "Lembut dan manis, setiap suapan adalah sebuah kenikmatan.",
  str_item_intro_8800313 = "Sebuah Boneka Windelion yang menawan dengan daya tarik visual dan kenikmatan taktil, dengan potensi untuk menjadi hadiah yang populer.",
  str_item_intro_8800413 = "Sebuah bola kristal yang memancarkan cahaya menawan, ideal untuk dekorasi rumah.",
  str_item_intro_8800112 = "Salep cepat aksi untuk keseleo dan memar. Ini adalah keharusan untuk rumah dan perjalanan.",
  str_item_intro_8800212 = "Ini meminimalkan gesekan dan menghaluskan permukaan, cocok untuk berbagai penggunaan.",
  str_item_intro_8800312 = "Tanaman pot yang berwarna cerah dan ramah lingkungan yang tumbuh subur di tempat yang cerah.",
  str_item_intro_8800412 = "Sebuah pisau yang sangat tajam. Memotong segala sesuatu dengan mudah, disukai oleh pengrajin.",
  str_item_intro_8800111 = "Ini cocok untuk mendinginkan barang dan juga aman untuk diminum.",
  str_item_intro_8800211 = "Bahan peledak berdaya tinggi yang harus ditangani dengan hati-hati.",
  str_item_intro_8800311 = "Kain rami yang tahan lama dan polos, cocok untuk berbagai keperluan.",
  str_item_intro_8800411 = "Sebuah hiasan sederhana yang memancarkan pesona halus.",
  str_item_intro_8800123 = "Resep yang menjelaskan persyaratan untuk membuat Suplemen Nutrisi.",
  str_item_intro_8800223 = "Resep yang menjelaskan persyaratan untuk membuat Kue Yummy.",
  str_item_intro_8800323 = "Resep yang menjelaskan persyaratan untuk membuat Boneka Windelion yang Mewah.",
  str_item_intro_8800423 = "Sebuah resep yang menjelaskan persyaratan untuk membuat Bauble Kristal.",
  str_item_intro_8800122 = "Resep yang menjelaskan persyaratan untuk membuat Salep Eksternal.",
