  str_item_8800005 = "Fragmen Kuno",
  str_item_intro_8800005 = "Awalnya bagian dari reruntuhan, fragmen batu ini ditandai oleh perjalanan waktu.",
  str_item_8800006 = "Carrier Exploration",
  str_item_intro_8800006 = "Carrier yang dirancang untuk eksplorasi material alkimia, dengan 2 unit yang diisi ulang setiap hari pada pukul 05:00 waktu server.",
  str_item_8800008 = "Dana Atelier",
  str_item_intro_8800008 = "Keuntungan dari Mini Atelier. Dengan bantuan Klaudia, toko ini pasti akan terkenal di Astra!",
  str_item_8800010 = "SP",
  str_item_intro_8800010 = "Diperoleh dari kerja keras di Mini Atelier, ini dapat meningkatkan Amulets dan Knacks di Skill Tree.",
