  str_item_8800013 = "Alchemy Material Crate III",
  str_item_intro_8800013 = "Mengandung bahan alkimia tingkat tinggi.",
  str_item_1602411 = "Pepita",
  str_item_intro_1602411 = "Pepita, bola api pemberontak yang penuh semangat. Meskipun dia lahir di Illumina, dia telah bergabung dengan True Order. Dia adalah pemberontak di hati, menolak untuk tunduk pada kehendak siapa pun. Sebaliknya, dia mengikuti hasrat dan nalurinya kemanapun mereka membawanya.",
  str_item_3220241 = "Pepita Solamber",
  str_item_intro_3220241 = [[
